window.__Q=window.__Q||{};window.__Q["tcm/1/A1"]=[{"q":"”乙癸同源“可归属于","o":["心和肝的关系","肺和脾的关系","肝和肾的关系","肺和肾的关系","心和肾的关系"],"a":2,"e":"天干中乙属肝、癸属肾，肝藏血、肾藏精，精血互生互化，故称乙癸同源，亦即精血同源。肺与肾体现为金水相生，心与肾体现为水火既济，肺与脾为土金相生，心与肝为君臣相配，皆无乙癸同源之名，不可混淆"},{"q":"饮在肠间称为","o":["痰饮","悬饮","溢饮","支饮","留饮"],"a":0,"e":"四饮按饮停部位划分，饮停胃肠者称痰饮，故饮在肠间属痰饮。悬饮为饮停胸胁、咳唾引痛；溢饮为饮溢四肢肌肤、身体疼重；支饮为饮停胸膈、咳逆倚息不得卧。留饮指饮邪久留不去，非按部位命名，均非肠间之饮"},{"q":"“痰阻于肺”可见的临床症状是","o":["喘咳咯痰","胸闷心悸","恶心呕吐","半身不遂","眩晕昏冒"],"a":0,"e":"痰为津液代谢失常所生，阻于肺则肺失宣降、气道不利，故见喘咳咯痰、痰多质稠。胸闷心悸为痰饮凌心、阻遏心阳；恶心呕吐为痰浊中阻、胃失和降；半身不遂多为风痰阻络；眩晕昏冒为痰浊上蒙清窍，皆非痰阻于肺之象"},{"q":"阳盛格阴的本质是","o":["虚寒证","实寒证","虚热证","实热证","虚证"],"a":3,"e":"阳盛格阴是邪热极盛、深伏于里，阳气被遏不能外达四肢而格阴于外，本质为实热，外现假寒，即真热假寒。虚寒证、虚热证皆属虚，无格拒之力；实寒证是阴盛格阳的真寒假热，与阳盛格阴恰相反；虚证更非其本质"},{"q":"“阴阳二十五人”的体质分类方法出自","o":["《难经》","《伤寒论》","《金匮要略》","《黄帝内经·素问》","《黄帝内经·灵枢》"],"a":4,"e":"阴阳二十五人的体质分类出自《灵枢·阴阳二十五人》，以阴阳五行结合五音、五色、五形将人分为二十五类。《素问》虽有体质相关论述，但此分类实载于《灵枢》;《难经》《伤寒论》《金匮要略》均无此二十五人划分，故不属之"},{"q":"“血府”是指","o":["心","肝","女子胞","脉","脾"],"a":3,"e":"《素问》称脉者血之府也，脉为血液运行的管道，故血府指脉。心主血脉而藏神，非血之府；肝藏血、脾统血，皆为调控血量之脏；女子胞主月经与胎育，称胞宫，均与血府之名不符"},{"q":"卫外功能不固的脏腑病机定位是","o":["心","肺","脾","肝","肾"],"a":1,"e":"肺主气属卫，肺气宣发将卫气输布体表，卫气司腠理开阖而主卫外，故卫外不固定位于肺，常表现为自汗、易感外邪。脾主运化而主肌肉，肾藏精主纳气，心主血脉，肝主疏泄藏血，虽与正气相关，但不直接主司卫外开阖"},{"q":"大肠的主要生理功能是","o":["受盛","传化糟粕","化物","泌别清浊","通行元气"],"a":1,"e":"大肠接受小肠下传的食物残渣，吸收其中多余水分，形成粪便并排出体外，故主传化糟粕。受盛、化物是小肠的功能，泌别清浊亦属小肠，通行元气为三焦之职，均与大肠的主要生理功能不符"},{"q":"一年季节中，“长夏”的五行归属是","o":["木","火","土","金","水"],"a":2,"e":"五行与季节配属为春木、夏火、长夏土、秋金、冬水，长夏介于夏秋之间、湿气当令，故归属土。木应春，火应夏，金应秋，水应冬，各主其时，与长夏之土判然有别"},{"q":"中医治疗疾病的指导思想是","o":["治病求本","扶正祛邪","调整阴阳","三因制宜","标本缓急"],"a":0,"e":"治病求本是中医治疗疾病的根本指导思想，强调透过现象抓住疾病本质，谨察阴阳所在而调之、以平为期。扶正祛邪、调整阴阳、三因制宜、标本缓急皆为具体治则，从属于治病求本，而非最高层次的指导思想"},{"q":"根据五行学说属于相克关系传变，错误的是","o":["木旺乘土","土旺乘水","水旺乘火","火旺乘金","土不生金"],"a":4,"e":"相乘是相克太过，木乘土、土乘水、水乘火、火乘金皆沿相克链条传变，属相克关系。土不生金是土不资生金，属相生关系中的母不生子，并非相克传变，故为错误项"},{"q":"下列除哪项外，都体现了阴阳的互根关系","o":["阴在内，阳之守也","孤阴不生，独阳不长","阳在外，阴之使也","重阴必阳，重阳必阴","阴损及阳，阳损及阴"],"a":3,"e":"互根指阴阳相互依存、互为根本，阴在内阳之守、孤阴不生独阳不长、阳在外阴之使、阴损及阳阳损及阴皆体现互根。重阴必阳、重阳必阴说的是阴阳在一定条件下向对立面转化，属阴阳转化，不属互根关系"},{"q":"元气生成的主要物质来源是","o":["肾中精气","水谷精气","清气","脏腑精气","经气"],"a":0,"e":"元气根源于肾，由肾中精气所化生，并经三焦布散全身，推动各脏腑功能，故其主要物质来源为肾中精气。水谷精气是后天之气的来源，清气参与宗气生成，脏腑精气、经气皆非元气发生之本"},{"q":"根据五行学说，“肾”的“母”行的属性是","o":["金","木","土","火","水"],"a":0,"e":"五行中生我者为母，肾在五行属水，金能生水，故肾之母行为金，肺金充养肾水即金水相生之理。木、火为水所生或所克，土克水，水为肾本行，皆非肾之母行"},{"q":"根据情志致病理论，可引起二便失禁、遗精滑泄的是","o":["暴怒","忧思","喜乐","恐惧","思虑"],"a":3,"e":"恐则气下，过度恐惧使气机下陷、损伤肾气，肾主封藏而司二便，肾气不固则二便失禁、遗精滑泄。暴怒则气上，多致吐血昏厥；忧思、思虑则气结伤脾；喜乐则气缓、心气涣散，均不出现下焦失固之象"},{"q":"下列除哪项外，都不是暑邪的致病特点","o":["炎上","生风","易夹湿","易伤肺","阻遏气机"],"a":2,"e":"暑为夏季主气，其性炎热升散，易耗气伤津，且夏季多雨，暑常夹湿，故易夹湿确为暑邪致病特点。炎上属火邪，生风多为热极动风，易伤肺是燥邪特征，阻遏气机是湿邪致病特点，皆非暑邪本有"},{"q":"对五时气候、物候运转规律的抽象得出的是","o":["五行相生","五行相克","五行制化","五行相乘","五行相侮"],"a":0,"e":"五行相生揭示木火土金水递相资生的次序，是对五时气候、物候依春夏长夏秋冬有序运转、相互促进规律的抽象。相克、相乘、相侮反映的是克制与异常克制关系，制化是生克结合的自稳机制，均非对五时更替规律的直接概括"},{"q":"行于脉外的气是","o":["元气","宗气","营气","卫气","脏腑之气"],"a":3,"e":"卫气属阳，运行于脉外，布散于体表、肌肉、肓膜之间，主温养、护卫、司开阖。营气行于脉内，与血同行而化生血液；元气根于肾经三焦布散；宗气积于胸中走息道；脏腑之气布于脏腑，均非行于脉外者"},{"q":"主司妇女带下的奇经脉是","o":["阳维脉","阳跷脉","带脉","任脉","督脉"],"a":2,"e":"带脉环绕腰腹一周，约束纵行诸经，主司妇女带下，故有带下之名。阳维脉维系阳经，阳跷脉主下肢运动，任脉总任一身之阴而主胞胎，督脉总督一身之阳，皆不主带下"},{"q":"阴阳互损的病理变化与何脏的关系密切","o":["心","肝","脾","肺","肾"],"a":4,"e":"肾藏元阴元阳，为一身阴阳之根本，阴损及阳、阳损及阴多以肾中阴阳亏虚为枢纽，故阴阳互损与肾关系最密切。心、肝、脾、肺虽各有阴阳，但非元阴元阳所藏之地，不居于阴阳互损的核心"},{"q":"明清时期温病学家吴又可的代表作是","o":["《瘟疫论》","《温热论》","《湿热条辨》","《温病条辨》","《温热经纬》"],"a":0,"e":"吴又可为明末温病学家，著《瘟疫论》，创戾气学说，开温疫辨证之先河。《温热论》为叶天士所著，《湿热条辨》为薛雪，《温病条辨》为吴鞠通，《温热经纬》为王孟英，作者各别"},{"q":"人体生殖能力丧失提示","o":["心气衰竭","肝精衰竭","肺气衰竭","脾精衰竭","肾精衰竭"],"a":4,"e":"肾主藏精，肾中精气盛衰直接决定生殖机能，肾精衰竭则天癸竭、生殖能力丧失。心气衰竭主要影响血脉与神志，肝、脾所藏之精并非生殖之本，肺气衰竭主呼吸，皆不决定生殖能力的存亡"},{"q":"饮食过饱，首先损伤的脏腑是","o":["心","肺","脾胃","肝胆","肾"],"a":2,"e":"胃主受纳、脾主运化，饮食入口先入于胃，过饱则食积胃脘、损伤脾胃运化，故首先伤脾胃。心主血脉，肺主气，肝胆主疏泄，肾藏精，虽可间接受累，但饮食过饱首当其冲者是脾胃"},{"q":"在下肢内侧内踝尖上8寸以下循行其前缘的经脉是","o":["足太阴脾经","足厥阴肝经","足少阴肾经","足少阳胆经","足阳明胃经"],"a":1,"e":"足三阴经在内踝尖上八寸以下，排列依次为厥阴在前、太阴在中、少阴在后，故循行于前缘者为足厥阴肝经，过八寸后太阴交出在前。足太阴脾经在八寸以下居中，足少阴肾经居后；足少阳胆经、足阳明胃经循于外侧，不在内侧前缘"},{"q":"共同参与后天之气生成的是","o":["肺、脾","肺、肝","心、肾","肝、脾","心、肺"],"a":0,"e":"后天之气主要指宗气，由肺吸入的自然清气与脾胃运化的水谷精气在胸中结合而成，故肺、脾共同参与其生成。肝主疏泄、心主血脉、肾藏精虽各司其职，但不直接参与清气与水谷精气的结合以生成后天之气"},{"q":"患者受风后出现汗出、恶风，与风邪的何种特性有关","o":["风性数变","风性善行","风性主动","风性轻扬","风性开泄"],"a":4,"e":"风性开泄，易使腠理疏松开张，营阴外泄则汗出，卫外不固则恶风，故汗出恶风与风性开泄直接相关。风性数变指发病急、变化快，善行指病位游移，主动指振颤抽搐等动象，轻扬指易袭阳位，均不解释汗出恶风"},{"q":"导致虚热证的病理变化是","o":["阳偏衰","阴偏衰","阳偏盛","阴偏盛","阳盛格阴"],"a":1,"e":"阴偏衰即阴虚，阴液不足不能制阳，阳气相对偏亢而生内热，故发为虚热证，常见五心烦热、潮热盗汗。阳偏衰生虚寒证，阳偏盛、阴偏盛分别为实热、实寒，阳盛格阴本质是实热而见假寒，皆非虚热"},{"q":"“阴中求阳”是指","o":["在扶阳剂中适当佐以滋阴药","在滋阴剂中适当佐以扶阳药","在温阳散寒同时佐以扶阳","在清泻阳热同时佐以滋阴","以上皆是"],"a":0,"e":"阴中求阳是张景岳提出的治法，指补阳时在扶阳剂中适当佐以滋阴药，使阳有所化、阳得阴助而生化无穷。在滋阴剂中佐扶阳药为阳中求阴；温阳散寒佐扶阳、清泻阳热佐滋阴均非此义，故不成立"},{"q":"《素问·生气通天论》中“使人薄厥”的病机是","o":["怒则气上","喜则气缓","思则气结","悲则气消","恐则气下"],"a":0,"e":"《素问·生气通天论》载大怒则形气绝、血菀于上，使人薄厥，怒则气上，气血逆乱上冲于脑而发薄厥。喜则气缓、思则气结、悲则气消、恐则气下各有其病机，皆与大怒血菀于上的薄厥无涉"},{"q":"下列各项可用阴阳对立制约解释的是","o":["物极必反","阴损及阳","阳盛伤阴","重阴必阳","阳生阴长"],"a":2,"e":"对立制约指阴阳相互斗争、相互抑制，阳盛则制约阴而伤阴，故阳盛伤阴体现对立制约。阴损及阳体现互根，重阴必阳、物极必反体现转化，阳生阴长体现互根互用，均非对立制约"},{"q":"《丹溪心法·痰》说：“善治痰者，不治痰而治气，气顺则一身之津液，亦随气而顺矣。”其理论依据是","o":["气能生津","气能行津","气能摄津","津能载气","津能养气"],"a":1,"e":"气为津液运行之动力，气行则水行，气滞则水停，故气顺则津液亦随气而顺体现气能行津，治痰先治气即在此基础上使痰随气而化。气能生津指气助津液生成，气能摄津指固摄防流失，津能载气、津能养气是津对气的作用，均非题干所论"},{"q":"“水谷之海，六腑之大源也”是指","o":["胆","胃","大肠","小肠","膀胱"],"a":1,"e":"胃主受纳腐熟水谷，为气血生化之源，故称水谷之海、六腑之大源。胆主藏精汁，大肠传导糟粕，小肠受盛化物，膀胱贮尿排尿，虽皆属六腑，但无水谷之海之称"},{"q":"心为五脏六腑之大主的理论依据是","o":["心主血","心主神志","心主思维","心总统魂魄","心总统意志"],"a":1,"e":"心主神志，为五脏六腑之大主，神明统帅全身脏腑功能，主明则下安。心主血、心主脉是心的血脉功能，总统魂魄、总统意志并非心的规范表述，且皆不足以作为大主的理论依据，唯神志的统帅作用可当之"},{"q":"足厥阴经行于头顶与督脉及足太阳经交于","o":["神庭穴","四神聪穴","百会穴","风府穴","风池穴"],"a":2,"e":"足厥阴肝经上行至巅顶，与督脉、足太阳膀胱经交会于百会穴，故巅顶头痛多责之厥阴肝经。神庭为督脉与足太阳、阳明交会，风府、风池偏于项部，四神聪为经外奇穴，均非厥阴与督脉、太阳之交会处"},{"q":"心血亏虚时会出现","o":["面色红润","面色萎黄","面色无华","面色晦暗","面色红赤"],"a":2,"e":"心主血脉，其华在面，心血不足则面部血脉空虚，故面色无华、苍白。面色红润为气血充盈之常象；面色萎黄多属脾虚血少；面色晦暗多为瘀血或肾虚；面色红赤为热象或阴虚火旺，皆非心血亏虚本色"},{"q":"主要循行于下肢的经脉是","o":["手经","足经","阴经","阳经","手三阴经"],"a":1,"e":"十二经脉中手经循行于上肢，足经循行于下肢，故主要循行于下肢者为足经。阴经、阳经是按阴阳属性划分，手足皆可分阴阳；手三阴经行于上肢内侧，与下肢无涉"},{"q":"肺主治节主要是指肺气具有","o":["宣降体内的津液","与皮毛相合防御外邪","治理调节肺的呼吸和全身之气血津液的机能","促进宗气的形成","将脏腑代谢后的浊液下输于膀胱"],"a":2,"e":"肺主治节指肺气具有治理调节呼吸及全身气血津液运行输布的功能，是肺主气、司呼吸、通调水道等作用的综合概括。宣降津液仅为通调水道一端，合皮毛御邪属肺主卫外，促进宗气生成属参与后天之气，浊液下输膀胱是通调水道的具体表现，皆不足以概括治节全体"},{"q":"中医学认为，构成人体有机整体的中心是","o":["五脏","六腑","脑","命门","经络"],"a":0,"e":"中医学以五脏为中心，通过经络联系六腑、五官九窍、四肢百骸，构成有机整体，故五脏是人体整体的中心。六腑为传化之府，脑、命门虽为重要脏器或生命之门，经络为联系通道，皆非整体中心的定位"},{"q":"认识外感温热邪气的疾病发展规律的病机理论是","o":["六经病机","经络病机","卫气营血病机","脏腑病机","气血津液病机"],"a":2,"e":"卫气营血病机由叶天士创立，用以概括外感温热病由卫分、气分、营分到血分逐步深入的传变规律，揭示温热邪气的病理层次。六经病机主伤寒，经络、脏腑、气血津液病机为一般病机分类，均非专论温热发展规律者"},{"q":"“经络”一词首见于","o":["《黄帝内经》","《难经》","《伤寒论》","《针灸甲乙经》","《脉经》"],"a":0,"e":"经络一词首见于《黄帝内经》,《灵枢》《素问》中多篇论述经脉、络脉，奠定经络学说基础。《难经》《伤寒论》《针灸甲乙经》《脉经》成书均晚于《内经》，虽各有发挥，但非首见之处"},{"q":"行于脉内的气是","o":["元气","宗气","营气","卫气","脏腑之气"],"a":2,"e":"营气属阴，运行于脉中，与血同行，化生血液并营养全身，故行于脉内者为营气。卫气行于脉外；元气根于肾布于三焦；宗气积于胸中；脏腑之气布散于各脏腑，皆非行于脉内者"},{"q":"人们对脏腑的最早的认识来源于","o":["哲学的推论","对人和动物的解剖观察","对人体功能的概括","对生命活动的观察","对疾病防治的总结"],"a":1,"e":"脏腑概念最初源于古人对人体及动物尸体解剖的直观观察，《内经》中已有解剖度量记载，故解剖观察是其最早来源。哲学推论、功能概括、生命观察、疾病防治总结是脏腑理论形成的后世途径，但非最初来源"},{"q":"瘀血所致出血的特点是","o":["出血量多","出血色淡","出血紫黯或有血块","出血量小","血色鲜红"],"a":2,"e":"瘀血阻滞脉道，血不归经而外溢，其出血色紫黯、质稠或有血块，常伴刺痛、痛处固定。出血量多、色鲜红多为热迫血妄行或气虚不摄；出血色淡多为气血亏虚；量小非瘀血出血的定性特征"},{"q":"“寒极生热”主要说明的阴阳关系是","o":["阴阳制约","阴阳对立","阴阳互根","阴阳消长","阴阳转化"],"a":4,"e":"寒极生热指寒到极致在一定条件下转化为热，体现阴阳在一定条件下向对立面转化的关系。阴阳制约、对立强调相互抑制，互根强调相互依存，消长强调量的增减，皆不能解释寒极生热的质变转化"},{"q":"关于下法，下列说法错误的是","o":["邪在半表半里者可下","高龄津枯便秘不宜用峻下法","不可过量或久用，以防正气受损","脾胃虚弱者慎用","妇人行经期、妊娠期慎用"],"a":0,"e":"下法适用于里实热结、燥屎内停等，邪在半表半里当用和法，误用下法徒伤正气，故该说法错误。高龄津枯便秘不宜峻下、不可过量久用防伤正、脾胃虚弱者慎用、经期妊娠慎用，均为下法的正确注意点"},{"q":"属于五行“水”的特性，下列错误的是","o":["寒凉","流动","闭藏","向下","滋润"],"a":1,"e":"五行之水曰润下，其特性概括为寒凉、滋润、向下、闭藏，故寒凉、向下、滋润、闭藏皆属水。流动是水的物理性状，非五行学说归纳的水行特性，常被混淆设错，故为错误项"},{"q":"六淫中引起“行痹”的最主要邪气是","o":["风邪","寒邪","湿邪","暑邪","火邪"],"a":0,"e":"风邪善行而数变，侵袭肢体关节使痹痛游走不定，故行痹以风邪为主，关节疼痛游走。寒邪致痛痹，痛有定处、遇寒加重；湿邪致着痹，重着固定；暑邪、火邪多致热痹，关节红肿热痛，均非行痹之因"},{"q":"“春夏养阳，秋冬养阴”的养生原则源于","o":["顺应自然","养性调神","护肾保精","调摄饮食","体魄锻炼"],"a":0,"e":"春夏养阳、秋冬养阴出自《素问·四气调神大论》，主张依四时阴阳消长调养，春夏顺其生发而养阳，秋冬顺其收藏而养阴，体现顺应自然的养生原则。养性调神、护肾保精、调摄饮食、体魄锻炼均为具体养生方法，不属这一因时养生原则的归属"},{"q":"“用温远温”此属于","o":["因人制宜","因地制宜","因时制宜","既病防变","未病先防"],"a":2,"e":"用温远温指温热季节或温热之时慎用温药，是依时令气候用药的禁忌，属因时制宜。因人制宜依体质年龄性别，因地制宜依地域环境，既病防变、未病先防属治未病范畴，均非用温远温所体现"},{"q":"《素问·五藏生成》说：“多食酸，则（ ）”","o":["骨痛而发落","脉凝泣而变色","筋急而爪枯","肉胝皱而唇揭","皮槁而毛拔"],"a":3,"e":"《素问·五藏生成》载多食酸则肉胝皱而唇揭，酸入肝，过食酸则肝气盛而克脾，脾主肌肉、其华在唇，故肌肉皱缩、口唇掀起。脉凝泣而变色为多食咸，筋急而爪枯为多食辛，皮槁而毛拔为多食苦，骨痛而发落为多食甘，五味所伤各有所主"},{"q":"推拿相应的经络腧穴，可以调节脏腑气血，增强五脏生理功能，以下操作可以增强运化功能的是","o":["推拿内关","推脾经","推肝经","推拿劳宫","推拿神门"],"a":1,"e":"脾主运化，推拿脾经可健运脾胃、促进水谷精微的吸收输布，故能增强运化功能。内关为心包经络穴，宽胸和胃；劳宫清心火；神门宁心安神；肝经主疏泄，均不以增强运化为主要作用"},{"q":"在六淫中，最易伤肺的邪气是","o":["风邪","寒邪","暑邪","湿邪","燥邪"],"a":4,"e":"燥性干涩、易伤津液，肺为娇脏、喜润恶燥，外合皮毛、开窍于鼻，燥邪多从口鼻而入，最易损伤肺津而致干咳少痰。风邪虽常犯肺，多致外感表证；寒邪、暑邪、湿邪各有偏重，唯燥邪以伤肺津为特征"},{"q":"“用寒远寒”是指","o":["阳虚之人，慎用寒凉","阴寒盛的体质，慎用寒凉","西北方天气寒冷，慎用寒凉","秋冬季节寒冷，慎用寒凉","老年人，慎用寒凉"],"a":3,"e":"用寒远寒指寒冷时令慎用寒凉药，秋冬季节寒冷，使用寒凉药当避其时，属因时制宜的用药禁忌。阳虚之人、阴寒体质慎用寒凉属因人制宜，西北方寒冷慎用寒凉属因地制宜，老年慎用寒凉亦属因人，均非用寒远寒本义"},{"q":"下列表述中属于症的是","o":["肺痈","消渴","肝阳上亢","心血亏虚","恶寒"],"a":4,"e":"症指疾病的具体症状和体征，恶寒是自觉怕冷的症状，属症。肺痈、消渴是病名；肝阳上亢、心血亏虚是对病机本质的概括，属证，皆非单纯的症状"},{"q":"下列阳偏衰的病因有","o":["先天不足","后天失养","劳倦内伤","久病伤正","热病后期耗气"],"a":4,"e":"阳偏衰是阳气虚损、机能减退而虚寒内生的病理，热病后期邪热虽退，每因大汗、吐下之后气随津伤而阳气耗损，可形成阳偏衰。先天不足、后天失养多先致气血生化不足，劳倦内伤、久病伤正常先损气阴，与题干所指热病后阳气耗伤的病机取向不同"},{"q":"与内湿形成密切相关的脏腑是","o":["脾","肾","肝","肺","心"],"a":0,"e":"脾主运化水湿，脾虚运化失职则水湿内停，故内湿形成与脾关系最密切，诸湿肿满皆属于脾。肾主水、肺通调水道、肝主疏泄、心主血脉虽参与水液代谢，但内湿生成的中心环节在脾的运化功能"},{"q":"人体生命活动的主宰是","o":["精","神","血","津液","痰"],"a":1,"e":"神是人体生命活动的总称，主宰脏腑经络、气血津液的功能活动，得神者昌、失神者亡，故生命活动的主宰是神。精为生命物质基础，血与津液为营养物质，痰为病理产物，皆不能主宰生命活动"},{"q":"“梅核气”的病机描述最准确的是","o":["肝气郁结","脾虚生痰","痰气凝结","津伤化燥","痰火互结"],"a":2,"e":"梅核气以咽中如有物梗、咯吐不出、吞咽不下为特征，因情志不畅致肝气郁结，气郁生痰，痰气互结于咽喉，故病机为痰气凝结。单纯肝气郁结无痰形；脾虚生痰、津伤化燥、痰火互结皆非梅核气痰气交阻的核心"},{"q":"根据五行学说，木之“所不胜”的“子”是","o":["木","水","金","火","土"],"a":1,"e":"五行中克我者为所不胜，木受金克，故木之所不胜为金；生我者为母、我生者为子，金生水，水为金之子，故木之所不胜之子为水。木为本体，金是木之所不胜而非其子，火、土与金无直接母子关系"},{"q":"下列各项，属于和法以外的是","o":["和解表里","调和肝脾","调和胆胃","调和胃肠","调和气机"],"a":4,"e":"和法是通过和解或调和作用祛除病邪的治法，包括和解表里、调和肝脾、调和胆胃、调和胃肠等，针对半表半里或脏腑失调。调和气机属理气法范畴，并非和法的具体分类，故为和法以外之项"},{"q":"根据五行学说，土壅木郁属于","o":["母病及子","子病及母","相乘传变","相侮传变","母子同病"],"a":3,"e":"相侮即反克，正常为木克土，土壅反侮木而致木郁，是反向克制，属相侮传变。母病及子、子病及母属相生关系传变；相乘是沿相克方向的过度克制，与土壅木郁的反向克制不同；母子同病亦非此列"},{"q":"少阳经病变常作为引经的药物是","o":["防风","柴胡","升麻","独活","川芎"],"a":1,"e":"柴胡归肝胆经，善疏解少阳枢机之邪，为少阳经病的引经与要药，小柴胡汤即以其为君。防风、独活多引太阳经，升麻引阳明经，川芎引厥阴经，各归其经，均非少阳引经之品"},{"q":"中医学理论体系发展最活跃的时期是","o":["先秦","两汉","魏晋隋唐","宋金元","明清"],"a":3,"e":"宋金元时期医家辈出、学派林立，金元四大家各创学说，温补、攻下、滋阴、寒凉争鸣，是中医学理论体系发展最活跃的时期。先秦为奠基，两汉形成体系，魏晋隋唐继承积累，明清趋于综合与温病学派兴起，活跃程度均不及宋金元"},{"q":"据五行学说，下列属于“虚则补其母”治法的是","o":["培土制水","佐金平木","滋水涵木","抑木扶土","泻火补水"],"a":2,"e":"虚则补其母指某脏虚证补其母脏，肾属水为肝木之母，滋水涵木即滋肾阴以养肝阴，属虚则补其母。培土制水是培土以制水泛；佐金平木、抑木扶土属抑强；泻火补水是泻心火滋肾水，用于水火不济，皆非补母之法"},{"q":"属于结石的多发部位，下列错误的那项是","o":["大肠","胃","胆","膀胱","肾"],"a":0,"e":"结石多发生于胆、胃、肾、膀胱等空腔脏器，与胆汁、胃液、尿液等分泌排泄异常有关，故胆、胃、肾、膀胱皆为多发部位。大肠主传导糟粕，内容物为成形粪便，并非结石常见的形成与停留之处"},{"q":"和法，可以消除哪个部位之邪","o":["半表半里","表","里","上","下"],"a":0,"e":"和法以和解少阳为代表，专治邪居半表半里、寒热往来之证，通过和解使半表半里之邪得以祛除。汗法解表，下法攻里，吐法涌上，消法散结，各有定位，皆非和法所主之半表半里"},{"q":"下列关于经络在病理情况下的说法，错误的是","o":["内脏病变反映于五官九窍的途径","内脏病变相互影响的途径","内脏病变反映于体表一定部位的途径","外邪由表入里的途径","运行气血、感应传导的通道"],"a":4,"e":"运行气血、感应传导是经络的生理功能，而非病理情况下的作用，故该项错误。经络在病理上可反映内脏病变于五官九窍及体表、沟通内脏间的相互影响，并成为外邪由表入里的传变途径，均属病理应用"},{"q":"下列各项，属于补法适应证以外的是","o":["脏腑气虚","脏腑血虚","脏腑阴虚","脏腑阳虚","脏腑气滞"],"a":4,"e":"补法适用于气血阴阳诸虚证，脏腑气虚、血虚、阴虚、阳虚皆在其列。脏腑气滞属气机郁滞的实证，治当行气、理气，用补法则壅滞助邪，故为补法适应证以外之项"},{"q":"卫气的分布特点是","o":["上出息道，下走气街","熏于肓膜，散于胸腹","通过三焦，流行全身","上荣头目，达于周身","与血同行，环周不休"],"a":1,"e":"卫气运行于脉外，其分布熏于肓膜、散于胸腹，并布散于肌表、温养脏腑。上出息道、下走气街是宗气的分布；通过三焦流行全身是元气；上荣头目、达于周身偏于清阳之气；与血同行、环周不休是营气，皆非卫气分布"},{"q":"具有“藏而不泻”特点的是","o":["五脏","六腑","脏腑","五脏六腑","以上均非"],"a":0,"e":"五脏主藏精气而不泻，故藏而不泻是五脏的特点，精气充满而不外泄。六腑主传化水谷而不藏，泻而不藏；脏腑、五脏六腑混称及以上均非均不能准确对应藏而不泻的归属"},{"q":"下列属于汗法范畴以外的是","o":["解表","透疹","导滞","祛湿","消肿"],"a":2,"e":"汗法通过开泄腠理、发汗祛邪，涵盖解表、透疹、祛湿、消肿等发散之法。导滞属消法，以消食导滞、通腑除积为能，非发汗解表范畴，故为汗法以外之项"},{"q":"在男子，若元气亏虚，可见到滑精的症状其病机是","o":["气不行精","气不生精","气不摄精","精不化气","精气互化"],"a":2,"e":"气有固摄作用，气能摄精，元气亏虚则固摄无权，精关不固而滑精，故病机为气不摄精。气不行精指推动排精无力，气不生精指精的生成不足，精不化气、精气互化是精与气的转化关系，皆不解释滑精的固摄失司"},{"q":"临床上血虚日久的患者往往兼有气虚，是因为","o":["气能生血","气能行血","气能摄血","血能养气","血能载气"],"a":3,"e":"血为气之母，血能养气，血液充足则气有所附、得以化生，血虚日久则气失所养而随之不足，故血虚患者多兼气虚。气能生血、行血、摄血是气对血的作用；血能载气指气依附于血而行，主要解释气脱，皆非血虚致气虚之由"},{"q":"人的生命活动具有生、长、壮、老的自然规律，在整个生命过程中具有决定性作用的是","o":["肾中精气盛衰","心脏的搏动","脏腑经络功能","气血津液的生成输布","阴阳的动静相召"],"a":0,"e":"肾藏精，肾中精气的盛衰决定人体生、长、壮、老、已的生命历程，《素问》以女七男八述其节律，故起决定性作用的是肾中精气盛衰。心脏搏动、脏腑经络功能、气血津液输布、阴阳动静相召虽为生命活动所必需，但不主导生命周期的阶段演进"},{"q":"男子以肾为先天，以精、气为本，性格多为","o":["内向","喜静","细腻","多愁善感","外向"],"a":4,"e":"男子以肾为先天，以精、气为本，阳气偏盛，性格多外向、主动、刚毅。内向、喜静、细腻、多愁善感多为阴柔之质的表现，常归属于以肝血、阴精为重的体质倾向，非男子之常"},{"q":"皮肤感受邪气常传于","o":["肺","心","肝","脾","肾"],"a":0,"e":"肺主皮毛，皮毛为一身之表，外邪侵袭肌表常由皮毛内传于肺，故皮肤感受邪气常传于肺。心主血脉、肝主疏泄、脾主肌肉、肾藏精各有属表属里之不同，皮毛与肺相合，邪由皮毛内传首归肺系"},{"q":"头痛痛在巅顶，病变多属于","o":["太阳经","阳明经","少阳经","厥阴经","太阴经"],"a":3,"e":"足厥阴肝经循行上达巅顶，与督脉交会于百会，故巅顶头痛多属厥阴经病变。太阳经头痛多在项背，阳明经在前额及眉棱，少阳经在头两侧，太阴经头痛多伴脾虚湿象，部位各有所主"},{"q":"用下列哪种药物可预防菌痢","o":["贯众","板蓝根","大青叶","茵陈","马齿苋"],"a":4,"e":"马齿苋性寒，能清热解毒、凉血止痢，对痢疾杆菌有抑制作用，常用于预防和治疗细菌性痢疾。贯众、板蓝根、大青叶偏于清热解毒利咽，茵陈主清利湿热退黄，均非预防菌痢的专药"},{"q":"阴偏衰所形成的病理变化是","o":["实热","实寒","虚热","虚寒","真寒假热"],"a":2,"e":"阴偏衰即阴虚，阴液不足、制阳无权，阳气相对亢盛而虚热内生，故阴偏衰形成虚热证。实热由阳偏盛所致，实寒由阴偏盛，虚寒由阳偏衰，真寒假热是阴盛格阳，皆非阴偏衰之果"},{"q":"发病的重要条件是","o":["正气不足","邪盛而正未衰","邪气","正气与邪气的斗争","正衰邪盛"],"a":2,"e":"邪气是发病的重要条件，外邪侵袭人体、破坏阴阳平衡而发病，正气存内则邪不可干说明正气不足是内在根据，邪气则是不可缺少的重要条件。正气不足是发病的内在根据，正邪斗争决定是否发病，邪盛正未衰、正衰邪盛是具体的邪正态势，均非重要条件的规范表述"},{"q":"阴阳交感是指","o":["阴阳二气的运动","阴阳二气的和谐状态","阴阳二气相互对立的状态","阴阳二气相互感应","阴阳二气在运动中相互感应而交合的过程"],"a":4,"e":"阴阳交感指阴阳二气在运动中相互感应而交合的过程，是万物生成变化的根源。阴阳二气的运动是前提，和谐状态是交感的结果，相互对立是关系之一，相互感应只是交合的一个环节，皆不足以完整定义交感"},{"q":"我国第一部药物学专著是","o":["《黄帝内经》","《难经》","《伤寒杂病论》","《神农本草经》","《本草纲目》"],"a":3,"e":"《神农本草经》成书于汉代，是我国现存最早的药物学专著，载药三百六十五种，分上中下三品。《黄帝内经》为医学理论奠基之作，《难经》侧重理论与脉诊，《伤寒杂病论》为辨证论治之书，《本草纲目》为明代巨著，成书远晚"},{"q":"五脏病机的基本病理变化是","o":["五脏津液运行的失常","五脏阴阳气血失调","五脏精气运行失调","五脏寒热失调","五脏血液运行失调"],"a":1,"e":"五脏病机的基本病理变化是五脏阴阳气血的失调，阴阳偏盛偏衰、气血亏虚或运行失常皆涵盖其中。津液运行失常、精气运行失调、寒热失调、血液运行失常仅涉及某一侧面，不能概括五脏病机的全体"},{"q":"肾其华在","o":["面","爪","毛","唇","发"],"a":4,"e":"肾其华在发，发为血之余，又赖肾精滋养，故发的荣枯与肾精盛衰相关。心其华在面，肝其华在爪，肺其华在毛，脾其华在唇，五脏之华各有所属"},{"q":"以下均属于造成“津液不足”病机，错误的是","o":["燥热之邪","发热","五志之火","吐泻","伤湿"],"a":4,"e":"津液不足由津液耗伤过多或生成不足所致，燥热之邪、发热、五志之火皆能灼伤津液，吐泻则津液大量丢失，均为常见原因。伤湿是湿邪困阻，湿为阴邪，易阻气机而非耗伤津液，反可致水湿内停，故为错误项"},{"q":"循行于四肢外侧面的经脉是","o":["手经","足经","阴经","阳经","奇经"],"a":3,"e":"十二经脉中阳经循行于四肢外侧，阴经循行于四肢内侧，故循行于四肢外侧面者为阳经。手经、足经是按上下肢划分，四肢皆可有手经足经；阴经行于内侧，奇经不循四肢外侧面为主"},{"q":"心主神志最主要的物质基础是","o":["津液","精液","血液","宗气","营气"],"a":2,"e":"心主神志以血液为最主要的物质基础，血足则神有所养、神志清晰，血者神气也。津液、精液虽可化血，宗气走息道、营气化血，但直接濡养心神、维持神志活动者首推血液"},{"q":"《脉经》的作者是","o":["张仲景","王叔和","皇甫谧","孙思邈","陈无择"],"a":1,"e":"《脉经》为西晋王叔和所撰，是我国现存最早的脉学专著，系统总结脉诊经验。张仲景著《伤寒杂病论》，皇甫谧著《针灸甲乙经》，孙思邈著《千金方》，陈无择著《三因极一病证方论》，各有所著"},{"q":"脾的升清作用的确切内涵是","o":["脾的阳气主升","脾以升为健","脾气散精，上归于肺","与胃的降浊相对而言","输布津液，防止水湿内生"],"a":2,"e":"脾主升清的确切内涵是脾气将水谷精微上输于肺，脾气散精、上归于肺，再由肺宣降布散全身。脾的阳气主升、以升为健是概括性说法，与胃降浊相对是气机升降的总体比较，输布津液防水湿内生侧重运化，均非升清的确切所指"},{"q":"下列五行生克规律的表述，错误的是","o":["木为水之子","火为土之母","水为火之所不胜","木为土之所不胜","金为木之所胜"],"a":4,"e":"所胜指我克者，木克土，故木之所胜为土；金克木，金是木的所不胜。木为水之子、火为土之母、水为火之所不胜、木为土之所不胜均表述正确，唯金为木之所胜颠倒克我关系，故错误"},{"q":"根据五行学说，肝病而致肾病属于","o":["母病及子","子病及母","传其所胜","传其所不胜","相克"],"a":1,"e":"肝属木，肾属水，水生木，肾为肝之母，肝病及肾是子病及母。母病及子是肾病及肝；传其所胜是沿相克方向传变，如肝病传脾；传其所不胜是反向克制传变；相克为一般克制关系，均非肝病及肾的归属"},{"q":"适用“急则治标”治则的是","o":["阴虚咳嗽","持续低热","大出血","慢性胃痛","下肢水肿"],"a":2,"e":"急则治标指标病急重时先治其标，大出血势急，可致气随血脱、危及生命，当先止血以治标。阴虚咳嗽、持续低热、慢性胃痛、下肢水肿多为慢性病，标证不急，当缓则治本或标本兼顾"},{"q":"膀胱的生理功能，依赖哪脏之气与膀胱之气的协调","o":["心气","肾气","肝气","肺气","脾气"],"a":1,"e":"膀胱主贮尿排尿，其气化功能依赖肾气的蒸腾气化，肾气充足则膀胱开阖有度，故膀胱生理功能依赖肾气与膀胱之气的协调。心气、肝气、肺气、脾气虽各有所主，但与膀胱贮排尿液的气化作用无直接协调关系"},{"q":"根据五行学说，金水相生是指","o":["肺肾关系","肺脾关系","肺心关系","肺肝关系","肺胃关系"],"a":0,"e":"肺属金，肾属水，金生水，肺肾之间存在资生关系，故金水相生指肺肾关系，肺阴、肾阴相互资生。肺脾是土金相生，肺心是火克金，肺肝是金克木，肺胃亦属土金相生，均非金水相生"},{"q":"捕捉信息、传递信息的能力所指的经络功能是","o":["运行气血作用","联络沟通作用","感应传导作用","调节平衡作用","指导养生康复"],"a":2,"e":"经络的感应传导作用指其能感应和传递针灸等刺激信息及机体各种信息，即捕捉、传递信息的能力。运行气血是运输作用，联络沟通是联系脏腑组织，调节平衡是协调阴阳，指导养生康复是临床应用，皆非感应传导的定义"},{"q":"金元四大家中倡导“火热论”的是","o":["张元素","刘完素","张从正","朱丹溪","李东垣"],"a":1,"e":"刘完素为金元四大家之一，倡导火热论，认为百病多因火热，主张用寒凉药，世称寒凉派。张元素为易水派，张从正主攻下，朱丹溪倡滋阴降火，李东垣主温补脾胃，各树一帜"},{"q":"十二经脉气血流注形式为","o":["手足贯注","直线贯注","循环贯注","左右贯注","上下贯注"],"a":2,"e":"十二经脉气血流注首尾相贯、如环无端，由肺经起依次传注，周而复始，形成循环贯注的流注形式。手足贯注、左右贯注、上下贯注只是循行中的局部联系，直线贯注不符合经脉循环流注的实际，均非其流注形式"},{"q":"机体在不同年龄阶段会呈现的不同体质特点，这体现了体质的","o":["个体差异性","群体趋同性","相对稳定性","特征连续性","动态可变性"],"a":4,"e":"体质随年龄增长而呈现不同特点，如小儿稚阴稚阳、老年阴阳俱虚，说明体质在生命过程中可发生变化，体现动态可变性。个体差异性指人与人之间体质不同，群体趋同性指人群共性，相对稳定性指体质在一定时期保持恒定，特征连续性非体质基本特征的标准表述"},{"q":"与心相表里的是","o":["胆","胃","大肠","小肠","三焦"],"a":3,"e":"心与小肠通过经脉相互络属，构成表里关系，心经属心络小肠，小肠经属小肠络心。胆与肝相表里，胃与脾相表里，大肠与肺相表里，三焦与心包相表里，皆非心的表里之脏"},{"q":"下利适用于“热结旁流”的治则是","o":["热因热用","寒者热之","热者寒之","通因通用","塞因塞用"],"a":3,"e":"热结旁流是燥屎内结、热迫津液从旁而下，看似下利实则里实，当用泻下通腑，以通治通，即通因通用。热因热用是反治法，用于真寒假热；寒者热之、热者寒之是正治；塞因塞用用于真虚假实，均非热结旁流之治"},{"q":"肺与哪个季节相通应","o":["春","夏","长夏","秋","冬"],"a":3,"e":"肺在五行属金，秋季燥气当令，金气清肃，与肺的清肃之性相合，故肺与秋相通应。春属木应肝，夏属火应心，长夏属土应脾，冬属水应肾，四时与五脏各相匹配"},{"q":"根据五行学说，属“相侮”传变的是","o":["心病及肝","心病及肺","心病及脾","心病及肾","肾病及心"],"a":3,"e":"心属火，肾属水，正常为水克火，心病及肾是火反侮水，属相侮传变。心病及肝是子病及母，心病及肺是火克金的相乘传变，心病及脾是母病及子，肾病及心是水克火的正常相克，均非相侮"},{"q":"五脏阴阳失调病变的根本是","o":["心的阴阳失调","肺的阴阳失调","脾的阴阳失调","肝的阴阳失调","肾的阴阳失调"],"a":4,"e":"肾藏元阴元阳，为一身阴阳之根本，肾中阴阳失调可累及其他五脏，故五脏阴阳失调病变的根本在肾。心、肺、脾、肝的阴阳失调多为局部或继发性病变，虽可相互影响，但不构成五脏阴阳失衡的根本"},{"q":"金元时期，在治疗上主张“滋阴降火”的医家是","o":["张元素","刘完素","张从正","朱丹溪","李东垣"],"a":3,"e":"朱丹溪为金元四大家之一，倡导滋阴降火，认为阳常有余、阴常不足，主张滋阴为主，世称滋阴派。张元素重脏腑辨证，刘完素主寒凉，张从正主攻下，李东垣主温补脾胃，学术主张各异"},{"q":"《素问》：“四变之动，脉与之上下”，所体现的是","o":["恒动观念","辨证论治","形神一体观","整体观念","辨证观念"],"a":3,"e":"四变之动、脉与之上下说明四时气候的变化会使人体脉象相应改变，体现人与自然的统一性，属整体观念中天人一体的内容。恒动观念强调运动变化，辨证论治强调辨证施治，形神一体强调形神统一，均非此经文所体现"},{"q":"感邪后缓慢发病，这种发病形式称之为","o":["复发","继发","合病","并病","徐发"],"a":4,"e":"徐发指感邪后发病缓慢，多因邪气较轻或正气较强，邪正相持，经一段时间才显现症状。复发是愈后再次发作，继发是在原病基础上发生新病，合病是两病同时发生，并病是一病未愈又发他病，均非缓慢发病之意"},{"q":"下列各项，为疾病发生的内在原因是","o":["正气与邪气的斗争","邪盛而正未衰","邪气","正气不足","正衰邪盛"],"a":3,"e":"正气不足是疾病发生的内在根据，正气存内则邪不可干，正气虚则邪气得以入侵。邪气是发病的重要条件，正邪斗争决定是否发病，邪盛正未衰、正衰邪盛是具体的邪正对比状态，皆非内在原因"},{"q":"大肠功能失常可直接影响","o":["肾失气化","肝失疏泄","肺失肃降","脾失健运","脾失升清"],"a":2,"e":"大肠与肺通过经脉相表里，大肠传导糟粕功能失常，腑气不通，可上逆影响肺的肃降，致咳嗽、气喘等。肾失气化、肝失疏泄、脾失健运、脾失升清虽与水液或气机相关，但与大肠传导直接相关者是肺的肃降"},{"q":"同病异治的实质是","o":["证同治异","证异治异","病同治异","证异治同","病同治同"],"a":1,"e":"同病异治指同一种疾病，因证候不同、发病阶段或体质差异而治法不同，实质是证异治异，体现辨证论治。证同治异、病同治异与同病异治相悖；证异治同是异病同治的反向表述；病同治同不符合同病异治之意"},{"q":"根据五行学说，下列符合相克关系的是","o":["木克金","火克土","土克水","水克木","金克火"],"a":2,"e":"五行相克次序为木克土、土克水、水克火、火克金、金克木，故土克水属相克关系。木克金错误，应为金克木；火克土错误，应为火克金；水克木错误，应为水生木；金克火错误，应为火克金，均违背相克规律"},{"q":"心神清明通畅是心哪个生理特性的体现","o":["心气下降","心主血","心藏神","心主通明","心主脉"],"a":3,"e":"心主通明指心气、心阳推动温养，使心神清明、血脉通畅，心神清明通畅正是心主通明的体现。心气下降非心的规范气机特点，心主血、心藏神、心主脉分别强调血液、神志、脉管功能，皆不直接说明清明通畅之性"},{"q":"经络学说在中医学中的应用，错误的是","o":["阐释病理变化","指导临床诊断","指导手术治疗","指导养生","指导保健"],"a":2,"e":"经络学说可阐释病理变化、指导临床诊断、指导养生保健，并广泛用于针灸推拿等治疗。指导手术治疗并非经络学说的应用范畴，手术属现代外科手段，与经络理论无直接对应关系，故为错误项"},{"q":"“阴根于阳，阳根于阴”说明了阴阳之间的何种关系","o":["阴阳交感","阴阳互根","阴阳对立","阴阳消长","阴阳转化"],"a":1,"e":"阴根于阳、阳根于阴说明阴阳双方相互依存、互为存在的根本，属阴阳互根关系。阴阳交感强调交合，对立强调相互制约，消长强调量的变化，转化强调质变，皆非此语本义"},{"q":"饮在胸胁称为","o":["痰饮","悬饮","溢饮","支饮","留饮"],"a":3,"e":"官方答案为【支饮】，但依据教材，正确答案为【悬饮】。四饮以饮停部位命名，饮后水流胁下、咳唾引痛者称悬饮，故饮在胸胁当属悬饮。支饮是饮停胸膈、咳逆倚息短气不得卧，与胸胁部位不符；痰饮停于肠间，溢饮溢于四肢，留饮指饮邪久留，均非胸胁之饮"},{"q":"当人处于安静状态时，血主要归藏于","o":["心","脾","肾","肺","肝"],"a":4,"e":"肝藏血，具有贮藏血液、调节血量的功能，人安静时机体需血减少，余血归于肝，故血主要归藏于肝。心主血脉而行血，脾统血，肾藏精，肺主气，皆无安静时归藏血液之能"},{"q":"具有推动和调控各脏腑、经络、形体和官窍生理活动的气是","o":["元气","宗气","营气","卫气","脏腑之气"],"a":0,"e":"元气根于肾，经三焦布散全身，推动和调控各脏腑、经络、形体、官窍的生理活动，是人体生命活动的原动力。宗气走息道司呼吸，营气化血养全身，卫气主卫外温养，脏腑之气仅布于本脏腑，皆非推动调控全身者"},{"q":"下列除哪项外，均属于结石的致病特点","o":["多发于六腑","阻滞气机，损伤脉络","在体内形成瘕块","病程较长，症状不固定","可发生绞痛"],"a":0,"e":"多发于六腑说的是结石的好发部位，并非致病特点，故为除外项。结石阻滞气机、损伤脉络，久留体内可形成瘕块，病程较长且症状不固定，移动或梗阻时可发生绞痛，这些才是结石的致病特点，部位与致病特点不可混为一谈"},{"q":"五音中属于五行之“木”的是","o":["宫音","角音","商音","徵音","羽音"],"a":1,"e":"五音配五行，角、徵、宫、商、羽分别对应木、火、土、金、水，故属木者为角音。徵音属火，宫音属土，商音属金，羽音属水，五音与五行一一对应，不可错位"},{"q":"据中医治则中标本的划分，下列错误的是","o":["正气为本，邪气为标","症状为本，病机为标","先病为本，后病为标","原发病为本，继发病为标","医生为标，患者为本"],"a":1,"e":"标本划分中正气为本、邪气为标，先病为本、后病为标，原发病为本、继发病为标，医者为标、患者为本亦通，而正确的关系是病机为本、症状为标，故症状为本、病机为标颠倒本末，为错误项"},{"q":"联结心之搏动和肺之呼吸的中心环节是","o":["元气","宗气","心气","肺气","肝气"],"a":1,"e":"宗气积于胸中，上出息道而司呼吸，贯注心脉而行气血，故为联结心之搏动与肺之呼吸的中心环节。元气为生命原动力，心气、肺气各主本脏功能，肝气主疏泄，皆不能同时维系心搏与呼吸的联结"},{"q":"中医治疗疾病的根本原则是","o":["调整阴阳","治病求本","扶正祛邪","调理脏腑","三因制宜"],"a":1,"e":"治病求本是中医治疗疾病的根本原则，强调透过现象抓住疾病的本质，正治反治、扶正祛邪等均由此派生。调整阴阳是针对阴阳失调的具体治法，扶正祛邪针对邪正盛衰，调理脏腑针对脏腑功能失常，三因制宜强调因时因地因人，皆属具体治则而非根本原则"},{"q":"脾在液为","o":["涎","泪","汗","涕","唾"],"a":0,"e":"脾在液为涎，涎为脾脏所化，具有湿润口腔、助益吞咽的作用，脾虚则涎液清稀或多唾。泪为肝之液，由肝血化生，肝虚则目涩少泪；汗为心之液，津液经心阳蒸化外泄为汗；涕为肺之液，肺开窍于鼻；唾为肾之液，肾虚则唾多"},{"q":"提出“阳常有余，阴常不足”的医家是","o":["张元素","刘完素","张从正","朱丹溪","李东垣"],"a":3,"e":"朱丹溪即朱震亨，为金元四大家之一，创滋阴派，主张阳常有余、阴常不足，治宜滋阴降火，代表作为《丹溪心法》。刘完素为寒凉派，主张六气皆从火化；张从正为攻邪派，擅用汗吐下三法；李东垣为补土派，重脾胃升降；张元素为易水派，重视脏腑辨证"},{"q":"“太仓”指的是","o":["三焦","胃","小肠","脾","大肠"],"a":1,"e":"胃主受纳、腐熟水谷，为水谷之海，故称太仓，又称仓廪之官，饮食入胃而后化生精微。三焦为决渎之官，主通行元气与水液；小肠为受盛之官，主受盛化物、泌别清浊；大肠为传导之官，主传导糟粕；脾主运化而非受纳"},{"q":"下列关于邪正斗争决定疾病转归的说法中，错误的是","o":["邪盛正衰则病进","正盛邪衰则病退","正虚邪衰则病危","邪盛而正未衰则病为实证","正衰邪盛，阴阳离决则死亡"],"a":2,"e":"邪正斗争决定病势进退：正盛邪衰则病退，邪盛正衰则病进，邪盛而正未衰则发为实证，正衰邪盛至阴阳离决则死亡。正虚邪衰时邪气已退，仅有正气亏虚，病势趋于好转而非危重，故该说法错误。其余各项均符合邪正盛衰与病势的对应关系"},{"q":"具有“实而不满”特点的是","o":["五脏","六腑","脏腑","奇恒之腑","以上均非"],"a":1,"e":"六腑主受盛和传化水谷，饮食入则充实，传输后即空虚，故实而不满、泻而不藏。五脏主化生和贮藏精气，精气充满而不宜泻，故满而不实；奇恒之腑形态似腑、功能似脏，既非实而不满也非满而不实；脏腑为五脏六腑的总称，不具此单一特点"},{"q":"属于系统病机，下列错误的是","o":["内生五邪病机","外感病机","脏腑病机","经络病机","阴阳病机"],"a":4,"e":"系统病机主要阐述脏腑、经络、外感及内生五邪等具体系统的病变规律，如脏腑病机论五脏六腑功能失调，经络病机论经气运行失常。阴阳病机属基本病机，与邪正盛衰、精气血津液失常并列，揭示一切病变的普遍规律，而非某一系统，故不属于系统病机"},{"q":"明清时期温病学家叶天士的代表作是","o":["《瘟疫论》","《温热论》","《湿热条辨》","《温病条辨》","《温热经纬》"],"a":1,"e":"叶天士为清代温病学家，代表作《温热论》首创卫气营血辨证，提出温邪上受、首先犯肺、逆传心包。吴又可著《瘟疫论》，创戾气学说；薛雪著《湿热条辨》，专论湿热；吴鞠通著《温病条辨》，创三焦辨证；王孟英著《温热经纬》，为温病文献汇编"},{"q":"下列属于《灵枢·营卫生会》老年人“昼不精，夜不瞑”原因错误的是","o":["气血衰","气道涩","营气衰少","心神失养","卫气内伐"],"a":3,"e":"《灵枢·营卫生会》认为老年人昼不精、夜不瞑，源于气血衰、肌肉枯、气道涩，五脏之气相搏，营气衰少而卫气内伐，卫气不得入阴。气血衰、气道涩、营气衰少、卫气内伐均为原文所列原因；心神失养虽可见失眠，但非该篇所论，故为错误项"},{"q":"下列病症宜采用治其标方法的是","o":["脾虚泄泻","阴虚内热","吐血","食积泄泻","气虚感冒"],"a":2,"e":"吐血为急性出血，病势危急，出血不止可致气随血脱，故须急则治标，先止血以安其命，待血止后再图治本。脾虚泄泻、气虚感冒属本虚，宜治本或标本兼顾；阴虚内热宜滋阴清热治本；食积泄泻属实，当消食导滞，非急重脱证"},{"q":"异名手足阴经交接的部位是","o":["腹","足","胸","头","手"],"a":2,"e":"手足阴经在胸中交接：手太阴肺经与足太阴脾经、手少阴心经与足少阴肾经、手厥阴心包经与足厥阴肝经均交于胸。手足阳经交接于头面，如手阳明与足阳明交于鼻旁；阴经与阳经在手足末端交接；头为诸阳之会，腹、足、手均非阴经互交之处"},{"q":"与情志抑郁最为相关的是","o":["髓海空虚","心神不守","肝失疏泄","心神不足","肝气升发太过"],"a":2,"e":"肝主疏泄，调畅气机与情志，疏泄不及则气机郁滞，出现情志抑郁、胸闷太息，故与抑郁最相关。肝气升发太过则烦躁易怒而非抑郁；髓海空虚见健忘耳鸣，属肾精不足；心神不守、心神不足多见心悸失眠，属心神病变"},{"q":"以下哪种说法是错误的","o":["舌为心之苗","汗为心之液","心为血之府","心为神之舍","心其华在面"],"a":2,"e":"脉为血之府，血液运行于脉中，脉道约束血液循行，故血之府当属脉而非心，该说法错误。舌为心之苗、心开窍于舌；汗为心之液；心藏神，为神之舍；心其华在面，面色红润与否可候心血，四项均为心的正确表述"},{"q":"体胖之人，饮食宜","o":["清淡","多食甘润生津之品","多食辛辣燥烈之品","多食碱性食物","多食酸性食物"],"a":0,"e":"体胖之人多痰湿内盛，脾胃运化相对呆滞，饮食宜清淡，少食肥甘厚味，以免助湿生痰。甘润生津之品适于阴虚体瘦者；辛辣燥烈助火伤津且碍胃；碱性、酸性食物非中医饮食宜忌的核心划分，均非胖人所宜"},{"q":"“邪之所凑，其气必虚”，主要是指","o":["邪气是发病的重要条件","邪气伤人，必伤人体的正气","正气不足，邪气易于侵犯人体","正气不足，邪气亢盛","正气虚弱，邪气不足"],"a":2,"e":"邪之所凑，其气必虚强调正气不足是疾病发生的内在根据，正气虚则防御功能减弱，邪气得以乘虚而入。邪气是发病重要条件，但非该句所强调；邪气伤人必伤正气说的是发病后的损耗；正气不足邪气亢盛、正气虚弱邪气不足均未体现乘虚侵袭之意"},{"q":"治疗血虚病证时，常以补气药配合补血药使用，其理论依据是","o":["气能生血","气能行血","气能摄血","血能养气","血能载气"],"a":0,"e":"气能生血指气是血液生成的动力，水谷精微经气化作用化生为血，故血虚时配伍补气药，气旺则血生，即有形之血不能速生，无形之气所当急固。气能行血指气推动血行，气能摄血指气统摄血液不外溢；血能养气、血能载气均为血对气的作用，方向相反"},{"q":"“大怒则形气绝，而血菀于上”的病机是","o":["气不摄血","气机逆乱","血随气脱","血随气逆","气随血脱"],"a":3,"e":"大怒致肝气上逆，气机升发太过，血随气逆上冲于头面，故形气绝而血菀于上，甚则吐血、昏厥。气不摄血为气虚不能统血而出血；血随气脱、气随血脱均为气血大量脱失的危象，与气逆上冲的病机不同；气机逆乱涵盖过宽，未点明血随气上"},{"q":"《灵枢·本神》中提到“肝气虚则恐，实则（ ）”","o":["惊","忧","怒","喜","悲"],"a":2,"e":"《灵枢·本神》载肝气虚则恐，实则怒，愤怒为肝气实、疏泄过亢的情志表现，肝气实则烦躁易怒。惊多因心气不足或突受惊吓；忧为肺志，悲亦属肺；喜为心志，喜乐过度则伤心；悲即忧伤，均非肝实证之情志"},{"q":"阴阳互损最易发生在何脏","o":["心","肝","脾","肺","肾"],"a":4,"e":"肾藏元阴元阳，为一身阴阳之根，肾阴肾阳相互依存，故阴损及阳、阳损及阴的阴阳互损最易发生于肾。心主血脉与神明，肝主疏泄藏血，脾主运化，肺主气司呼吸，虽各有阴阳，但非阴阳互损之根，不如肾典型"},{"q":"明清时期，首创“卫气营血”辨证理论的医家是","o":["吴鞠通","赵献可","叶天士","薛雪","吴又可"],"a":2,"e":"叶天士于清代首创卫气营血辨证，著《温热论》，按卫、气、营、血四个层次辨温病传变。吴鞠通创三焦辨证；薛雪专论湿热；赵献可、张景岳偏于命门学说；吴又可著《瘟疫论》主戾气说，均未创卫气营血辨证"},{"q":"幼儿出现五迟、五软，可能由以下哪个原因导致","o":["外感风寒","禀赋不足","饮食过饱","七情内伤","过逸"],"a":1,"e":"五迟五软为小儿生长发育迟缓，多因先天禀赋不足、肾精亏虚，肾主骨生髓，精亏则骨骼肌肉发育不良。外感风寒为外感病，急性起病；饮食过饱伤脾胃，致积滞；七情内伤在小儿少见；过逸少动非先天发育障碍之因"},{"q":"推动血液运行的基本动力是","o":["心的功能","脾的功能","肝的功能","肺的功能","肾的功能"],"a":0,"e":"心主血脉，心气是推动血液在脉中运行的基本动力，心气充沛则脉搏有力、血行通畅。肺朝百脉、主气，助气推动血行；肝主疏泄，调畅气机以助血行；脾主统血，统摄血液不外溢；肾藏精化血，为生成之源，皆非基本动力"},{"q":"下列哪项不属于肺气宣发的生理作用","o":["排出体内浊气","宣散卫气","将津液输布全身，外达皮毛","将代谢后的津液化为汗液排出体外","使全身的血液会聚于肺"],"a":4,"e":"肺主宣发，向上向外宣散肺气，表现为排出体内浊气、宣散卫气至皮毛、将津液和水谷精微输布全身外达皮毛、代谢后津液化汗排出。使全身血液会聚于肺为肺朝百脉，属肺主气司呼吸与朝百脉之功，方向为向内汇聚，非宣发"},{"q":"亡阳的主要原因是机体内的阳气大量亡失，治宜","o":["滋阴制阳","扶阳消阴","回阳救逆","救阴固脱","阴中求阳"],"a":2,"e":"亡阳为阳气大量亡失，四肢厥逆、脉微欲绝、冷汗淋漓，属危急危象，治宜回阳救逆，急用大剂辛热如附子、干姜，方如四逆汤。滋阴制阳用于阴虚阳亢；扶阳消阴用于阳虚阴盛；救阴固脱用于亡阴；阴中求阳为补阳时佐以滋阴之法"},{"q":"根据五行学说，怒“所胜”的情志是","o":["喜","思","悲","恐","惊"],"a":1,"e":"按五行生克，怒属木，思属土，木克土，土为木之所胜，故怒所胜的情志为思，即肝木之志可制约脾土之志。喜属火，为木所生之子；悲属金，为木之所不胜；恐属水，为木之母，均未体现木克土之所胜"},{"q":"关于“阴阳转化”，下列说法不确切的是","o":["寒极生热，热极生寒","重阴必阳，重阳必阴","物之生从于化，物之极由乎变","阴胜则阳病，阳胜则阴病","动复则静，阳极反阴"],"a":3,"e":"阴阳转化指阴阳在一定条件下向对立面转化，寒极生热、热极生寒、重阴必阳、重阳必阴、物之极由乎变、动复则静阳极反阴均体现物极必反。阴胜则阳病、阳胜则阴病说明阴阳对立制约中一方偏盛则另一方受损，属阴阳消长的病理，并非转化"},{"q":"使津液变成汗、尿是气的","o":["推动","温煦","固摄","气化","中介"],"a":3,"e":"气化指通过气的运动而产生的各种变化，津液在气的推动和固摄下，经气化作用化为汗液、尿液排出体外，是水液代谢的重要环节。推动指激发推动血行与水液运行；固摄指固持血液、津液不外泄；温煦指温养脏腑；中介非气的基本功能"},{"q":"被称为“决渎之官”的是","o":["胆","胃","三焦","小肠","膀胱"],"a":2,"e":"三焦为决渎之官，水道出焉，具有疏通水道、运行水液及通行元气的功能。胆为中精之府、中正之官，主藏排胆汁；胃为仓廪之官，主受纳腐熟；小肠为受盛之官，主泌别清浊；膀胱为州都之官，主贮尿排尿，皆非决渎之官"},{"q":"我国第一部临床学专著是","o":["《黄帝内经》","《难经》","《伤寒杂病论》","《神农本草经》","《医宗金鉴》"],"a":2,"e":"《伤寒杂病论》为张仲景所著，创立辨证论治体系，是我国第一部临床学专著，后分为《伤寒论》与《金匮要略》。《黄帝内经》为我国第一部医学理论经典，奠定理论基础；《难经》补充《内经》；《神农本草经》为第一部药学专著；《医宗金鉴》为清代丛书"},{"q":"七情内伤首先伤及","o":["肝魂","心神","脾意","肺魄","肾志"],"a":1,"e":"心主神志，为五脏六腑之大主，七情内伤首先扰动心神，出现心悸、失眠、神志不宁，而后及于相应脏腑。肝魂、脾意、肺魄、肾志虽分属五脏所藏，但七情致病以心神为先导，心神受损后方可波及其他脏腑"},{"q":"可随气升降，无处不到，或在脏腑经络，或滞留于机体某些部位的是","o":["水饮","湿气","痰","瘀血","败精"],"a":2,"e":"痰为津液代谢失常所生，其中无形之痰可随气机升降出入，无处不到，或停滞脏腑经络，或滞留机体局部，致病广泛、症状多变。饮多停聚于胸膈、肺胃、四肢等局部，流动较小；瘀血为有形之血，停滞不移；败精多郁阻于下焦精室"},{"q":"饮食的消化吸收需要五脏协同完成，特别是","o":["肝、胆","心、小肠","肺、大肠","肾、膀胱","脾、胃"],"a":4,"e":"胃主受纳、腐熟水谷，脾主运化水谷精微，二者一纳一运、一降一升，共同完成饮食的消化吸收，为气血生化之源，故称脾胃为后天之本。肝胆主疏泄、藏血，助脾胃运化但非核心；肺大肠主传导排泄；肾膀胱主水液；均非消化吸收的主导"},{"q":"六淫中引起“着痹”的最主要邪气是","o":["风邪","寒邪","湿邪","热邪","燥邪"],"a":2,"e":"湿性重着黏滞，侵袭肌表经络则气血运行阻滞，肌肉关节沉重酸痛、痛处固定不移，故为着痹之主邪。风邪善行而数变，致行痹，疼痛游走不定；寒邪收引凝滞，致痛痹，疼痛剧烈遇寒加重；热邪致热痹，关节红肿热痛；燥邪伤津，多不致痹"},{"q":"下列哪一项与肝的疏泄功能关系最不密切","o":["情志的舒畅","脾胃的运纳","血液的循行","津液的输布","呼吸运动的正常"],"a":4,"e":"肝主疏泄，调畅气机，进而调畅情志、促进脾胃运纳、推动血液循行与津液输布，皆与疏泄密切相关。呼吸运动主要依赖肺主气司呼吸、肾主纳气及肺气宣降完成，肝疏泄虽可调畅全身气机，但对呼吸并非直接主导，故关系最不密切"},{"q":"提出“先安未受邪之地”防治原则的是","o":["王孟英","叶天士","张仲景","张景岳","张从正"],"a":1,"e":"叶天士在《温热论》中提出务在先安未受邪之地，即在温病传变之前，先顾护可能被邪气传变的脏腑，阻断病势发展，体现既病防变思想。王孟英著《温热经纬》；张仲景著《伤寒杂病论》；张景岳、张从正虽有治验，均未提出此说"},{"q":"胃的生理功能是","o":["受纳熟腐","受盛化物","传导变化","形成尿液","运行津液"],"a":0,"e":"胃主受纳、腐熟水谷，饮食入胃经胃气腐熟化为食糜，下传小肠，故胃又称水谷之海、太仓。受盛化物为小肠之功，小肠受盛胃中食糜并泌别清浊；传导变化属大肠，传导糟粕形成粪便；形成尿液属肾与膀胱；运行津液属三焦"},{"q":"营气的作用主要是","o":["润泽肌肤","化生血液","温煦内脏","充养脑髓","化生神志"],"a":1,"e":"营气为水谷精微中精纯柔和部分，行于脉中，具有化生血液和营养全身的作用，营气与津液入脉化血，故营气充则血液足。润泽肌肤为津液与卫气之功；温煦内脏属卫气；充养脑髓属肾精；化生神志属心主神明，均非营气主职"},{"q":"内伤病因中易导致郁证、癫、狂、消渴、瘿病的是","o":["过劳","过逸","饮食不节","七情内伤","饮食偏嗜"],"a":3,"e":"七情内伤直接影响脏腑气机，气机郁滞日久可致郁证，痰气互结于咽喉成梅核气，痰迷心窍则癫狂，气郁化火伤津则消渴，气郁痰凝于颈则瘿病。过劳多耗气血，过逸致气血不畅、痰瘀，饮食不节或偏嗜主要伤脾胃，均非此类情志病之主因"},{"q":"津液亏虚可以导致气的衰少，其主要原因是","o":["气能生津","气能行津","气能摄津","津能载气","津能生气"],"a":4,"e":"津能生气指津液是化生气的物质基础之一，水谷精微所化之津液充足则气有所生，津液亏虚则气的化生不足而气衰。气能生津、气能行津、气能摄津均为气对津液的作用，方向相反；津能载气指津液为气之载体，津脱则气脱，侧重气的丢失而非生成"},{"q":"以下哪项属于六腑","o":["肝","心","脾","三焦","脑"],"a":3,"e":"六腑为胆、胃、小肠、大肠、膀胱、三焦，共主受盛和传化水谷，以通为用、以降为顺，泻而不藏。肝、心、脾属五脏，主化生和贮藏精气，满而不实；脑为奇恒之腑，形态似腑而功能似脏，均不属六腑"},{"q":"与调节情志有密切关系的脏是","o":["心","脾","肝","肾","肺"],"a":2,"e":"肝主疏泄，调畅全身气机与情志活动，肝气调达则气血和调、心情舒畅，故为调节情志之主脏。心主神明，为情志活动的主宰而非调节；脾主运化与思，肺主气与忧悲，肾主藏精与恐，虽各主一志，但疏泄调畅情志以肝为要"},{"q":"古人对黄河中下游流域的气候变化及其与物候变化之间的相互联系的自然规律进行总结，抽象生化而形成的是","o":["阴阳学说","精气学说","元气说","五行学说","水地说"],"a":3,"e":"五行学说源于古人对黄河中下游流域气候与物候变化规律的观察，将木火土金水与春夏季长冬、生长化收藏相对应，抽象概括出事物间的生克关系。阴阳学说概括对立统一；精气学说探讨世界本原；元气说、水地说均为古代哲学的本原论，非由物候变化规律概括而成"},{"q":"下列脏腑中具有喜润恶燥特点是","o":["肺","脾","心","肝","肾"],"a":0,"e":"肺为娇脏，喜润恶燥，肺主气司呼吸、外合皮毛，燥邪最易伤肺津，致干咳少痰、咽干鼻燥，故肺喜润。脾喜燥恶湿，湿邪最易困脾；心主血脉与神明；肝主疏泄而藏血；肾主水而藏精，均无喜润恶燥之特性"},{"q":"灌注于骨节、脏腑、脑髓的是","o":["精","气","血","津","液"],"a":4,"e":"津与液同为水谷精微所化，津清稀、流动性大，布散于肌肤、孔窍、血脉；液稠厚、流动性小，灌注于骨节、脏腑、脑髓等深层组织，起濡养润滑作用。精为生命物质基础；气为推动温煦之力；血行于脉中，均非灌注骨节脑髓者"},{"q":"魄门是指","o":["肛门","飞门","户门","吸门","贲门"],"a":0,"e":"魄门即肛门，为消化道末端，主管排泻糟粕，五脏六腑皆赖其排泄废物，故称魄门亦为五脏使。飞门为口唇，户门为牙齿，吸门为会厌，贲门为胃之上口，四处均属七冲门中的其他部位，并非魄门所指之处"},{"q":"五脏主五志，则忧属","o":["心","肾","肝","肺","脾"],"a":3,"e":"五脏主五志，肺在志为忧，悲亦属肺，忧伤过度则耗伤肺气，肺主气司呼吸的功能受损，故忧归属于肺。心在志为喜，喜乐过度则伤心；肝在志为怒，怒则伤肝；脾在志为思，思虑过度伤脾；肾在志为恐，恐则伤肾，均非忧之所属"},{"q":"《灵枢·天年》提到二十岁的运动特征为","o":["好趋","好走","好步","好坐","好卧"],"a":0,"e":"《灵枢·天年》描述人生十岁为一阶段，二十岁血气始盛、肌肉方长，动作敏捷故好趋。三十岁血气充盈，肌肉坚固，故好步；四十岁气血渐衰，好坐；五十岁肝叶始薄，好卧；好走非该篇对二十岁的典型描述"},{"q":"《老子·二十五章》所说：“人法地，地法天，天法道，道法自然。”此段文字体现的思维方式是","o":["整体宏观","天人合一","天人同气","天人同构","天人同律"],"a":1,"e":"人法地、地法天、天法道、道法自然，强调人取法于天地，人与天地自然遵循同一法则而相互统一，体现天人合一的整体思维。天人同气侧重人与天地共享精气；天人同构、同律强调形质与规律相应，整体宏观为更宽泛的思维特征，均非该段主旨"},{"q":"与水湿痰饮形成关系密切的是","o":["心、肺、脾功能障碍","肺、脾、肝功能障碍","脾、肝、肾功能障碍","肺、脾、肾功能障碍","心、脾、肾功能障碍"],"a":3,"e":"水湿痰饮的生成与肺通调水道、脾运化水湿、肾主水气化密切相关：肺失宣降则水道不通，脾失运化则水湿内停，肾失气化则水液泛溢，三脏功能障碍是水湿痰饮内生的关键。心主血脉，肝主疏泄，虽可调气助水行，但非水液代谢的核心脏腑"},{"q":"感受寒邪而致“伤寒”的机理是","o":["寒邪伤于肌腠","寒邪入侵脏腑","寒邪自内而生","寒邪直中脏腑","寒邪侵及血分"],"a":0,"e":"伤寒指寒邪侵袭肌表，伤于肌腠卫阳，卫阳被遏、营阴郁滞，见恶寒发热、头身疼痛、无汗脉紧，属外感表证。寒邪入侵脏腑、直中脏腑发为中寒，病在里而不在表；寒邪自内而生属内寒，由阳虚所致；寒邪侵及血分非伤寒初起之机理"},{"q":"气与血的关系主要表现在","o":["来源与分布方面","生化与运行方面","功能与结构方面","先天与后天方面","调节与统摄方面"],"a":1,"e":"气与血的关系可概括为气为血之帅、血为气之母：气能生血、行血、摄血，血能养气、载气，主要体现于血的生化与运行方面。来源与分布、功能与结构、先天与后天、调节与统摄均非对气血关系的经典概括"},{"q":"根据五行学说，五行相侮的基本概念是","o":["某行之气亢盛传及母脏","某行之气亢盛传及子脏","某行之气虚衰传及“所胜”","某行之气亢盛侵及“所不胜”","某行之气亢盛传及“所胜”"],"a":3,"e":"相侮即反克，指五行中某一行过于强盛，反过头来克制原本克制自己的所不胜一行，如肝火犯肺即木火刑金。某行之气亢盛传及所胜为相乘而非相侮；某行之气虚衰传及所胜亦属相乘范畴；亢盛传及母脏、子脏则为母病及子或子病及母"},{"q":"具有生殖功能和繁衍生命的精微物质是","o":["水谷之精","广义之精","气","生殖之精","脏腑之精"],"a":3,"e":"生殖之精为先天之精，藏于肾，具有生殖能力、繁衍生命的作用，是生命产生的物质基础。水谷之精为后天脾胃化生，主营养；广义之精泛指构成人体和维持生命活动的一切精微物质；气为活力物质；脏腑之精为各脏腑功能活动的物质基础"},{"q":"“阴在内，阳之守也；阳在外，阴之使也”，说明了","o":["阴阳的相互对立","阴阳的相互消长","阴阳的相互转化","阴阳的互根互用","阴阳的相互制约"],"a":3,"e":"阴在内为阳之守，阳在外为阴之使，说明阴为阳的物质基础、阳为阴的功能表现，阴阳双方相互依存、互为根本并相互为用，即互根互用。相互对立强调阴阳属性相反；相互消长强调量的增减变化；相互转化强调物极必反；相互制约强调相互抑制，均非此句主旨"},{"q":"精血津液的生成及其相互转化依靠气的","o":["推动作用","温煦作用","防御作用","固摄作用","气化作用"],"a":4,"e":"气化指气的运动所产生的各种变化，精、血、津液的生成及其相互转化，如精化血、津化血、津液化汗尿，皆赖气化作用完成。推动作用指激发脏腑功能与推动血行；温煦作用指产生热量温暖机体；防御作用指护卫抗邪；固摄作用指统摄血液津液不外泄"},{"q":"下列何项属反治治则","o":["塞因塞用","实则泻之","虚则补之","损益兼用","寒者热之"],"a":0,"e":"反治指顺从疾病假象而治，塞因塞用即以补益药治疗具有闭塞不通假象的虚证，如气虚便秘用补气药、血虚经闭用养血药，适用于至虚有盛候。实则泻之、虚则补之、寒者热之皆逆其证象而治，属正治；损益兼用为扶正祛邪的具体运用"},{"q":"据五行学说，心火亢盛致肺阴不足属于","o":["金克火","火侮金","火克金","金生火","火乘金"],"a":4,"e":"心火与肺金本为相克关系，即火克金，属正常制约；心火亢盛过度克制肺金，致肺阴不足，属五行相乘中的火乘金。金克火为反克，不存在；火侮金为相侮，指金反克火，与病势相反；金生火为相生，与克伐无关"},{"q":"下列各项，与肾中精气生理功能关系不密切的是","o":["促进机体的生长发育","促进水液代谢","促进生殖功能的成熟","主生长发育和生殖","人体生命活动的根本"],"a":4,"e":"肾中精气的生理功能主要体现为促进机体生长发育、促进生殖功能成熟、主生长发育和生殖、推动和调节水液代谢等具体作用。人体生命活动的根本是对肾作为先天之本的整体地位概括，而非肾中精气某一具体生理功能，与题干所问的具体功能关系不密切"},{"q":"脾统血的主要作用机理是","o":["控制血液的流速","控制内脏的血液容量","控制外周血液容量","控制血液在脉道内的运行","控制血液上荣头目"],"a":3,"e":"脾统血指脾气具有统摄、控制血液在脉道内正常运行而不溢出脉外的生理功能，脾气充足则血有所统。控制血液流速、控制内脏或外周血液容量均非脾统血的确切内涵；控制血液上荣头目属心主血脉、肝升发，与脾统血无关"},{"q":"“痰阻于心”可见的临床症状是","o":["喘咳咯痰","胸闷心悸","恶心呕吐","半身不遂","眩晕昏冒"],"a":1,"e":"痰浊阻于心，心阳被遏、心脉不畅，故见胸闷、心悸，甚则神志异常。喘咳咯痰为痰饮阻肺、肺失宣降；恶心呕吐为痰饮停胃、胃气上逆；半身不遂为痰瘀阻络、中风；眩晕昏冒为痰浊蒙蔽清阳，均非痰阻于心之主症"},{"q":"精、气、血、津、液是构成人体和维持人体的物质基础，其中属于阳的是","o":["精","气","血","津","液"],"a":1,"e":"精、血、津、液皆为有形有质的液态或固态物质，性偏阴，主濡养滋润；气为无形而运行不息的精微物质，具有推动、温煦等作用，性偏阳，故其中属阳者为气。精、血、津、液均属阴，与气的阳动之性相对"},{"q":"根据五行学说，“泻南补北法”的理论基础是","o":["五行相生","五行相克","五行制化","五行胜复","五行相侮"],"a":1,"e":"泻南补北法即泻心火、补肾水，用于心火亢盛、肾水不足的心肾不交证。南属火归心，北属水归肾，水本克火，补肾泻心是调整水火相克关系，故理论基础为五行相克。相生为资生助长；制化讲生克协调；胜复为报复性调节；相侮为反克，均非其直接依据"},{"q":"梅核气为痰气结于","o":["心","咽喉","肠胃","肺","皮肤"],"a":1,"e":"梅核气为痰气郁结于咽喉，患者自觉咽中如有物梗塞，咯之不出、咽之不下，但不碍饮食，多因情志不畅、肝气郁结、痰气互结所致。结于心则胸闷心悸；结于肠胃则脘痞呕恶；结于肺则喘咳咯痰；结于皮肤则见瘰疬痰核，均非梅核气病位"},{"q":"虚实病机中“实”的内涵是","o":["正气充实","邪气亢盛","邪盛正衰","正胜邪却","正气有余"],"a":1,"e":"虚实病机中，实指邪气亢盛，正气未虚，邪正相争剧烈，临床表现为亢奋、有余的实证。正气充实、正气有余属正气充足，非实的含义；邪盛正衰为正虚邪实之象；正胜邪却为病退向愈，均非实的确切内涵"},{"q":"用下列哪种药可以预防细菌病","o":["贯众","板蓝根","大青叶","茵陈","马齿苋"],"a":4,"e":"马齿苋性寒味酸，功能清热解毒、凉血止痢，对痢疾杆菌等肠道致病菌有抑制作用，故可用于预防细菌性痢疾等细菌性疾病。板蓝根、大青叶偏于清热解毒、凉血利咽，多用于温毒发斑、大头瘟疫；贯众偏于杀虫清热解毒；茵陈为利湿退黄要药，均非预防细菌病之首选"},{"q":"促进机体生殖机能成熟的物质是","o":["气血","元气","肾气","天癸","肾精"],"a":3,"e":"天癸是肾中精气充盈到一定程度产生的精微物质，能促进生殖器官发育成熟并维持生殖机能，女子二七、男子二八天癸至而有子。气血为营养与推动之基；元气为生命原动力；肾气为肾的功能之气，范围较广；肾精为物质基础，均非直接促进生殖成熟者"},{"q":"根据五行学说，肝病而致肺病属于","o":["母病及子","相乘","子病及母","相侮","相克"],"a":3,"e":"肝属木，肺属金，金本克木；肝病而致肺病，是木反过头来克制金，属五行相侮，即木火刑金、肝火犯肺。母病及子为母脏病传子脏；子病及母为子脏病传母脏；相乘为过度克制所胜，肝木所胜为脾土，非肺；相克为正常制约，均不合"},{"q":"统摄感觉功能的是","o":["脾意","肾志","心神","肺魄","肝魂"],"a":2,"e":"心主神明，统摄人的精神、意识、思维及感觉功能，目之视、耳之听等感觉皆赖心神主导，故统摄感觉功能者为心神。脾意、肾志、肺魄、肝魂虽各有所主，如肺魄主本能感觉动作、肝魂主谋虑，但均在心神统摄之下，不能独立统摄全部感觉"},{"q":"下列关于五脏所藏的叙述，错误的是","o":["心藏神","肝藏魂","肺藏魄","脾藏意","肾藏智"],"a":4,"e":"五脏所藏为心藏神、肝藏魂、肺藏魄、脾藏意、肾藏志，故肾藏智的说法错误。心藏神为主宰精神活动；肝藏魂随神往来；肺藏魄并精出入；脾藏意主思维记忆；肾藏志主意志与记忆，五脏所藏之中并无肾藏智之论"},{"q":"小儿发育迟缓，骨骼不坚的主要病机是","o":["肾精亏虚","肾阴不足","肾阳亏虚","脾气虚弱","肝血不足"],"a":0,"e":"肾主骨生髓，肾精充足则骨髓生化有源、骨骼坚固，小儿肾精亏虚则骨髓空虚，发育迟缓、骨骼不坚、囟门迟闭。肾阴不足主潮热盗汗等虚热；肾阳亏虚主畏寒肢冷；脾气虚弱主运化失常、肌肉消瘦；肝血不足主筋脉失养、爪甲不荣，均非骨骼不坚之主因"},{"q":"劳力过度主要伤及","o":["气","血","精","神","津液"],"a":0,"e":"劳力过度，形体劳倦，耗伤气血，尤以气伤为著，故有劳则气耗之说，症见少气懒言、神疲乏力。血伤多见于失血或久病入络；精伤多因房劳过度、肾精亏耗；神伤多因七情内伤、劳心过度；津液伤多因大汗、吐泻或热盛，均非劳力过度之主要所伤"},{"q":"阴阳的征兆是","o":["寒热","上下","水火","晦明","动静"],"a":2,"e":"阴阳的征兆以水火最具代表性，水性寒凉、润下、沉静属阴，火性温热、炎上、躁动属阳，故以水火为阴阳之征兆。寒热为阴阳的属性之一；上下、晦明、动静皆为阴阳的具体表现或划分依据，但作为象征性征兆，以水火最为典型"},{"q":"经络系统中，与脏腑有直接络属关系者为","o":["经脉","络脉","十五别络","十二经脉","奇经八脉"],"a":3,"e":"十二经脉又称正经，与脏腑有直接的络属关系，阴经属脏络腑、阳经属腑络脏，构成脏腑经络联系的主体。经脉为运行气血通道的总称，范围过大；络脉为经脉分支，无直接络属；十五别络加强表里经联系；奇经八脉不直属脏腑，无络属关系"},{"q":"六淫中引起“痛痹”的最主要邪气是","o":["风邪","热邪","湿邪","寒邪","燥邪"],"a":3,"e":"寒性凝滞收引，侵袭经络则气血运行不畅、不通则痛，疼痛剧烈且遇寒加重、得温减轻，故为痛痹之主邪。风邪致行痹，疼痛游走；湿邪致着痹，重着固定；热邪致热痹，红肿热痛；燥邪伤津，多不致痹痛"},{"q":"少腹疼痛，痛经闭经，经血紫色成块，或见崩漏，为瘀血阻于","o":["肝","三焦","胃肠","冲任","胞宫"],"a":4,"e":"瘀血阻滞胞宫，冲任受损，气血运行不畅，故见少腹疼痛、痛经闭经，经血紫暗成块，瘀血阻络、血不归经则崩漏。瘀阻于肝则胁痛；阻于三焦则气化不利；阻于胃肠则脘腹刺痛、便血；冲任虽与月经密切相关，但为气血运行之络道，瘀血停滞、经血成块病位在胞宫"},{"q":"亡血家不可发汗，其理论依据是","o":["血可化津","津能生血","津能载气","气能摄血","血能载气"],"a":0,"e":"亡血家不可发汗，因血与津液同源互化，血可化津，大量失血者血虚则津液亦亏，若再发汗则津液外泄，津血更伤，甚则气随津脱，故禁用汗法。津能生血指津液化生血液；津能载气指津为气之载体；气能摄血指气统摄血液；血能载气指血为气之载体，均未切中津血同源之理"},{"q":"下列属于提高正气，增强抗病能力具体措施，错误的是","o":["早期诊断","药物预防及人工免疫","锻炼身体","生活起居有规律","调摄精神"],"a":0,"e":"提高正气、增强抗病能力的措施包括调摄精神、锻炼身体、生活起居有规律、药物预防及人工免疫等，旨在扶正固本。早期诊断、早期治疗属于既病防变，是疾病已发生后的防治措施，并非提高正气、增强抗病能力之法，故为错误项"},{"q":"机体阳气的不足与下列哪两个脏的关系最密切","o":["心与肾","肺与脾","脾与肾","肝与脾","心与脾"],"a":2,"e":"阳气不足与脾肾关系最密切：肾阳为一身阳气之根，脾阳赖肾阳温煦，脾主运化水谷精微以充养阳气，脾肾阳虚则畏寒肢冷、完谷不化。心与肾重在心肾相交、水火既济；肺与脾主气与水谷；肝与脾主疏泄与运化；心与脾主血与神，均非阳气不足之核心"},{"q":"血和津液生成的共同物质来源是","o":["水谷精微","宗气","精","元气","营气"],"a":0,"e":"血和津液均由脾胃运化的水谷精微所化生，水谷精微入脉，经气化作用化为血液，其津液部分布散为津液，故二者来源相同。宗气为清气与水谷之气结合而成；精为生命物质基础；元气为先天之精所化；营气为水谷精微之精专部分，仅化血之一环"},{"q":"肺被称为水上之源的原因是","o":["宣发水谷精微至头面","宣发卫气于皮毛腠理","肃降宗气至脐下以资元气","呼出体内浊气","肃降水液，通调水道"],"a":4,"e":"肺主肃降，通调水道，将津液向下输布至肾与膀胱，促进水液下行排泄，故称肺为水之上源。宣发水谷精微至头面、宣发卫气于皮毛均为宣发之功，非上源之称的依据；肃降宗气至脐下资元气为肺主气的一部分；呼出浊气属宣发，均非通调水道"},{"q":"长期过度安逸，养尊处优，四体不勤，多易形成","o":["阴虚体质","痰瘀体质","阳虚体质","痰湿体质","气郁体质"],"a":1,"e":"长期过度安逸、养尊处优、四体不勤，则气血运行迟缓，脾胃功能呆滞，水湿不化聚而为痰，血行不畅留而为瘀，日久形成痰瘀体质，或见形体肥胖、肢体困重。阴虚体质因阴液亏少；阳虚体质因阳气不足；痰湿体质偏于水湿凝聚，瘀象不显；气郁体质因情志不畅，均非过逸之典型结果"},{"q":"目的视觉功能主要取决于","o":["肾中精气的充盈","肝血的充足","脾气的健运","肾阳的蒸化","肾阴的滋养"],"a":1,"e":"肝开窍于目，肝藏血，目之视觉功能赖肝血濡养，肝血充足则视物清晰、目润灵活，肝血不足则视物昏花、干涩夜盲。肾中精气充盈主要影响目之精气与瞳神；脾气健运为气血生化之源，属间接作用；肾阳蒸化、肾阴滋养均通过肾精，非视觉之直接所主"},{"q":"扶正祛邪兼用的基本原则是","o":["先扶正后祛邪","先祛邪后扶正","扶正为主，兼以祛邪","扶正不留邪，祛邪不伤正","祛邪为主，兼以扶正"],"a":3,"e":"扶正祛邪兼用适用于正虚邪实、扶正恐留邪、祛邪恐伤正的病证，其基本原则是扶正不留邪、祛邪不伤正，使扶正有助于祛邪、祛邪不损正气。先扶正后祛邪、先祛邪后扶正属先后分用，非兼用；扶正为主兼祛邪、祛邪为主兼扶正虽有主次，但未点明不留邪、不伤正的核心原则"},{"q":"属于既病防变方法，下列错误的是","o":["人工免疫","早期诊断","早期治疗","先安未受邪之地","阻截病传途径"],"a":0,"e":"既病防变指在疾病已发生后早期诊断、早期治疗，先安未受邪之地，阻截病传途径，防止病邪传变。人工免疫通过接种预防疫病，属未病先防的范畴，是在疾病未发生时提高抗病能力的措施，不属于既病防变，故为错误项"},{"q":"禀赋强弱的决定因素是","o":["天时地理","后天补充","父母体质","母体孕期调养","家族遗传疾病"],"a":2,"e":"禀赋强弱主要取决于父母体质，父母精气充盛则子女先天禀赋足，体质强健，因肾精源于父母，先天之精决定禀赋。天时地理影响后天环境；后天补充、母体孕期调养虽能影响胎儿发育，但非决定因素；家族遗传疾病为特定病种，不等于禀赋强弱"},{"q":"下列病证宜采用“通因通用”治法的是","o":["脾虚泄泻","肾虚便秘","伤风汗出","心虚多汗","肾虚尿频"],"a":2,"e":"通因通用即以通治通，用具有通利作用的药物治疗具有通泄症状的实证。伤风汗出因风邪客表、营卫不和，用辛温解表药发汗祛邪，邪去则汗止，属以发汗治汗出的通因通用。脾虚泄泻、肾虚便秘、心虚多汗、肾虚尿频均属虚证，当用补益固涩，属塞因塞用或虚则补之"},{"q":"主要表现为血液的生成和运行关系的两脏是","o":["肺、肾","肺、肝","心、肾","心、脾","心、肺"],"a":3,"e":"心主血脉，推动血液运行；脾主统血，统摄血液于脉中，且为气血生化之源，血液的生成与运行与心脾关系最密切。肺主气、朝百脉，助气行血；肾藏精化血；肝藏血调血量；虽参与血液生成运行，但生成之源在脾、运行之主在心，肺肝肾非最主要"},{"q":"属于阳的事物或现象是","o":["下降","静止","涩脉","洪脉","面色晦暗"],"a":3,"e":"阴阳属性划分中，洪脉脉体宽大、充实有力、来盛去衰，具有推动、亢进之象，故属阳。下降主沉降、静止主宁静，皆属阴；涩脉往来艰涩不畅，血行呆滞，属阴；面色晦暗沉暗无华，亦属阴，三者均非阳象"},{"q":"饮在肌肤称为","o":["痰饮","悬饮","溢饮","支饮","留饮"],"a":2,"e":"饮邪流溢于四肢肌肤，见肢体浮肿、沉重疼痛、无汗，称为溢饮，因水饮泛溢肌表所致。痰饮为饮停胃肠，见脘腹痞满、肠鸣沥沥；悬饮为饮停胸胁，见胸胁胀痛、咳唾引痛；支饮为饮停胸膈，见咳逆倚息、短气不得卧；留饮为饮邪久留不去，均非饮在肌肤"},{"q":"“形盛则神旺，形衰则神疲，形谢则神灭”说明","o":["形神是相辅相成，密不可分的","形神是对立的","形神可以转化","形神是运动的","形神是相对的"],"a":0,"e":"形为神之物质基础，神为形之功能表现，形盛则神旺、形衰则神疲、形谢则神灭，说明形与神相互依存、不可分离，即形神合一、相辅相成。形神对立、转化、运动、相对等说法均未切中形神相互为用、密不可分的核心关系"},{"q":"下列各项，既属病因，又属病理产物的是","o":["寒邪","热邪","燥邪","瘀血","七情"],"a":3,"e":"瘀血既是疾病过程中形成的病理产物，如气虚、气滞、血热、血寒致血液运行不畅或溢出脉外而成，又可反过来阻滞气机、阻塞血脉，成为新的致病因素，故既属病因又属病理产物。寒邪、热邪、燥邪、七情均为原始致病因素，非病理产物"},{"q":"六淫中可致“首如裹”的邪气是","o":["风邪","湿邪","寒邪","燥邪","热邪"],"a":1,"e":"湿性重浊，湿邪袭表则清阳不升、头面困重，故见头重如裹，并伴肢体困重、苔腻。风邪善行，多致头痛游走或咽痒；寒邪收引，致头痛遇寒加重；燥邪伤津，致头面干燥；热邪上炎，致头痛头晕、面红目赤，均非首如裹之因"},{"q":"七情内伤可影响脏腑气机，其中恐则","o":["气上","气下","气缓","气结","气消"],"a":1,"e":"七情影响脏腑气机，恐为肾志，恐则气下，致气机下陷，见二便失禁、遗精、骨痿等，即恐伤肾。怒则气上，肝气上逆；喜则气缓，心气涣散；思则气结，脾气郁结；悲则气消，肺气耗伤，均非恐之气机变化"},{"q":"金之“母”的“所胜”是","o":["木","水","金","火","土"],"a":1,"e":"按五行相生相克推求，金之母为土，因土生金；土之所胜为水，因土克水，故金之母的所胜为水。木为金之所胜，即金克木；金为本体自身；火为金之所不胜，即火克金；土为金之母，均非金之母的所胜"},{"q":"下列属于调理脏腑治则以外的是","o":["用寒远寒，用热远热","实则泻腑，虚则补脏","脏病治腑","虚则补其母，实则泻其子","腑病治脏"],"a":0,"e":"调理脏腑治则包括实则泻腑、虚则补脏、脏病治腑、腑病治脏及虚则补其母、实则泻其子等，围绕脏腑虚实与生克关系调治。用寒远寒、用热远热属因时制宜，即根据季节气候慎用寒热药，非调理脏腑之法，故为错误项"},{"q":"下列哪项是引起阳偏胜盛的机理","o":["阳邪入侵，内合人身之阳","气郁化火","五志化火，耗伤阴血","感受阴邪，从阳化热","血瘀、食积化热化火"],"a":2,"e":"阳偏胜即阳盛，指阳气亢奋、热量过剩的实热状态。五志过极化火，火热内盛而耗伤阴血，阴不制阳则阳气更亢，故五志化火耗伤阴血可致阳偏胜。阳邪入侵、气郁化火、阴邪从阳化热、血瘀食积化热虽亦能生热，但多为外感或郁积化热之途，与情志化火耗阴致阳亢的机理侧重不同"},{"q":"根据经络的循行分布路线和联系范围来取穴，称为","o":["表里配穴","阴阳取穴","循经取穴","前后配穴","整体取穴"],"a":2,"e":"循经取穴依据经络的循行分布路线和联系范围选取穴位，即经脉所过、主治所及，如头面病取手阳明经穴。表里配穴取相表里的经穴相配；阴阳取穴按阴阳经配伍；前后配穴取胸腹与背腰部穴相配；整体取穴强调全身调整，均非依循行路线取穴"},{"q":"汗法用于透疹时，一般选用具有透疹功能的","o":["益气解表药","燥湿健脾药","苦寒沉降药","辛热解表药","辛凉解表药"],"a":4,"e":"汗法用于透疹，旨在辛散透达、疏风清热，使疹毒外透，故多选辛凉解表药，如薄荷、蝉蜕、牛蒡子，代表方如银翘散。益气解表药用于气虚外感；燥湿健脾药用于湿证；苦寒沉降药主清热泻下，与透疹升散相反；辛热解表药用于风寒表证，助热伤津，均非透疹所宜"},{"q":"大怒主要影响机体的","o":["呼吸功能","疏泄功能","藏精功能","气化功能","运化功能"],"a":1,"e":"大怒为肝之志，暴怒伤肝，使肝气升发太过、疏泄失职，气机逆乱，血随气逆，甚则昏厥，故主要影响疏泄功能。呼吸功能由肺肾主司；藏精功能属肾；气化功能属肾与三焦；运化功能属脾，均非大怒直接所伤"},{"q":"明清时期，提出“温邪上受，首先犯肺，逆传心包”的医家是","o":["吴鞠通","赵献可","叶天士","薛雪","吴又可"],"a":2,"e":"温邪上受、首先犯肺、逆传心包出自叶天士《温热论》，是卫气营血辨证对温病初起传变的概括，说明温邪从口鼻而入，先犯肺卫，不入气分而直入营血则逆传心包。吴鞠通创三焦辨证；薛雪论湿热；吴又可主戾气说；赵献可倡命门说，均非此论提出者"},{"q":"“重阴必阳”说明了阴阳之间的何种关系","o":["阴阳交感","阴阳互根","阴阳对立","阴阳消长","阴阳转化"],"a":4,"e":"重阴必阳指阴气盛极则向阳转化，与重阳必阴同理，说明阴阳在一定条件下可向其对立面转化，属阴阳转化。阴阳交感指阴阳相互交合；互根指相互依存；对立指属性相反；消长指量的增减，均未体现物极必反的转化之义"},{"q":"五脏分阴阳，其中属于阳中之阳的是","o":["肝","心","脾","肺","肾"],"a":1,"e":"五脏分阴阳，心肺居上属阳，肝脾肾居下属阴；心属阳中之阳，因心主血脉、主神明，具有温煦、推动、升发之性；肺属阳中之阴，主肃降、宣发，性偏沉降。肝为阴中之阳，脾为阴中之至阴，肾为阴中之阴，均非阳中之阳"},{"q":"情志活动与五脏相关，其中起着主导作用的是","o":["肝","心","脾","肺","肾"],"a":1,"e":"心主神明，为五脏六腑之大主，精神意识思维活动皆由心主导，故情志活动中心起主导作用。肝主疏泄调畅情志，是调节情志之脏，但非主导；脾主思、肺主忧悲、肾主恐，各主一志，均受心神统摄，不能主导全部情志活动"},{"q":"两经或三经同时发病，这种情况是","o":["循经传","越经传","并病","直中","合病"],"a":4,"e":"合病指两经或三经同时发病，如太阳与阳明合病，邪气同时侵袭多经。并病为一经病证未罢又出现另一经病证，有先后次第；循经传按十二经次序相传；越经传跳过一经相传；直中为病邪直入三阴脏腑，不经三阳，均非同时发病"},{"q":"症见胸闷呕恶，脘腹痞满，头身困重，口腻不渴，腹泻便溏等，其病机最可能是","o":["湿浊困阻","肝郁脾虚","阳不化气","暑热内蕴","湿热下注"],"a":0,"e":"胸闷呕恶、脘腹痞满、头身困重、口腻不渴、腹泻便溏，皆因湿性重浊黏滞，困阻中焦脾胃，气机升降失常，故病机为湿浊困阻。肝郁脾虚见胸胁胀痛、情志抑郁、便溏；阳不化气见水肿、小便不利；暑热内蕴见发热烦渴；湿热下注见黄疸、淋浊、带下，均非此证"},{"q":"金元四大家中“攻邪派”的代表人物是","o":["张元素","刘完素","张从正","朱丹溪","李东垣"],"a":2,"e":"张从正为金元四大家之一，创攻邪派，主张邪去则正安，擅用汗、吐、下三法攻逐邪气，著有《儒门事亲》。刘完素为寒凉派，主六气从火化；朱丹溪为滋阴派，主阳有余阴不足；李东垣为补土派，重脾胃；张元素为易水派，重脏腑辨证"},{"q":"“阴平阳秘，精神乃治”属于","o":["志健康的标志","生理健康的标","心理健康的标志","理想体质的标志","体质评价的标志"],"a":3,"e":"阴平阳秘、精神乃治出自《素问·生气通天论》，指阴气平和、阳气固密，阴阳协调平衡，则精神充足、身体健康，被视为理想体质的标志。生理健康、心理健康仅为健康的一个方面；志健康、体质评价表述不完整或不确切，均非该句的经典归属"},{"q":"影响宗气盛衰的脏腑是","o":["心与肺","肝与肾","肺与肾","肺与脾","肝与脾"],"a":3,"e":"宗气由肺吸入的清气与脾胃运化的水谷之气结合而成，积于胸中，走息道以行呼吸、贯心脉以行气血，故其盛衰取决于肺的呼吸与脾的运化。心主血脉、肝主疏泄、肾主纳气虽与气机相关，但不直接参与宗气的生成；肺与肾、肝与脾均未切中清气与水谷之气结合之源"},{"q":"清气与水谷之气结合，称为","o":["元气","宗气","营气","卫气","中气"],"a":1,"e":"宗气由肺吸入的自然界清气与脾胃化生的水谷之气相结合而成，聚集于胸中膻中，故又称大气。元气由肾中先天之精所化，赖后天水谷滋养；营气为水谷精微之精专部分，行于脉中；卫气为水谷精微之慓悍部分，行于脉外；中气为中焦脾胃之气，均非清气与水谷之气结合"},{"q":"根据五行学说，火不暖土实际是指","o":["心阳不温脾土","肝阳不温脾土","肾阳不温脾土","肺阳不温脾土","脾阳自身不足"],"a":2,"e":"火不暖土指肾阳即命门之火不足，不能温煦脾土，致脾阳虚衰、运化失职，见五更泄泻、完谷不化、腰腹冷痛，即脾肾阳虚。心阳、肝阳、肺阳不温脾土均非五行火土关系的常规所指；脾阳自身不足为脾阳虚，不涉及命门火衰，均非火不暖土之本义"},{"q":"可用阴阳对立制约解释的是","o":["寒极生热","阴损及阳","寒者热之","重阴必阳","阴中求阳"],"a":2,"e":"阴阳对立制约指阴阳双方相互抑制、相互约束，寒者热之即用温热药治疗寒证，以阳热制约阴寒，体现阴阳制约关系。寒极生热、重阴必阳体现阴阳转化；阴损及阳体现互根；阴中求阳为补阳时佐以滋阴之法，体现互根互用，均非对立制约"},{"q":"《灵枢·本神》中提到“心气虚则悲”，病机是因为","o":["心藏神","心为君主之官","心在志为喜","心主血","心主脉"],"a":2,"e":"《灵枢·本神》称心气虚则悲，实则笑不休，因心在志为喜，喜为心之志，心的虚实变化反映于喜悲：心气不足则悲，心气有余则喜笑不休。心藏神为心的功能概述；心为君主之官言其地位；心主血、心主脉言其血脉功能，均未直接说明喜悲情志的归属"},{"q":"在肾的闭藏功能中，最具有生理意义的是","o":["纳气归肾，促进元气的生成","固摄二便，防止二便失禁","固摄水液，防止水液无故流失","固摄精气，防止精气无故散失","摄纳阳气，防止阳气浮越于上"],"a":3,"e":"肾主闭藏，其中最具有生理意义的是固摄精气，防止精气无故流失，使肾精充盈，进而化生天癸、主生殖与生长发育。纳气归肾助肺吸气；固摄二便、固摄水液、摄纳阳气虽皆属肾的固摄作用，但精气为生命之本，固摄精气是闭藏功能中最核心者"},{"q":"精、气、神的综合表现是","o":["思维","生命","呼吸","运动","睡眠"],"a":1,"e":"精、气、神为人身三宝，精能化气、气能生神，三者相互化生、共同体现于生命活动之中，故精气神的综合表现是生命。思维与睡眠属神的活动，呼吸属气的作用，运动属形与气的功能，均只反映某一方面，不能概括精气神的综合表现"},{"q":"调神必须以下列哪项为首务","o":["健脑","补脾","养心","调肝","益肾"],"a":2,"e":"心主神明，为精神意识思维活动的主宰，神志活动以心为统领，故调神必须养心为首务，养心安神则神志清明。健脑、调肝、益肾虽有助于神，但分别针对髓海、疏泄、先天之本；补脾益气为气血生化之源，均非调神的首要之举"},{"q":"产生“薄厥”的病因，多是","o":["悲伤","过喜","大怒","惊恐","思虑"],"a":2,"e":"薄厥指因大怒而致气血上逆、郁于头部，出现突然昏厥、面红目赤等，即血菀于上，源于大怒伤肝、肝气上逆、血随气逆。悲伤致气消；过喜致气缓、喜伤心；惊恐致气下或气乱；思虑致气结，均非薄厥之病因"},{"q":"与心火不能下滋于肾的病变相关的是","o":["心主通明","心主血脉","心气下降","心主藏神","心为生之本"],"a":2,"e":"心位于上属火，肾位于下属水，正常情况下心火即心气应下降以温肾水，肾水应上济以滋心火，形成水火既济。若心气不降、心火不能下滋于肾，则心肾不交，见心烦失眠、腰膝酸软。心主通明、心主血脉、心主藏神、心为生之本均为心的生理功能或地位，与心火下交肾水无直接对应"},{"q":"盛夏时节，患者伤暑后症见气短乏力，口渴欲饮，合理的病机解释是","o":["暑热炽盛","扰及心神","耗气伤津","暑湿夹杂","热极生风"],"a":2,"e":"暑为阳邪，其性炎热升散，盛夏伤暑，热迫津外泄则多汗，汗出过多则津液耗伤，气随津泄则气短乏力，口渴欲饮为津伤之象，故病机为耗气伤津。暑热炽盛但未见明显伤津耗气；扰及心神见心烦神昏；暑湿夹杂见身重苔腻；热极生风见抽搐，均非本题主症"},{"q":"全身气机调畅最重要的环节是","o":["肺主呼气，肾主纳气","心火下降，肾水上升","肝气主升，肺气主降","脾气主升，胃气主降","肺气宣发，亦主肃降"],"a":2,"e":"肝主疏泄，调畅气机，肝气升发；肺主气司呼吸，肺气肃降，一升一降是全身气机调畅最重要的环节，故有肝升肺降为气机之枢纽的说法。肺主呼气肾主纳气为呼吸运动；心火下降肾水上升为水火既济；脾气主升胃气主降为脾胃升降；肺气宣发肃降为肺自身气机，均非全身气机之总枢纽"},{"q":"下列阴和阳的概念中，最确切的是","o":["阴和阳是中国古代的两点论","阴和阳即是矛盾","阴和阳代表对立的事物","阴和阳代表对立又相互关联的事物属性","阴和阳说明相互关联着的事件"],"a":3,"e":"阴阳是对自然界相互关联的某些事物或现象对立双方属性的概括，既相互对立又相互关联，且多指属性而非具体事物本身。阴阳是中国古代两点论、即是矛盾、代表对立的事物、说明相互关联着的事件等表述，或失之宽泛，或将阴阳等同于具体事物或矛盾，均未准确揭示其属性概括的本质"},{"q":"“泌别清浊”属于","o":["胃的功能","小肠的功能","三焦的功能","膀胱的功能","胆的功能"],"a":1,"e":"小肠主受盛化物、泌别清浊，将水谷精微与水谷残渣分开，精微由脾转输全身，糟粕下传大肠，水液渗入膀胱。胃主受纳腐熟，三焦为决渎之官主气化水道，膀胱贮尿排尿，胆贮藏排泄胆汁，均不承担分清别浊之职"},{"q":"中医病因学将病因分为四类，其中一类为其他致病因素。下列病因属于其他致病因素的是","o":["寒邪","暑邪","寄生虫","瘀血","燥邪"],"a":2,"e":"中医病因四分法将病因分为外感、内伤、病理产物及其他致病因素，寄生虫、外伤、药邪、医过等归入其他类。寒邪、暑邪、燥邪属六淫外感病因；瘀血是疾病过程中形成的病理产物性病因，并非外来其他因素"},{"q":"属于中医学基本特点的是","o":["同病异治","异病同治","审因论治","辨证论治","标本同治"],"a":3,"e":"中医学基本特点为整体观念与辨证论治，辨证论治是认识疾病和治疗疾病的基本原则，强调辨证与论治相结合。同病异治、异病同治是辨证论治的具体运用体现；审因论治、标本同治属治疗原则，不属学科基本特点层面的概括"},{"q":"根据五行学说，面见赤色，脉见洪象的病证是","o":["肝病","心病","脾病","肺病","肾病"],"a":1,"e":"五行中赤色、洪脉均属火，心在五行属火，故面见赤色、脉见洪象定位在心病。肝病见青色弦脉，脾病见黄色缓脉，肺病见白色浮脉，肾病见黑色沉脉，各以其色脉归属相应五脏，切忌混淆"},{"q":"新感外邪较盛所易出现的发病形式是","o":["并病","继发","顿发","复发","徐发"],"a":2,"e":"顿发指疾病发病急骤、病情较重，多因新感外邪盛或疠气入侵，正气骤然抗邪所致。并病为一经病未愈又见另一经病；继发是原发病基础上另发新病；复发是愈后重新发作；徐发起病缓慢，均非新邪壅盛之发病形式"},{"q":"六腑的共性病机特点是","o":["藏精功能失常","通降功能失常","受纳功能失常","藏泄功能失常","气化功能失常"],"a":1,"e":"六腑以传化水谷为职，生理上强调通降下行，故其病机共性为通降失常、腑气不通，如胃气上逆、肠腑秘结。藏精功能失常属五脏病机；受纳仅为胃的功能；藏泄失常见肝；气化失常多责肾与三焦，皆非六腑整体共性"},{"q":"脘腹重坠、便意频数、久泻久利、肛门重坠的病机定位是","o":["心","肺","脾","肝","肾"],"a":2,"e":"上述表现属中气下陷（脾气虚陷），脾主升清，脾气虚弱则升举无力，致脘腹重坠、久泻脱肛、肛门下坠。心主血脉、肺主气司呼吸、肝主疏泄、肾主纳气与主水，均不主升清举陷，故病位不在这些脏"},{"q":"五脏生理功能的特点是","o":["传化物而不藏，实而不能满","藏精气而不泻，实而不能满","传化物而不藏，满而不能实","藏精气而不泻，满而不能实","虚实交替，泻而不藏"],"a":3,"e":"《素问·五脏别论》载五脏“藏精气而不泻也，故满而不能实”，即五脏贮藏精气，精气宜充满而不宜壅实。六腑则“传化物而不藏，实而不能满”。A项把五脏错写成传化物；B项“实而不能满”实为六腑特点，二者易被对调设错"},{"q":"属于治未病的内容，以下错误的那项是","o":["调摄精神","加强锻炼","审因论治","人工免疫","起居有常"],"a":2,"e":"治未病含未病先防与既病防变，调摄精神、加强锻炼、起居有常、人工免疫均属未病先防的具体措施。审因论治是针对已病之证辨析病因确立治则的诊疗原则，不属于预防养生范畴，故为错误项"},{"q":"下列选项中，不属于气机失调的是","o":["气滞","气逆","气陷","气闭","气虚"],"a":4,"e":"气机失调指气的升降出入运动失常，包括气滞、气逆、气陷、气闭、气脱等。气虚是气的总量不足、功能减退，属气的数量与功能病变，并非运行形式失常；气滞为郁滞不通，气逆为上升太过，气陷为升举无力，气闭为闭塞不通，均属气机失调"},{"q":"《素问·疏五过论》所说“尝贵后贱”可致“脱营”病，体现的是","o":["人体自身的完整性","自然环境对人体生理的影响","社会环境对人体生理的影响","自然环境对人体病理的影响","社会环境对人体病理的影响"],"a":4,"e":"“尝贵后贱”指社会地位、生活环境的剧烈变化，因社会因素致病，且已形成“脱营”病变，故体现社会环境对人体病理的影响。B、D项属自然环境的生理或病理作用；A项指人体自身整体性，均未涉及社会地位变迁这一病因"},{"q":"主运化水液的脏是","o":["心","肾","肺","脾","肝"],"a":3,"e":"脾主运化，包括运化水谷与运化水液，将水液上输于肺、布散全身，为胃行其津液。肾主水液依赖气化，肺主行水通调水道，心主血脉，肝主疏泄，虽与水液代谢有关，但“主运化水液”专指脾的职能"},{"q":"根据五行学说，治疗肝肾阴亏，肝阳上亢之证，应选用的是","o":["滋水涵木法","益火补土法","培土制水法","泻南补北法","金水相生法"],"a":0,"e":"肾属水、肝属木，水能生木，肾阴为肝阴之源。肝肾阴亏、肝阳上亢系水不涵木，治宜滋肾阴以养肝阴，即滋水涵木法。益火补土是温肾阳以补脾阳；培土制水是健脾以制水湿；泻南补北为泻心火补肾水；金水相生是肺肾同补"},{"q":"明清时期，提出“阳非有余”、“真阴不足”的医学家是","o":["张介宾","赵献可","叶天士","薛雪","吴又可"],"a":0,"e":"张介宾（张景岳）为明代医家，著《景岳全书》，倡“阳非有余”“真阴不足”之说，主张温补命门、填补真阴。赵献可亦重命门但主“命门火衰”；叶天士为清代温病学家，创卫气营血辨证；薛雪论湿热；吴又可著《温疫论》倡戾气说"},{"q":"按照“穿着衣服必须不失四时之节”的原则，早春宜","o":["减裤不减衣","减衣不减裤","减衣减裤","加衣加裤","加衣减裤"],"a":1,"e":"“穿着不失四时之节”要求依季节增减衣被，早春阳气初升而寒气未尽，下体尤须保暖，故宜减衣不减裤，即“春捂”重在护下。减衣减裤易使寒邪侵及下焦；加衣加裤违逆春生之气；单纯加衣减裤或减裤不减衣均不合早春护阳原则"},{"q":"劳力过度，易损伤的脏腑是","o":["脾、肺","心、脾","心、肺","心、肝","肝、脾"],"a":0,"e":"劳力过度则耗气，脾为气血生化之源、肺主一身之气，故体劳过度最先损伤脾肺之气，见少气懒言、神疲乏力、食少便溏。心脾多因思虑劳神所伤；心肺常见劳神或外邪；肝肾多为房劳、七情所伤，均非劳力过度之主要靶脏"},{"q":"由于心主宰整个人体的生命活动，故称心为","o":["相傅之官","将军之官","君主之官","受盛之官","传道之官"],"a":2,"e":"《素问·灵兰秘典论》以官职喻脏腑，心主神明、主宰生命活动，故称“君主之官”。相傅之官指肺，辅佐心主治节；将军之官指肝，主谋虑；受盛之官指小肠；传道之官指大肠，各有所指，不可张冠李戴"},{"q":"具有化生和贮藏精气特点的是","o":["五脏","六腑","脏腑","五脏六腑","奇经八脉"],"a":0,"e":"五脏的共同生理特点是化生和贮藏精气，“藏精气而不泻，故满而不能实”。六腑则是受盛和传化水谷，“传化物而不藏，实而不能满”。脏腑为五脏六腑总称；奇经八脉属经络系统，均不具化生贮藏精气之共性"},{"q":"五脏分阴阳，其中属于阴中之至阴的是","o":["肝","心","脾","肺","肾"],"a":2,"e":"五脏分阴阳，心为阳中之阳，肺为阳中之阴，肝为阴中之阳，肾为阴中之阴，脾为阴中之至阴。脾属土，主运化而居中央，喜燥恶湿，故以“至阴”名之；若误把肾、肝认作至阴，即混淆了阴阳属性划分"},{"q":"肝火上炎和肝阳上亢均可见到的症状是","o":["胸胁刺痛","急躁易怒","两目干涩","肢体麻木","腰膝酸软"],"a":1,"e":"肝火上炎与肝阳上亢皆因肝的气火偏亢、疏泄失常，故均见急躁易怒、头目胀痛、面红目赤等肝旺表现。两目干涩多属肝阴虚或肝血不足；肢体麻木为肝血亏虚筋脉失养；腰膝酸软是肝肾阴虚；胸胁刺痛责之肝郁血瘀，均非二者共有"},{"q":"《难经经释》说：“邪扶生气而来，虽进而易退”，是指","o":["母病及子","子病犯母","相乘传变","相侮传变","表里传变"],"a":0,"e":"母病及子指邪气由母脏传及子脏，如肾水母病传肝木，因子脏得母气相扶，故病虽进亦易退，此即“邪扶生气而来”之意。子病犯母为子脏病反传母脏，其势较逆；相乘、相侮是相克异常；表里传变是表里经相传，均与此描述不符"},{"q":"具有“阳脉之海”之称的经脉是","o":["阳维脉","阳跷脉","阴跷脉","阴维脉","督脉"],"a":4,"e":"督脉行于腰背正中，总督一身之阳经，故称“阳脉之海”。阳维脉维系诸阳经，主一身之表；阳跷脉主司下肢运动与眼睑开合；阴跷、阴维分主阴经维系，均无“阳脉之海”之称"},{"q":"“至虚有盛候”指的是","o":["真虚假实证","真实假虚证","真寒假热证","真热假寒证","虚实转化证"],"a":0,"e":"“至虚有盛候”指本质为虚证，却表现出类似实证的假象，属真虚假实证，如脾虚腹胀、气虚便秘，治当补虚。真实假虚证是“大实有羸状”；真寒假热、真热假寒属寒热格拒；虚实转化是证候动态演变，均非此语所指"},{"q":"明清时期，首创三焦辨证理论的医家是","o":["吴又可","赵献可","叶天士","薛雪","吴鞠通"],"a":4,"e":"清代吴鞠通著《温病条辨》，首创三焦辨证，将温病分上、中、下三焦论治。叶天士创卫气营血辨证；吴又可著《温疫论》主戾气说；赵献可、薛雪分别以命门学说、湿热论著称，均非三焦辨证创始者"},{"q":"明确提出“三因学说”的医学家是","o":["王叔和","皇甫谧","孙思邈","巢元方","陈言"],"a":4,"e":"宋代陈言（陈无择）在《三因极一病证方论》中明确提出三因学说，将病因分为内因、外因、不内外因。王叔和编次《伤寒论》、皇甫谧著《针灸甲乙经》、孙思邈著《千金方》、巢元方撰《诸病源候论》，均非三因学说提出者"},{"q":"六淫邪气中，具有伤津而不耗气致病特征的是","o":["风邪","火邪","暑邪","燥邪","湿邪"],"a":3,"e":"燥邪干涩，易伤津液，其致病以津伤为主，一般不伴明显耗气，故见口鼻干燥、干咳少痰。暑邪致病常挟湿且耗气伤津；火（热）邪既伤津又耗气动血；风邪轻扬开泄；湿邪重浊黏滞、阻气，均非单纯伤津不耗气"},{"q":"从经脉分出的最大络脉分支是","o":["经别","络穴","孙络","浮络","别络"],"a":4,"e":"别络是从经脉分出、较大的络脉，共有十五条（十二经别络加任、督及脾之大络），主沟通表里两经。孙络是最细小的络脉，浮络是浮行于浅表的络脉；经别是经脉的别行分支；络穴是穴位而非脉，均非最大络脉分支"},{"q":"“肾为气之根”主要是指","o":["肾阳","肾为先天之本","肾藏精","肾主纳气","肾主水液"],"a":3,"e":"肾主纳气，能摄纳肺吸入的清气，使气归于下焦，故称“肾为气之根”，与肺主呼气共同维持呼吸深度。肾阳为诸阳之本；肾为先天之本言其藏精；肾藏精主生殖发育；肾主水液司气化，均不直接解释“气之根”"},{"q":"气化功能失常而出现小便异常的病机定位是","o":["大肠","小肠","膀胱","胃","胆"],"a":2,"e":"膀胱为州都之官，主贮尿排尿，其气化功能失常则见尿频、尿急、癃闭、遗尿等小便异常。小肠泌别清浊，大肠主传导糟粕，胃主受纳腐熟，胆贮藏胆汁，皆非直接主司小便贮排之腑"},{"q":"二便与五脏密切相关，关系最为密切的是","o":["肝","心","脾","肺","肾"],"a":4,"e":"肾主水、司气化，又主封藏，开窍于二阴，大便秘结或泄泻、小便癃闭或失禁皆与肾的气化、阴阳盛衰密切相关。脾主运化影响大便，肺与大肠相表里，肝主疏泄调气机，心主血脉，然二便总司仍以肾为最密切"},{"q":"称为“罢极之本”的脏是","o":["心","肝","脾","肾","肺"],"a":1,"e":"《素问·六节藏象论》称肝为“罢极之本”，因肝主筋、藏血，筋脉运动依赖肝血濡养，肝血充足则耐受疲劳。心为生之本、肺为气之本、肾为封藏之本、脾为仓廪之本，均非“罢极之本”，不可混淆五脏的藏象称谓"},{"q":"以下属于奇恒之腑的是","o":["胆","胃","三焦","小肠","大肠"],"a":0,"e":"奇恒之腑包括脑、髓、骨、脉、胆、女子胞，其形态似腑而功能似脏，胆内藏胆汁（精气）而不直接传化水谷，故属奇恒之腑。胃、三焦、小肠、大肠皆为空腔器官，主受盛传导水谷，属六腑而非奇恒之腑"},{"q":"膻中又称作","o":["气海","血海","髓海","水谷之海","经脉之海"],"a":0,"e":"膻中为心包络，位于胸中，宗气聚集于此，故称“气海”，又称“上气海”。血海指冲脉或肝所藏之血；髓海为脑；水谷之海指胃；经脉之海指冲脉，均非膻中之别名"},{"q":"根据五行学说，下列属“相侮”传变的是","o":["火传木","火传金","火传土","火传水","水传火"],"a":3,"e":"相侮即反克，指五行中“所胜”一行反过头来欺侮“所不胜”一行，火本克水，火反传水即火侮水，属相侮传变。火传木是子病犯母（相生逆传）；火传金、火传土、水传火皆非火被水克之反向，需注意区别相克与反克"},{"q":"观察“虚里”变化，以了解其盛衰的是","o":["元气","宗气","营气","卫气","脏腑之气"],"a":1,"e":"虚里位于左乳下，为胃之大络、宗气所聚之处，触诊虚里的搏动可了解宗气的盛衰及心脏功能。元气根于肾，营气、卫气运行于脉内外，脏腑之气分属各脏，均不聚集于虚里，故观察虚里专候宗气"},{"q":"足三阴经的走向是","o":["从胸走手","从手走头","从头走足","从足走腹胸","从足走手"],"a":3,"e":"十二经脉循行走向规律为：手三阴从胸走手，手三阳从手走头，足三阳从头走足，足三阴从足走腹胸。故足三阴经（脾、肝、肾经）自足部上行至腹胸部；从足走手、从胸走手等均不符合三阴三阳的循行规律"},{"q":"水精四布，五经并行是指肺哪两个功能的协调","o":["肺朝百脉和主治节","肺主气和司呼吸","宣发与肃降","肺主行水","肺主皮毛"],"a":2,"e":"“水精四布，五经并行”描述肺将水谷精微和水液输布全身，是肺主宣发与肃降两功能协调的结果：宣发将精微上输头面、外达皮毛，肃降使之下输脏腑、下归膀胱。肺朝百脉、主治节、司呼吸、主皮毛虽属肺的功能，但不直接对应这句对水液输布的描述"},{"q":"人体精神活动的物质基础是","o":["精","肝","血","神","津液"],"a":2,"e":"血是神志活动的主要物质基础，血液充足则神志清晰、精力充沛，血虚则见心悸失眠、健忘多梦。精主生长发育生殖，津液主濡润，神是生命活动总体现而非物质基础，肝为藏血之脏，均非“精神活动的物质基础”这一命题的答案"},{"q":"“大实有羸状”指的是","o":["真虚假实证","真实假虚证","真寒假热证","真热假寒证","虚实夹杂证"],"a":1,"e":"“大实有羸状”指本质为实邪壅盛，反表现出羸瘦、倦怠等类似虚证的假象，属真实假虚证，治当泻实。“至虚有盛候”才是真虚假实证；真寒假热、真热假寒属寒热真假；虚实夹杂是虚实并见，均与此处“大实”本质不符"},{"q":"生命的基本特征为","o":["气化作用","气机升降","气血充盈","脏腑功能正常","经络功能正常"],"a":0,"e":"气化是生命的本质特征，指体内精、气、血、津液的生成、转化及代谢过程，气化停止则生命终止。气机升降是气运动的形式；气血充盈是健康表现；脏腑、经络功能正常是生命活动条件，但均非概括生命基本特征的概念"},{"q":"肺之窍是指","o":["鼻","舌","耳","目","口"],"a":0,"e":"肺开窍于鼻，鼻为呼吸之门，肺气通于鼻，肺和则鼻能知臭香。舌为心之窍，耳为肾之窍，目为肝之窍，口为脾之窍，五官各配五脏，鼻专属于肺，故肺之窍为鼻"},{"q":"下列不属于　“七冲门”的是","o":["气门","吸门","贲门","飞门","户门"],"a":0,"e":"七冲门出自《难经》，指飞门（唇）、户门（齿）、吸门（会厌）、贲门（胃上口）、幽门（胃下口）、阑门（大小肠交界）、魄门（肛门）。吸门、贲门、飞门、户门均在其列；气门不在七冲门之中，故为答案"},{"q":"属于“证候”选项，下列错误的是","o":["四诊检查所得","内外致病因素","疾病的特征","疾病的性质","疾病的全过程"],"a":4,"e":"证候是疾病过程中某一阶段或某一类型的病理概括，包含病因、病位、病性及邪正关系，反映疾病某阶段的本质。四诊所得是其表现依据，内外因素是病因，特征与性质是其内容；“疾病的全过程”是“病”的概念而非“证候”，故错误"},{"q":"明清时期，提出“凡温病者，始于上焦”、“上焦不治则传中焦”、“中焦不治即传下焦”的医家是","o":["吴又可","赵献可","叶天士","薛雪","吴鞠通"],"a":4,"e":"清代吴鞠通《温病条辨》以三焦为纲，提出“凡温病者始于上焦”，并论上焦不治则传中焦、中焦不治即传下焦，系统阐述温病传变。吴又可主戾气说；叶天士创卫气营血辨证；赵献可论命门；薛雪论湿热，均未提出三焦传变之论"},{"q":"金元四大家中，“养阴派”的代表人物是","o":["刘完素","李杲","张从正","朱震亨","张元素"],"a":3,"e":"金元四大家中，朱震亨（朱丹溪）倡“阳常有余，阴常不足”，主张滋阴降火，为养阴派代表。刘完素主寒凉、为寒凉派；李杲（李东垣）重脾胃、为补土派；张从正主攻下、为攻邪派；张元素不属金元四大家之列"},{"q":"下列各项，决定疾病是否发生的是","o":["饮食情志","居住环境","正邪斗争的胜负","六淫性质","体质强弱"],"a":2,"e":"疾病发生与否取决于正气与邪气斗争的胜负，正胜邪则不发病，邪胜正则发病，“正气存内，邪不可干”。饮食情志、居住环境、六淫性质是致病条件，体质强弱影响正气，但都通过正邪斗争这一根本机制起作用，并非决定性环节本身"},{"q":"“动极者镇之以静”主要说明的阴阳关系是","o":["阴阳相互转化","阴阳互根互用","阴阳相互消长","阴阳对立制约","阴阳动态平衡"],"a":3,"e":"动属阳、静属阴，“动极者镇之以静”即以静抑制过亢之动，体现阴阳相互对立、相互制约的关系。互根互用强调阴阳依存为用；消长指数量增减变化；转化是阴阳属性转变；动态平衡是结果，均非“以静制动”所体现的对立制约"},{"q":"根据五行学说，属五行相乘传变的是","o":["肝病及心","肝病及肾","肝病及肺","肝病及脾","脾病及心"],"a":3,"e":"相乘指五行中一行过强或另一行过弱，导致相克过度，肝属木、脾属土，木克土，肝病及脾即木乘土，属相乘传变。肝病及心是母病及子；肝病及肾是子病犯母；肝病及肺是相侮（木反侮金）；脾病及心非相乘，需注意区分"},{"q":"主要起维系全身经脉作用的经脉是","o":["正经","奇经","阳跷脉、阴跷脉","阳维脉、阴维脉","督脉"],"a":3,"e":"阳维脉、阴维脉分别维系一身之阳经与阴经，起联络、维系全身经脉的作用，故为答案。正经是十二经脉主体；奇经八脉总督、统率诸经；跷脉主司运动与眼睑开合；督脉总督阳经，均非“维系”之专责"},{"q":"与气的生成密切相关的脏是","o":["心肝脾","肺肝肾","肺脾肾","心肺肾","肝脾肾"],"a":2,"e":"气由肾精、脾胃化生的水谷精微与肺吸入的自然界清气结合而成，故与肺、脾、肾三脏密切相关：肾藏精化气，脾运化水谷精微，肺吸入清气。心主血脉、肝主疏泄虽调气机，但不直接参与气的生成，故不在其列"},{"q":"治疗血虚证时，常在补血药中配用益气之品的理论依据是","o":["血能生气","气能行血","气能摄血","血能载气","气能生血"],"a":4,"e":"气能生血，气是化生血液的动力，营气和津液经气化作用化生为血，故补血时配伍益气之品可促进血的生成。血能生气是血为气之母；气能行血推动血运行；气能摄血固摄血不外溢；血能载气是气的载体，均非此处配伍的理论依据"},{"q":"根据五行学说，面见青色，脉见弦象的病证是","o":["肝病","心病","脾病","肺病","肾病"],"a":0,"e":"青色、弦脉在五行属木，肝属木，故面见青色、脉见弦象定位在肝病，常伴胁痛、烦躁等。心病见赤色洪脉；脾病见黄色缓脉；肺病见白色浮脉；肾病见黑色沉脉，各以色脉归脏，青弦专属肝"},{"q":"分布在人体皮肤表面的络脉是","o":["浮络","孙络","太阴别络","厥阴别络","少阳别络"],"a":0,"e":"浮络是浮行于人体浅表、显露于皮肤的络脉，故分布于皮肤表面者为浮络。孙络是最细小的络脉，分布全身组织间隙；太阴、厥阴、少阳别络为特定经脉的较大分支，虽可循行体表，但并非专指浮于皮肤表面者"},{"q":"空腹进食大量未成熟的柿子或黑枣，易形成","o":["肝结石","胃结石","胆结石","肾结石","膀胱结石"],"a":1,"e":"空腹进食大量未成熟柿子或黑枣，其所含鞣酸与胃酸结合形成不溶性沉淀，聚集于胃中形成胃结石（柿石）。肝、胆、肾、膀胱结石的形成与结石成分及局部环境有关，与进食柿子无直接因果，故均非答案"},{"q":"既属于六腑，又属于奇恒之腑的是","o":["三焦","脑","胆","髓","胃"],"a":2,"e":"胆既为六腑之一，又列入奇恒之腑：因其为空腔器官、与肝相表里而属腑，又因内藏胆汁（精气）、不直接传化水谷而属奇恒之腑。三焦、胃为六腑；脑、髓为奇恒之腑，均不兼具双重归属"},{"q":"先哲对脏腑功能的认识最早来自","o":["解剖观察","哲学推论","对疾病的总结","对人体功能的概括","对生命活动的观察"],"a":0,"e":"先哲对脏腑功能的认识最早源于直观的解剖观察，古代解剖为藏象学说奠定了基础，如《内经》已有脏腑形态、大小、位置的记载。哲学推论、对疾病与生命现象的总结、功能概括是后世理论提炼的方法，但并非最初来源"},{"q":"头痛痛在后头及项部，病变多在","o":["阳明经","太阳经","厥阴经","少阳经","任脉"],"a":1,"e":"头痛以后头及项部为主者，病变多在太阳经，因足太阳膀胱经循行于后头、项背，故见项背强痛。阳明经头痛多在额部及眉棱；少阳经头痛在头之两侧；厥阴经头痛在巅顶；任脉循行前正中线，均不符合后头项部定位"},{"q":"上达头部巅顶的经脉是","o":["手太阴肺经","足阳明胃经","足厥阴肝经","足太阳膀胱经","足少阴肾经"],"a":2,"e":"足厥阴肝经循行“上出额，与督脉会于巅”，故上达巅顶、巅顶头痛多责之肝经。手太阴肺经不循头面；足阳明胃经行于面额；足太阳膀胱经循后头项背为主；足少阴肾经循喉咙挟舌本，均不以巅顶为其归经特征"},{"q":"蛔虫致病，临床常见","o":["发热恶寒","腹痛腹泻","脐周疼痛","口渴神昏","胁下癥积"],"a":2,"e":"蛔虫寄生于小肠，扰动肠胃、阻碍气机，故临床常见脐周疼痛，乍作乍止，伴面色萎黄、消瘦等。发热恶寒多为外感；腹痛腹泻多属湿热或食滞；口渴神昏为热入心营；胁下癥积责之瘀血痰饮，均非蛔虫之典型表现"},{"q":"人体气虚可见自汗的症状，其理论依据是","o":["气能生津","气能行津","气能摄津","津能载气","津能养气"],"a":2,"e":"气能摄津，气固摄津液使其不随意外泄，气虚则固摄无权，津液外泄而自汗。气能生津指气促进津液生成；气能行津推动输布；津能载气、津能养气言津液对气的作用，均不能解释气虚自汗的固摄失常机制"},{"q":"具有“满而不实”特点的是","o":["五脏","六腑","脏腑","五脏六腑","以上均非"],"a":0,"e":"《素问·五脏别论》谓五脏“藏精气而不泻，故满而不能实”，即五脏精气宜充满而不宜壅实，故具“满而不实”特点。六腑为“实而不能满”，恰与五脏相反；脏腑为总称；五脏六腑并提则混淆二者，故均非答案"},{"q":"中医学的学科属性是","o":["属于自然科学的范畴","属于人文社会科学的范畴","属于中国古代哲学的范畴","属于自然哲学的范畴","以自然科学为主体，与人文社会科学多学科相交融的医学科学"],"a":4,"e":"中医学是以自然科学为主体，与人文社会科学多学科相交融的医学科学，兼具自然科学与人文社会科学双重属性。单归自然科学、人文社会科学、中国古代哲学或自然哲学，均片面割裂了其学科内涵，未能全面概括其交融特征"},{"q":"房劳过度易损伤的脏腑是","o":["肝","心","脾","肺","肾"],"a":4,"e":"房劳过度耗伤肾精，肾藏精主生殖，故房劳过度最易损伤肾，见腰膝酸软、头晕耳鸣、遗精早泄等。肝、心、脾、肺虽可因劳倦或七情受损，但与房事直接耗伤肾精的病机对应最为密切者仍是肾"},{"q":"《素问·五脏别论》称为“实而不能满”者，指的是","o":["五脏","六腑","奇恒之腑","脏腑","脑髓"],"a":1,"e":"《素问·五脏别论》称六腑“传化物而不藏，故实而不能满”，指六腑受盛水谷、传导化物，内容物充实但须下行排空，不能久留满溢。五脏为“满而不能实”；奇恒之腑形态似腑而功能似脏；脑髓属奇恒之腑，均非“实而不能满”所指"},{"q":"暑季常感四肢困倦、胸闷呕吐、大便溏泄，是由于","o":["暑性炎热","扰乱心神","暑湿夹杂","热极生风","耗气伤津"],"a":2,"e":"暑季多湿，暑湿相合，湿性重浊黏滞、困阻脾胃，故见四肢困倦、胸闷呕恶、大便溏泄。暑性炎热重在壮热烦渴；扰乱心神见神昏谵语；热极生风见抽搐；耗气伤津见气短乏力、口渴，均不能概括湿困中焦之象"},{"q":"五行学说中“金”的特性是","o":["曲直","炎上","从革","润下","稼穑"],"a":2,"e":"五行中“金曰从革”，从革指变革、顺从变革，引申为清洁、肃降、收敛等特性。曲直属木，炎上属火，润下属水，稼穑属土，各有归属，唯有“从革”专指金行"},{"q":"下列除哪项外都是结石形成的常见原因","o":["情志不遂","体质因素","喜欢甜食","服药不当","空腹食柿"],"a":2,"e":"结石形成常见原因包括情志不遂致气郁、体质因素、服药不当及空腹食柿（鞣酸成石）等，情志、体质、药物、饮食偏嗜均可促生。喜欢甜食并非结石形成的公认常见原因，故为例外项"},{"q":"狭义之精指的是","o":["津液","生殖之精","血","水谷之精","脏腑之精"],"a":1,"e":"狭义之精专指生殖之精，即禀受于父母、主司生殖繁衍的精微物质。津液、血是其他基本物质；水谷之精是脾胃化生之精；脏腑之精为广义之精，散布于五脏，均非“狭义之精”的定义"},{"q":"下列哪种情况不能构成阴阳关系","o":["寒与热","动与静","上升和外出","表与里","水与火"],"a":2,"e":"阴阳需是对立统一、属性相反的两个方面，寒与热、动与静、表与里、水与火皆属性相反可构成阴阳。上升与外出同属阳（升、出皆为阳），二者属性相同、方向相近，不构成对立，故不能构成阴阳关系"},{"q":"与生长发育、生殖关系最密切的脏腑是","o":["心","脾","肺","肾","肝"],"a":3,"e":"肾藏精，主生长、发育与生殖，肾精充盛则生长发育正常、生殖机能旺盛，故与生长发育、生殖关系最密切者为肾。心主血脉神明，脾主运化，肺主气，肝主疏泄藏血，虽参与生命活动，但不主生殖发育之根本"},{"q":"以下除哪项外均属于内生五邪","o":["内风","内寒","内暑","内湿","内燥"],"a":2,"e":"内生五邪指内风、内寒、内湿、内燥、内火（内热），由脏腑气血功能失调产生，属内伤病机。暑为夏季外感六淫之一，纯属外邪，无“内暑”之说，故为例外项"},{"q":"夺血者无汗，其理论依据是","o":["血可化津","津能生血","津能载气","气能摄血","血能载气"],"a":0,"e":"“夺血者无汗”指血液亏耗者不可发汗，因血与津液同源互化，血可化津，血虚则津液不足，发汗更伤津血。津能生血是津液化血；津能载气、气能摄血、血能载气分别言津血与气的关系，均非“夺血无汗”的直接依据"},{"q":"昼夜分阴阳，上午为","o":["阴中之阳","阳中之阳","阳中之阴","阴中之阴","阴中之至阴"],"a":1,"e":"昼属阳、夜属阴，上午阳气渐盛，为阳中之阳；下午阳气渐衰，为阳中之阴；前夜为阴中之阴，后夜（平旦前）为阴中之阳。阴中之至阴配脾与长夏，故上午当属阳中之阳"},{"q":"疾病的发生是因为","o":["阴偏盛","阳偏衰","阴阳失调","阴阳互损","阴阳转化"],"a":2,"e":"阴阳失调是疾病发生、发展变化的根本病机，阴阳偏盛偏衰、互损、格拒、转化等皆为失调的具体表现。阴偏盛、阳偏衰只是失调的一种类型；阴阳互损、转化是演变形式，均不能概括为疾病发生的总机制"},{"q":"与宗气生成关系密切的是肺的哪项功能","o":["肺主一身之气","肺主行水","肺气宣发","肺朝百脉","肺主治节"],"a":0,"e":"宗气由肺吸入的清气与脾胃化生的水谷精气结合而成，肺主一身之气，参与宗气生成并推动其布散。肺主行水通调水道；宣发是气运动形式；朝百脉、主治节是肺辅助心治理调节的功能，均非宗气生成所依据之功能"},{"q":"脾统血的作用机制是","o":["气的固摄作用","气的温煦作用","气的气化作用","气的卫外作用","气的防御作用"],"a":0,"e":"脾统血指脾气能固摄血液，使之运行于脉中而不逸出脉外，其机制是气的固摄作用，脾虚气弱则统摄无权而见出血。温煦作用主温暖脏腑；气化主转化；卫外、防御作用主抗邪，均与固摄血液运行无关"},{"q":"养生首见于","o":["《黄帝内经》","《庄子·内篇》","《类经》","《摄生消息论》","《寿世保元》"],"a":1,"e":"“养生”一词首见于《庄子·内篇》之《养生主》，阐述顺应自然、护养生命的养生思想。《黄帝内经》系统论述养生但晚出；《类经》为明代张介宾注《内经》之作；《摄生消息论》《寿世保元》均为后世养生著作，非首次出现之处"},{"q":"根据五行学说，心病及肝属于","o":["母病及子","相乘","子病及母","相侮","制化"],"a":2,"e":"心属火、肝属木，木生火，肝为母、心为子，心病及肝即子病犯母（子病及母）。母病及子是肝病及心；相乘相侮属相克异常（如肝病及脾、肝病及肺）；制化是正常生克协调，均不符合心病传肝的逆向相生关系"},{"q":"春季多风病，夏季多暑病，秋季多燥病，说明六淫致病具有何种特性","o":["外感性","季节性","地域性","相兼性","转化性"],"a":1,"e":"春多风、夏多暑、秋多燥，说明六淫致病随季节时令而不同，具有明显的季节性。外感性指六淫从外侵袭；地域性指不同地区多发病各异；相兼性指两邪以上相合致病；转化性是邪气性质随体质转变，均非题干所述"},{"q":"关于“火热内生”的形成，说法错误的是","o":["阳气过盛可化火","邪郁可化火","五志过极可化火","阴虚可致火旺","阴盛可致阴火"],"a":4,"e":"火热内生多因阳气过盛、邪郁化火、五志过极化火或阴虚火旺，皆属阳盛或阴虚之病理。阴盛则寒，当生内寒，不可能致“阴火”；“阴火”实为气虚或阴虚所生之火，故该说法错误"},{"q":"《素问·八正神明论》说：“月生无泻，月满无补，月郭空无治，是谓得时而调之。”此段文字体现的思维方式是","o":["整体宏观","辨证唯物","恒动变化","天人合一","动静相召"],"a":3,"e":"此说据月相盈亏决定针刺补泻，体现人体生理病理与自然界月相变化相应，属天人合一（人与天地相参）的思维方式。整体宏观强调从整体把握事物；辨证唯物、恒动变化、动静相召均未直接反映人与自然的对应关系"},{"q":"《素问·气交变大论》说：“善言天者，必应于人；善言古者，必验于今；善言气者，必彰于物；善言应者，同天地之化；善言化言变者，通神明之理。”此段文字体现的思维方式是","o":["形象思维","意象思维","应象思维","整体宏观","恒动变化"],"a":3,"e":"该段以天、人、古、今、物、化相互印证，强调以整体、联系的观点认识事物，体现整体宏观的思维方式。形象思维凭具体形象；意象思维重在象的概括；应象思维以象类比；恒动变化强调运动变化，均未突出天人古今整体联系这一主旨"},{"q":"华佗创立的健身方法是","o":["八段锦","五禽戏","太极拳","舞蹈","按摩"],"a":1,"e":"华佗模仿虎、鹿、熊、猿、鸟五种动物动作创编“五禽戏”，以导引健身、防治疾病。八段锦、太极拳为后世导引功法；舞蹈、按摩虽为养生保健之法，但均非华佗所创"},{"q":"“见微知著，弥患于未萌，是为上工”之语出自","o":["《医学源流论·防微论》","《医学心悟》","《金匮要略》","《素问·玉机真脏论》","《素问·上古天真论》"],"a":1,"e":"此语强调于疾病萌芽、征兆细微之时早察觉、早治疗，体现治未病、防微杜渐的思想，出自《医学心悟》。《金匮要略》为张仲景论杂病之书；《素问·上古天真论》虽首倡“治未病”之说，但无此具体表述；《素问·玉机真脏论》《医学源流论》亦非该语出处"},{"q":"以阴阳失调来阐释真寒假热或真热假寒，其病机是","o":["阴阳偏盛","阳偏衰","阴阳格拒","阴阳互损","阴阳离决"],"a":2,"e":"阴阳格拒指阴阳一方偏盛至极，将另一方排斥格拒于外，形成寒热真假之象：阴盛格阳见真寒假热，阳盛格阴见真热假寒。阴阳偏盛、偏衰是单纯寒热虚实；互损是阴阳俱虚；离决是生命终结，均不能解释寒热真假"},{"q":"中医学整体观念形成的哲学基础是","o":["天人一体观","气一元论","形神一体观","五脏一体观","阴阳对立统一"],"a":1,"e":"气一元论认为气是构成世界万物的本原，天地万物皆由气化生，人与天地万物同源于气，为中医学整体观念（人与天地相参、人体自身统一）奠定了哲学基础。天人一体观、形神一体观、五脏一体观是整体观念的内容而非哲学基础；阴阳对立统一是辩证法思想"},{"q":"五脏中，具有“以升为健”特点的脏是","o":["心","肝","脾","肾","肺"],"a":2,"e":"脾气主升，脾以升为健，脾升则水谷精微上输心肺、头面，并维持内脏位置恒定。心主血脉、肝主疏泄升发、肾主封藏（以降为顺）、肺主宣发肃降（以降为主），虽有升发之能，但“以升为健”专指脾的升清功能"},{"q":"根据五行学说，按相克规律确定的治法是","o":["益火补土法","培土生金法","佐金平木法","金水相生法","滋水涵木法"],"a":2,"e":"佐金平木法通过清肃肺气（金）以抑制肝木亢逆，属依据五行相克（金克木）规律确立的治法。益火补土、培土生金、金水相生、滋水涵木均依相生规律（火生土、土生金、金生水、水生木）而设，故非相克治法"},{"q":"能调节十二经脉气血，主要与奇恒之腑有较密切关系者为","o":["浮络","十二经筋","十五别络","奇经八脉","十二经别"],"a":3,"e":"奇经八脉交错循行于十二经脉之间，能调节十二经脉气血，且与脑、髓、女子胞等奇恒之腑关系密切。浮络是浅表络脉；十二经筋、十二经别是经脉的附属部分；十五别络沟通表里两经，均无统率调节十二经气血并联系奇恒之腑之能"},{"q":"关于既病防变，下列叙述错误的是","o":["早期诊断","早期治疗","防止疾病发展","防止病邪侵害","防止疾病传变"],"a":3,"e":"既病防变指疾病已发生后，通过早期诊断、早期治疗，防止疾病发展与传变。“防止病邪侵害”属未病先防的内容（避邪防病），并非既病之后防变的措施，故叙述错误"},{"q":"下列除哪项外均可归属于五行之“水”","o":["五色之黑","六腑之膀胱","五脏之肾","五体之筋","五味之咸"],"a":3,"e":"五行中水对应五色之黑、五脏之肾、六腑之膀胱、五味之咸及五体之骨。筋在五体属木（肝主筋），不属水，故为例外项。其余各项均归属水行，配属关系明确"},{"q":"下列属于治法的是","o":["正治","扶正","祛邪","泻下","调整阴阳"],"a":3,"e":"治法是治疗疾病的具体方法，如汗、吐、下、和、温、清、消、补八法，泻下属下法，为具体治法。正治、扶正、祛邪、调整阴阳属治疗原则（治则）范畴，层次高于治法，故非具体治法"},{"q":"患者高热、面红、咳喘、脉数有力。对于这种实热证可以依据阴阳的何种关系进行治疗","o":["阴阳互根互用","阴阳转化","阴阳对立","阴阳交感","阴阳平衡"],"a":2,"e":"实热证见高热、面红、脉数有力，属阳盛，治宜“热者寒之”，以寒凉药制约亢盛之阳，依据的是阴阳对立制约关系。互根互用言阴阳依存；转化言属性转变；交感言阴阳交合；平衡是状态，均非“以寒治热”的直接理论依据"},{"q":"喉为何脏之门户","o":["脾","肺","肾","心","肝"],"a":1,"e":"喉为呼吸之通道，上连于咽、下通气管，肺气上通于喉，故喉为肺之门户，肺气壅滞则咽喉不利。脾开窍于口，肾开窍于耳，心开窍于舌，肝开窍于目，各窍分属五脏，喉则专归于肺"},{"q":"提出“灵机记性在脑而不在心”的医家是","o":["李时珍","王清任","汪昂","张景岳","张仲景"],"a":1,"e":"清代王清任著《医林改错》，重视解剖，提出“灵机记性在脑而不在心”，纠正了传统“心主神明”之说的偏颇。李时珍著《本草纲目》；汪昂著《本草备要》；张景岳为明代医家；张仲景著《伤寒杂病论》，均未提出此论"},{"q":"中医学整体观念的内涵是","o":["人体是一个有机的整体","自然界是一个统一的整体","昼夜晨昏对人体的影响","人是一个有机整体，人和自然、社会环境的统一性","脏腑肢体官窍联结成一个整体"],"a":3,"e":"中医学整体观念的内涵包括人体自身是一个有机整体，以及人与自然环境、社会环境的统一性，即“天人一体”“形神一体”。仅言人体整体、自然界整体或昼夜影响、脏腑肢体官窍联系，都只涵盖局部，未完整概括整体观念的全部内涵"},{"q":"排精不畅，伴精道疼痛，睾丸胀痛，小腹胀满，其最直接的病机描述是","o":["精亏","精少","精热","精瘀","精凝"],"a":3,"e":"精瘀指精道瘀滞不通，故见排精不畅、精道疼痛，并可伴睾丸胀痛、小腹胀满等症。精亏、精少以精液量少的虚象为主；精热见精液黄稠；精凝非规范病机术语，均不能描述精道阻滞不通的实证病机"},{"q":"感受寒邪而致“中寒”的机理是","o":["寒邪伤于肌表","寒邪入侵经脉","寒邪自内而生","寒邪直中脏腑","寒邪侵及血分"],"a":3,"e":"“中寒”指寒邪不循肌表，直接侵入脏腑，损伤脏腑阳气，见脘腹冷痛、呕吐泄泻、四肢厥冷等里寒证。寒邪伤于肌表为“伤寒”；入侵经脉、侵及血分是邪气由表入里的不同阶段；寒邪自内而生属内寒，均非“中寒”之本义"},{"q":"阴阳转化的内在根据是","o":["交合感应","对立制约","消长平衡","互根互用","无限可分"],"a":3,"e":"阴阳互根互用指阴阳双方互为存在前提、相互为用，是阴可转化为阳、阳可转化为阴的内在根据，如“重阴必阳，重阳必阴”。对立制约是转化的动力条件之一；消长平衡是转化的量变过程；交合感应、无限可分均非转化的内在根据"},{"q":"主运化的脏是","o":["心","脾","肺","肝","肾"],"a":1,"e":"脾主运化，包括运化水谷精微与水液，为气血生化之源，故称“后天之本”。心主血脉神明，肺主气司呼吸，肝主疏泄藏血，肾藏精主水纳气，虽各司其职，但“主运化”专属于脾"},{"q":"下列属于奇恒之腑的是","o":["胃","小肠","三焦","胆","膀胱"],"a":3,"e":"奇恒之腑包括脑、髓、骨、脉、胆、女子胞，胆因其内藏胆汁而不直接传化水谷，形态似腑、功能似脏，故属奇恒之腑。胃、小肠、三焦、膀胱皆为空腔、主传导水谷的六腑，与奇恒之腑“藏而不泻”的特点不同"},{"q":"根据五行学说，脾病传肾的机理是","o":["相克","相侮","母病及子","相乘","子病犯母"],"a":3,"e":"脾属土、肾属水，土克水，脾病传肾是相克过度，属相乘传变。相侮为反克，如脾土反侮肝木；母病及子如心病及肺；子病犯母如肺病及心，方向均不同，注意相乘与相侮之别"},{"q":"下列哪项属于寒邪的性质","o":["轻扬开泄","重浊","凝滞","黏滞","干涩"],"a":2,"e":"寒性凝滞，寒邪侵袭使气血运行阻滞不畅，“痛则不通”，故寒邪致病多见疼痛。轻扬开泄是风邪特性；重浊、黏滞是湿邪特性；干涩是燥邪特性，各自归属明确，唯有凝滞属寒"},{"q":"在父母生殖之精的基础上及胎孕期间内外环境的影响下，子代所形成的相对稳定个体固有特性指的是","o":["禀赋","后天因素","体质","环境因素","地理因素"],"a":0,"e":"禀赋指子代在父母生殖之精基础上，于胎孕期间受内外环境影响所形成的相对稳定、固有的个体特性，即先天禀赋。体质是禀赋与后天因素共同作用形成的整体素质；后天因素、环境、地理因素均属出生后的影响，不合“相对稳定个体固有特性”的定义"},{"q":"胆汁的分泌与排泄，主要取决于","o":["肝主疏泄的功能","胆贮藏胆汁的功能","胆排泄胆汁的功能","脾主运化的功能","小肠泌别清浊的功能"],"a":0,"e":"胆汁由肝之余气所化，贮存于胆，其分泌与排泄依赖肝主疏泄功能的调畅，肝气疏泄正常则胆汁排泄通畅。胆的贮藏、排泄功能是胆汁运行环节而非决定因素；脾主运化、小肠泌别清浊与胆汁分泌排泄无直接主导关系"},{"q":"脏与脏之间主要是先后天互相资生关系的是","o":["心与肾","心与脾","心与肺","脾与肾","心与肝"],"a":3,"e":"脾为后天之本、气血生化之源，肾为先天之本、藏精主生殖，脾肾之间为先天与后天互相资生、相互促进的关系：脾运化水谷精微以充养肾精，肾阳温煦脾土以助运化。心与肾是水火既济；心与脾是血的生成运行；心与肺是气血关系；心与肝是血液与神志，均非先后天资生"},{"q":"下列哪项是瘀血致病的特征","o":["腹痛，泻后痛减","形成肿胀，时聚时减","胁痛且胀，随情绪波动而增减","胸闷咳嗽，不能平卧","疼痛如针刺，位置不移"],"a":4,"e":"瘀血阻滞经脉，不通则痛，其疼痛特点为刺痛、痛处固定不移、拒按，夜间加剧，并见舌质紫暗、面色晦暗等。泻后痛减多为食积；肿胀时聚时减属气滞或水肿；胁痛随情绪波动为肝郁气滞；胸闷咳喘不能平卧为痰饮停肺，均非瘀血特征"},{"q":"患者急性发病，壮热，烦渴，面红目赤，尿黄，便干，舌苔黄。其病机是","o":["阳盛格阴","阳损及阴","阳热偏盛","阳盛伤阴","阴盛格阳"],"a":2,"e":"急性发病、壮热、烦渴、面红目赤、尿黄便干、苔黄、脉数有力，为阳热之邪偏盛、正气未衰的实热证，病机属阳热偏盛。阳盛格阴见真热假寒；阳损及阴是阳虚累及阴；阳盛伤阴强调阴液受损；阴盛格阳见真寒假热，均与纯实热表现不符"},{"q":"形体消瘦，便溏，舌红少苔，多见于","o":["心阴虚","肝阴虚","脾阴虚","肺阴虚","肾阴虚"],"a":2,"e":"脾阴虚则运化失职、阴液不足，故见形体消瘦、便溏，伴舌红少苔、口干等阴虚象。心阴虚以心悸失眠为主；肝阴虚见目涩、胁痛；肺阴虚见干咳少痰；肾阴虚见腰膝酸软、潮热，虽各有阴虚，但便溏消瘦定位在脾"},{"q":"用下列哪种药可以预防肝炎","o":["贯众","板蓝根","大青叶","茵陈","马齿苋"],"a":3,"e":"茵陈为利湿退黄要药，善清肝胆湿热，常用于湿热黄疸，现代用于预防和治疗肝炎。贯众、板蓝根、大青叶重在清热解毒、凉血利咽；马齿苋清热解毒、凉血止痢，均非预防肝炎之首选药"},{"q":"“春夏养阳，秋冬养阴”是遵循养生基本原则中的","o":["延缓衰老","顺应自然","预防疾病","形神兼养","动静结合"],"a":1,"e":"“春夏养阳，秋冬养阴”要求依随四时阴阳消长规律调养阴阳，春夏顺其生发而护阳，秋冬顺其收藏而养阴，属顺应自然的养生原则。延缓衰老、预防疾病是养生目的；形神兼养、动静结合是养生方法，均非此语所遵循的原则"},{"q":"与思维的产生关系最为密切的是","o":["肝","心","脾","肺","肾"],"a":1,"e":"心主神明，主司精神、意识、思维活动，故与思维的产生关系最为密切者为心。肝主疏泄、调畅情志；脾主思，为思虑活动的物质基础相关；肺主气；肾藏精生髓充脑，虽参与神志活动，但思维之主宰仍归于心"},{"q":"注于脉中，化生血液的是","o":["元气","宗气","营气","心气","卫气"],"a":2,"e":"营气行于脉中，富有营养，能化生血液，故注于脉中化生血液者为营气。元气根于肾、为生命原动力；宗气积于胸中、走息道；心气推动血脉运行；卫气行于脉外、温养防御，均不直接化生血液"},{"q":"五行调节事物整体动态平衡的机制是","o":["制化","我生","克我","我克","生我"],"a":0,"e":"制化指五行之间相生与相克相互制约、相互调节，维持事物整体动态平衡的机制，如木生火、火克金、金克木的配合。我生、克我、我克、生我仅描述五行相生相克的单向关系，不能体现整体的动态平衡调节"},{"q":"情志刺激可引起下列哪个病证","o":["伤寒","中暑","虫证","胸痹","食积"],"a":3,"e":"情志过极，尤其怒、思、忧悲，致气机郁滞或逆乱，气血运行不畅，心脉痹阻则发胸痹。伤寒、中暑为外感六淫所致；虫证由寄生虫引起；食积因饮食停滞，均与情志刺激无直接因果关系"},{"q":"以下均属于肾的系统，错误的是","o":["二阴","女子胞","发","膀胱","耳"],"a":1,"e":"肾的系统联系包括肾开窍于耳及二阴、其华在发、在体合骨、与膀胱相表里。女子胞（子宫）虽与肾精、冲任密切相关，但在五脏系统归属上，女子胞主要隶属于肝（肝主藏血、冲任隶于肝肾），故在“属于肾的系统”中列为错误项"},{"q":"“乙癸同源”是指哪两脏的关系","o":["心与肾","肺与肾","脾与肾","肝与肾","肝与肺"],"a":3,"e":"天干配五行脏腑中，乙属木配肝，癸属水配肾，乙癸同源即肝肾同源，因肝藏血、肾藏精，精血互生，故肝肾关系密切，又称“精血同源”。心与肾为水火既济；肺与肾为金水相生；脾与肾为先后天资生；肝与肺为气血升降，均非乙癸同源"},{"q":"胆经的名称是","o":["足少阳胆经","足阳明胆经","足太阳胆经","足少阴胆经","足太阴胆经"],"a":0,"e":"胆经的全称为足少阳胆经，属足三阳经之一，循行于头身侧面。足阳明为胃经，足太阳为膀胱经，足少阴为肾经，足太阴为脾经，各经名称与所属脏腑固定，不可错配"},{"q":"胃的生理特性是","o":["喜润恶燥主降","喜燥恶湿主降","喜润恶燥主升","喜燥恶湿主","主宣降"],"a":0,"e":"胃为阳土，主受纳腐熟水谷，其气以降为顺，胃喜润恶燥，津液充足则受纳腐熟有权，故生理特性为喜润恶燥、主降。脾则喜燥恶湿、主升；“主宣降”是肺的特性；喜燥恶湿主降、喜润恶燥主升均为脾胃特性的错配"},{"q":"下列选项中不属于经络学说在诊断中的具体运用的是","o":["望小儿指纹","耳壳视诊","腧穴诊断","分经诊断","望体态"],"a":4,"e":"经络学说在诊断中的运用包括望小儿指纹（络脉）、耳壳视诊（耳与经络脏腑相关）、腧穴诊断（压痛、结节）、分经诊断（按经脉循行辨病位）。望体态是通过观察病人形体姿态判断病情，属望诊一般内容，非经络学说的具体运用"},{"q":"与血液生成关系最密切的脏腑是","o":["心","肺","肝","脾","肾"],"a":3,"e":"脾为气血生化之源，脾胃运化水谷精微，上输心肺，经气化作用化生为血，故与血液生成关系最密切的脏腑是脾。心主血脉推动运行；肺主气参与气化；肝藏血调节血量；肾藏精、精能化血，虽均参与，但生化之源首推脾胃"},{"q":"根据五行学说，调节事物整体动态平衡的是","o":["相生","相克","相乘","相侮","制化"],"a":4,"e":"制化指五行相生相克相互配合、相互制约，从而维持事物整体动态平衡的调节机制，如“亢则害，承乃制”。相生、相克是单向关系；相乘、相侮是异常的相克，均不能体现“调节整体动态平衡”的含义"},{"q":"人身之阳气在正常情况下有养神柔筋、温煦脏腑的作用，为生理之火，中医还称之为","o":["君火","相火","少火","壮火","阴火"],"a":2,"e":"生理之火能温煦脏腑、养神柔筋，为人体正常阳气，称“少火”，“少火生气”。君火、相火多指心火与命门之火；壮火为亢盛之邪火，“壮火食气”；阴火为脾胃气虚或阴虚所生之火，均非生理之火的称谓"},{"q":"基于推演络绎，以下除了哪项外，均属于火","o":["小肠","筋","脉","面","舌"],"a":1,"e":"按五行推演，火对应心、小肠、脉、舌、面、笑、苦、赤等，故小肠、脉、面、舌均属火。筋在五体属木（肝主筋），为肝之系统，不属火，故为例外项"},{"q":"脾经的终端与何经的起点相接","o":["肺经","胃经","肝经","心经","肾经"],"a":3,"e":"足太阴脾经起于足大趾，上行入腹，其分支“复从胃别上膈，注心中”，与手少阴心经相接，故脾经终端与心经起点相接。肺经起于中焦，胃经接肺经，肝经、肾经虽与脾经有流注关系，但直接注心中而接心经者为脾经"},{"q":"阴偏盛所形成的病理变化是","o":["实热","实寒","虚热","虚寒","真寒假热"],"a":1,"e":"阴偏盛即阴邪亢盛，阴盛则寒，且正气未虚，故形成实寒证，见形寒肢冷、腹痛拒按、苔白等。实热为阳偏盛；虚热为阴虚；虚寒为阳偏衰；真寒假热为阴盛格阳，均非阴偏盛所直接形成者"},{"q":"心神的物质基础是","o":["血","气","精","津","营气"],"a":0,"e":"心藏神，血是神志活动的物质基础，血气充盈则心神得养、神志清晰。气为推动与温煦；精主生殖发育；津主濡润；营气是血的组成部分，虽均属生命基本物质，但直接作为“心神的物质基础”者当推血"},{"q":"“膏粱之变，足生大丁”是指","o":["饮食过饱","饮食过饥","饮食不洁","进食大量高粱","嗜食辛辣"],"a":0,"e":"“膏粱之变，足生大丁”出自《素问·生气通天论》，指长期过食肥甘厚味（膏粱），致脾胃运化失健、湿热火毒内生，发于肌肤则生疔疮。饮食过饥是摄食不足；饮食不洁致胃肠病；高粱为具体谷物；嗜食辛辣仅偏嗜之一，均未概指厚味太过"},{"q":"下列各项中的医学思想错误的是","o":["伤寒早治重太阳病阶段","温病早治重在卫分证阶段","先安未受邪之地属于预见性治疗","早期治疗的前提是早期的正确诊断","疾病做到早治就一定不会发生传变"],"a":4,"e":"早治可延缓或阻止疾病传变，但传变受邪气性质、体质、治疗是否得当等多因素影响，“早治就一定能防止传变”过于绝对，故错误。伤寒早治重太阳、温病早治重卫分、先安未受邪之地属预见性治疗、早期诊断是早期治疗前提，均属正确的防治思想"},{"q":"长期饮食过饥，气血生化减少，正气不足，容易导致","o":["外邪入侵","湿热内生","痰湿内停","肝气郁结","食滞胃肠"],"a":0,"e":"长期饮食过饥，气血生化乏源，正气亏虚，卫外不固，故易致外邪入侵，即“正气存内，邪不可干”，正虚则邪凑。湿热内生、痰湿内停多因脾虚运化失职或过食肥甘；肝气郁结责之情志；食滞胃肠因饮食停滞，均非过饥正虚之直接后果"},{"q":"经络的调节平衡作用是","o":["单向的","正向的","逆向的","垂直的","良性双向的"],"a":4,"e":"经络的调节平衡作用是良性双向的，当机体功能偏亢时予以抑制，偏衰时予以兴奋，使失衡的功能恢复正常，如针刺的双向调节。单向、正向、逆向、垂直均不能概括这种“泻有余、补不足”的双向良性调节特点"},{"q":"瘀血在舌质上表现为","o":["舌质紫暗","舌质淡红","舌质淡白","舌质鲜红","舌质红绛"],"a":0,"e":"瘀血内停，气血运行不畅，舌失濡养，故舌质紫暗，或见瘀点瘀斑、舌下络脉迂曲。舌质淡红为正常；淡白主气血两虚；鲜红主热；红绛主热入营血或阴虚火旺，均非瘀血的舌象特征"},{"q":"六腑的生理特点是","o":["贮藏精气","化生精气","传导精气","传化水谷","运化水液"],"a":3,"e":"六腑的共同生理特点是受盛和传化水谷，以通降下行为顺，“传化物而不藏，实而不能满”。贮藏、化生精气是五脏功能；传导精气表述不准；运化水液是脾的功能，均非六腑“传化水谷”的共性概括"},{"q":"与内脏下垂有关的脏是","o":["脾","肺","肾","肝","心"],"a":0,"e":"脾主升清，脾气上升以维持内脏位置恒定，脾气虚弱、升举无力则致内脏下垂，如胃下垂、子宫脱垂、脱肛，常伴脘腹重坠、久泻。肺主气、肾主纳气、肝主疏泄、心主血脉，均不主升举内脏，故病位在脾"},{"q":"膀胱的贮尿和排尿功能主要依赖于","o":["肺的通调水道","肾的气化功能","肝的疏泄","三焦决渎","脾的运化水液"],"a":1,"e":"膀胱贮尿排尿依赖肾的气化作用，肾气充足则膀胱开合有度，尿液的贮存与排泄正常；肾气不足则见尿频、遗尿或癃闭。肺通调水道、脾运化水液、肝疏泄、三焦决渎虽参与水液代谢，但膀胱开合的直接主持者在肾的气化"},{"q":"有主水和纳气功能的脏是","o":["肝","心","脾","肺","肾"],"a":4,"e":"肾主水，司气化以调节水液代谢；肾又主纳气，摄纳肺吸入之清气，故兼具主水与纳气功能者为肾。肝主疏泄藏血，心主血脉神明，脾主运化水谷，肺主气司呼吸、通调水道但纳气归肾，均不兼具此二功能"},{"q":"开创了中医“预防为主”思想的先河，首次明确提出“治未病”一词典籍是","o":["《黄帝内经》","《医学源流论》","《医学启蒙》","《金匮要略》","《诸病源候论》"],"a":0,"e":"《黄帝内经》首创“治未病”之说，如《素问·四气调神大论》“是故圣人不治已病治未病”，开中医预防为主思想之先河。《金匮要略》“见肝之病，知肝传脾”是既病防变的具体运用；《医学源流论》《诸病源候论》《医学启蒙》均晚出，非首次提出之处"},{"q":"下列哪项是火邪、燥邪、暑邪共同的致病特点","o":["耗气","上炎","伤津","动血","生风"],"a":2,"e":"火、燥、暑三者均属阳邪或燥热之邪，易损伤人体津液，故伤津是其共同致病特点，见口渴、尿少、便干。耗气主要是暑、火；上炎是火邪特性；动血、生风多属火（热）邪，燥、暑不具此共性，故均非三者共有"},{"q":"最易导致病位游移不定的外邪是","o":["风邪","暑邪","湿邪","火邪","寒邪"],"a":0,"e":"风性善行而数变，致病部位游移不定，如行痹之关节疼痛游走无常，故最易导致病位游移者为风邪。暑邪多挟湿、发病急；湿邪重浊黏滞、病位固定；火邪炎上；寒邪凝滞、痛处固定，均不主游移"},{"q":"下列各项，属于消法范畴以外的是","o":["消食导滞","行气活血","化痰利水","驱虫","健脾"],"a":4,"e":"消法是通过消食导滞、行气活血、化痰利水、驱虫等方式，使有形之邪渐消散除的治法。健脾属补法（补益脾胃），旨在扶正补虚，与消法“攻削有形实邪”的性质相反，故不属于消法范畴"},{"q":"《饮膳正要》一书中说：“春气温，宜食（）以凉之。”","o":["菽","麻","麦","黍","苦"],"a":2,"e":"《饮膳正要》论四时饮食，谓“春气温，宜食麦以凉之”，麦性凉，可清热除烦，顺应春季温气。菽、麻、黍、苦等各有所宜，但此句专指“麦”，故其余选项不合原文"},{"q":"水湿痰饮多从何脏论治","o":["心、肾","肺、脾、肾","心、脾、肝、肾","肺、肝、脾、肾","心、肝、脾、肺、肾"],"a":1,"e":"水湿痰饮的生成与肺、脾、肾三脏功能失调密切相关：脾失运化则水湿内停，肺失宣降则水道不通、聚而成痰，肾失气化则水液泛滥，故有“脾为生痰之源，肺为贮痰之器，肾为水脏”之说。心主血脉、肝主疏泄虽调气机，但非水湿痰饮论治之主脏"},{"q":"阴阳的相互转化是","o":["绝对的","有条件的","必然的","偶然的","量变的"],"a":1,"e":"阴阳转化是阴阳双方在一定条件下向其对立面转化的过程，需具备“重”“极”等条件，如“重阴必阳，重阳必阴”“寒极生热，热极生寒”，故转化是有条件的。绝对、必然、偶然、量变均不能准确描述这一需条件促成的变化"},{"q":"由水谷精微中的精华部分所化生的气是","o":["元气","宗气","营气","卫气","脏腑之气"],"a":2,"e":"营气由脾胃化生的水谷精微中精华部分（营阴）所化生，行于脉中，营养全身并化生血液。元气根于肾精；宗气由清气与水谷精气结合；卫气为水谷精微中慓悍滑利部分、行于脉外；脏腑之气是各脏功能之气，均非水谷精华之最精细化生者"},{"q":"与津液代谢关系最密切的脏腑有","o":["肝、脾、肾","脾、肺、肾","心、肝、脾","脾、肺、心","肝、肺、肾"],"a":1,"e":"津液代谢依赖脾的运化传输、肺的宣发肃降通调水道、肾的气化蒸腾，三脏协同完成水液的生成、输布与排泄，故关系最密切者为脾、肺、肾。肝主疏泄调气机、心主血脉推动运行虽参与，但非主持津液代谢的核心脏腑"},{"q":"最早提出“七情和合”药物配伍理论的是","o":["《黄帝内经》","《难经》","《伤寒杂病论》","《神农本草经》","《本草纲目》"],"a":3,"e":"《神农本草经》最早提出“七情和合”的药物配伍理论，将药物配伍关系概括为单行、相须、相使、相畏、相杀、相恶、相反七种。《黄帝内经》奠定理论基础；《难经》《伤寒杂病论》重在辨证论治；《本草纲目》为明代本草巨著，均非七情和合之首创"},{"q":"容易导致脾气耗损、心血不足的病因是","o":["风寒","温燥","饮食过饱","大怒","思虑过度"],"a":4,"e":"思虑过度耗伤心脾，思虑伤脾则脾气耗损、运化失职，心血不足则心悸失眠、健忘多梦，故思虑过度易致脾气耗损、心血不足。风寒、温燥为外邪；饮食过饱伤脾胃；大怒伤肝，均不直接导致心脾气血两虚"},{"q":"下列属于五行之“火”，错误的是","o":["心","笑","汗","苦","魄"],"a":4,"e":"五行中火对应心、小肠、脉、舌、面、笑、汗、苦等，故心、笑、汗、苦均属火。魄在五脏神志中属肺（肺藏魄），肺属金，故魄不属火，为例外项"},{"q":"中医学认为，构成人体这个有机整体的中心是","o":["五脏","六腑","脑","命门","经络系统"],"a":0,"e":"中医学认为人体以五脏为中心，五脏通过经络联系六腑、五官、九窍、四肢百骸，构成有机整体，故构成人体这个有机整体的中心是五脏。六腑、脑、命门、经络系统虽为整体组成部分，但均非居中心主导地位者"},{"q":"六淫中易侵犯人体上部和肌腠的外邪是","o":["风邪","寒邪","湿邪","燥邪","暑邪"],"a":0,"e":"风性轻扬开泄、升发向上，易袭阳位，故易侵犯人体上部（头面）和肌腠（表卫），见头痛、恶风、汗出等。寒邪重浊凝滞、湿邪重浊黏滞易困下部；燥邪伤津；暑邪多挟湿，均无“易犯上部肌腠”之特性"},{"q":"下列名称错误的是","o":["手太阴肺经","足阳明胃经","手厥阴心包经","手太阳膀胱经","足少阴肾经"],"a":3,"e":"十二经脉以手足、阴阳、脏腑命名，膀胱经循行于下肢后侧，属足太阳，正确名称为足太阳膀胱经。手太阳所配为小肠经，将手、足混用即成错误名称。手太阴肺经、足阳明胃经、手厥阴心包经、足少阴肾经的阴阳、脏腑与循行部位均相符，命名无误"},{"q":"下列关于劳逸损伤与疾病发生关系的叙述，错误的是","o":["久视伤血","久坐伤肉","久立伤骨","久卧伤心","久行伤筋"],"a":3,"e":"《素问·宣明五气》所载五劳所伤为久视伤血、久卧伤气、久坐伤肉、久立伤骨、久行伤筋，久卧耗伤的是气而非心。久视伤血因目得血而能视，久立伤骨因骨赖肾精充养，均属经典对应。把久卧归于心，混淆了五劳与五脏的固定配属"},{"q":"中医学理论体系确立的时期为","o":["春秋战国","战国至秦汉","两晋隋唐","宋金元","明清"],"a":1,"e":"战国至秦汉时期《黄帝内经》《难经》《伤寒杂病论》《神农本草经》相继问世，奠定脏腑、经络、辨证论治等理论基础，标志中医学理论体系确立。春秋战国仅是理论萌芽，两晋隋唐以临床经验积累为主，宋金元学派争鸣，明清温病学说成熟，均晚于确立阶段"},{"q":"金元时期，倡导“百病皆由脾胃衰而生”的医家是","o":["张元素","刘完素","张从正","朱丹溪","李东垣"],"a":4,"e":"李东垣为金元四大家补土派代表，著《脾胃论》，认为脾胃为后天之本、气血生化之源，脾胃虚则百病由生，治重升阳补气。刘完素主寒凉、张从正主攻邪、朱丹溪主滋阴，学术主张各异；张元素虽重脏腑辨证，但未提出脾胃衰生百病之论"},{"q":"由于精神情志的刺激，影响机体阴阳气血和脏腑的生理平和，造成气机郁结，气郁日久则从阳化热，对这一过程最准确的描述是","o":["邪郁化火","气郁化火","五志过极化火","内伤化火","邪盛化火"],"a":2,"e":"情志过极直接扰乱脏腑气机，气郁日久从阳化热而化火，因五志过激所致，故称五志过极化火。气郁化火泛指气机郁滞化火，可由多种原因引起，未突出情志刺激这一特定前提；邪郁化火指外感六淫郁而化热，属外感病机，与情志内伤无涉"},{"q":"临床上治疗多汗、漏汗时，可采用补气之法，其理论依据是","o":["气能行津","气能摄津","气能生津","津能载气","津能生气"],"a":1,"e":"气能摄津指气固摄津液使其不致无故外泄，汗为津液所化，气虚固摄失职则多汗、漏汗，补气可固表止汗。气能生津指气促进津液生成，气能行津指气推动津液输布，二者针对津液生成与输布障碍，与汗液外泄的固摄问题不同；津能载气、津能生气均非止汗依据"},{"q":"肝主疏泄的基本生理功能是","o":["调畅情志活动","调畅全身气机","促进脾胃运化","推动血行津布","促进男女生殖"],"a":1,"e":"肝主疏泄指肝气疏通、畅达全身气机，是肝最基本、最核心的生理功能，其余功能皆由此衍生。调畅情志、促进脾胃运化、推动血行津布、促进生殖等均为调畅气机在不同方面的具体体现，属派生功能，不具基本性，故以调畅全身气机为答案"},{"q":"载有“络之别者为孙”的著作是","o":["《灵枢·经脉》","《灵枢·经别》","《灵枢·经筋》","《灵枢·经水》","《灵枢·脉度》"],"a":4,"e":"《灵枢·脉度》载经脉为里、支而横者为络、络之别者为孙，明确经脉、络脉、孙络的层次。《灵枢·经脉》论十二经脉循行病候，经别、经筋、经水诸篇分论经别、经筋与经脉类比水系，均未载此句，故非出处"},{"q":"小肠“泌别清浊”的功能，下列哪项是错误的","o":["分为水谷精微和食物残渣","吸收水谷精微和津液","对食物残渣和废水的处理","既能传导，又吸收水液","是脾的升清和胃的降浊功能的具体体现"],"a":3,"e":"小肠泌别清浊是将食糜分为水谷精微与食物残渣，吸收精微津液上输于脾，残渣下输大肠、废水渗入膀胱，体现脾升清胃降浊。传导糟粕、排泄粪便属大肠功能，小肠虽吸收水液但不主传导，故既能传导又吸收水液的说法混淆了小肠与大肠的职责"},{"q":"气机升降之“枢”是指","o":["肺主呼气，肾主纳气","心火下降，肾水上升","脾主升清，肺主肃降","脾气主升，胃气主降","肝主升发，肺主肃降"],"a":3,"e":"脾主升清、胃主降浊，同居中焦，一升一降为全身气机升降之枢。肺主呼气肾主纳气体现呼吸中的升降，心火下降肾水上升为水火既济，肝主升发肺主肃降调畅全身气机，均非中焦枢纽；脾升肺降之说亦非经典表述"},{"q":"认为“六气皆从火化”的医家是","o":["张元素","刘完素","张从正","朱丹溪","李东垣"],"a":1,"e":"刘完素为金元四大家寒凉派代表，认为风、寒、暑、湿、燥、火六气皆能化火，治主清热泻火，故有六气皆从火化之说。张元素讲求脏腑辨证，张从正主攻邪，朱丹溪倡阳常有余阴常不足而主滋阴，李东垣主脾胃内伤，皆非此论提出者"},{"q":"“塞因塞用”不适用于下列哪种病证","o":["脾虚腹胀","血枯经闭","肾虚尿闭","气郁腹胀","阴虚便秘"],"a":3,"e":"塞因塞用即以补开塞，用补益药治疗因虚致塞的病证，适用于脾虚腹胀、血枯经闭、肾虚尿闭、阴虚便秘等虚性闭塞。气郁腹胀由肝气郁结、气机阻滞所致，属实证，当疏肝理气，若用补益反致气机愈滞，故不适用"},{"q":"大肠的病机特点是","o":["受纳功能失常","运化功能失常","传导功能失常","调节功能失常","腐熟功能失常"],"a":2,"e":"大肠主传导糟粕，其病机核心为传导功能失常，临床见便秘或泄泻。受纳失常、腐熟功能失常皆属胃病，运化失常归于脾，调节功能多指肝疏泄气机与情志，均非大肠病机特点，故以传导功能失常概括。大肠以通为用，传导失司则排便异常，是其病机核心"},{"q":"主张命门为人身之主的医家是","o":["吴鞠通","赵献可","叶天士","薛雪","吴又可"],"a":1,"e":"赵献可著《医贯》，力倡命门学说，认为命门为人身之主、生命之本，强调命门火温煦推动脏腑功能。吴鞠通著《温病条辨》，叶天士创卫气营血辨证，薛雪论湿热，吴又可著《瘟疫论》主戾气说，均不以命门为身主立论"},{"q":"某些远离海洋的山区，人群中易患地方性甲状腺肿，其发病因素是","o":["地域因素","气候因素","先天禀赋，体质较弱","工作环境","精神状态"],"a":0,"e":"地方性甲状腺肿因山区水土中碘等元素缺乏或过多所致，属地域因素致病，无传染性。气候因素指四时六气变化，工作环境指职业性理化因素，精神状态属情志内伤，先天禀赋只影响个体易感性，均不能解释山区人群集群发病这一地域特征"},{"q":"小肠“泌别清浊”的功能，下列错误的是","o":["分为水谷精微和食物残渣","吸收水谷精微和津液","对食物残渣和废水的处理","排泄尿液","是脾的升清和胃的降浊功能的具体体现"],"a":3,"e":"小肠泌别清浊将水谷分为精微与残渣，吸收精微津液上输于脾，残渣下输大肠、多余水液渗入膀胱，是脾升清胃降浊的具体体现。尿液的贮存与排泄由膀胱主之，赖肾的气化完成，小肠只将废水下渗膀胱，并无排泄尿液之功，故此项错误"},{"q":"脾在志为","o":["怒","思","喜","悲","恐"],"a":1,"e":"五脏在志为心喜、肝怒、脾思、肺悲、肾恐，故脾在志为思，思虑过度最易耗伤脾气。怒归肝、喜归心、悲归肺、恐归肾，均为五脏与情志的固定对应，彼此不可混淆，本题以脾配思为定论。脾在志为思，思虑过极则气结，直接影响脾的运化与统血"},{"q":"金元四大家中“滋阴派”的代表人物是","o":["张元素","刘完素","张从正","朱丹溪","李东垣"],"a":3,"e":"朱丹溪倡阳常有余、阴常不足，治主滋阴降火，为金元四大家滋阴派代表。刘完素创寒凉派，张从正创攻下派，李东垣创补土派；张元素虽为金元医家、讲求脏腑辨证，但不在金元四大家之列，均非滋阴派"},{"q":"五脏生理特性中，“以升为健”的脏为","o":["肾","肺","脾","肝","心"],"a":2,"e":"脾气以升为健，主升清，将水谷精微上输头面心肺，脾气升则清阳得布、内脏位置维系，故以升为健。肺主肃降以降为顺，肾主封藏，肝主升发而喜条达，心主血脉与神明，均不以以升为健概括其特性。肺主肃降体现肺气以降为顺，与脾以升为健相对，二者共调气机"},{"q":"具有“喜燥恶湿”特性的脏腑是","o":["肝","脾","胃","肾","肺"],"a":1,"e":"脾主运化水湿，其功喜干燥而恶湿邪困阻，湿浊最易困脾碍运，故脾喜燥恶湿。胃为燥土，喜润恶燥，与脾燥湿相济；肝喜条达恶抑郁，肾主水而恶燥，肺喜润恶燥，四者皆非喜燥恶湿之脏。胃喜润恶燥，赖脾运化水湿以济其燥，二者燥湿相济，共同完成饮食消化"},{"q":"脾之大络散布的部位是","o":["上肢部","下肢部","背部","胸胁部","腹部"],"a":3,"e":"脾之大络名大包，从脾分出后布散于胸胁，故其散布部位为胸胁，有渗灌营卫气血之用。上肢、下肢分别为手、足经脉分布区，背部多属足太阳膀胱经与督脉，腹部为脾胃诸经所布，均非脾之大络的散布部位"},{"q":"以下哪种疾病在气候转变的季节或寒冬易复发","o":["失眠","脏躁","哮病","某些月经不调病证","癫狂"],"a":2,"e":"哮病为痰饮内伏、遇外邪或气候骤变而发的痰鸣气喘疾患，气候转变或寒冬易引动伏痰而复发，故有冬病之称。失眠、脏躁多关情志心神，某些月经不调涉气血冲任，癫狂与痰火、情志相关，均无明显的季节性复发规律"},{"q":"虚损病证表现虚候，用补益方药来治疗它，此被概括为下列中哪一项","o":["逆者正治","从者反治","实者泻之","虚者补之","塞因塞用"],"a":3,"e":"虚者补之指虚证出现虚象时用补益药治疗，属正治法中针对虚证的具体治则。塞因塞用是以补益治虚性闭塞的反治法，针对塞的假象；实者泻之针对实证，从者反治指顺从假象而治，均与虚损见虚候用补法的概括不符"},{"q":"水不涵木是指","o":["肾阳虚不能煦肝阳","肝阴虚不能充养肾阴","肾阴虚不能滋养肝阴","肝火太旺下劫肾阴","肝阴不足导致肾阴亦虚"],"a":2,"e":"肾属水、肝属木，水能生木，肾阴滋养肝阴，肾阴亏虚不能滋养肝阴，致肝阴不足、肝阳上亢，称水不涵木，属母病及子。肝阴虚不能充养肾阴为子盗母气，肝火太旺下劫肾阴属木反耗水，肾阳虚不能温煦肝阳及肝阴不足致肾阴亦虚均非水不涵木本义"},{"q":"病机之名，首先见于","o":["《黄帝内经》","《伤寒论》","《金匮要略》","《难经》","《中藏经》"],"a":0,"e":"病机之名首见于《黄帝内经》，《素问·至真要大论》有谨守病机、各司其属之论，奠定病机学说基础。《伤寒论》以六经辨证论外感，《金匮要略》论杂病，《难经》补脉学与脏腑理论，《中藏经》论脏腑虚实，均晚于《内经》且非首见病机之名"},{"q":"属于五行之“金”，下列错误的那项是","o":["大肠","湿","西","毛","咳"],"a":1,"e":"五行中金配大肠、西方、皮毛、肺与咳等，肺主皮毛、肺气上逆为咳，皆属金行；湿为长夏主气、脾所恶，五行归属土而非金，故为错误项。大肠为金之腑，西为金之方位，毛属金之五体，咳为金之病候，四项归类均无误"},{"q":"体质偏阳的患者，不宜采用的治法是","o":["甘寒","酸寒","咸寒","清润","温补"],"a":4,"e":"偏阳体质者阳气偏盛、阴精相对不足，易化热伤阴，治宜甘寒、酸寒、咸寒清热滋阴或清润，温补则助阳生火、更耗阴液，故属禁忌。甘寒、酸寒、咸寒均能清热或滋阴降火，清润亦养阴清热，四法皆合偏阳体质，唯温补助火伤阴不宜"},{"q":"五脏中，与血液运行最不密切的是","o":["心","肝","脾","肺","肾"],"a":4,"e":"心主血脉而推动血行，肝藏血并调节血量，脾统血使血不外溢，肺朝百脉辅心行血，四者均直接参与血液运行。肾主藏精、主水，虽精血同源可化生血液，但不直接推动、统摄或调节血行，故与血液运行关系最不密切"},{"q":"“木火刑金”在五行学说中属于","o":["相乘","相侮","相生","子病及母","母病及子"],"a":1,"e":"相侮指五行中某一行过强，反凌克己之行，即以下犯上的反向克制。木本受金克，肝火过旺反灼肺金，见咳嗽、咯血，称木火刑金，属木侮金。相乘是沿相克方向的过度克制，如木乘土；相生及子病及母、母病及子均属相生关系异常，不涉及反克"},{"q":"下列属相侮的是","o":["心病及脾","脾病及肾","脾病及肝","肾病及肺","脾病及心"],"a":2,"e":"相侮为反向克制，脾属土、肝属木，木本克土，脾病反及于肝即土侮木，属相侮。心病及脾为火生土的母病及子，脾病及肾为土克水的相乘，肾病及肺与脾病及心均属母子传变范畴，三者皆非被克者反克克己者，故不属相侮"},{"q":"可直接伤及心神的病因是","o":["风寒","温燥","七情内伤","饮食不洁","房劳过度"],"a":2,"e":"心主神志，七情内伤直接损伤脏腑精气、扰动心神，如暴喜伤心、大怒伤肝并扰动心神，故七情可直接伤及心神。风寒、温燥为外感六淫，多从皮毛口鼻入犯肌表肺卫；饮食不洁损伤脾胃，房劳过度耗伤肾精，均需经脏腑传变才及心神，非直接损伤"},{"q":"六淫中引起筋脉拘挛、屈伸不利、腠理闭塞、气机收敛的邪气是","o":["风邪","寒邪","湿邪","暑邪","火邪"],"a":1,"e":"寒性收引，寒邪侵袭使气机收敛、腠理闭塞、经络筋脉挛急，故见筋脉拘挛、屈伸不利与无汗，符合寒邪致病特点。风邪善行而数变、主疏泄，湿邪重浊黏滞、阻遏气机，暑邪升散耗气伤津，火邪燔灼迫血妄行，均无收引拘挛之性"},{"q":"奇恒之腑的生理特点是","o":["受盛水谷","传化水谷","排泄糟粕","其气象地","其气象天"],"a":4,"e":"官方答案为【其气象天】，但依据教材，正确答案为【其气象地】。《素问·五脏别论》明言脑、髓、骨、脉、胆、女子胞六者藏于阴而象于地、故藏而不泻，是为奇恒之腑；胃、大肠、小肠、三焦、膀胱才是其气象天、故泻而不藏的传化之腑。原答案把传化之腑的特点误加于奇恒之腑，与经典原文相悖。受盛水谷、传化水谷、排泄糟粕皆属六腑泻而不藏的功能，亦非奇恒之腑所长"},{"q":"五心烦热、潮热盗汗、口燥咽干可见于下列何证","o":["邪郁化火","气郁化火","五志过极化火","阴虚火旺","阴火证"],"a":3,"e":"阴虚火旺因体内阴液亏少、虚火内生，见五心烦热、潮热盗汗、口燥咽干，属虚热证。邪郁化火、气郁化火、五志过极化火均属实火，由外邪、气机郁滞或情志过激引发；阴火证为脾胃气虚、阴火上冲，伴身热而渴、脉洪大而虚，均非阴虚潮热盗汗之象"},{"q":"下列表述中属于证的是","o":["水痘","麻疹","风寒感冒","头痛","恶寒"],"a":2,"e":"证是疾病发展过程中某一阶段的病机概括，风寒感冒为外感风寒、邪犯肺卫的证候，故属证。水痘、麻疹为具体病种，属病；头痛既可为症状亦可为病名；恶寒是患者自觉怕冷的症状，均非对病机本质的概括"},{"q":"根据五行学说，下列符合相生关系的是","o":["木生金","火生木","土生水","水生火","金生水"],"a":4,"e":"五行相生次序为木生火、火生土、土生金、金生水、水生木，故金生水符合相生关系。木生金逆相生之序，火生木为木生火之反，土生水、水生火皆颠倒母子关系，唯金生水顺五行相生之次。金生水即肺金滋养肾水，为相生链条中的一环，其余四项均逆相生之序"},{"q":"与语言、声音、呼吸关系最为密切的是","o":["元气","肺气","宗气","中气","心气"],"a":2,"e":"宗气积于胸中，上出息道以行呼吸，贯心脉以行气血，与语言、声音、呼吸的强弱直接相关。元气为生命原动力，根于肾；肺气虽司呼吸，但语言声音的有力与否取决于宗气盛衰；中气指脾胃之气，心气主血脉神明，均非语言声音呼吸的主导"},{"q":"中医学关于“证”的高度概括是","o":["临床症状","疾病原因","病机本质","疾病部位","疾病性质"],"a":2,"e":"证是对疾病过程中某一阶段病理本质的概括，中医学以病机本质高度概括证，涵盖病因、病位、邪正关系。临床症状是证的外在表现，疾病原因、部位、性质仅为病机的组成部分，单独均不足以概括证的整体内涵"},{"q":"下利治法符合“实则泻其子”治则思想的是","o":["肝火旺泻心火","脾火旺泻胆火","肝火旺泻脾","肝火旺泻肺","肺热泻大肠"],"a":0,"e":"实则泻其子指实证泻其五行中我生之子。肝属木，木生火，心属火为肝之子，肝火旺泻心火即泻子，符合治则。脾火旺泻胆火非母子关系，肝火旺泻脾为木乘土，肝火旺泻肺为木侮金，肺热泻大肠为肺与大肠相表里的脏腑论治，均非泻子"},{"q":"肾在液为","o":["唾","泪","汗","涕","涎"],"a":0,"e":"肾在液为唾，唾为肾精所化，咽而不吐有滋养肾精之用。泪为肝之液，汗为心之液，涕为肺之液，涎为脾之液，五脏与五液的配属固定，故唾归于肾而不他属。肾精化生唾液，故咽唾可保肾精，五脏化液各有归属，唾独归于肾"},{"q":"补气药与利水药配合治疗水肿病，依据的理论是","o":["气能生津","气能行津","气能摄津","津能载气","津能生气"],"a":1,"e":"气能行津指气的推动作用是津液输布运行的动力，气虚或气滞则水液停聚为水肿，补气药与利水药同用即本于此。气能生津指气促进津液生成，气能摄津指固摄防外泄，二者不针对水液停滞；津能载气、津能生气言津液对气的作用，与水湿泛滥的治法无涉"},{"q":"《素问·五藏生成篇》说：“多食咸，则（ ）”","o":["脉凝泣而变色","皮槁而毛拔","筋急而爪枯","肉胝皱而唇揭","骨痛而发落"],"a":0,"e":"《素问·五藏生成篇》载多食咸则脉凝泣而变色，咸入肾、过食伤肾，肾水克心火，血脉运行滞涩而色泽改变。皮槁而毛拔为多食苦，筋急而爪枯为多食酸，肉胝皱而唇揭为多食甘，骨痛而发落为多食辛，各有五味所伤，非咸味所致"},{"q":"脾主升清的内涵是","o":["脾之阳气上升心肺","脾气以升为健","脾气将水谷精微上输头面心肺","脾气输布水液于全身","脾气上升防止下出血"],"a":2,"e":"脾主升清指脾气将水谷精微上输于头面心肺，以濡养清窍、化生气血，是脾运化功能的核心环节。脾气以升为健概括脾的功能特性而非升清内涵，输布水液于全身为脾运化水湿之功，上升以防下出血属脾统血范畴，脾之阳气上升心肺表述笼统，均未切中升清要义"},{"q":"下列选项中，属于瘀血导致出血特点的是","o":["出血多见于身体的下部","血色淡，质清稀","伴有气虚症状","出血伴有刺痛拒按","出血时间较长"],"a":3,"e":"瘀血阻滞脉道，不通则痛，故出血伴刺痛、拒按，血色多暗或有块。出血见于下部、血色淡质清稀、伴气虚症状、出血时间较长均为气虚不摄血或脾虚便血等虚性出血特点，与瘀血实性刺痛、拒按的出血性质相反"},{"q":"肺吸入自然界的清气主要依靠","o":["肺气宣发","肺气肃降","肺朝百脉","肺治理调节血液运行","肺治理调节津液代谢"],"a":1,"e":"肺气肃降使肺气向下、向内运行，吸入自然界清气下纳于肾，完成呼吸运动的吸气环节。肺气宣发主呼出浊气、布散津液；肺朝百脉指血液经肺进行气体交换，治理调节血液运行与津液代谢分别为肺辅心行血、通调水道之功，均非吸入清气所依"},{"q":"具有受盛和传化水谷的是","o":["五脏","六腑","脏腑","奇恒之腑","以上均非"],"a":1,"e":"六腑共同的生理特点是受盛和传化水谷，以通为用、泻而不藏，故具受盛传化功能者为六腑。五脏主藏精气而不泻，奇恒之腑虽中空但藏精气，脏腑为五脏六腑的总称，以上均非更不能概括，故均非本题所指"},{"q":"与肾的功能有关的是","o":["主神志","开窍于口","其华在发","在时为春","在体合脉"],"a":2,"e":"肾其华在发，头发的生长与荣枯依赖肾精、肝血的濡养，故发为肾之外候。主神志属心，开窍于口属脾，在时为春属肝，在体合脉属心，四者均非肾的生理联系，唯其华在发归于肾。发为肾之外候，其荣枯可知肾精盛衰，肝血亦充养毛发，但以肾精为本"},{"q":"厥阴经病变，多选择的引经药物是","o":["藁本","葛根","川芎","柴胡","独活"],"a":2,"e":"厥阴经病变常用川芎引经，川芎辛温行散，善入厥阴肝经、上行头目，为厥阴头痛要药。藁本多引太阳经，葛根引阳明经，柴胡引少阳经，独活引少阴经，各归其经，均非厥阴经的引经药。厥阴为肝经，川芎入肝经且上行头巅，故为厥阴头痛引经首选"},{"q":"气的运行受阻而不畅通，称为","o":["气机失调","气滞","气机不畅","气逆","气闭"],"a":2,"e":"气机不畅指气的运行受阻而不够通畅，为气机失常中较轻浅的状态。气机失调是各类气机失常的总称，涵盖过与不及；气滞强调局部郁滞并见胀满疼痛，程度较重；气逆为气升太过或降之不及，气闭为气机闭塞、外出受阻，均非单纯运行不畅"},{"q":"胆汁的正常分泌和排泄主要依赖的是","o":["肝主疏泄","脾主运化","胃主通降","肺主宣降","肾的气化"],"a":0,"e":"胆汁由肝之余气所化，其正常分泌与排泄依赖肝主疏泄调畅气机，肝气疏泄正常则胆汁排泄通畅。脾主运化、胃主通降、肺主宣降、肾的气化分别参与消化、受纳、水道与二便，虽与消化相关，但均非胆汁分泌排泄的直接主导"},{"q":"确立辨证论治理论体系的典籍是","o":["《黄帝内经》","《难经》","《伤寒杂病论》","《神农本草经》","《医宗金鉴》"],"a":2,"e":"《伤寒杂病论》为张仲景所著，创立六经辨证与脏腑辨证，将理、法、方、药融为一体，标志辨证论治理论体系确立。《黄帝内经》奠定理论基础，《难经》补充脉学脏腑，《神农本草经》为药学著作，《医宗金鉴》为清代编纂的教材性医书，均非确立辨证论治之典"},{"q":"创立六经辨证方法的医家是","o":["朱丹溪","张机","张元素","李杲","叶天士"],"a":1,"e":"张机即张仲景，著《伤寒杂病论》，创立六经辨证方法，以三阴三阳概括外感热病发展规律。朱丹溪主滋阴，张元素讲求脏腑辨证，李杲主补脾胃，叶天士创卫气营血辨证，均非六经辨证的创立者。张机即张仲景，六经辨证以太阳、阳明、少阳、太阴、少阴、厥阴统摄外感热病"},{"q":"《灵枢•五癃津液别》所说“天寒衣薄则为溺与气，天热衣厚则为汗”，说明了","o":["人体自身的完整性","自然环境对人体生理的影响","社会环境对人体生理的影响","自然环境对人体病理的影响","社会环境对人体病理的影响"],"a":1,"e":"天寒衣薄则为溺与气、天热衣厚则为汗，说明寒热气候变化影响汗尿生成与排泄，体现自然环境对人体生理的影响。人体自身完整性强调脏腑整体联系，社会环境指人际、制度因素，题干所论为气候而非社会，且属生理调节而非病理变化，故余项不合"},{"q":"观察心主血脉的功能是否正常时，与哪一项关系较小","o":["面色","舌色","脉象","心胸部的感觉","爪色"],"a":4,"e":"心主血脉，其功能是否正常可从面色、舌色、脉象及心胸部感觉等方面观察，面色红润、舌色淡红、脉和缓有力、心胸舒畅为功能正常之象。爪为肝之华，爪色主要反映肝血盛衰，与心主血脉关系较小，故为所选"},{"q":"临床上利小便实大便的理论依据为","o":["小肠的泌别清浊功能","脾的运化功能","肺的通调水道功能","小肠主液功能","小肠的主受盛功能"],"a":0,"e":"小肠泌别清浊将水谷精微与糟粕分开，使水液归于膀胱、糟粕入于大肠，通过利小便使水湿分消、大便成形，故利小便实大便本于此。脾运化、肺通调水道虽参与水液代谢，小肠主液、主受盛亦为其功能之一，均未直接说明大小便分走的机制"},{"q":"根据五行学说，心病及肺属于","o":["母病及子","子病及母","相乘传变","相侮传变","母子同病"],"a":2,"e":"心属火、肺属金，火本克金，心病及肺是沿相克方向的过度克制，属相乘传变。母病及子、子病及母为相生关系异常，如心病及脾、肾病及肺；相侮为反向克制，如肝火犯肺，均非心病及肺的传变方式。心病及肺即心火乘肺金，属相乘传变，与相侮的反向克制判然有别"},{"q":"膀胱生理功能的实现依赖以下哪项与膀胱之气的协调","o":["心气","肾气","肝气","肺气","脾气"],"a":1,"e":"膀胱贮尿排尿依赖肾气气化，肾气充盛则开阖有度，水道通调，膀胱之气与肾气相须为用。心气主血脉神明，肝气主疏泄，肺气主宣降通调水道，脾气主运化升清，虽与津液代谢相关，但均非与膀胱之气直接协调以司开阖者"},{"q":"“正气存内，邪不可干”，主要是指","o":["邪气是发病的重要条件","邪气伤人，正气必然受损","正气充足，与邪相争，驱邪外出","正气旺盛，邪气难以入侵","正气虚弱，邪气不足"],"a":3,"e":"正气存内、邪不可干强调正气旺盛则邪气难以入侵，突出正气在发病中的主导作用。邪气是发病重要条件说的是邪气作用，邪伤人正气必损论及邪气致病后果，正邪相争驱邪外出为发病后正气抗邪，正气虚弱邪气不足则语义不通，均非本句主旨"},{"q":"易患咳嗽、腹泻、食积等证的是","o":["老人","小儿","男性","女性","更年期妇女"],"a":1,"e":"小儿脏腑娇嫩、形气未充，脾常不足、肺常虚，易被外邪与饮食所伤，故易患咳嗽、腹泻、食积等证。老人正气渐虚、机能衰退，男性、女性及更年期妇女虽有各自生理特点，但均无小儿易虚易实、易寒易热与肺脾娇嫩的发病特征"},{"q":"气机升降之“枢”是指哪一种升降关系","o":["肺主呼气，肾主纳气","肝主升，肺主降","脾主升，胃主降","心火下降，肾水上承","脾之主升，肺之主降"],"a":2,"e":"脾主升清、胃主降浊，同居中焦，一升一降为气机升降之枢，与气机升降之枢及枢纽诸问同义。肺主呼气肾主纳气属呼吸升降，肝升肺降调全身气机，心火下降肾水上承为水火既济，脾主升肺主降并非中焦升降相因之枢"},{"q":"真虚假实证的治疗原则应是","o":["单独祛邪","单独扶正","先扶正后祛邪","扶正兼祛邪","祛邪扶正并重"],"a":1,"e":"真虚假实证本质为虚，虽见腹胀、闭满等类似实证的假象，仍当单独扶正，补其不足则假象自除。单独祛邪、祛邪扶正并重用于真实假虚或虚实夹杂；先扶正后祛邪、扶正兼祛邪适用于正虚邪恋、虚实夹杂，均非纯虚之证所宜"},{"q":"心气推动和调控血液在脉道中运行的功能概括为","o":["心生血","心主血脉","心主藏神","心为生之本","心主通明"],"a":1,"e":"心主血脉指心气推动和调控血液在脉道中运行，心气充沛则搏动有力、脉象和缓，血行通畅。心生血说法不确，心主藏神为心主神明之功，心为生之本言其重要性，心主通明指心阳温煦，均未概括推动调控血行这一核心功能"},{"q":"只有外感而无内生的邪气是","o":["风邪","寒邪","湿邪","暑邪","燥邪"],"a":3,"e":"暑邪为夏季主气，纯属外感，无内生之说，故只有外感而无内生者为暑邪。风、寒、湿、燥既可外感六淫，亦可因脏腑功能失调内生，称内风、内寒、内湿、内燥，均有内外两途，唯暑邪例外。暑邪纯属外感，夏至后立秋前感之，无内生暑邪之说，与他邪迥异"},{"q":"下列病因中，最有可能导致气脱的是","o":["伤寒","失血","饱食","痰饮","疠气"],"a":1,"e":"失血过多使气随血脱，气无所附而大量外亡，故最易导致气脱，正是血能载气之理。伤寒多伤阳气或化热，饱食伤脾胃运化，痰饮为病理产物阻遏气机，疠气为烈性传染病邪，均不以气随血脱的亡失为突出病机"},{"q":"下列哪种说法与三焦有关","o":["太仓","五脏之本","中精之腑","孤府","中正之官"],"a":3,"e":"三焦无表里配对，有名无形，包罗五脏六腑之外，故称孤府。太仓指胃，为受纳水谷之腑；五脏之本说法不一，多指肾或脾胃；中精之腑指胆，因其藏精汁；中正之官亦指胆，主决断，均非三焦之称。三焦包罗诸脏、通行元气，有名无形，故独称孤府，与有形之腑不同"},{"q":"金元四大家中，倡导疾病多与脾胃内伤有关的医家是","o":["张元素","刘完素","张从正","朱丹溪","李东垣"],"a":4,"e":"李东垣为金元四大家补土派，著《脾胃论》，倡百病皆由脾胃衰而生，强调脾胃内伤是诸多疾病之源。张元素重脏腑辨证，刘完素主寒凉，张从正主攻邪，朱丹溪主滋阴，四家虽各有创见，但以脾胃内伤立说者唯李东垣"},{"q":"大肠为","o":["元神之府","玄府","血府","孤府","传导之府"],"a":4,"e":"大肠主传导糟粕，故称传导之府，形质中空、以通为用，主排泄粪便。元神之府指脑，玄府为汗孔等细微孔窍，血府指脉，孤府指三焦，四者各有专指，均与大肠的传导功能不相涉。大肠传导糟粕、排泄粪便，故称传导之府，以通降为顺，与五脏藏精气有别"},{"q":"五行学说中“土”的特性是","o":["曲直","炎上","从革","润下","稼穑"],"a":4,"e":"五行中土爰稼穑，播种收获体现生化、承载、受纳之性，故土之特性为稼穑。曲直为木之特性，炎上属火，从革属金，润下属水，五者各归其行，唯稼穑专属于土。稼穑指种植收获，合土生化承载之性，五行特性各有专指，土独以稼穑概括"},{"q":"中医学象思维的特征是","o":["形象思维","意象思维","应象思维","抽象思维","逻辑思维"],"a":1,"e":"中医学象思维以物象为基础、取象比类以通达意象，其核心特征为意象思维，通过象征与类比把握对象的功能与关系。形象思维偏于具体形象，抽象思维、逻辑思维侧重概念推演，应象思维强调天人相应，均非中医学象思维的核心概括"},{"q":"六淫中易袭阳位，具有轻扬开泄特性的外邪是","o":["风邪","寒邪","湿邪","暑邪","火邪"],"a":0,"e":"风邪轻扬开泄，善行而数变，易袭阳位，常伤及人体上部、肌表与肺卫，见头痛、汗出、恶风等。寒邪收引，湿邪重浊趋下，暑邪升散伤津，火邪炎上燔灼，虽多犯阳位或上部，但轻扬开泄、易袭阳位为风邪独有之性"},{"q":"气机升降出入的枢纽是","o":["肝、肺","肺、肾","脾、胃","肝、胆","心、肾"],"a":2,"e":"脾主升清、胃主降浊，二者同居中焦，一升一降为全身气机升降出入的枢纽。肝升肺降调畅全身气机，肺肾协调呼吸出纳，肝胆共主疏泄，心肾相交水火既济，虽皆参与气机调节，但不居中焦升降之枢。脾胃居中焦，为气机升降之枢，肝升肺降则为全身气机调节，二者层次不同"},{"q":"中医认识发病原理，主要从以下哪个角度来认识","o":["正邪相搏","阴阳失调","饮食失调","气血失常","脏腑功能失调"],"a":0,"e":"中医认识发病原理主要从正邪相搏入手，正气不足为发病内在根据，邪气为重要条件，正邪交争决定疾病发生与转归。阴阳失调、气血失常、脏腑功能失调均为发病后的病机变化，饮食失调仅为致病因素之一，均未概括发病的基本原理"},{"q":"关于湿浊内生的论述错误的是","o":["与肺、脾、肾等脏腑调节水液代谢功能失调有关","与脾的关系最为密切","脾肾阳虚会导致湿浊内生","临床可见头重如裹、肢体重浊等表现","不会引起痉病"],"a":4,"e":"湿浊内生与肺、脾、肾调节水液代谢功能失调相关，脾虚失运最为关键，可见头重如裹、肢体重浊等症，湿浊亦可酿痰化热、引动肝风而致痉病，故不会引起痉病错误。其余各项分别说明湿浊的脏腑相关性、脾的主导地位、阳虚生湿的机理及典型表现，均属正确论述"},{"q":"中医学认为人类寿命的自然限度是","o":["80岁","90岁","100岁","110岁","120岁"],"a":4,"e":"中医学认为人类寿命的自然限度为一百二十岁，此即《黄帝内经》尽终其天年、度百岁乃去之谓。八十、九十、百岁多为对百岁的约称或不同说法，一百一十岁无经典依据，均非天年的定数。天年一百二十岁为《内经》定论，其余说法或为约数，或无经典依据"},{"q":"天癸的产生主要取决于","o":["肾中精气的充盈","脾气的健运","肾阳的蒸腾气化","肝血的充足","肾阴的濡润滋养"],"a":0,"e":"天癸是肾中精气充盈到一定程度产生的促进生殖发育的精微物质，故其产生主要取决于肾中精气的充盈。脾气健运为后天充养，肾阳蒸腾气化、肾阴濡润滋养是肾中精气作用的不同方面，肝血充足亦参与生殖，但皆非天癸产生的直接决定因素"},{"q":"下列各项，属阳的是","o":["地","水","静","气","形"],"a":3,"e":"气属阳，无形而主动，具有推动、温煦作用，故属阳。地、水、静、形均属阴的范畴，地与水为有形重浊之物，静为相对稳定之态，形为有形质之体，四者与气的主动、升散之性相反。气主动、主升散属阳，形质重浊、安静内守属阴，阴阳属性以此划分"},{"q":"患者，男，56岁。因情急恼怒而突发头痛而胀，继则昏厥仆倒，呕血，不省人事，肢体强痉，舌红苔黄，脉弦。其病机是","o":["气郁","气逆","气脱","气陷","气结"],"a":1,"e":"恼怒伤肝，肝气上逆，气逆于上则血随气涌，见头痛而胀、呕血，气血并走于上则可昏厥仆倒、不省人事，故病机为气逆。气郁为气机郁结，气脱为气大量亡失，气陷为清阳不升，气结为气机结聚，均无气血上涌、血随气逆的呕血昏厥之象"},{"q":"与精神意识思维活动关系最密切的是","o":["心主血脉的生理功能","肝主疏泄的生理功能","脾主运化的生理功能","肺主治节的生理功能","肾主藏精的生理功能"],"a":0,"e":"精神意识思维活动由心所主，心主血脉使血行濡养全身、心神得养，故在所列脏腑功能中关系最密切的是心主血脉的生理功能。肝主疏泄仅调畅情志，脾主运化、肺主治节、肾主藏精分别主消化、治节与藏精，皆非精神思维的主导"},{"q":"相为表里的手经交接的部位是","o":["腹","足","胸","头","手"],"a":4,"e":"相为表里的经脉在四肢末端交接，手经与手经交接于手指、手部，故手经表里交接部位为手。腹、胸多为足经与脏腑联系之处，足为足经交接之所，头为诸阳经会聚之处，均非手经表里相交接的部位。手经表里交接于手指，足经交接于足趾，头为诸阳之会，非表里经交接处"},{"q":"《灵枢·营卫生会》谓年轻人“昼精夜瞑”的原因，错误的是","o":["营卫调和","气血充盛","脾胃健运","肌肉滑利","气道通畅"],"a":2,"e":"《灵枢·营卫生会》论年轻人昼精夜瞑，因营卫调和、气血充盛、肌肉滑利、气道通畅，卫气昼行于阳、夜行于阴，睡眠与觉醒规律正常。脾胃健运并非该篇所列原因，气血充盛有赖脾胃，但此处强调营卫运行的通畅与调和，故脾胃健运为错误项"},{"q":"《针灸甲乙经》的作者是","o":["张仲景","王叔和","皇甫谧","孙思邈","陈无择"],"a":2,"e":"《针灸甲乙经》为西晋皇甫谧所撰，是中国最早的针灸学专著，系统整理经络腧穴与针灸疗法。张仲景著《伤寒杂病论》，王叔和著《脉经》并整理《伤寒论》，孙思邈著《千金方》，陈无择著《三因极一病证方论》，均非《针灸甲乙经》作者"},{"q":"循行分布特点可用“离、合、出、入”加以概括的是","o":["正经","奇经","十五别络","十二皮部","十二经别"],"a":4,"e":"十二经别从十二正经别出，有离、合、出、入的分布特点，深入体腔以加强表里经联系，故可用此四字概括。正经为循行主干，奇经八脉无表里关系，十五别络主体表沟通，十二皮部为络脉之气散布部位，均不以离合出入概括"},{"q":"与肺相表里的是","o":["大肠","小肠","胃","三焦","胆"],"a":0,"e":"肺与大肠相表里，手太阴肺经与手阳明大肠经相互络属，故与肺相表里者为大肠。小肠与心相表里，胃与脾相表里，三焦与心包相表里，胆与肝相表里，四者各有配对，均不与肺相配。肺与大肠经脉络属互为表里，肺气肃降有助于大肠传导，故二者相配"},{"q":"下列各项，适合用温法的是","o":["素体阴虚","素体血虚","孕妇","虚寒证","神昏"],"a":3,"e":"温法能温里散寒、补火助阳，适用于虚寒证，通过温补阳气以祛除里寒。素体阴虚、血虚者温药易伤阴动血，孕妇用温热药须慎防动胎，神昏多属热闭或痰蒙，非温法所宜，四者均非温法的适应证。温法专为里寒而设，虚寒者宜之，热证、阴虚及孕妇均当慎用或禁用"},{"q":"肝主藏","o":["魂","神","魄","志","意"],"a":0,"e":"肝藏魂，魂随神往来，肝血充足则魂有所舍，睡眠与梦境正常。心藏神，肺藏魄，肾藏志，脾藏意，五脏所藏之神志各有定属，魂归于肝而不他属。肝藏血、血舍魂，肝血足则魂安，五脏各有所藏，魂独归肝而不他属"},{"q":"中医养生学认为探索衰老机制的中心环节是","o":["肾中精气的盛衰","心肺的功能状态","脾胃运化功能的强弱","肝肾精血互化的状态","肾中精气的盛衰和脾的功能状态"],"a":4,"e":"衰老机制以肾中精气盛衰为根本，肾藏精主生长壮老已；脾胃为后天之本、气血生化之源，脾虚则精血亏虚、加速衰老，故探索衰老机制以肾中精气盛衰和脾的功能状态为中心环节。心肺功能、肝肾精血互化及单论肾精或单论脾胃，均只涉及局部，未涵盖先后天并重的核心"},{"q":"“中焦如沤”是描绘","o":["胃的受纳功能","脾的散精功能","小肠泌别清浊功能","脾胃、肝胆等脏腑的消化饮食物的生理过程","心、肺输布气血的作用"],"a":3,"e":"中焦如沤指中焦脾胃、肝胆等脏腑共同完成饮食物的消化、吸收与转输，如沤渍发酵以化生精微。胃的受纳、脾的散精、小肠泌别清浊仅为其中一环，心肺输布气血属上焦功能，均不足以概括中焦消化饮食物的整体过程"},{"q":"全身的气机主要靠哪两脏调节","o":["心与肝","心与肺","肝与脾","肝与肺","肝与肾"],"a":3,"e":"全身气机的升降主要靠肝与肺调节，肝主升发、肺主肃降，一升一降协调周身气机。心与肝主血脉与疏泄，心与肺主血与气，肝与脾主疏泄与运化，肝与肾主疏泄与封藏，虽各有关联，但不构成气机升降的主要调节者"},{"q":"“脾为气血生化之源”主要的理论依据是","o":["脾主升","脾主统血","朝百脉","脾恶湿","脾主运化"],"a":4,"e":"脾主运化水谷精微，将其化生为气血，故为气血生化之源；运化功能健旺则气血有源。脾主升清指精微上输，脾主统血指固摄血液，脾恶湿言其特性，朝百脉为肺的功能，均非气血生化之源的理论依据。脾运化水谷精微是气血化生的物质基础，故称后天之本、气血生化之源"},{"q":"脾为气血生化之源的理论依据是","o":["气能生血","人以水谷为本","脾主升清","脾能运化水谷精微","脾胃为后天之本"],"a":3,"e":"脾能运化水谷精微，将饮食化为气血，故称气血生化之源，其依据在运化功能本身。气能生血论气对血的生成作用，人以水谷为本强调饮食重要，脾主升清、脾胃为后天之本均为相关论述，但未直接指出运化水谷精微这一核心机制"},{"q":"在五行学说中，五气中的“风”归属于","o":["木","火","土","金","水"],"a":0,"e":"五气中风、暑、湿、燥、寒分别配木、火、土、金、水，风属春气，善行而数变，与木的生发、条达之性相类，故风归属于木。火、土、金、水分配暑、湿、燥、寒，各有五行归属，风不属之。风属木，与春气相应，善行而数变，正合木主升发条达之性"},{"q":"治疗阴虚证时，在滋阴剂中适当佐用扶阳药，使“阴得阳升而泉源不竭”，这可概括为","o":["阴阳并补","阴中求阳","阳中求阴","扶阳抑阴","阴病治阳"],"a":2,"e":"阳中求阴指在滋阴剂中适当佐用扶阳药，使阳气生发以助阴液化生，即阴得阳升而泉源不竭，适用于阴虚证。阴中求阳为补阳剂中佐滋阴药；阴阳并补用于阴阳两虚；扶阳抑阴、阴病治阳针对阳虚阴盛，均非滋阴佐扶阳之法"},{"q":"中焦的功能实际是指","o":["脾主运化的功能","胃的受纳功能","脾、胃受纳腐熟水谷，化生气血的功能","化生血液","输布水谷精微"],"a":2,"e":"中焦的功能实际指脾、胃受纳腐熟水谷并化生气血，涵盖饮食的消化、吸收与精微转输。单论脾主运化或胃的受纳仅及一面，化生血液、输布水谷精微为中焦功能的一部分，均未全面概括受纳腐熟、化生气血的整体过程"},{"q":"瘀血所致疼痛的特点是","o":["胀痛","窜痛","灼痛","刺痛","冷痛"],"a":3,"e":"瘀血阻滞脉道，不通则痛，其痛如针刺、部位固定、拒按，故瘀血所致疼痛特点为刺痛。胀痛多属气滞，窜痛为气机走窜或风邪，灼痛属热邪或阴虚火旺，冷痛属寒邪或阳虚，四者病机各异，均非瘀血刺痛"},{"q":"《灵枢·本脏》所说“分肉解利，皮肤润柔，腠理致密”，主要取决于","o":["营卫和调","卫气和利","营气和利","宗气充盛","元气充盛"],"a":1,"e":"《灵枢·本脏》以分肉解利、皮肤润柔、腠理致密描述卫气和利，卫气温分肉、充皮肤、肥腠理、司开阖，卫气和则腠理固密。营卫和调、营气和利、宗气充盛、元气充盛虽与人体防御相关，但分肉、皮肤、腠理的润泽致密直接取决于卫气和利"},{"q":"肺气中具有凉润、沉降作用的部分称为","o":["肺气","肺阳","肺精","肺阴","肺津"],"a":3,"e":"肺阴为肺气中具凉润、沉降作用的部分，能滋润肺体、制约肺气之温燥，使宣降有度。肺气泛指肺的功能活动，肺阳偏温煦，肺精、肺津重在濡润，但未突出凉润与沉降并重的特性，故以肺阴为确。肺阴肺阳分主凉润与温煦，肺阴不足则干咳、咽干、潮热，故以肺阴为沉降凉润者"},{"q":"中医学“治未病”的预防思想，最早见于","o":["《内经》","《难经》","《中藏经》","《伤寒杂病论》","《诸病源候论》"],"a":0,"e":"治未病的预防思想最早见于《内经》，《素问·四气调神大论》有圣人不治已病治未病之论，强调未病先防、既病防变。《难经》《中藏经》《伤寒杂病论》《诸病源候论》虽各有预防论述，但均晚于《内经》且非首见"},{"q":"“大法春宜吐”所体现的思想是","o":["因病制宜","因地制宜","因人制宜","因时制宜","因证制宜"],"a":3,"e":"大法春宜吐指春季阳气升发，宜用吐法顺应天时以祛邪，体现因时制宜。因病制宜针对具体病证，因地制宜据地域，因人制宜依体质年龄性别，因证制宜随证候化裁，四者均未体现春这一季节时令对治法的选择"},{"q":"脾虚所致的出血，可以通过健脾益气的方法来治疗，其理论依据是","o":["气能生血","气能行血","气能摄血","血能养气","血能载气"],"a":2,"e":"气能摄血指气固摄血液使之循行脉中而不外溢，脾虚气弱、统摄无权则血溢脉外而出血，健脾益气可复其摄血之职，故本于此。气能生血、气能行血分别指气促生血与推动血行，血能养气、血能载气言血对气的作用，均非脾虚出血用健脾益气的依据"},{"q":"以下不属于广义之精的是","o":["精","津","血","液","气"],"a":4,"e":"广义之精指构成人体和维持生命活动的一切精微物质，包括精、血、津、液，故气不属广义之精。精、津、血、液皆为有形有质的精微，属广义之精范畴，气虽为生命基本物质，但无形而主推动温煦，与精的精微物质属性不同"},{"q":"津液化为汗液排出体外，主要靠哪脏功能","o":["心主血脉","肺主宣发","肾主气化","肝主疏泄","脾主统摄"],"a":1,"e":"津液化为汗液排出体外，主要依赖肺主宣发，肺气宣发将津液输布至体表，经汗孔排泄为汗，并调节腠理开阖。心主血脉、肾主气化、肝主疏泄、脾主统摄分别参与血行、水液气化、气机调畅与血液固摄，均非汗液排泄的直接主导"},{"q":"体现事物阴阳属性的相对性的是","o":["对立制约","互根互用","互为消长","平衡协调","互相转化"],"a":4,"e":"阴阳在一定条件下可相互转化，如寒极生热、热极生寒，说明阴阳属性并非固定不变，体现其相对性。对立制约言阴阳相反相制，互根互用言相互依存，互为消长言量变，平衡协调言动态稳态，均未直接体现属性的相对与可变"},{"q":"五脏中称为“刚脏”的是","o":["心","脾","肺","肝","肾"],"a":3,"e":"肝为刚脏，肝气主升主动，性喜条达而恶抑郁，肝阳易亢、肝风易动，故以刚脏称之。心为阳中之阳主神明，脾为气机升降之枢，肺为娇脏易受外邪，肾主封藏为封藏之本，四者特性各异，均不称刚脏。肝气升动、易亢易逆，故以刚脏称之，与肺为娇脏、肾主封藏相对"},{"q":"体质的可变性与什么有关","o":["先天禀赋","后天因素","思维改变","智慧","阴虚体质"],"a":1,"e":"体质在先天禀赋基础上形成，后天因素如饮食、起居、环境、锻炼、疾病等可使体质发生改变，故体质的可变性与后天因素相关。先天禀赋决定体质基础而相对稳定，思维改变、智慧属精神层面，阴虚体质为体质类型之一，均非可变性的依据"},{"q":"肺与脾的关系，主要表现于","o":["气的生成和津液的输布代谢","气的生成","津液的输布代谢","血的生成","血的生成和津液的输布代谢"],"a":0,"e":"肺与脾的关系主要表现于气的生成与津液的输布代谢，肺吸入清气、脾运化水谷精微，二者合为宗气；脾运化水湿、肺通调水道，共同完成津液代谢。仅论气的生成或血的生成均片面，血的生成虽与脾相关但非肺脾关系的核心，故以二者并重为确"},{"q":"经络之间联系最主体的联系方式是","o":["十二经脉首尾衔接环周无端的联系","十二经脉相互间的交叉交会联系","奇经八脉自身之间的联系","十二经脉与奇经八脉之间的联系","经别、别络、浮络、孙络之间的联系"],"a":0,"e":"经络之间最主体的联系方式是十二经脉首尾衔接、环周无端，构成气血运行的主干通道。经脉交叉交会、奇经自身联系、经脉与奇经的联系及经别、别络、浮络、孙络的联系均为络属或辅助联系，非最主要方式，故以首尾衔接环周无端为答案"},{"q":"认识外感寒邪的疾病发展规律的病机理论是","o":["六经病机","三焦病机","卫气营血病机","脏腑病机","气血津液病机"],"a":0,"e":"六经病机以三阴三阳概括外感寒邪由表入里、由阳转阴的发展规律，是认识外感寒邪疾病发展规律的病机理论。三焦病机论湿热，卫气营血病机论温热，脏腑病机、气血津液病机分别论脏腑与气血津液失常，均非针对外感寒邪发展规律"},{"q":"生长发育迟缓、生殖功能减退的病机定位是","o":["心","肺","脾","肝","肾"],"a":4,"e":"肾藏精，主生长发育与生殖，肾精充盛则生长发育正常、生殖功能旺盛，肾精亏虚则见生长发育迟缓、生殖功能减退，故病机定位在肾。心主血脉神明，肺主气，脾主运化，肝主疏泄藏血，虽各有所主，但均非生长发育与生殖的主导"},{"q":"寒邪、湿邪的共同致病特点是","o":["损伤阳气","阻遏气机","病程缠绵","黏腻重浊","凝滞收引"],"a":0,"e":"寒邪、湿邪均为阴邪，易伤人体阳气，寒邪凝滞收引，湿邪重浊黏滞，此为二者共同致病特点。阻遏气机主要为湿邪，病程缠绵、黏腻重浊为湿邪特征，凝滞收引为寒邪独有，均非两者共有。寒湿皆为阴邪，同能耗伤阳气，但凝滞收引属寒、重浊黏滞属湿，各有侧重"},{"q":"除哪项外均属于疠气性质及致病特点","o":["传染性强","致病性强","气候反常","流行性强","病情危笃"],"a":2,"e":"疠气具有传染性强、致病性强、流行性强、病情危笃等特点，气候反常是其产生与流行的条件而非致病特点，故不属疠气性质及致病特点。其余四项分别从传染性、致病力、流行性与病情轻重描述疠气，均属其致病特点"},{"q":"关于清法，下列说法错误的是","o":["温者清之","具有泻火、解毒、凉血作用","适用于脏腑诸火","适用于里热证、火证、热毒证","一般可以久用"],"a":4,"e":"清法具有泻火、解毒、凉血作用，适用于里热证、火证、热毒证及脏腑诸火，体现温者清之的治则。清法易伤脾胃阳气、耗伤津液，中病即止，不可久用，故一般可以久用错误，其余各项均为清法的正确论述"},{"q":"在水液代谢、呼吸运动及阴阳互资等方面密切相关的两脏是","o":["心与肺","脾与肾","肾与肝","肝与肺","肺与肾"],"a":4,"e":"肺与肾在水液代谢、呼吸运动及阴阳互资方面密切相关，肺通调水道、肾主水，肺主呼气、肾主纳气，肺阴肾阴相互滋养。心与肺主气血，脾与肾主先后天，肾与肝主精血，肝与肺主气机升降，均不同时具备水液、呼吸与阴阳互资三方面联系"},{"q":"按五行属性分类，五化中属土者是","o":["生","长","化","收","藏"],"a":2,"e":"五化生、长、化、收、藏分别配木、火、土、金、水，土主生化、承载，故属土者为化。生属木，长属火，收属金，藏属水，四者各有五行归属，唯化归于土。化属土，应长夏生化之令，生发属木、长旺属火、收敛属金、闭藏属水"},{"q":"内湿的形成与何脏关系最为密切","o":["心","肝","脾","肺","肾"],"a":2,"e":"内湿的形成与脾关系最为密切，脾主运化水湿，脾虚失运则水湿内停，故有诸湿肿满皆属于脾之说。心主血脉，肝主疏泄，肺主通调水道，肾主水，虽参与水液代谢，但内湿生成的中心环节在脾的运化失职"},{"q":"上出息道的气是","o":["元气","宗气","营气","卫气","脏腑之气"],"a":1,"e":"宗气积于胸中，上出息道以行呼吸，下走气街以资先天，故上出息道的气为宗气。元气根于肾、通过三焦布散，营气与血同行，卫气散于胸腹、熏于肓膜，脏腑之气为各脏腑功能活动，均非上出息道之气"},{"q":"心气不足时会出现","o":["心脏搏动有力","脉象和缓有力","心脏搏动无力","面色红赤","精神恍惚"],"a":2,"e":"心气不足则心脏搏动无力、脉象虚弱，气血运行失于推动，故见心脏搏动无力。心脏搏动有力、脉象和缓有力为心气充沛之象，面色红赤多属热象或心火，精神恍惚多属心神失养或痰蒙，均非心气不足的典型表现"},{"q":"肾在志为","o":["怒","思","喜","恐","悲"],"a":3,"e":"肾在志为恐，恐伤肾，过度恐惧可使肾气不固、二便失禁。怒归肝，思归脾，喜归心，悲归肺，五脏与情志的配属固定，恐归于肾而不他属。恐为肾志，恐伤肾则气下，精髓不固，五脏五志各有定属，恐独归于肾"},{"q":"心的病机特点是","o":["血脉运行失常和神志意识改变","神志意识改变和呼吸功能失常","主气功能失常和血液运行不畅","血液统摄失常和神志意识改变","气血运行失和和神志意识改变"],"a":0,"e":"心主血脉、主神明，故心的病机特点为血脉运行失常和神志意识改变，如心悸、胸闷、失眠、神昏等。呼吸功能失常属肺，主气功能失常属肺，血液统摄失常属脾，气血运行失和表述笼统，均非心病机特点的准确概括"},{"q":"悲伤过度主要损伤的脏腑是","o":["肝","心","脾","肺","肾"],"a":3,"e":"悲伤伤肺，过度悲伤使肺气消耗、宣降失常，见气短、咳嗽、精神不振，故悲伤过度主要损伤肺。肝主怒，心主喜，脾主思，肾主恐，五脏与情志各有对应，悲不归肝、心、脾、肾，唯伤于肺。悲忧伤肺，肺气耗散则气短乏力，五脏五志配属固定，悲不归他脏"},{"q":"人的精神思维活动与哪个脏腑的功能最为密切","o":["心主神志","肺朝百脉","脾主统血","肝主藏血","肾主藏精"],"a":0,"e":"心主神志，人的精神、意识、思维活动由心主宰，心血充足、心神得养则神志清晰、思维敏捷。肺朝百脉辅心行血，脾主统血，肝主藏血调血量，肾主藏精生髓充脑，虽间接相关，但均非精神思维活动的主导脏腑功能"},{"q":"下列哪项不是脾的生理功能","o":["水谷的受纳和腐熟","水谷的精微的传输","水液的吸收和转输","脏器位置的维系","血液的统摄"],"a":0,"e":"水谷的受纳和腐熟是胃的生理功能，胃主受纳、腐熟水谷，不属于脾的功能。脾主运化，传输水谷精微、吸收转输水液；脾气主升以维系脏器位置；脾主统血以固摄血液，三者均为脾的生理功能。受纳腐熟属胃，脾主运化、升清、统血，二者分工明确，故受纳腐熟非脾所主"},{"q":"“利小便而实大便”的理论依据是","o":["脾主运化","肺主通调水道","小肠主受盛","小肠主化物","小肠主泌别清浊"],"a":4,"e":"小肠主泌别清浊，将水谷精微与糟粕分开，使水液入膀胱、糟粕入大肠，故利小便而实大便的理论依据在于此。脾主运化、肺主通调水道参与水液代谢但不直接分管大小便，小肠主受盛、主化物表述笼统，均未切中泌别清浊这一机制"},{"q":"温燥病的发病季节是","o":["夏末初秋","近冬深秋","长夏季节","冬末春初","春末夏初"],"a":0,"e":"温燥病发于夏末初秋，此时余热未消、燥与热结，感受温燥则见发热、咽干、干咳少痰等。近冬深秋多发凉燥，长夏季节多发湿邪，冬末春初多发风温，春末夏初多发风湿，四者与温燥的发病时令不同。温燥趁夏末余热而发，凉燥因深秋寒凉而成，二者同属燥邪而寒热属性不同"},{"q":"痰与饮的主要区别是","o":["热者为痰，寒者为饮","在体内为痰，在体表为饮","黏稠者为痰，清稀者为饮","色黄者为痰，色白者为饮","量多者为痰，量少者为饮"],"a":2,"e":"痰与饮均为水液代谢失常的病理产物，稠厚者为痰，清稀者为饮，质地清稠是二者主要区别。寒热、部位、颜色、量的多少均可随病情变化，并非区分痰饮的本质标准，如痰亦可寒、饮亦可热，均不足以作为主要区别"},{"q":"根据五行学说，未按五行相生顺序排列的是","o":["青、赤、黄、白、黑","筋、脉、肉、皮、骨","呼、笑、歌、哭、呻","酸、苦、甘、辛、咸","角、徵、商、宫、羽"],"a":4,"e":"五音角、徵、宫、商、羽对应木、火、土、金、水，按相生顺序应为角、徵、宫、商、羽，题中角、徵、商、宫、羽将商、宫颠倒，未按相生顺序排列。青赤黄白黑、筋脉肉皮骨、呼笑歌哭呻、酸苦甘辛咸均依次配木火土金水，排列无误"},{"q":"防止食复不包括","o":["饮食宜有营养","饮食应清淡","饮食宜易消化","饮食宜以温热性的食品为主","饮食应注意护养胃气"],"a":3,"e":"防止食复要求饮食有营养、清淡、易消化，并注意护养胃气，以助脾胃恢复，避免疾病复发。饮食不必以温热性食品为主，当据病证寒热与脾胃承受能力选择，过用温热反助邪生热，故该项不属于防止食复的要求"},{"q":"肺宣发功能异常时会出现","o":["尿量增多","汗量异常","食量正常","月经量异常","大便量异常"],"a":1,"e":"肺主宣发，将津液输布至体表并调节汗孔开阖，宣发功能异常则汗液排泄失常，见汗量异常或无汗、多汗。尿量增多与肺肃降、肾气化相关，食量、大便量主要关乎脾胃，月经量涉及肝脾冲任，均非肺宣发异常的直接表现"},{"q":"气之本是","o":["肝","心","脾","肺","肾"],"a":3,"e":"肺为气之本，肺主气司呼吸，吸入清气、呼出浊气，并参与宗气生成，故气之本在肺。肝主疏泄，心主血脉神明，脾为气血生化之源，肾为气之根主纳气，四者虽与气相关，但气之本专指肺而言。肺主气司呼吸，为气之本，肾纳气为气之根，二者分工，本在肺"},{"q":"与睡眠有密切关系的是","o":["元气","宗气","脏腑之气","经络之气","卫气"],"a":4,"e":"卫气昼行于阳、夜行于阴，卫气循行出入阴阳的规律决定睡眠与觉醒，故与睡眠关系密切的是卫气。元气为原动力，宗气司呼吸行气血，脏腑之气、经络之气分别为脏腑经络功能，均未直接主司睡眠的昼夜节律"},{"q":"下列各项，消法适用的病证是","o":["气滞中满之鼓胀","脾虚而腹胀","妇人血枯经闭","饮食停滞","阴虚热病"],"a":3,"e":"消法适用于饮食停滞、癥瘕积聚等实邪结聚之证，通过消食导滞、软坚散结以祛邪。气滞中满之鼓胀、脾虚腹胀宜行气或补益，妇人血枯经闭属虚当补，阴虚热病宜滋阴清热，均非消法所宜。消法针对有形实邪结聚，饮食停滞宜消食导滞，虚证、阴虚当补不宜消"},{"q":"下列说法正确的是","o":["女子以肝为先天，属阴，以血为用","女子以肾为先天，属阴，以气为用","男子以肝为先天，属阳，以血为用","男子以肝为先天，属阳，以气为用","男子以肾为先天，属阳，以血为用"],"a":0,"e":"女子以肝为先天，肝主藏血、主疏泄，女子以血为用，经、孕、产、乳皆耗血，故属阴、以血为用。以肾为先天、以气为用及男子以肝或肾为先天的诸种说法，均不符合女子以肝为先天、属阴、以血为用的经典认识"},{"q":"患者年高体衰，病属虚寒，久已卧床不起。今日晨起突然面色泛红，烦热不宁，语言增多，并觉口渴，舌淡，脉大而无根。其病机是","o":["阴盛格阳","阳虚阴盛","阳损及阴","阳气亡失","阴阳离决"],"a":0,"e":"久病虚寒、卧床不起者突然面红、烦热、语言增多、口渴，但舌淡、脉大而无根，为阴寒内盛、虚阳被格于外的真寒假热，即阴盛格阳。阳虚阴盛仅为虚寒本象，阳损及阴为阴阳俱虚，阳气亡失、阴阳离决为危亡之象，均无此虚阳浮越的假热表现"},{"q":"素体津亏血耗者，易致邪从","o":["寒化","热化","燥化","湿化","火化"],"a":2,"e":"素体津亏血耗者，体内津液不足，邪气易从燥化，化燥伤津更甚，故易致邪从燥化。寒化多见于阳虚阴盛之体，热化、火化多见于阳盛阴虚或感受热邪，湿化多见于脾虚湿盛之体，与津亏血耗的体质不相契合"},{"q":"十二经脉之气结、聚、散、络于关节的体系者为","o":["浮络","十二经筋","十五别络","孙络","十二经别"],"a":1,"e":"十二经筋是十二经脉之气结、聚、散、络于筋肉关节的体系，主司筋肉关节的运动，故符合结、聚、散、络于关节的特点。浮络为浮于体表的络脉，十五别络主加强表里联系，孙络为络之细小分支，十二经别主离合出入，均非经筋之属"},{"q":"瘀血最常见最特异性的指征为","o":["舌质紫暗，有瘀点瘀斑","疼痛","出血","肿块","失眠"],"a":0,"e":"瘀血最常见且最具特异性的指征是舌质紫暗、有瘀点瘀斑，舌象直接反映血脉瘀滞。疼痛、出血、肿块虽为瘀血常见表现，但可见于气滞、气虚、痰凝等多种病机，特异性不足；失眠与瘀血关系更远，均非最特异指征"},{"q":"肺主通调水道的功能主要依赖于","o":["肺主一身之气","肺司呼吸","肺输精于皮毛","肺朝百脉","肺主宣发与肃降"],"a":4,"e":"肺主通调水道依赖肺主宣发与肃降，宣发将津液输布体表、调节汗液，肃降使水液下输肾与膀胱、维持水道通调。肺主一身之气、司呼吸、输精于皮毛、朝百脉虽为肺的功能，但均未直接说明通调水道所依赖的宣降运动"},{"q":"属于病理产物类致病因素的是","o":["湿邪","火邪","药误","结石","胎毒"],"a":3,"e":"病理产物类致病因素包括痰饮、瘀血、结石等，结石为水液代谢异常、湿热煎熬等形成的病理产物，又可阻滞气机、损伤脏腑而致病。湿邪、火邪属外感六淫，药误属医源性因素，胎毒属先天因素，均非病理产物类"},{"q":"关于阳盛格阴，下列论述错误的是","o":["也叫真热假寒","邪热极盛，深伏于里，阳热被郁不能通达四肢","多见于外感热病的极期","临床表现为热象与寒象并见","本质上是本虚标实证"],"a":4,"e":"阳盛格阴即真热假寒，邪热极盛、深伏于里，阳气被郁不能外达四肢，见手足厥冷等假寒象，本质为实热证，非本虚标实证，故此项错误。其余各项分别指出其别名、病机、多见于外感热病极期及寒热并见的临床表现，均属正确论述"},{"q":"称为“元神之府”的是","o":["髓","脑","骨","脉","胆"],"a":1,"e":"脑为元神之府，脑由髓汇聚而成，主宰精神意识、感觉运动及生命活动。髓为肾精所化，骨主贮藏骨髓并支持形体，脉为血液运行之通道，胆主贮藏排泄胆汁、主决断，四者各有功能，均不称元神之府。脑为髓海、元神所居，故称元神之府，与髓、骨、脉、胆的功能各异"},{"q":"关于气虚的论述错误的是","o":["先天不足、后天失养均会导致气虚","临床可见到少气懒言、疲倦乏力等症状","气虚会影响血、津液的生化和运行","五脏皆有气虚证","易汗出者必然有气虚的原因"],"a":4,"e":"易汗出并非必然由气虚所致，阴虚内热、湿热蕴蒸、亡阳大汗等均可致汗出异常，故该项错误。先天不足、后天失养致气虚，气虚见少气懒言、疲倦乏力，气虚影响血与津液的生化运行，五脏皆有气虚证，四项均为气虚的正确论述"},{"q":"六淫中其性趋下的邪气是","o":["风邪","寒邪","湿邪","燥邪","火邪"],"a":2,"e":"湿性趋下，湿邪重浊，易袭人体下部，见下肢水肿、带下、淋浊、泻痢等，故其性趋下的邪气为湿邪。风邪轻扬易袭阳位，寒邪收引凝滞，燥邪干涩伤津，火邪炎上，四者致病部位与趋下之性不符。湿性重浊趋下，易犯下部，与风邪轻扬、火邪炎上相对，故其性趋下者为湿"},{"q":"阴损及阳发展到后期的结果是","o":["阴阳两虚","阴偏盛","阳偏盛","阴转化为阳","阳转化为阴"],"a":0,"e":"阴损及阳指阴液亏损日久，累及阳气，使阳气亦虚，发展到后期结果为阴阳两虚，以阴虚为主兼见阳虚。阴偏盛、阳偏盛为阴阳偏盛的实证，阴转化为阳、阳转化为阴为阴阳转化的极端变化，均非阴损及阳的后期转归"},{"q":"营气的分布特点是","o":["上出息道，下走气街","熏于肓膜，散于胸腹","通过三焦，流行全身","上荣头目，达于周身","与血同行，环周不休"],"a":4,"e":"营气与血同行于脉中，环周不休，具有濡养全身、化生血液的作用，故其分布特点为与血同行、环周不休。上出息道、下走气街为宗气，熏于肓膜、散于胸腹为卫气，通过三焦流行全身为元气，上荣头目、达于周身非营气特有的分布表述"},{"q":"劳神过度，又被称为","o":["体劳","心劳","肾劳","肝劳","房劳"],"a":1,"e":"劳神过度耗伤心血、损伤心神，故又称心劳，常见心悸、失眠、多梦、健忘等。体劳为体力劳动过度，肾劳多因房劳伤肾，肝劳多因情志或目视过度，房劳专指房事过度伤肾，均非劳神过度的别称。劳神过度耗伤心血心神，故称心劳，与体劳、房劳、肝劳所伤各异"},{"q":"明清时期，提出“卫之后方言气，营之后方言血”的医家是","o":["吴鞠通","赵献可","叶天士","薛雪","吴又可"],"a":2,"e":"叶天士著《温热论》，创立卫气营血辨证，提出卫之后方言气、营之后方言血的温病传变规律。吴鞠通创三焦辨证，赵献可主命门学说，薛雪论湿热病，吴又可著《瘟疫论》主戾气说，均非此论提出者。叶天士创卫气营血辨证，分温病为卫、气、营、血四个阶段，为温病学奠基"},{"q":"下列哪项是形容肺的生理特性的","o":["生之本","后天之本","脏之长也","先天之本","封藏之本"],"a":2,"e":"脏之长也出自《素问·痿论》肺者，脏之长也、为心之盖也，为形容肺生理特性的表述。生之本指心，后天之本指脾胃，先天之本指肾，封藏之本指肾，四者各有所指，均非肺的生理特性形容。肺为脏之长、心之盖，故称脏之长，余项分属心、脾、肾，不指肺"},{"q":"根据五行学说，脾病传心属于","o":["母病及子","相乘","子病及母","相侮","制化"],"a":2,"e":"脾属土、心属火，火生土，心火为母、脾土为子，脾病传心即子病及母。母病及子为心病及脾，相乘为木乘土等沿相克方向的过度克制，相侮为土侮木等反向克制，制化为五行相生相克的正常调节，均非脾病传心"},{"q":"主持诸气，总司人体气化的脏腑是","o":["三焦","脾","肾","肺","膀胱"],"a":0,"e":"三焦为元气运行的通道，主持诸气、总司人体气化，周身之气皆通过三焦布散，脏腑气化依赖于此。脾主运化，肾主气之根与气化，肺主气司呼吸，膀胱贮尿排尿，虽各参与气或水液活动，但均非总司气化者"},{"q":"心与哪个季节相通应","o":["春","夏","秋","冬","长夏"],"a":1,"e":"心属火，夏季火热当令，心气与夏气相通应，故心与夏相通。春属木通于肝，秋属金通于肺，冬属水通于肾，长夏属土通于脾，四时与五脏的对应固定，心不配春、秋、冬、长夏。心属火应夏，夏气通于心，四时五脏各有通应，心不与他季相配"},{"q":"下列各项，属于发病有关的外环境因素，错误的是","o":["地域因素","气候因素","工作环境","生活环境","精神状态"],"a":4,"e":"精神状态属情志内伤，是发病的内环境因素，不属于外环境。地域因素、气候因素、工作环境、生活环境均为外在环境，可影响疾病发生，其中地域与气候、工作与生活环境皆属外环境范畴，唯精神状态归于内环境"},{"q":"下列属于火热证症状特征，错误的是","o":["热（发热，恶热，喜冷）","赤（面赤，目赤，舌红）","稠（痰、涕、白带粘稠）","燥（口渴，咽干，便燥）","虚（乏力，气短，懒言）"],"a":4,"e":"火热证以热、赤、稠、燥为特征：热盛则发热恶热喜冷，火性上炎则面赤目赤舌红，煎灼津液则痰涕白带黏稠，伤津则口渴咽干便燥。乏力、气短、懒言是气虚推动无力、生机不足的表现，属虚证而非火热之象。热、赤、稠三项分别点明热象、上炎与津伤，均紧扣火邪特性"},{"q":"精、气、血、津液之间相互转化依靠气的","o":["推动作用","温煦作用","防御作用","固摄作用","气化作用"],"a":4,"e":"气化指气的推动和调控作用下，精、气、血、津液之间发生相互转化，如精化气、气化血、津血互生，故四者互化依赖气化。推动作用专指激发推动人体生长发育及血液津液运行，温煦作用指产热保温，固摄作用指固护血津不外泄，防御作用指抗御外邪，均不直接主司物质间的转化"},{"q":"下注于气街，并下行于足的气是","o":["元气","宗气","营气","卫气","脏腑之气"],"a":1,"e":"宗气积于胸中，上走息道以司呼吸，贯注心脉以行气血，并下注于气街、下行于足温养下肢，故下注气街而行于足者为宗气。元气根于肾，经三焦布散全身而不专主下行；营气行于脉中化生血液；卫气慓悍滑利，行于脉外温分肉、肥腠理；脏腑之气各守其脏，均无下注气街之能"},{"q":"可以概括精和血之间具有相互转化和相互滋生的关系的是","o":["精可化血","血可化精","精血同源","精血同根","血可养精"],"a":2,"e":"精与血同源于水谷精微，肾藏精、肝藏血，精可化血、血可化精，二者相互滋生转化，故以精血同源概括其关系，亦称肝肾同源。精可化血、血可化精、血可养精仅述单向转化，失之片面；精血同根强调同出一源而未突出相互滋生，皆不足以概括双向关系"},{"q":"内风与哪个脏关系最为密切","o":["心","肝","脾","肾","肺"],"a":1,"e":"肝主疏泄而调畅气机，主藏血而濡养筋脉，肝阳偏亢、肝风内动皆由肝的功能失常所致，故内风与肝关系最密切，临床常见眩晕、震颤、抽搐等肝风表现。心主神明，脾主运化，肾主封藏，肺主宣降，虽可间接影响筋脉，但均非内风产生的核心之脏"},{"q":"我国第一部脉学专著是","o":["《黄帝内经》","《难经》","《伤寒杂病论》","《脉经》","《濒湖脉学》"],"a":3,"e":"王叔和所撰《脉经》系统总结此前的脉学经验，专论脉象与诊脉方法，是我国现存第一部脉学专著。《黄帝内经》为医学理论奠基之作，非脉学专著；《难经》以问答阐释经典；《伤寒杂病论》主论辨证论治；《濒湖脉学》为明代李时珍所著，成书远晚于《脉经》"},{"q":"下列除哪项外均属于养生的原则","o":["天人合一，顺应自然","因人而异，辨证施养","调理脏腑，脾肾为先","热者寒之，寒者热之","动静结合，形神共养"],"a":3,"e":"养生原则重在顺应自然、辨证施养、调理脾肾、形神共养与动静结合，旨在扶正固本、益寿延年。热者寒之、寒者热之属正治法，是针对寒热偏盛的治疗法则，施于已病之人，并非未病养生所遵循，故不属养生原则。天人合一、因人而异、脾肾为先、动静形神四项皆为养生通例"},{"q":"异气是指","o":["六淫邪气","异常气候","情志变化","气机失常","乖戾之气"],"a":4,"e":"异气又称戾气、乖戾之气，吴又可《温疫论》提出，指一类致病力强、传染性大的异常之气，不同于常规六淫。六淫邪气为风、寒、暑、湿、燥、火六种外感病邪的统称；异常气候仅指反常天时；情志变化属内伤病因；气机失常是病理状态，皆非异气所指"},{"q":"脾之大络的分出位置是","o":["长强穴","大横穴","大包穴","渊腋穴","隐白穴"],"a":2,"e":"脾之大络由脾经分出，从大包穴布散于胸胁，总统全身之络，故其分出位置为大包。长强为督脉络穴，大横属脾经但非大络所出，渊腋为胆经穴，隐白是脾经井穴，均非脾之大络的分出之处"},{"q":"《金匮要略心典》说“吐下之余，定无完气。”其理论依据是","o":["气能生津","气能行津","气能摄津","津能载气","津能养气"],"a":3,"e":"津液是气的载体之一，气附于津而行，吐下之后津液大量外泄，气随津脱而耗伤，故有吐下之余定无完气之说，体现津能载气。气能生津、气能行津、气能摄津皆言气对津液的作用，方向相反；津能养气非教材所论负荷关系，均不能解释吐下后气随津亡"},{"q":"治疗前额头痛的病变，通常使用的引经药是","o":["白芷","柴胡","香附","羌活","苍术"],"a":0,"e":"白芷归阳明胃经，善祛风止痛，为前额及眉棱骨痛的引经药，前额属阳明经循行部位。柴胡引少阳，主治头侧痛；羌活引太阳，主治后头项痛；苍术燥湿健脾，香附疏肝理气，均非前额头痛的引经之品"},{"q":"“至虚有盛侯”描述的是","o":["真虚假实","真实假虚","因虚致实","因实致虚","虚实错杂"],"a":0,"e":"真虚假实即至虚有盛候，本质为正气极虚，却反见腹胀、闭塞等类似实证的假象，故至虚有盛候描述的是真虚假实。真实假虚为大实有羸状，本质实而外现虚象；因虚致实、因实致虚是虚实转化；虚实错杂是虚实并见，皆非此语所指"},{"q":"根据五行学说，佐金平木是指","o":["补肺泻肝","双补肝肺","泻肺补肝","双泻肝肺","以上均非"],"a":0,"e":"佐金平木是通过佐助肺金以清肃下行、抑制肝木上亢的治法，肺金虚而不能制木时补肺兼泻肝，故为补肺泻肝。双补肝肺无法平抑亢木；泻肺补肝更助木势；双泻肝肺伤及肺气；均不合佐金平木补肺抑肝之意"},{"q":"五行学说中“水”的特性是","o":["曲直","炎上","从革","润下","稼穑"],"a":3,"e":"《尚书·洪范》以水曰润下概括水的特性，指水具滋润、下行、寒凉、闭藏之性，故水的特性为润下。曲直是木的特性，炎上属火，从革属金，稼穑属土，五行各自的特性不可相混"},{"q":"“上焦如雾”，实际是指何作用","o":["心主血脉","肺主气","胃的受纳","心、肺的输布气血","肺主治节"],"a":3,"e":"上焦包括心与肺，上焦如雾形容心肺将水谷精微和气血如雾露般敷布全身、灌溉濡养，故实际指心、肺的输布气血作用。肺主气仅言肺司呼吸与生成宗气；心主血脉仅及血行；胃的受纳属中焦；肺主治节是对肺功能的概括，均未完整对应如雾的输布之象"},{"q":"根据五行学说，肝病传心属于","o":["母病及子","相乘","子病及母","相侮","制化"],"a":0,"e":"肝属木，心属火，木生火，肝为母、心为子，肝病传及其子即为母病及子。相乘是克制太过，相侮是反向克制，子病及母是子病反累其母，制化是生克协调的正常状态，皆与肝传心的母子相生关系不符"},{"q":"麻疹是一种常见的儿科疾病，其发生发展主要分为三个时期，即初期、中期、晚期，医生在治疗时，初期常用解表透疹法，中期常用清肺热法，后期常用滋养肺阴胃阴等方法，麻疹疾病的分期及其对应的治疗方案体现了哪种中医思维","o":["因人制宜","同病异治","异病同治","审因论治","虚则补之"],"a":1,"e":"同一疾病在初期、中期、后期分别采用解表透疹、清肺热、滋养肺胃之阴等不同治法，体现同病异治，即同一疾病因阶段、证候不同而治法各异。异病同治是不同疾病见同一证候用同一治法；因人制宜重在个体体质差异；审因论治强调针对病因；虚则补之仅是治则之一"},{"q":"下列药物性能中，属于阳的是","o":["寒、辛、浮","温、甘、升","热、咸、升","热、辛、沉","温、酸、降"],"a":1,"e":"药性阴阳以温热、辛甘淡、升浮为阳，寒凉、酸苦咸、沉降为阴，温性、甘味、升浮三者皆属阳，故温、甘、升为阳。寒与咸、酸属阴，沉降属阴，故寒辛浮、热咸升、热辛沉、温酸降四组皆夹杂阴药，不能归入纯阳"},{"q":"下列除哪项外均属于运动养生的内容","o":["太极拳","散步","冥想","气功","慢跑"],"a":2,"e":"运动养生以形体活动为主，太极拳、散步、气功、慢跑皆通过肢体运动调畅气血、强身健体。冥想以静坐调神、宁心养性为主，属调神养生而非运动养生，故不属运动内容"},{"q":"从众多不同事物的形象、现象、表象中“去粗取精、去伪存真、由此及彼、由表及里”进行提炼，抽取事物的本质，舍弃非本质的特征，称为","o":["观物取象","立象尽意","得意忘形","取象比类","其象相应"],"a":1,"e":"立象尽意是在观物取象所得表象的基础上，去粗取精、去伪存真、由此及彼、由表及里地提炼，抽取本质、舍弃非本质特征，以形象表达事物的内在意义。观物取象重在观察获取形象；取象比类重在以象类推；得意忘形、其象相应均非这一提炼抽象过程的准确概括"},{"q":"称肝为“罢极之本”，主要是由于肝有下列哪种功能","o":["促进血行","调畅气机","贮藏血液","疏通水道","疏泄肾精"],"a":2,"e":"肝主藏血，血能濡养筋脉，筋脉得养则耐疲劳，故肝被称为罢极之本，其称谓源于贮藏血液的功能。促进血行、调畅气机虽与肝相关，但不直接解释耐疲劳；疏通水道归于三焦气化；疏泄肾精非肝的主要功能表述"},{"q":"六淫中最易导致生风动血的邪气是","o":["风邪","寒邪","湿邪","火邪","燥邪"],"a":3,"e":"火邪性炽烈，易耗伤阴液、燔灼肝经而致热极生风，又易迫血妄行引起出血，故最易生风动血。风邪善行数变，主犯阳位、致痉挛；寒邪收引凝滞，主痛；湿邪重浊黏滞；燥邪干涩伤津，均不以生风动血为特点"},{"q":"观察心主血脉的功能是否正常，与下列哪项关系较小","o":["面色","舌色","爪色","脉象","胸部的感觉"],"a":2,"e":"心主血脉，其功能正常与否可通过面色红润、舌色淡红、脉象和缓有力及胸部舒畅无不适等观察判断。爪为筋之余，其色泽荣枯主要反映肝血盛衰，与心主血脉关系较小，故为无关之项。面色、舌色、脉象、胸部感觉皆为心主血脉的直接外在征象"},{"q":"“中精之腑”是指","o":["胃","胆","膀胱","小肠","三焦"],"a":1,"e":"胆内藏精汁（胆汁），故称中精之腑，又因藏清纯之汁而称中清之腑。胃主受纳腐熟，为水谷之海；膀胱贮尿排尿；小肠受盛化物、泌别清浊；三焦通行诸气、运化水液，均无中精之腑之名"},{"q":"人体生、长、壮、老、已的生命过程体现为","o":["恒动变化","动静相召","天人合一","整体宏观","法于阴阳"],"a":0,"e":"人体生、长、壮、老、已的生命过程，是精气由盛而衰、脏腑功能不断变化的动态历程，体现恒动变化，即生命始终处于运动变化之中。动静相召言阴阳动静的相互招引；天人合一言人与自然的统一；整体宏观强调整体性；法于阴阳是养生法则，均未直接对应生命历程的动态性"},{"q":"根据五行学说，由相生关系确立的治法是","o":["培土生金","培土制水","抑木扶土","佐金平木","泻火补水"],"a":0,"e":"培土生金即补脾益肺，土生金，脾土为肺金之母，补脾以资肺，是依据相生关系确立的治法。培土制水、抑木扶土、佐金平木均属相克关系的治法；泻火补水即泻南补北，水克火，亦属相克，皆非相生"},{"q":"风邪伤人，导致病变部位游走不定的原因是","o":["风性数变","风性善行","风性主动","风性轻扬","风性开泄"],"a":1,"e":"风性善行，指风邪致病病位游移不定、行走全身，如行痹的关节疼痛游走无常，故病变部位游走不定源于善行。风性数变指发病急、变化快；风性主动指动摇震颤；风性轻扬指易袭阳位；风性开泄指腠理开张汗出，均与病位游走无直接对应"},{"q":"心包络又称","o":["血府","膻中","奇恒之府","华盖","刚脏"],"a":1,"e":"心包络是包护心脏的外膜，具有保护心的作用，又称膻中，为心的外围。血府指脉（脉为血之府）或胸中；华盖是肺的别称；刚脏指肝；奇恒之府是胆、脑、髓等的归类，皆非心包络的别名"},{"q":"肺气是由什么化生而成","o":["肺气","肺阴和肺阳","先天之精","水谷之精","肺精和肺津"],"a":4,"e":"肺气由肺精、肺津化生，是肺脏进行宣发肃降等功能的物质基础，精津充盈则肺气充足。肺气自身不能化生肺气；肺阴与肺阳是肺气阴阳两方面；先天之精、水谷之精是精的来源而非肺气直接化生之物，均非肺气的直接来源"},{"q":"下列五行生克规律的表述，正确的是","o":["木为土之所胜","木为水之子","火为土之子","水为火之所胜","金为木之所胜"],"a":1,"e":"五行相生中水生木，故木为水之子，此项表述正确。木克土，土为木之所胜而非木为土之所胜；火生土，土为火之子而非火为土之子；水克火，火为水之所胜而非水为火之所胜；金克木，木为金之所胜而非金为木之所胜"},{"q":"治疗血瘀证，常酌配行气药物，其理论依据是","o":["气能行血","气能生血","气能摄血","血能载气","血能化气"],"a":0,"e":"气为血之帅，气能行血，气的推动是血液运行的动力，气行则血行，气滞则血瘀，故治血瘀证常酌配行气药以助血行。气能生血指气参与血的生成；气能摄血指固摄血液不外溢；血能载气、血能化气言血对气的作用，均非配伍行气药的依据"},{"q":"下列哪项不属于病后防复的内容","o":["防止复感新邪","截断病传途径","防止劳复","防止药复","防止食复"],"a":1,"e":"病后防复旨在病愈后防止复发，包括防复感新邪、防劳复、防食复、防药复等。截断病传途径属于既病防变的内容，是在已病之时防止病邪传变，而非病后防复的范畴，故不属病后防复"},{"q":"任脉的别络散布的部位是","o":["上肢部","下肢部","背部","胸胁部","腹部"],"a":4,"e":"任脉之别络名尾翳，从任脉分出后散布于腹部，故任脉别络散布部位为腹部。十二经脉的别络加强表里经联系，上肢、下肢、背部、胸胁各有相关经脉络脉分布，但均非任脉别络的布散部位"},{"q":"攻补兼施治则适用于何证","o":["虚证","真实假虚证","实证","真虚假实证","虚实夹杂证"],"a":4,"e":"攻补兼施是攻邪与扶正并用，适用于正虚邪实并见的虚实夹杂证，单纯攻邪伤正、单纯补虚留邪，故须兼顾。单纯虚证宜补，单纯实证宜攻；真实假虚、真虚假实当辨别真伪而治，或攻或补，均非攻补兼施的主治"},{"q":"根据五行学说，属于母病及子的是","o":["肺病及肾","肝病及肾","肺病及心","心病及肝","脾病及肾"],"a":0,"e":"肺属金，肾属水，金生水，肺为母、肾为子，肺病及肾即母病及子。肝病及肾、心病及肝皆为子病及母；肺病及心是火克金的相克失常；脾病及肾是土克水，属相乘，均非母病及子"},{"q":"绦虫病的形成多因","o":["嗜食肥甘","嗜酒过度","生食或食用未煮熟的猪、牛肉","脾胃虚弱","饮食不节"],"a":2,"e":"绦虫多因生食或食用未煮熟的含绦虫囊尾蚴的猪、牛肉而感染，故其形成多与饮食不洁的这一具体方式有关。嗜食肥甘、嗜酒过度、饮食不节是脾胃损伤的常见病因；脾胃虚弱是内在条件，但均非绦虫感染的直接原因"},{"q":"足厥阴肝经，过阴器，抵小腹，布胁肋，连目系，上出额，与督脉会与巅，故肝气郁结常见","o":["头晕胀痛","阴部湿疹","胸胁胀满","腰膝酸痛","面红耳赤"],"a":2,"e":"足厥阴肝经循行过阴器、抵小腹、布胁肋，肝气郁结则经气阻滞，故常见胸胁胀满。头晕胀痛、面红耳赤多为肝阳上亢；阴部湿疹多属湿热下注；腰膝酸痛多属肾虚，皆非肝气郁结循经的常见表现"},{"q":"根据五行学说，金气有余而致木气虚弱属","o":["母病及子","相侮","子病及母","相乘","制化"],"a":3,"e":"金克木为正常相克，若金气有余而过度克制木，致木气虚弱，即属相乘，故为相乘。相侮是木反克金的逆向克制；母病及子、子病及母属相生关系的失常；制化是正常协调状态，均不合金有余乘木"},{"q":"在不同地区生活，感受六淫邪气有所不同，说明六淫致病具有何种特性","o":["外感性","季节性","地域性","相兼性","转化性"],"a":2,"e":"不同地域的气候、水土条件不同，居民所受六淫邪气各有差异，如西北多燥、东南多湿，体现六淫致病的地域性。外感性指邪从外侵入；季节性指随季节而发；相兼性指两邪同犯；转化性指邪气性质转化，均与地区差异无关"},{"q":"患者久病，纳少，乏力，腹胀，但时有减缓，腹痛喜按，舌胖嫩而苔润，脉细弱无力。其病机是","o":["真实假虚","真实病证","真虚假实","真虚病证","虚中夹实证"],"a":2,"e":"患者纳少、乏力、脉细弱、舌胖嫩苔润、腹痛喜按皆为脾气虚之象，虽有腹胀看似实证，但时有减缓、喜按，说明胀满为虚中夹实的假象，本质为真虚，故病机是真虚假实。真实假虚是本质实而现虚象；虚中夹实是虚中兼有实邪，均有实邪内停，与本例纯虚不相同"},{"q":"五行学说中“木”的特性是","o":["曲直","炎上","从革","润下","稼穑"],"a":0,"e":"木曰曲直概括木的特性，曲言其枝干弯曲，直言其伸展升发，引申为生长、升发、条达、舒畅，故木的特性为曲直。炎上属火，从革属金，润下属水，稼穑属土，各有专属，不可混淆"},{"q":"一经证候未罢又出现另一经证候的情况是","o":["直中","合并","并病","循经传","越经传"],"a":2,"e":"并病指一经证候尚未解除，又出现另一经的证候，故一经未罢又见他经证候为并病。合病是两经或三经同时发病；直中是病邪直接侵入里经而不经表；循经传是依六经次序相传；越经传是跳过一经相传，均不同于一经未罢又现他经"},{"q":"可用阴阳互根互用解释的是","o":["寒极生热","阴病治阳","寒者热之","重阴必阳","阴中求阳"],"a":4,"e":"阴阳互根互用指阴依存于阳、阳依存于阴，双方互为根本、相互为用，阴中求阳即在补阳时佐以滋阴，使阳有所根，正体现此关系。寒极生热、重阴必阳属阴阳转化；寒者热之属纠正偏盛；阴病治阳虽涉及阴阳，但以互根互用解释者当推阴中求阳"},{"q":"金元四大家中倡导以汗、吐、下三法攻邪祛病的是","o":["张元素","刘完素","张从正","朱丹溪","李东垣"],"a":2,"e":"张从正为金元四大家之一，创攻邪派，主张病由邪生、邪去则正安，善用汗、吐、下三法攻逐邪气。刘完素主寒凉，倡六气皆从火化；李东垣主补脾胃，为补土派；朱丹溪主滋阴，为滋阴派；张元素为易水学派，均非攻邪派代表"},{"q":"下列哪项除外，均属养形的养生方法","o":["调理饮食","起居有时","节制房事","修德养性","劳逸结合"],"a":3,"e":"养形之法重在调养形体，包括调理饮食、起居有时、节制房事、劳逸结合等，以保形充精。修德养性重在道德修养与心神调摄，属养神的范畴，而非直接调养形体，故不属养形方法"},{"q":"下列病证与先天禀赋有密切关系的是","o":["五迟","五软","鸡胸","解颅","以上都是"],"a":4,"e":"五迟、五软、鸡胸、解颅皆为小儿生长发育障碍，多因先天禀赋不足、肾精亏虚、骨骼失养所致，与先天禀赋关系密切，故以上皆是。此四证虽表现各异，但同源于先天肾精不足，不能单举其一而排除其余"},{"q":"在疾病传变的过程中，少阳传太阴是","o":["循经传","越经传","表里传","合病","并病"],"a":0,"e":"六经循经传变依太阳、阳明、少阳、太阴、少阴、厥阴的次序，少阳之后接太阴，故少阳传太阴属循经传。越经传是跳过中间经而传；表里传是表里经之间相传；合病是数经同时发病；并病是一经未罢又见他经，均非按次序相接的传变"},{"q":"喜燥恶湿的脏是","o":["心","脾","肾","肺","肝"],"a":1,"e":"脾主运化水湿，性喜燥而恶湿，湿邪困脾则运化失职，故喜燥恶湿之脏为脾。胃喜润恶燥，与脾相反；心主血脉；肾主水而藏精；肺主宣降通调水道；肝主疏泄，皆不以喜燥恶湿为特点"},{"q":"根据五行学说，下列属“相乘”传变的是","o":["火传土","土传金","金传水","水传木","金传木"],"a":4,"e":"金克木为相克，金气偏旺传及于木即为相乘，故金传木属相乘传变。火传土、土传金、金传水、水传木皆遵循相生次序，属母病及子一类的相生传变，而非克制太过的相乘"},{"q":"下列不属于老年人体质特点的是","o":["脏腑功能衰退","精气神渐衰","虚多实少","代谢旺盛","多夹痰瘀"],"a":3,"e":"老年人体质以脏腑功能衰退、精气神渐亏、虚多实少、易夹痰瘀为特点，生机衰减，代谢随之减退而非旺盛。脏腑功能衰退、精气神渐衰、虚多实少、多夹痰瘀均符合老年生理，代谢旺盛与衰老的脏腑功能衰退相悖"},{"q":"感冒的治疗，可分别采用辛温解表或辛凉解表，此属于","o":["辨病论治","因人制宜","同病异治","异病同治","辨证论治"],"a":2,"e":"同病异治指同一疾病因证候、类型不同而采用不同治法，感冒有风寒风热之别，故分别用辛温解表与辛凉解表，属同病异治。异病同治是不同疾病同证同治；辨病论治重在辨病名；因人制宜针对体质年龄；辨证论治是诊疗总原则，此处所强调者具体为同病异治"},{"q":"下列属于吐法适应证以外的是","o":["食积停滞胃脘","顽痰留滞胸膈","痰涎阻塞于气道","误食毒物在胃中","积滞生热，腹胀而痛"],"a":4,"e":"吐法适用于邪气壅滞于胃脘、胸膈、气道等上部，如食积停滞胃脘、顽痰留滞胸膈、痰涎阻塞气道、误食毒物尚在胃中，皆宜吐而越之。积滞生热、腹胀而痛病位偏下、腑气不通，当用下法通腑泻热，非吐法所宜"},{"q":"下列各项中，属于相乘传变的是","o":["肺病及肾","肺病及心","心病及肝","肝病及肾","脾病及肾"],"a":4,"e":"脾属土，肾属水，土克水，脾气壅滞或脾病传及于肾即为相乘，故脾病及肾属相乘传变。肺病及肾为金生水的母病及子；肺病及心是火克金的相侮；心病及肝、肝病及肾均为子病及母，皆非相乘"},{"q":"藏象学说主要是研究","o":["脏腑生理","脏腑病理","脏腑生理、病理之间的关系","脏腑生理、病理及其相互关系","脏腑组织器官结构形态"],"a":3,"e":"藏象学说以研究脏腑的生理功能、病理变化及其相互关系为主要内容，通过外在征象探求内在脏腑的规律，故为脏腑生理、病理及其相互关系。单言生理或病理均不全面；脏腑组织器官结构形态属解剖学范畴，非藏象学说研究的重点"},{"q":"关于温法，下列说法错误的是","o":["形不足者，温之以气","清者温之","劳者温之","仅适用于寒实证","消除沉寒痼冷"],"a":3,"e":"温法通过温里散寒、温补阳气以祛除寒邪、扶助阳气，既适用于寒实证的温散，也适用于虚寒证的温补，仅适用于寒实证缩小了温法的范围，属错误。形不足者温之以气、劳者温之、清者温之皆为温法的运用，消除沉寒痼冷亦是其效用"},{"q":"经络系统中，具有加强十二经脉在体表联系的是","o":["正经","经别","经筋","别络","奇经"],"a":3,"e":"别络是经脉的分支，十二经脉各有一条别络，加上任、督及脾之大络共十五别络，主要加强十二经脉表里两经在体表的联系。正经即十二经脉本身；经别加强表里经在体内的联系；经筋联络筋肉关节；奇经调节十二经气血，均非主司体表联系"},{"q":"关于内生五邪，论述错误的是","o":["是由于内在脏腑和气血津液等生理功能异常引起","也有一定的六淫所伤","暑邪纯属外邪，并无“内暑”之说","津伤化燥属于内生五邪之一","阳气不足可致寒从内生"],"a":1,"e":"内生五邪由脏腑气血津液功能失常而产生，属内伤病理，与六淫外邪无涉，也有一定的六淫所伤与内生之义相悖，属错误。内风、内寒、内湿、内燥、内火皆源于内在功能失调；暑纯属外邪无内暑之说；津伤化燥、阳气不足生内寒均为内生五邪内容"},{"q":"手三阴经的走向是","o":["从胸走手","从手走头","从头走足","从足走头","从足走腹"],"a":0,"e":"十二经脉走向有手三阴从胸走手的规律，手太阴肺经、手厥阴心包经、手少阴心经皆自胸中循臂至手，故手三阴经从胸走手。从手走头为手三阳；从头走足为足三阳；从足走腹（胸）为足三阴，方向各别"},{"q":"六淫既可单独伤人，又可两种及以上同时侵犯人体，说明六淫致病具有何种特性","o":["外感性","季节性","地域性","相兼性","转化性"],"a":3,"e":"相兼性指两种或两种以上邪气可同时侵犯人体，如风寒、风湿、湿热并见，六淫既可单独伤人又可相兼致病，正体现此特性。外感性指邪自外受；季节性指随季节而发；地域性指因地区而异；转化性指邪气在一定条件下性质转化，均与数邪同犯无关"},{"q":"“阴损及阳”、“阳损及阴”、“阴阳俱损”，是根据","o":["阴阳互根","阴阳对立","阴阳消长","阴阳转化","阴阳制约"],"a":0,"e":"阴阳互根互用指阴阳互为存在前提、相互资生促进，阴精能化生阳气，阳气能化生阴精，故阴损日久累及阳、阳损日久累及阴，终至阴阳俱损，皆根于互根关系。对立制约言双方的对抗；消长言量的增减；转化言在一定条件下属性转变；制约与对立同义，均非互损的理论基础"},{"q":"属于五脏功能的表现的是","o":["五志","五气","五味","五臭","五音"],"a":0,"e":"五脏各有志，心在志为喜、肝为怒、脾为思、肺为悲、肾为恐，五志是五脏功能活动在精神情志方面的表现，故属五脏功能表现。五气、五味、五臭、五音是五行学说对事物属性的归类，用以联系脏腑，并非五脏本身的功能表现"},{"q":"牙龈红肿，口臭，多见于","o":["心火上炎","肺热灼盛","肝火上炎","胃火上冲","胆经郁热"],"a":3,"e":"足阳明胃经循行绕口唇、入齿龈，胃火炽盛循经上冲，则牙龈红肿、口臭，故牙龈红肿口臭多见于胃火上冲。心火上炎多见口舌生疮；肺热灼盛多见咽痛咳嗽；肝火上炎多见目赤头胀；胆经郁热多见口苦胁痛，病位与胃经不符"},{"q":"关于防止食复，以下说法错误的是","o":["饮食宜有营养","饮食宜清淡","饮食宜消化","饮食宜以温热性的食品为主","饮食应注意护养胃气"],"a":3,"e":"防止食复要求饮食清淡、富有营养、易于消化并注意护养胃气、避免肥甘厚味，以助胃气恢复。强调以温热性食品为主并无普遍依据，且热性食品恐助热伤津，反不利于病后调养，故此项说法错误"},{"q":"导致食复的原因，错误的是","o":["多食","强食","不注意“忌口”","滥服补剂","不注重饮食卫生"],"a":3,"e":"食复多因病后多食、强食，或不注意忌口、饮食不洁，致脾胃重伤、旧病复发。滥服补剂属药复范畴，是药物使用不当引起的复发，与饮食因素无直接关系，故非导致食复的原因"},{"q":"膀胱的主要病机特点是","o":["受纳功能失常","传导功能失常","气化作用失常","腐熟功能失常","藏精功能失常"],"a":2,"e":"膀胱主贮尿与排尿，其功能依赖肾的气化，气化不利则小便癃闭、遗尿失禁，故膀胱的主要病机特点为气化作用失常。受纳失常属胃；传导失常属大肠；腐熟失常属胃；藏精失常属肾，皆非膀胱的病机特点"},{"q":"中医学描述肺“虚如蜂巢”所体现的思维方式是","o":["形象思维","意象思维","应象思维","抽象思维","逻辑思维"],"a":0,"e":"形象思维凭借直观形象和生动比喻来认识事物，以肺虚如蜂巢之象描摹肺的形态结构，直观可感，属形象思维。意象思维重在以意取象；应象思维重在人与自然的对应；抽象思维运用概念判断推理；逻辑思维遵循逻辑规则，均不同于这种直观描摹"},{"q":"体阴而用阳的脏是","o":["心","脾","肾","肺","肝"],"a":4,"e":"肝藏血而属阴，主疏泄而升发属阳，故肝体阴而用阳，其体为阴血所充，其用为疏泄升动。心、肺、脾、肾虽各有阴阳属性，但以体阴用阳概括其脏腑特性者，专指肝，其余诸脏不以此称"},{"q":"肾中精气的主要生理功能是","o":["促进机体的生长发育","促进生殖功能的成熟","主生长发育和生殖","化生血液的物质基础","人体生命活动的根本"],"a":2,"e":"肾藏精，肾中精气能化生天癸、促进生殖器官发育成熟并维持生殖功能，又推动机体生长壮老已，故其主要生理功能为主生长发育和生殖。促进生长发育、促进生殖成熟仅各举一端；化生血液的物质基础是营气津液；生命活动的根本是对肾精作用的泛化，均不全面"},{"q":"统摄运动功能的是","o":["脾意","肾志","心神","肺魄","肝魂"],"a":2,"e":"心主神明，神为五脏六腑之大主，统驭全身脏腑经络的功能活动，运动功能亦由心神统摄，故统摄运动功能者为心神。脾意主思虑，肾志主志意，肺魄主本能感觉动作，肝魂主谋虑，皆受心神统率而非统摄全身运动"},{"q":"能主二便的脏腑是","o":["脾","三焦","膀胱","小肠","肾"],"a":4,"e":"肾开窍于前阴与后阴，主司二便的排泄，肾气充足则二便通畅有度，故能主二便的脏腑是肾。脾主运化；三焦通行诸气与水液；膀胱贮尿排尿，仅主小便；小肠泌别清浊，皆不能统主二便"},{"q":"在下列阴阳失调病机中，最易出现虚阳外越的是","o":["阴损及阳","阳损及阴","阴盛格阳","阳盛格阴","阴虚阳亢"],"a":2,"e":"阴盛格阳时阴寒之邪壅盛于内，将虚衰之阳格拒于外，出现身热、面红等假热之象，本质为里真寒、外假热，阳气浮越于外，故最易出现虚阳外越。阴损及阳、阳损及阴是阴阳互损；阳盛格阴是真热假寒；阴虚阳亢是虚热上扰，均非虚阳外越"},{"q":"下列属于养生内容的是","o":["治疗、防病、益寿","强身、康复、益寿","强身、防病、治疗","康复、防病、益寿","强身、防病、益寿"],"a":4,"e":"养生以强身健体、预防疾病、益寿延年为内容，旨在未病先防、却老延年，故属于养生内容者为强身、防病、益寿。治疗属已病之后的医疗；康复针对病后功能障碍；此二者与养生的未病调养主旨不同，凡含治疗的选项皆非纯养生内容"},{"q":"以调节气机升降为主要关系的两脏","o":["肺与肾","肺与肝","肺与脾","肝与脾","心与肝"],"a":1,"e":"肝主升发，肺主肃降，一升一降相反相成，共同调节全身气机的升降运动，故以调节气机升降为主要关系的两脏是肺与肝。肺与肾主呼吸与纳气；肺与脾主气的生成；肝与脾主藏血与统血、疏泄与运化；心与肝主血与神，均不专主气机升降"},{"q":"关于邪正虚实，以下说法不正确的是","o":["正邪斗争影响着疾病的发展和转归","正邪的力量在疾病发展中不是一成不变的","一般来说，正盛则邪退","正邪相搏，斗争剧烈，是实证的特点","正邪相搏，斗争剧烈，是虚证的特点"],"a":4,"e":"实证以邪气亢盛、正邪相搏剧烈为主要特点，正邪相搏、斗争剧烈是虚证的特点与实邪亢盛之义相悖，属错误。正邪斗争影响疾病发展转归、力量对比不断变化、正盛则邪退，以及斗争剧烈为实证特点，均为正确表述"},{"q":"聚于胸中之气指的是","o":["元气","宗气","营气","卫气","脏腑之气"],"a":1,"e":"宗气由肺吸清气与脾胃水谷精气结合而成，聚积于胸中膻中之处，故称聚于胸中之气。元气根于肾而布散全身；营气行于脉中；卫气行于脉外；脏腑之气各属于脏，皆不以聚于胸中为特点"},{"q":"邪郁化火的机制是","o":["邪气阻遏气机，导致阳气郁滞，生热化火","邪气亢盛自行化火","阳邪有余，导致人身阳盛化火","阳邪阻遏人身水道，耗伤津液化火","阴邪阻遏人身水道，津液流行不畅，导致局部阴虚化火"],"a":0,"e":"邪郁化火是风、寒、湿、燥等邪气或痰饮瘀血等病理产物阻遏气机，使阳气郁滞不通，郁而化热生火，其基本机制在阳气郁滞。邪气亢盛自行化火、阳邪有余致阳盛化火皆非郁而化火；阻遏水道耗伤津液或局部阴虚化火，均偏离气机郁滞这一核心"},{"q":"称为“封藏之本”的脏是","o":["心","肝","脾","肾","肺"],"a":3,"e":"肾主封藏，藏精而不妄泄，主生长发育与生殖，故被称为封藏之本。心主血脉为君主之官；肝主疏泄，主藏血；脾主运化，为气血生化之源；肺主宣发肃降，皆非封藏之本"},{"q":"五脏中，下列各项均与女子胞关系最为密切，错误的是","o":["心","肝","脾","肺","肾"],"a":3,"e":"女子胞主月经与孕育，依赖心主血、肝藏血、脾统血及肾藏精提供精血，故与心、肝、脾、肾关系最为密切。肺主气而朝百脉，虽参与气的生成，但与女子胞的经孕功能无直接密切联系，故为错误之项"},{"q":"阴偏衰的治疗原则是","o":["滋阴壮水","寒者热之","损其有余","扶阳益火","热者寒之"],"a":0,"e":"阴偏衰即阴虚，阴液不足不能制约阳，致虚热内生，治当滋阴以制阳，即滋阴壮水（阳病治阴）。寒者热之、热者寒之属正治，针对寒热偏盛；损其有余是泻实；扶阳益火用于阳虚，均与阴虚的治则相反"},{"q":"在五行学说中，五季中的“长夏”归属于","o":["木","火","土","金","水"],"a":2,"e":"五行配五季，木配春、火配夏、土配长夏、金配秋、水配冬，长夏湿气主令，与脾土相应，故长夏归属于土。春属木、夏属火、秋属金、冬属水，季节与五行的对应固定，不容混淆"},{"q":"寒主收引是指","o":["寒邪阻滞气机","寒邪损伤阳气","寒邪耗气伤津","寒邪重浊黏滞","使气机收敛，筋脉挛急"],"a":4,"e":"寒主收引指寒邪侵袭可使气机收敛闭塞、腠理致密、筋脉拘急挛缩，故表现为使气机收敛、筋脉挛急。阻滞气机是寒邪凝滞的一面；损伤阳气是寒邪伤阳；耗气伤津是暑热之邪的特点；重浊黏滞是湿邪的特性，均非收引之所指"},{"q":"“昼不精，夜不暝”这一临床现象是由阴阳的何种关系失调导致的","o":["阴阳对立制约","阴阳交感互藏","阴阳消长转化","阴阳自和平衡","阴阳互根互用"],"a":4,"e":"阴阳互根互用指阴阳相互依存、互为根本，昼属阳、夜属阴，白天阳气需阴精的承载涵蓄方得精神，夜间阴血需阳气的回归方得安寐，互根互用失调则昼不精、夜不暝。对立制约、交感互藏、消长转化、自和平衡虽皆阴阳关系，但不直接解释昼夜精神与睡眠的失常"},{"q":"以下属于基本病机的是","o":["阴阳失调","邪正盛衰","气血失调","津液代谢失调","以上均是"],"a":4,"e":"基本病机是对疾病机理的高度概括，包括邪正盛衰、阴阳失调、气血失调、津液代谢失调等，故以上均是。各项分别从不同层面揭示病机共性，缺一不足以概括基本病机的全部内容"},{"q":"心与肝的关系主要表现在","o":["血行方面","气血的生成","精神、思维、意识活动","血行和精神、思维、意识活动","气血的生成和精神、思维、意识活动"],"a":3,"e":"心主血脉、主神明，肝藏血、主疏泄而调情志，二者在血的运行的调节及精神、思维、意识活动方面相互配合，故心与肝的关系主要表现于血行和精神思维意识活动。二者不直接参与气血的生成，凡含气血生成之项均非其主要关系"},{"q":"下列各项均属于津液的排泄途径，错误的是","o":["汗","尿","呼气","呕吐物","粪"],"a":3,"e":"津液排泄的主要途径为汗、尿、呼气及随大便排出，呕吐物是胃气上逆的病理排出物，属异常丢失而非正常排泄途径，故为错误项。汗由腠理排泄，尿由膀胱排出，呼气带走水分，粪带走部分津液，皆属正常排泄"},{"q":"易损伤脾胃阳气，导致寒湿内生的病因是","o":["嗜酒","嗜烟草","嗜辛辣","嗜生冷寒凉","嗜酸"],"a":3,"e":"生冷寒凉之品易损伤脾胃阳气，致中焦虚寒、运化失司，水湿不化而内生寒湿，故嗜生冷寒凉是该病因。嗜酒、嗜辛辣多助湿热；嗜烟草多燥热伤肺；嗜酸收敛，皆非损伤脾胃阳气生寒湿的主要因素"},{"q":"根据五行学说，金之子是","o":["木","水","金","火","土"],"a":1,"e":"五行相生次序为木、火、土、金、水，金生水，故金之子为水。木、火为金所克或克金者，与金无相生的母子关系；土为金之母；金自身无子，均不合金之子的提问"},{"q":"养生的基本原则中，重在调养的内脏是","o":["心、肾","心、脾","肝、肾","肝、心","肾、脾"],"a":4,"e":"养生重在调养先天之本肾与后天之本脾，肾藏精主生长发育，脾为气血生化之源，二者充盛则正气足、寿可延，故重在调养的内脏为肾、脾。心主神明、肝主疏泄虽需调摄，但养生原则所重在脾肾两本，其余配伍均未同时涵括先后天之本"},{"q":"津液输布失常所导致的痰饮水肿等病证与哪个脏腑有关","o":["肝","心","胃","肺","肾"],"a":3,"e":"肺主宣发肃降、通调水道，为水之上源，肺失宣降则水道不利，津液输布失常而聚为痰饮、发为水肿，故与肺关系密切。脾主运化水湿、肾主水液气化虽亦参与，但通调水道、布散津液以肺为要；肝主疏泄、胃主受纳，与津液输布失常的关系相对间接"},{"q":"肾主藏","o":["魂","神","魄","志","意"],"a":3,"e":"五脏所藏各异，心藏神、肝藏魂、肺藏魄、脾藏意、肾藏志，故肾主藏志。神、魂、魄、意分属心、肝、肺、脾，各有专属，不能与肾所藏之志相混"},{"q":"具有“壅遏营气，令无所避”功能的是","o":["脾","心","脉","气","三焦"],"a":2,"e":"脉为血之府，脉道能约束、壅遏营血使之循行脉中而不四散外溢，故壅遏营气、令无所避指的是脉的功能。脾主统血、心主血脉、气推动血行、三焦通行诸气，虽都与血或气相关，但直接发挥壅遏约束之职者为脉"},{"q":"关于“阴虚火旺”的论述错误的是","o":["此“火”属于虚火","是人体阴阳失调的一种表现","多由精亏血少、阴液大伤引起","阴虚阳亢是其基本病机","治疗宜以苦寒清热为主"],"a":4,"e":"阴虚火旺之火为虚火，由精亏血少、阴液大伤、阴虚阳亢而生，治宜滋阴降火、甘寒清热，若以苦寒清热为主则更伤阴液，属错误。此火属虚火、为阴阳失调的表现、多由精亏血少引起、基本病机为阴虚阳亢，均为正确论述"},{"q":"在经络系统中，承载大部分气血输送任务的是","o":["十二皮部","十二经筋","十二别络","十二经脉","十二经别"],"a":3,"e":"十二经脉是气血运行的主要通道，内外贯通、营运全身，承载大部分气血输送任务。十二皮部是经气散布于体表的部位；十二经筋主约束骨骼、司关节运动；别络加强表里经联系；经别加强体内联系，皆非气血输送的主干"},{"q":"属于养生基本原则，错误的是","o":["“治未病”的预防思想","人与自然环境和谐统一","突出精神心理健康","“节阴阳而调刚柔”的守中思想","辨证论治"],"a":4,"e":"养生基本原则包括治未病的预防思想、人与自然和谐统一、突出精神心理健康、节阴阳而调刚柔的守中思想等。辨证论治是中医诊治疾病的基本原则，针对已病者的辨证与施治，不属养生基本原则，故为错误之项"},{"q":"水火之宅是指","o":["脾","胃","肾","肝","肺"],"a":2,"e":"肾藏元阴元阳，为一身阴阳之根本，水火同居其中，故称水火之宅。脾为气血生化之源；胃主受纳腐熟；肝藏血主疏泄；肺主气司呼吸，皆不具备水火并藏、为阴阳之宅的特性"},{"q":"脏腑关系中，“水火既济”指的是","o":["肝与肾","心与肾","肝与脾","肺与脾","肺与肝"],"a":1,"e":"心属火位居于上，肾属水位居于下，心火下降温肾水，肾水上济滋心火，水火相交、阴阳协调，即水火既济，指心与肾的关系。肝肾同居下焦，肝脾主藏血统血与运化，肺脾主气与水液，肺肝主气机升降，均非水火既济所论"},{"q":"“阴脉之海”指的是","o":["督脉","冲脉","任脉","带脉","跷脉"],"a":2,"e":"任脉循行于腹面正中线，总任一身之阴经，故称阴脉之海。督脉总督一身之阳，为阳脉之海；冲脉并足少阴上行，为十二经之海；带脉环绕腰腹；跷脉主眼睑开合与下肢运动，皆非阴脉之海"},{"q":"下列除哪项外均是中医饮食养生所提倡的","o":["药膳保健","克服饮食偏嗜","注意饮食卫生","强调高营养饮食","提倡饮食有节"],"a":3,"e":"中医饮食养生提倡药膳保健、克服饮食偏嗜、注意饮食卫生、提倡饮食有节，重在调和脾胃、谨和五味。强调高营养饮食并非其主张，过食肥甘厚味反致脾胃损伤、痰湿内生，与饮食有节、谨和五味的宗旨相悖"},{"q":"关于补法，下列说法错误的是","o":["精不足者，补之以味","“大实有羸状”者，可以补","分峻补、平补、缓补","补血须不忘补气","常根据其虚在何脏，直接补其脏"],"a":1,"e":"补法适用于虚证，大实有羸状是真实假虚，本质为邪实壅盛、外现虚象，当泻不当补，误补则助邪，故此项错误。精不足者补之以味、分峻补平补缓补、补血不忘补气、按虚在何脏而补其脏，均为补法的正确运用"},{"q":"针刺腧穴时，局部有酸、麻、重、胀等感觉及沿经脉走向传导的现象称为","o":["守气","得气","气脱","行气","补气"],"a":1,"e":"针刺得气是指针入腧穴后，局部产生酸、麻、重、胀等针感，并沿经脉走向传导，是针刺取效的关键，故该现象称为得气。守气是得气后保持针感；行气是促使针感传导的手法；气脱是气的暴脱；补气是补益之法，均非此现象之名"},{"q":"《灵枢·经水》所提及的：“脏之坚脆，腑之大小，谷之多少，脉之长短”与下列哪项关系最为密切","o":["环境基础","解剖基础","医药基础","自然科学基础","人文哲学基础"],"a":1,"e":"《灵枢·经水》以脏之坚脆、腑之大小、谷之多少、脉之长短描述脏腑的形态、容量与结构差异，属对人体形态结构的认识，与解剖基础关系最密切。环境基础论水土气候；医药基础论药物方技；自然科学基础、人文哲学基础范围过泛，均不若解剖基础贴合此类形态描述"},{"q":"经络分阴阳，被称为“阳脉之海”的是","o":["督脉","任脉","阴维脉","阳维脉","带脉"],"a":0,"e":"督脉循行于背部正中，总督一身之阳经，故被称为阳脉之海。任脉总任一身之阴，为阴脉之海；阴维脉维系诸阴经；阳维脉维系诸阳经；带脉环绕腰腹，皆非阳脉之海"},{"q":"具有“通行诸气和运化水液”生理功能的腑是","o":["胆","膀胱","胃","三焦","小肠"],"a":3,"e":"三焦为六腑之一，其功能是通行诸气、运行水液，气与水液皆借三焦之道布散全身，故具此功能的腑为三焦。胆贮藏排泄胆汁；膀胱贮尿排尿；胃受纳腐熟；小肠受盛化物、泌别清浊，均不主通行诸气与运化水液"},{"q":"区分五脏、六腑、奇恒之腑三类的最主要依据是","o":["解剖形态的差异","分布部位的不同","功能特点的不同","经脉阴阳属性的不同","病理表现的不同"],"a":2,"e":"五脏以化生和贮藏精气为特点，六腑以受盛和传化水谷为特点，奇恒之腑形态似腑而功能似脏，三者划分的核心依据是功能特点的不同。解剖形态、分布部位、经脉属性、病理表现虽各有差异，但均非区分三类的最主要依据"},{"q":"“天癸”的产生取决于","o":["先天禀赋的强弱","元气的充沛","肾阴肾阳的协调平衡","肾中精气的充盈","后天之精的充养"],"a":3,"e":"天癸是肾中精气充盈到一定程度所产生的、促进生殖器官发育成熟和维持生殖功能的精微物质，故其产生取决于肾中精气的充盈。先天禀赋强弱是基础；元气充沛、肾阴肾阳协调、后天之精充养皆有助于肾精，但天癸产生的直接条件是肾精充盈"},{"q":"瘀血的脉象可表现为","o":["浮缓","浮紧","细涩","濡细","滑数"],"a":2,"e":"瘀血内停，血脉不畅，脉道艰涩，故脉象细涩，患者可见刺痛固定、面色晦暗、舌紫暗等。浮缓多为中风或表虚；浮紧主外感风寒表实；濡细主湿或虚；滑数主痰热或食积，均与瘀血的脉象不符"},{"q":"下列各项，除哪项外均属于中医基础理论课程的主要内容","o":["中医学的哲学基础","中医学对人体生理活动的认识","中医学对疾病基本规律的认识","中医学对疾病防治原则的认识","中医学对宇宙变化的认识"],"a":4,"e":"中医基础理论课程内容包括中医学的哲学基础、对人体生理活动的认识、对疾病基本规律的认识以及对疾病防治原则的认识。中医学对宇宙变化的认识不属该课程的主要内容，其余四项构成中基课程的基本框架"},{"q":"津液在体内得不到正常的转输和布散，在体内环流迟缓，困阻于内的病理状态，称之为","o":["阳不化气","湿浊困阻","阳虚水泛","水气凌心","湿遏热伏"],"a":1,"e":"津液得不到正常转输布散，环流迟缓而困阻于内，即为湿浊困阻，属津液输布排泄障碍形成的病理状态。阳不化气指阳气不足不能化生水气；阳虚水泛是阳虚水液泛滥；水气凌心是水气上冲犯心；湿遏热伏是湿邪郁遏热邪，均与此定义有别"},{"q":"五脏主五液，肾之液为","o":["汗","唾","涕","泪","涎"],"a":1,"e":"五脏化生五液，心在液为汗、肺在液为涕、肝在液为泪、脾在液为涎、肾在液为唾，故肾之液为唾。汗、涕、泪、涎分属心、肺、肝、脾，各有归属，非肾所主之液"},{"q":"衄家不可发汗，其理论依据是","o":["血可化津","津能生血","津能载气","气能摄血","血能载气"],"a":0,"e":"衄家久衄失血，血虚则津液亦亏，因血可化津、津血同源，夺血者无汗，若再发汗必重伤津血，故有衄家不可发汗之戒。津能生血是津对血的作用；津能载气言津为气之载体；气能摄血、血能载气皆非禁汗的理论依据"},{"q":"关于津伤化燥的形成原因论述错误的是","o":["可起于久病伤阴耗液","可发生于大汗、大吐、大下之后","可发生于亡血失精之后","可发生于热性病过程中","必须有内热因素参与才能形成"],"a":4,"e":"津伤化燥可由久病伤阴耗液、大汗大吐大下、亡血失精或热性病过程中津液受损而形成，并非必须有内热参与，故该项错误。其余四项均为津伤化燥的常见成因，指出其阴液耗伤的共同机制"},{"q":"五脏分阴阳，其中属于阳中之阴的是","o":["肝","心","脾","肺","肾"],"a":3,"e":"五脏分阴阳，心肺居上属阳，肝肾居下属阴，心为阳中之阳，肺主肃降、性偏阴，为阳中之阴。肝为阴中之阳，肾为阴中之阴，脾为阴中之至阴，皆不属阳中之阴"},{"q":"肝在液为","o":["涎","泪","汗","涕","唾"],"a":1,"e":"肝开窍于目，在液为泪，泪由肝血化生并濡润眼睛，故肝在液为泪。涎为脾之液，汗为心之液，涕为肺之液，唾为肾之液，五液各归五脏，不能相混"},{"q":"肾藏（ ），为先天之本，水火之宅，是元气、阴精的生发之源","o":["气","血","阴","精","阳"],"a":3,"e":"肾主藏精，精是构成人体和维持生命活动的基本物质，肾精充盛则生机旺盛，故肾藏精，为先天之本、水火之宅、元气与阴精生发之源。气、血、阴、阳虽皆与肾相关，但先天之本与生发之源所藏者，专指肾精"},{"q":"中医学理论体系形成于","o":["隋唐时期","金元时期","明清时期","战国至两汉时期","春秋战国时期"],"a":3,"e":"中医学理论体系形成于战国至两汉时期，《黄帝内经》《难经》《伤寒杂病论》《神农本草经》等经典相继问世，奠定理论与临床基础。隋唐、金元、明清为发展与成熟阶段；春秋战国仅为其奠基的早期，体系尚未形成"},{"q":"气的运动受阻，不畅通，称为","o":["气机不畅","气结","气闭","气逆","气虚"],"a":0,"e":"气的运动称为气机，气的运动受阻、运行不畅通即为气机不畅，程度较轻而未至完全闭塞。气结是气郁结聚；气闭是气闭塞不通而窍闭；气逆是气升发过度或当降不降；气虚是气的量不足，均非单纯的受阻不畅"},{"q":"“阴阳离决，精气乃绝”是指","o":["阴阳平衡关系的破坏","阴阳对立关系的破坏","阴阳互根关系的破坏","阴阳消长关系的破坏","阴阳转化关系的破坏"],"a":2,"e":"阴阳互根指阴依阳存、阳依阴生，双方互为根本，阴阳离决、精气乃绝即阴阳互根关系破裂、彼此分离，生命随之终止。对立制约破坏强调制约失常；消长、转化关系破坏各有不同表现，皆非互根离决所致"},{"q":"肾主纳气的主要生理功能作用是","o":["使肺之呼吸保持一定的深度","有助于元气的固摄","有助于精液的固摄","有助于元气的生成","有助于肺气的宣发"],"a":0,"e":"肾主纳气，摄纳肺所吸入的清气，使呼吸保持一定深度，防止气浮于上，故其主要作用为使肺之呼吸保持一定的深度。固摄元气、固摄精液分属肾气不同方面；元气生成源于肾精；肺气宣发属肺的功能，均非肾主纳气之效"},{"q":"下列关于五脏外合五体的叙述，错误的是","o":["心合脉","肝合爪","脾合肉","肺合皮","肾合骨"],"a":1,"e":"五脏外合五体为心合脉、肝合筋、脾合肉、肺合皮、肾合骨，肝合爪的表述错误，爪为筋之余，是肝的外华而非所合之体。心合脉、脾合肉、肺合皮、肾合骨均正确，唯肝当合筋而非合爪"},{"q":"下列不属于肝的主要生理功能的是","o":["调节全身水液代谢","调节全身血量","调节全身阴阳","调畅全身气机","调节一切情志活动"],"a":2,"e":"肝主疏泄、主藏血，能调畅气机、调节血量、调畅情志并参与水液代谢的调节，但不具有调节全身阴阳的功能，故该项不属肝的生理功能。调节血量、气机、情志、水液代谢皆与肝的疏泄、藏血相关，为肝所有"},{"q":"“中焦如沤”主要是描述","o":["胃的受纳","脾的散精","小肠泌别清浊","胃的腐熟水谷","大肠传化糟粕"],"a":3,"e":"中焦包括脾胃，中焦如沤形容脾胃腐熟水谷、消化饮食并化生营血的状态，故主要描述胃的腐熟水谷。胃的受纳仅指容纳饮食；小肠泌别清浊、大肠传化糟粕属下焦；脾的散精是运化的一环，均未完整概括如沤的腐熟之象"},{"q":"《素问·天元纪大论》:“太虚寥廓，肇基化元，万物资始，五运终天，布气真灵，摁统坤元……生生化化，品物咸章。”体现的中医学思维方式是","o":["象思维","系统思维","变易思维","意象思维","应象思维"],"a":1,"e":"该经文描述太虚元气为万物之始，五运终天、布气真灵、生生化化、品物咸章，把宇宙万物视为由气化生成、相互联系、不断生化的有机整体，体现系统思维。象思维、意象思维、应象思维重在以象取类比；变易思维侧重运动变化，而此段更突出万物由气化而成、彼此关联的整体图景，故以系统思维为当"},{"q":"贯注于心肺之脉的气是","o":["元气","宗气","营气","卫气","脏腑精气"],"a":1,"e":"宗气上走息道以司呼吸，贯注于心肺之脉以推动气血运行，故贯注于心肺之脉的气是宗气。元气根于肾，经三焦布散；营气行于脉中化生血液；卫气行于脉外温煦防御；脏腑精气各归于脏，均无贯注心肺之脉的专门作用"},{"q":"治疗血瘀证时，常酌配补气、行气药物的依据是","o":["气能生血","气能行血","气能摄血","血能载气","血能化气"],"a":1,"e":"气为血之帅，气能行血，气推动血液运行，气行则血行，故治血瘀证配伍补气、行气药以增强推动之力。气能生血言血的生成；气能摄血言固摄；血能载气、血能化气言血对气的作用，均非配伍行气药治瘀的依据"},{"q":"关于阴盛格阳下列论述错误的是","o":["也叫真寒假热","阴寒之邪壅盛于内，逼迫衰极之阳浮越于外","多见于虚寒形病变的严重阶段","常有身热、面颊泛红等热性症状","也有感受热邪的因素影响，故见假热症状"],"a":4,"e":"阴盛格阳即真寒假热，阴寒之邪壅盛于内，逼迫虚衰之阳浮越于外，多见于虚寒病变的严重阶段，可见身热、面颊泛红等假热之象，其假热源于内寒格阳而非感受热邪，故该项论述错误。其余各项均合阴盛格阳的病机"},{"q":"曾提出“土气为万物之源，胃气为养生之主。胃强则强，胃弱则弱，有胃则生，无胃则死，是以养生家当以脾胃为先”的医家是","o":["张景岳","李东垣","朱丹溪","孙思邈","张仲景"],"a":0,"e":"张景岳重视脾胃，提出土气为万物之源、胃气为养生之主、养生家当以脾胃为先，强调脾胃在养生中的主导地位。李东垣为补土派，重在补脾胃升阳气；朱丹溪主滋阴；孙思邈重医德与食疗；张仲景著《伤寒杂病论》，皆非此论的提出者"},{"q":"“筋之余”是指","o":["面","爪","毛","唇","发"],"a":1,"e":"肝在体合筋，其华在爪，爪的色泽形态可反映肝血的盛衰，故称爪为筋之余。面为心之外华；毛为肺之外华；唇为脾之外华；发为血之余，皆非筋之余"},{"q":"下列关于实的叙述，错误的是","o":["外感邪盛","肌肤经络闭塞","气机升降失调","脏腑功能亢进","气血壅滞瘀结"],"a":2,"e":"实指邪气亢盛、脏腑功能亢进、气血壅滞瘀结等病理状态，气机升降失调属气机失常，可见于虚实多种病机，并非实的专属内涵，故为错误叙述。外感邪盛、肌肤经络闭塞、脏腑功能亢进、气血壅滞瘀结皆为实的常见表现"},{"q":"胃下垂、肾下垂、子宫脱垂、脱肛等症的病机，可能性最大的是","o":["气逆","气陷","气闭","气脱","气滞"],"a":1,"e":"气陷是气虚升举无力、清阳不升，以致内脏位置下移，胃下垂、肾下垂、子宫脱垂、脱肛皆由中气下陷、固摄升举失职所致。气逆是气上冲；气闭是闭塞不通；气脱是气外脱；气滞是运行不畅，均不致内脏下垂"},{"q":"可用阴阳相互转化解释的是","o":["寒极生热","阴损及阳","寒者热之","阴病治阳","阴中求阳"],"a":0,"e":"阴阳转化指阴阳在一定条件下可向其对立面转变，寒极生热即寒到极点转化为热，体现物极必反的转化规律。阴损及阳属阴阳互损；寒者热之属正治；阴病治阳、阴中求阳皆基于阴阳互根，均非相互转化的例证"},{"q":"根据五行学说，“肝火犯肺”属于","o":["子病犯母","相克","相乘","相侮","母病及子"],"a":3,"e":"金克木为正常相克，肝火犯肺是肝木反克肺金，属以下犯上的逆向克制，即相侮。相乘是顺克太过；子病犯母、母病及子属相生关系失常；相克是正常制约，均不能准确说明肝火犯肺的反克本质"},{"q":"金元时期，提出“病由邪生”、“邪去则正安”的医家是","o":["张元素","刘完素","张从正","朱丹溪","李东垣"],"a":2,"e":"张从正为金元四大家之一，主张病由邪生、邪去则正安，治疗重在攻邪，善用汗吐下三法。刘完素主寒凉；朱丹溪主滋阴；李东垣主补土；张元素为易水学派，皆非此论的倡导者"},{"q":"《素问·生气通天论》所谓：“阴平阳秘，精神乃治”，是指","o":["阴阳的对立制约关系正常","阴阳的依存互根关系正常","阴阳的消长平衡关系正常","阴阳的相互转化关系正常","阴阳的交感互藏关系正常"],"a":2,"e":"阴平阳秘，精神乃治指阴气平和、阳气固密，阴阳双方在消长变化中维持动态平衡，故为阴阳的消长平衡关系正常。对立制约、依存互根、相互转化、交感互藏虽皆为阴阳关系，但此语强调的是阴阳协调平衡的常态"},{"q":"关于邪郁化火论述错误的是","o":["可由风、寒、燥、湿等外邪引起","可由痰饮、瘀血等病理产物引起","因为人身有阳气，所以邪郁必然化火","其基本机制是人体阳气郁滞","邪郁化火可致疮疡"],"a":2,"e":"邪郁化火是邪气阻遏气机致阳气郁滞而化火，并非人身有阳气就必然化火，其形成需气机郁滞的条件，故该项错误。风寒燥湿等外邪、痰饮瘀血等病理产物均可致郁；基本机制为阳气郁滞；邪郁化火可致疮疡，均为正确论述"},{"q":"人的生命源于","o":["阴阳交感","阴阳互根","阴阳对立","阴阳转化","阴阳消长"],"a":0,"e":"阴阳交感指阴阳二气相互感应、交合，是万物产生和生命起源的根本，人的生命源于阴阳交感。互根、对立、转化、消长是阴阳的其他关系，虽参与生命活动，但作为生命之源者，当推阴阳交感"},{"q":"体型中最有代表性的差异是","o":["肥瘦","皮肉之厚薄","肤色","身高","腠理之坚松"],"a":0,"e":"体型指人体的形态外观，肥瘦反映形体壮实与虚胖、精气盛衰的差异，是体型中最具代表性的差异。皮肉厚薄、肤色、身高、腠理坚松虽也体现体质差别，但皆不及肥瘦之具代表性"},{"q":"人体之精分藏于五脏，但主要藏于","o":["肝","心","脾","肺","肾"],"a":4,"e":"五脏皆藏精，但肾藏精为主，肾精包括先天之精与后天之精，主生长发育与生殖，故人体之精主要藏于肾。肝藏血、心藏神、脾藏意、肺藏气，虽各有所藏，但非精的主要所藏之处"},{"q":"五脏六腑之大主是","o":["心","肺","脾","肝","肾"],"a":0,"e":"心主神明，为五脏六腑之大主，统率全身脏腑经络的功能活动，故五脏六腑之大主是心。肺为相傅之官；脾为仓廪之官；肝为将军之官；肾为作强之官，皆不及心之主宰地位"},{"q":"《小儿药证直诀》的作者是","o":["王叔和","皇甫谧","孙思邈","钱乙","陈无择"],"a":3,"e":"《小儿药证直诀》为宋代钱乙所著，系统论述小儿疾病的辨证论治，是儿科专著。王叔和著《脉经》；皇甫谧著《针灸甲乙经》；孙思邈著《千金方》；陈无择著《三因极一病证方论》，皆非本书作者"},{"q":"虚实病机中“虚”的内涵是","o":["邪气微弱","邪气亢盛","正气不足","正气郁闭","正邪相持"],"a":2,"e":"虚实病机中，虚指正气不足、抗病能力低下，实指邪气亢盛，故虚的内涵是正气不足。邪气微弱、邪气亢盛言邪的盛衰；正气郁闭属气机闭阻；正邪相持是相持不下，均非虚的定义"},{"q":"疾病的发生、发展与转归主要取决于","o":["邪正的盛衰","合理的饮食","禀赋的强弱","邪气的性质","感邪的轻重"],"a":0,"e":"疾病的发生、发展与转归取决于正气与邪气的力量对比，正邪盛衰决定发病与否及病势趋向，故主要取决于邪正的盛衰。合理饮食、禀赋强弱、邪气性质、感邪轻重皆是影响因素，但不若邪正盛衰之根本"},{"q":"卫气虚弱，与下列哪一项关系最密切","o":["肺气虚","脾气虚","心气虚","肾气虚","肝气虚"],"a":0,"e":"肺主气、司呼吸，宣发卫气于体表以温分肉、充皮肤、肥腠理，卫气的生成与布散依赖肺气，故卫气虚弱与肺气虚关系最密切。脾气虚重在运化；心气虚重在血脉；肾气虚重在封藏纳气；肝气虚重在疏泄，皆非卫气虚弱的主要相关之脏"},{"q":"易于感冒，是气的什么功能减弱的表现","o":["推动作用","温煦作用","防御作用","固摄作用","气化作用"],"a":2,"e":"气的防御作用指气能护卫肌表、抗御外邪，防御功能减弱则卫外不固，易受外邪侵袭而感冒，故易于感冒是防御作用减弱的表现。推动、温煦、固摄、气化作用分别关乎激发运动、保温、固护血津和物质转化，均与抗御外邪无直接对应"},{"q":"属于“实则泻其子”治则的治疗是","o":["肝火旺泻心火","脾火旺泻胆火","肝火旺泻脾","肝火旺泻肺","肺热泻大肠"],"a":0,"e":"实则泻其子指实证泻其所属五行之子，肝属木、心属火，木生火，心为肝之子，肝火旺泻心火即泻子以治母实，属实则泻其子。肝火泻肺是泻其所克；肺热泻大肠是泻表里之腑；余项皆不合母子相生的泻子之义"},{"q":"清气与水谷之气结合关系到","o":["元气的生成","宗气的生成","营气的生成","卫气的生成","全身之气的生成"],"a":1,"e":"宗气由肺吸入的自然界清气与脾胃化生的水谷精气结合而成，积于胸中，故清气与水谷之气结合关系到宗气的生成。元气源于肾精；营气、卫气由水谷精气化生；全身之气是诸气总称，皆非清气与水谷之气直接结合之物"},{"q":"生命形成的根本在于","o":["阴阳互根","父母之精交合","阴阳对立","阴阳转化","阴阳消长"],"a":1,"e":"生命由父母之精交合而成，精是生命的物质基础，两精相搏而有新生命，故生命形成的根本在于父母之精交合。阴阳互根、对立、转化、消长是阴阳的关系，虽贯穿生命过程，但非生命形成的物质根源"},{"q":"在疾病传变的过程中，从太阳传至太阴是","o":["循经传","越经传","表里传","逆传","顺传"],"a":1,"e":"六经传变中，太阳传阳明、少阳为循经，若从太阳径传太阴，跳过阳明、少阳两经，即为越经传。循经传是按次序相传；表里传是表里经相移；逆传、顺传多就温病卫气营血或三焦而言，均不合太阳直接传太阴"},{"q":"对全身络脉起主导作用的是","o":["正经","奇经","阳跷脉、阴跷脉","阳维脉、阴维脉","别络"],"a":4,"e":"别络是络脉中的较大者，十五别络网络全身络脉，对全身络脉起主导统率作用，故为别络。正经即十二经脉，属经而非络；奇经调节十二经气血；跷脉、维脉皆属奇经，主司特定功能，均不对全身络脉起主导作用"},{"q":"临床上治疗瘀血病证时，在使用活血化瘀药物的同时会加入行气的药物，其理论依据是","o":["气能生血","气能行血","气能摄血","血能载气","血能养气"],"a":1,"e":"气为血之帅，气能行血，气推动血液运行，气行则血行，故活血化瘀的同时加入行气药，借气行以助血行。气能生血言血之生成；气能摄血言固摄；血能载气、血能养气言血对气的作用，均非加用行气药的依据"},{"q":"脾在时为","o":["春","长夏","秋","冬","夏"],"a":1,"e":"五行配四时五季，脾属土，土主长夏，长夏湿气当令与脾土相应，故脾在时为长夏。春属木应肝，夏属火应心，秋属金应肺，冬属水应肾，四季与五脏的对应各有归属，非脾之所主"},{"q":"肝在时为","o":["春","长夏","秋","冬","夏"],"a":0,"e":"肝主疏泄，喜条达而恶抑郁，与春气生发相应，故肝气旺于春，春阳升动有助肝气条达。夏属火应心，长夏属土应脾，秋属金应肺，冬属水应肾，四时与五脏各有所配，唯春对应肝，余季分属他脏"},{"q":"人体根本之气是","o":["元气","卫气","营气","宗气","经络之气"],"a":0,"e":"元气根于肾，由肾中精气所化生，赖脾胃运化之水谷精气培育，经三焦布散全身，是人体最根本、最重要的气，故为人体根本之气。宗气积胸中而行呼吸、贯心脉，营气行脉中化生血液，卫气行脉外司防御，皆由元气派生，非根本"},{"q":"“壮水之主，以制阳光”是指","o":["阴中求阳","阳中求阴","阳病治阴","阴病治阳","治寒以热"],"a":2,"e":"“壮水之主，以制阳光”为王冰对阴虚火旺治法的概括，即滋阴以抑制相对亢盛之阳，属阳病治阴。阳中求阴是于补阴中佐以补阳，阴中求阳反之，均为阴阳互根的具体运用；阴病治阳针对阳虚，治寒以热属正治，与滋阴制火无关"},{"q":"肾精化为生殖之精以施泄，依靠于","o":["肾阳推动","肾阴滋润","天癸促发","脾胃运化","肝气疏泄"],"a":2,"e":"天癸是肾中精气充盈到一定程度产生的精微物质，能促进生殖器官发育成熟并维持生殖机能，肾精化生生殖之精而施泄全赖天癸促发。肾阳推动重在温煦激发脏腑机能，肾阴滋润重在濡润，脾胃运化供给后天之精，肝气疏泄调畅气机，均非施泄的直接动因"},{"q":"在疾病传变过程中，由太阴传至阳明是","o":["循经传","越经传","表里传","直中","合病"],"a":2,"e":"太阴属脾、阳明属胃，二者互为表里，太阴传阳明即由表入里、由阴转阳的表里传。循经传是依十二经次序相传，越经传是跳过一经而传，直中为邪气直入三阴，合病为两经同时发病，均与太阴阳明的表里关系不符"},{"q":"下列哪项是对肺的主要生理机能的高度概括","o":["肺主气司呼吸","肺主行水","肺气宣降","肺朝百脉","肺主治节"],"a":4,"e":"肺主治节指肺辅佐心治理调节全身气、血、津液及脏腑机能，涵盖主气、司呼吸、宣降、通调水道、朝百脉等，是对肺主要生理机能的高度概括。肺主气司呼吸、主行水、肺气宣降、肺朝百脉皆只是治节某一方面的具体体现，不足以概括全局"},{"q":"阴阳学说是研究阴阳的内涵及其","o":["运动状态","静止状态","标示的事物现象","运动变化规律","辨证法"],"a":3,"e":"阴阳学说研究阴阳的内涵及其运动变化规律，认为阴阳既对立统一又处于不断的消长转化之中。运动状态、静止状态只是阴阳属性的表现方面，标示的事物现象属阴阳的可分性，辨证法为哲学概念，均非该学说研究的核心对象"},{"q":"血之余为","o":["骨","发","齿","血海","唇"],"a":1,"e":"发由血所养，故称发为血之余，血盛则发润泽，血虚则发枯槁脱落。骨为肾所主，齿为骨之余，唇属脾之外华，血海即冲脉，皆非血之余，其中齿与骨同源于肾，尤须与发区分"},{"q":"呼吸与五脏密切相关，特别是","o":["肝","心","脾","肺","肾"],"a":3,"e":"肺主气司呼吸，直接主宰呼吸运动，故呼吸与五脏关系中首推肺。肾主纳气仅摄纳肺吸入之清气，肝主疏泄调畅气机，脾主运化生气，心主血脉行血，虽与呼吸间接相关，但均不直接司呼吸运动"},{"q":"临床上，小儿常易感受外邪或因饮食所伤而发病，其主要因素是","o":["地域因素","气候因素","体质因素","生活、工作环境","精神状态"],"a":2,"e":"体质因素决定正气强弱与邪气易感性，小儿脏腑娇嫩、形气未充，体质脆弱，故易感外邪或因饮食所伤而发病。地域、气候、生活与工作环境属外在环境条件，精神状态影响气机，皆须通过体质这一内在根据才起作用"},{"q":"“痰阻于胃”可见的临床症状是","o":["喘咳咯痰","胸闷心悸","恶心呕吐","半身不遂","眩晕昏冒"],"a":2,"e":"胃主受纳腐熟，痰浊阻滞于胃，胃失和降、气机上逆，故见恶心呕吐。喘咳咯痰为痰阻于肺，胸闷心悸为痰阻心脉，半身不遂为痰阻经络，眩晕昏冒为痰蒙清窍，病位各别，不可与痰阻于胃混淆"},{"q":"明清时期，首创“戾气”说的医家是","o":["吴鞠通","赵献可","叶天士","薛雪","吴又可"],"a":4,"e":"吴又可（吴有性）著《温疫论》，首创戾气说，认为温疫由口鼻吸入戾气而发，非一般六淫。吴鞠通著《温病条辨》创三焦辨证，叶天士创卫气营血辨证，薛雪专论湿热，赵献可倡命门学说，均与戾气说无涉"},{"q":"用于阳盛格阴的治则是","o":["寒因寒用","热因热用","通因通用","热者寒之","寒者热之"],"a":0,"e":"阳盛格阴即真热假寒，内里热盛而格阴于外，见四肢厥冷等假寒象，治当以寒药治其假寒，即寒因寒用。热因热用治阴盛格阳之真寒假热，通因通用治真实假虚之泄泻，热者寒之、寒者热之属正治，与格阴反治不同"},{"q":"心在窍为","o":["爪","唇","鼻","口","舌"],"a":4,"e":"心开窍于舌，舌为心之苗，心的气血上荣于舌，故心之精气盛衰可于舌质、舌色及语言功能体现。爪为肝之外华，唇为脾之外华，鼻为肺之窍，口为脾之窍，各归其脏，唯舌属心"},{"q":"天人合一的思维方式属于","o":["象思维","系统思维","变易思维","逻辑思维","辨证思维"],"a":1,"e":"天人合一将人与自然界视为相互关联的有机整体，强调人与天地相应，属系统思维。象思维是以象取类比象的思维方式，变易思维强调事物运动变化，逻辑思维与辨证思维非中医学概括天人关系的主要思维方式"},{"q":"下列除哪项外均属于影响体质的先天因素","o":["父母的体质","父母的生育年龄","母体孕期调养","家庭居住地","母体妊娠期疾病"],"a":3,"e":"家庭居住地属后天的生活环境，影响体质但非先天因素，故为除外项。父母的体质与生育年龄决定禀赋强弱，母体孕期调养与妊娠期疾病直接影响胎儿发育，均属先天因素，与居住地的后天属性判然有别"},{"q":"容易导致人体阴阳失调的饮食因素有","o":["饮食不洁","饮食过饱","五味偏嗜","饮食过饥","寒热偏嗜"],"a":4,"e":"寒热偏嗜直接导致阴阳偏盛偏衰，如过食寒凉伤阳、过食温热伤阴，是导致阴阳失调的饮食因素。饮食不洁多致脾胃湿热或虫积，过饱伤脾胃运化，过饥致气血生化不足，五味偏嗜则致脏腑偏盛偏衰，病机侧重各异"},{"q":"明清时期，改正了古籍中的某些解剖错误，并发展了瘀血理论的医家是","o":["吴又可","赵献可","叶天士","薛雪","王清任"],"a":4,"e":"王清任著《医林改错》，改正古籍中人体解剖的某些错误，并创立瘀血理论，提出补阳还五汤等逐瘀方剂。吴又可倡戾气说，赵献可主命门学说，叶天士创卫气营血辨证，薛雪论湿热，皆非更正解剖发展瘀血理论者"},{"q":"在肺的生理功能中与尿液生成关系密切的是","o":["肺朝百脉","肺气宣发","肺气肃降","肺为娇脏","肺主气司呼吸"],"a":2,"e":"肺气肃降使肺气向下向内运行，并将津液下输至肾与膀胱，参与尿液生成，故与尿液生成关系密切。肺朝百脉指全身血液经肺，肺气宣发主向上向外布散，肺主气司呼吸主气体交换，肺为娇脏言其易受邪，均非直接关乎尿液生成"},{"q":"以下可用阴阳互相转化来解释的是","o":["阳虚则寒","重阴必阳","寒者热之","阴损及阳","阴盛则阳病"],"a":1,"e":"重阴必阳指阴气盛极而转化为阳，是阴阳在一定条件下相互转化的典型例证。阳虚则寒属阳虚阴盛的病理，寒者热之为正治法则，阴损及阳是阴虚累及阳气的互损，阴盛则阳病为阴盛伤阳，均非转化"},{"q":"下列事物中属阳的是","o":["左","右","北","浊","寒"],"a":0,"e":"阴阳属性以方位分，左升右降，左属阳、右属阴；以南为阳、北为阴，故北属阴；浊重下沉属阴，清轻上升属阳；寒凉属阴，温热属阳。五项之中唯左符合阳的属性，其余皆属阴"},{"q":"“内风”与何脏关系最为密切","o":["心","肝","脾","肺","肾"],"a":1,"e":"肝主疏泄，主藏血，风气通于肝，肝阳上亢或肝血不足均可化生内风，故内风与肝关系最密切。心主神志，脾主运化，肺主气，肾主水，虽可因他脏病变引动肝风，但内风之化生终究以肝为根本"},{"q":"脏腑病机理论的指导思想是","o":["阴阳失调","五行失常","整体观念","邪正盛衰","标本缓急"],"a":2,"e":"整体观念是脏腑病机理论的指导思想，强调人体脏腑经络是一个有机整体，病理上相互影响、传变。阴阳失调、邪正盛衰是病机的基本内容，五行失常是传变规律，标本缓急是治疗原则，均非指导思想层面的概括"},{"q":"下列哪项不属于烧烫伤","o":["沸水烫伤","雷电击伤","高温灼伤","蒸汽灼伤","烈火烧伤"],"a":1,"e":"烧烫伤由热力所致，沸水烫伤、高温灼伤、蒸汽灼伤、烈火烧伤皆属热力损伤。雷电击伤系电能所致电击伤，其损伤机制与热力烧伤不同，另有电烧伤的特点，故不属一般烧烫伤范畴"},{"q":"精血同源可归属于","o":["心与肾的关系","脾与肾的关系","肺与肾的关系","肝与肾的关系","心与肝的关系"],"a":3,"e":"肝藏血、肾藏精，精能生血、血能化精，精血互生互化，故称精血同源，归属于肝肾关系，又称肝肾同源。心与肾主要是水火既济，脾与肾为先后天互资，肺与肾为金水相生，心与肝主血脉与藏血，均非精血同源"},{"q":"《素问•六节藏象论》中，“封藏之本”所指的是","o":["心","肺","脾","肝","肾"],"a":4,"e":"《素问·六节藏象论》称肾主蛰，为封藏之本，肾主藏精，闭藏肾精而不妄泄，故为封藏之本。心为生之本，肺为气之本，脾为仓廪之本，肝为罢极之本，各有其称，封藏专属于肾"},{"q":"下列选项中，属于药邪形成原因错误的是","o":["用药过量","炮制不当","配伍不当","用法不当","言语不当"],"a":4,"e":"药邪指药物使用不当致病情加重或产生新病，用药过量、炮制不当、配伍不当、用法不当均为其成因。言语不当属医护言行失当，可致医源性疾病，但不产生药邪，与药物本身的制备和使用无直接关系"},{"q":"阳偏衰则会出现","o":["虚热证","实热证","实寒证","寒热错杂","虚寒证"],"a":4,"e":"阳偏衰即阳气不足，温煦功能减退，虚寒内生，故出现虚寒证，症见畏寒肢冷、面色苍白、脉虚迟。虚热证由阴偏衰所致，实热证由阳偏盛所致，实寒证由阴偏盛所致，寒热错杂为寒热并见，均非阳虚之候"},{"q":"下列哪项不属于瘀血致病的临床表现","o":["肌肤甲错","出血紫黯","刺痛拒按","唇甲色淡","肿块固定"],"a":3,"e":"唇甲色淡是血虚不能濡养爪甲口唇的表现，不属瘀血致病。瘀血阻滞不通则刺痛拒按、痛处固定不移，肌肤失养则肌肤甲错，血不归经则出血紫黯，有形之邪停积则成肿块固定，皆为瘀血典型表现"},{"q":"明清时期，认为温病的病因是戾气，而非一般六淫的医学家是","o":["吴鞠通","赵献可","叶天士","薛雪","吴又可"],"a":4,"e":"吴又可著《温疫论》，提出温病（温疫）病因是戾气而非一般六淫，从口鼻而入。吴鞠通著《温病条辨》，叶天士倡卫气营血辨证，薛雪论湿热病，赵献可主命门学说，均未提出戾气致病之说"},{"q":"经络系统中，有加强经脉在体表联系和渗灌气血等作用的是","o":["经脉","络脉","浮络","孙络","别络"],"a":1,"e":"络脉由经脉分出，纵横交错，遍布全身，有加强经脉在体表联系和渗灌气血的作用。经脉为经络系统主干，浮络是浮于体表的络脉，孙络是最细小的络脉，别络为较大的分支，皆属络脉的不同层次而非整体功能概括"},{"q":"疾病发生的内在根据是","o":["邪气盛","正气虚","阴阳失调","寒热偏胜","邪正盛衰"],"a":1,"e":"正气虚是疾病发生的内在根据，正气不足则卫外不固、邪气得以侵入，故正气存内则邪不可干。邪气盛是发病的重要条件，阴阳失调是病机总纲，寒热偏胜为病机表现，邪正盛衰决定病证虚实，均非发病的内在根据"},{"q":"使用催吐剂，正确的调理方法是","o":["糜粥自养","食辛辣食物","硬性食物","寒凉食物","热性食物"],"a":0,"e":"涌吐后胃气受损、津液耗伤，故以糜粥自养，调养胃气、补充津液而助恢复。食辛辣、热性食物助火伤津，硬性食物难消化碍胃，寒凉食物伤中阳，皆不宜于吐后调护，与糜粥自养的顾护胃气相反"},{"q":"“水火既济”是属于","o":["心肾关系","肝肾关系","脾肾关系","肺肾关系","心肺关系"],"a":0,"e":"心属火居上，肾属水居下，心火下温肾水使肾水不寒，肾水上济心火使心火不亢，如此水火既济，属心肾关系。肝肾关系为精血同源，脾肾为先后天互资，肺肾为金水相生，心肺为气血相依，均非水火既济"},{"q":"下列各项在五行中属“土”的是","o":["收","苦","肉","风","鼻"],"a":2,"e":"五行中土爰稼穑，主生化、承载、受纳，肌肉由脾胃化生之水谷精微所养，在体合肉，故肉属土。收为金之特性，苦味入心属火，风为木之气，鼻为肺之窍属金，皆与土的生化承载之性不符"},{"q":"肺主气的功能取决于","o":["司呼吸","宗气的生成","全身气机的调节","朝百脉","主治节"],"a":0,"e":"肺主气包括主呼吸之气与主一身之气，而肺主气的功能以司呼吸为基础，呼吸正常则清浊交换、气机调畅。宗气生成是肺主一身之气的具体体现，全身气机调节赖肺的宣降，朝百脉、主治节为肺的其他机能，皆非主气的直接依据"},{"q":"下列哪项在心主血脉中起关键作用","o":["心血充盈","心气充沛","心神安宁","心搏如常","脉道通利"],"a":1,"e":"心主血脉指心气推动血液在脉中运行，心气充沛则搏动有力、血行通畅，故心气是主导因素。心血充盈是物质基础，心搏如常是气充足的表现，脉道通利是必要条件，心神安宁属心主神志范畴，皆非起关键作用的动力"},{"q":"十二经脉，内属于腑脏，外络的组织是","o":["肢节","下肢部","背部","胸胁部","腹部"],"a":0,"e":"《灵枢》称经脉内属于腑脏、外络于肢节，十二经脉内连脏腑、外布肢体关节，故外络的组织是肢节。下肢部、背部、胸胁部、腹部只是肢节与躯干的局部，不足以概括经脉外络的整体范围"},{"q":"能够辅助心行血于周身的是肺的哪项生理机能","o":["肺朝百脉","肺为华盖","肺主气司呼吸","肺主行水","肺气肃降"],"a":0,"e":"肺朝百脉指全身血液经百脉会聚于肺，通过呼吸进行气体交换，再输布全身，辅助心推动血液运行周身。肺为华盖言其位置最高，肺主气司呼吸主气体交换，肺主行水主通调水道，肺气肃降主气下行，均非助心行血"},{"q":"心为“君主之官”的理论依据是","o":["心总统意志","心主血脉","心主神志","心主情志","心总统魂魄"],"a":2,"e":"心主神志，神明为一身之主，故心称君主之官，强调其对全身机能的主宰作用。心主血脉是心的另一机能，总统意志、总统魂魄非心的规范表述，心主情志亦不确，皆非君主之官的理论依据"},{"q":"脏腑中“主津”作用的是","o":["脾","肾","大肠","小肠","三焦"],"a":2,"e":"大肠接受小肠下注之物，吸收其中残余水分而变化成形，故称大肠主津。小肠主液，泌别清浊而吸收水谷精微与大量水液，脾主运化水液，肾主水，三焦为水道，均与主津之称不符"},{"q":"金元四大家中，在治疗中善用寒凉清热的医家是","o":["张元素","刘完素","张从正","朱丹溪","李东垣"],"a":1,"e":"刘完素为金元四大家之一，倡导火热论，治疗善用寒凉清热，世称寒凉派。张从正主攻下，为攻邪派；朱丹溪倡滋阴，为滋阴派；李东垣重脾胃，为补土派；张元素为易水学派代表，非寒凉派"},{"q":"“吐下之余，定无完气”病机理论依据是","o":["气能生津","气能行津","津能载气","血能载气","津血同源"],"a":2,"e":"津能载气，津液是气的载体之一，吐下太过则津液大量丢失，气随津脱而耗伤，故有吐下之余定无完气之说。气能生津、气能行津言气对津液的作用，方向相反；血能载气指血为气母，津血同源言二者互化，均非此说的依据"},{"q":"经络系统中的主干线，数量较少者是","o":["经脉","络脉","浮络","孙络","别络"],"a":0,"e":"经脉是经络系统的主干，多为纵行、路径较长、数量较少，环流贯注如环无端。络脉由经脉分出而数量众多，浮络、孙络、别络皆属络脉范畴，分支细小、分布广泛，与经脉为主干线、数量较少的特点相反"},{"q":"既属于“五体”，又属奇恒之腑的是","o":["脑","脉","女子胞","髓","胆"],"a":1,"e":"五体为皮、肉、筋、骨、脉，奇恒之腑为脑、髓、骨、脉、胆、女子胞，脉兼具二者，故既属五体又属奇恒之腑。脑、髓、女子胞、胆虽属奇恒之腑但不入五体，五体中骨虽亦属奇恒之腑，须明脉之双重归属"},{"q":"创立“引经报使”理论的医家是","o":["刘完素","张元素","孙思邈","张子和","张介宾"],"a":1,"e":"张元素（洁古）创立引经报使理论，认为某些药物可引导诸药直达病所，如桔梗载药上行、牛膝引血下行。刘完素主寒凉，张子和即张从正主攻下，孙思邈为唐代医家，张介宾为明代温补派，均非引经报使说的创立者"},{"q":"生气之主指的是","o":["肝","心","脾、胃","肺","肾"],"a":3,"e":"肺主一身之气，参与气的生成特别是宗气的生成，并能调节全身气机，故称生气之主。脾胃为气血生化之源，称生气之源；肾藏精化气，为生气之根；肝主疏泄调气，心主血脉行血，皆非生气之主"},{"q":"下列各项，与肺主通调水道功能关系最密切的是","o":["气机的调节","朝百脉","主宣发与肃降","司呼吸","宗气的生成"],"a":2,"e":"肺主通调水道指肺通过宣发肃降调节津液的输布、运行与排泄，宣发将津液布散全身、外达皮毛，肃降使津液下输肾与膀胱，故以主宣发与肃降关系最密切。气机调节、朝百脉、司呼吸、宗气生成虽为肺的功能，但不直接主水道通调"},{"q":"胃的主要病机特点是","o":["受纳腐熟功能失常","贮藏排泄功能失常","消化吸收功能失常","传导功能失常","气化功能失常"],"a":0,"e":"胃主受纳、腐熟水谷，故其主要病机为受纳腐熟功能失常，见纳呆、胃脘胀痛、嗳腐吞酸等。贮藏排泄失常属肝胆，消化吸收失常属脾，传导失常属大肠，气化失常属膀胱或三焦，病位与胃各异"},{"q":"与防止出血密切相关的两脏是","o":["心与肝","肝与脾","心与脾","肝与肾","肺与肝"],"a":1,"e":"肝藏血，脾统血，肝血充足则血有所归，脾气健旺则血不外溢，二者共同防止出血，故与防止出血密切相关者为肝与脾。心主血脉、肾藏精、肺主气，虽与血相关，但统摄与藏血之职分属肝脾，余脏不主此"},{"q":"在气的生成过程中，尤为重要的是","o":["肺的呼吸功能","脾胃的运化功能","肾的闭藏功能","肺肾的协调功能","心的主血功能"],"a":1,"e":"脾胃为气血生化之源，水谷精微是气化生的基础，故气的生成中脾胃运化尤为重要。肺的呼吸吸入自然之清气、肾的闭藏固摄精气、肺肾协调、心主血脉行血皆参与气的生成或运行，但后天化生之源以脾胃为要"},{"q":"六淫中最易伤肺的邪气是","o":["风邪","寒邪","燥邪","暑邪","热邪"],"a":2,"e":"燥邪干涩，易伤津液，肺为娇脏、喜润恶燥，开窍于鼻、外合皮毛，燥邪多从口鼻而入首犯肺，故燥邪最易伤肺。风邪善行数变，寒邪收引凝滞，暑邪升散耗气，热邪燔灼伤津，伤肺之专以燥邪为最"},{"q":"六淫中致病后可出现各种秽浊症状的邪气是","o":["风邪","寒邪","燥邪","湿邪","热邪"],"a":3,"e":"湿性秽浊，致病可见面垢眵多、大便溏泻、下痢黏冻、带下浑浊等秽浊症状，故为湿邪。风邪善行而数变，寒邪凝滞主痛，燥邪干涩伤津，热邪燔灼动血，皆无秽浊这一特征"},{"q":"患者，男，40岁。素有高血压病史，现症见眩晕耳鸣，面红头胀，腰膝酸软，失眠多梦，时有遗精或性欲亢进，舌红，脉沉弦细。其病机是","o":["阴虚内热","阴损及阳","阴虚阳亢","阳损及阴","阴虚火旺"],"a":2,"e":"眩晕耳鸣、面红头胀为肝阳上亢，腰膝酸软、遗精、脉沉弦细为肾阴亏虚，阴虚于下、阳亢于上，故病机为阴虚阳亢。阴虚内热以潮热盗汗为主，阴损及阳、阳损及阴强调阴阳互损，阴虚火旺重在虚火内扰，均无上亢之象"},{"q":"横骨压痛，提示","o":["月经不调","肠痈","高血压","肺脏疾病","脾虚"],"a":0,"e":"横骨相当于耻骨部位，为胞宫、冲任所过，妇人耻骨部压痛多提示妇科经带胎产病变，如月经不调。肠痈压痛在右下腹阑尾点，高血压多见头痛眩晕，肺脏疾病见胸部体征，脾虚以腹部虚喜按为主，部位与横骨不同"},{"q":"真实假虚证的治疗原则应是","o":["祛邪兼扶正","扶正兼祛邪","先祛邪，后扶正","单独祛邪","先扶正，后祛邪"],"a":3,"e":"真实假虚即大实有羸状，本质为实邪内聚、阻滞气血，外见类似虚象的假象，治当攻邪为主，故单纯祛邪。祛邪兼扶正、扶正兼祛邪适用于虚实夹杂，先祛邪后扶正、先扶正后祛邪有虚实主次先后之别，均非纯实之治"},{"q":"八纲辨证的总纲是","o":["虚实","阴阳","表里","寒热","真假"],"a":1,"e":"阴阳是八纲辨证的总纲，表、里、寒、热、虚、实六者皆可归属于阴阳，表热实为阳，里寒虚为阴，故以阴阳统摄其余六纲。虚实、表里、寒热是八纲的具体内容，真假是辨证疑点，均不能总括八纲"},{"q":"下列各组经脉中，从胸腔走向手指末端的是","o":["心肝肾经","心肺心包经","胆胃三焦经","心胆小肠经","肺脾胆经"],"a":1,"e":"手三阴经起于胸腔，循上肢内侧走向手指末端，故心肺心包经从胸走手。心肝肾经中肝肾属足经，胆胃三焦经多从手走头或从头走足，肺脾胆经、心胆小肠经走向各异，不合胸走手指"},{"q":"气在中医学理论体系中比较完整的概念是","o":["泛指机体的生理功能","构成世界的基本物质","构成人体和维持人体生命活动的最基本物质","指人体抗病能力","维持人体生命活动的基本物质"],"a":2,"e":"气是构成人体和维持人体生命活动的最基本物质，具有推动、温煦、防御、固摄、气化等作用，此概念涵盖其物质性与功能性，最为完整。泛指生理功能失之宽泛，构成世界的基本物质为哲学概念，抗病能力仅指卫气，维持生命的基本物质表述不全"},{"q":"属于六经病机中三阳病的病机特征的是","o":["多属热、属实","多属虚、属寒","多属寒、属实","多属热、属虚","多正虚、邪盛"],"a":0,"e":"三阳病包括太阳、阳明、少阳，多由邪气亢盛、正气未虚，邪正剧争，故病机以热、实为主。三阴病正气已虚，多属虚属寒、多正虚邪盛；多寒属实、多热属虚的表述均与三阳病不符"},{"q":"根据五行学说，水火既济是指","o":["心肾相交","肝脾调和","肝肾同源","肺肾相生","脾肾互济"],"a":0,"e":"心属火、肾属水，心火下降温肾、肾水上升济心，水火相交既济，故水火既济即心肾相交。肝脾调和为肝脾关系，肝肾同源指精血互生，肺肾相生为金水相生，脾肾互济为先后天互资，均非水火既济"},{"q":"称为“髓海”的是","o":["太阳经","脑","肾","脉","肝"],"a":1,"e":"《灵枢·海论》称脑为髓之海，脑由髓汇聚而成，髓由肾精化生，肾精充足则髓海满，故脑称髓海。太阳经为经脉之名，肾主骨生髓但不称髓海，脉为奇恒之腑，肝主疏泄，皆非髓海"},{"q":"在影响疾病传变的因素中起决定作用的是","o":["邪正斗争","环境因素","生活因素","诊治因素","心理因素"],"a":0,"e":"邪正斗争贯穿疾病传变始终，正胜邪则病退，邪胜正则病进，其力量对比决定传变的方向与速度，故起决定作用。环境、生活、诊治、心理等因素通过影响邪正斗争而影响传变，均属影响因素而非决定因素"},{"q":"推动人体生长发育及脏腑生理活动的气是","o":["元气","宗气","营气","卫气","动气"],"a":0,"e":"元气由肾中精气化生，经三焦布散全身，推动人体生长发育并激发各脏腑经络的生理活动，是人体生命活动的原动力。宗气主呼吸与贯心脉，营气营养全身并化血，卫气防御固表，动气非经脉之气常态称谓，均非推动生长发育之气"},{"q":"脏腑之中，被称为“孤府”的是","o":["胆","胃","三焦","脾","脑"],"a":2,"e":"三焦为六腑之一，无表里相配、无形质可循，独行于一身而主气化、通水道，故称孤府，言其独立于脏腑配对之外。胆为六腑兼奇恒之腑，胃主受纳，脾为脏，脑为奇恒之腑，皆不称孤府"},{"q":"属于奇恒之腑，下列错误的是","o":["脑","三焦","胆","脉","骨"],"a":1,"e":"奇恒之腑包括脑、髓、骨、脉、胆、女子胞，三焦属六腑而不属奇恒之腑，故为错误项。脑、胆、脉、骨均在奇恒之腑之列，其中胆既属六腑又属奇恒之腑，须与三焦的纯六腑属性区分"},{"q":"下列哪项是胃的生理功能","o":["水谷精微的转输","水谷的受纳和腐熟","水液的吸收和转输","脏器位置的维系","血液的统摄"],"a":1,"e":"胃主受纳水谷、腐熟水谷，将食糜下传小肠，故胃的生理功能是水谷的受纳和腐熟。水谷精微的转输属脾，水液的吸收转输属小肠、脾，脏器位置的维系属脾主升举，血液的统摄属脾统血，病位功能各异"},{"q":"中医饮食养生所提倡的，下列错误的是","o":["药膳保健","注意饮食卫生","提倡饮食有节","克服饮食偏嗜","强调高营养饮食"],"a":4,"e":"中医饮食养生提倡饮食有节、注意卫生、克服偏嗜、药膳保健，讲究五谷为养、五味调和，从不强调高营养饮食，故强调高营养饮食错误。药膳保健、注意饮食卫生、提倡饮食有节、克服饮食偏嗜均为中医养生的重要内容"},{"q":"嗜酒可引起的是","o":["寒从中生","聚湿生痰","耗伤肺津","食滞胃肠","心火亢盛"],"a":1,"e":"酒性湿热，嗜酒过度则湿热内蕴，脾失健运，湿聚成痰，故嗜酒可聚湿生痰。寒从中生多因阳虚内寒，耗伤肺津多为燥热，食滞胃肠由饮食过量，心火亢盛多因情志或热邪，均非嗜酒的直接主要后果"},{"q":"五行学说中“火”的特性是","o":["曲直","炎上","从革","润下","稼穑"],"a":1,"e":"火曰炎上，火性温热、升腾、光明，炎上即引申为凡温热、升腾、明亮之象皆归于火。曲直为木之特性，从革为金之特性，润下为水之特性，稼穑为土之特性，五行各自特性分明，不可混淆"},{"q":"心主血脉与哪一项机能密切相关","o":["心藏神","心脉畅通","心神清明","心气充盈","心血充足"],"a":0,"e":"心主血脉与心藏神密切相关，血是神志活动的物质基础，血脉充盈运行正常则心神得养、神志清明。心脉畅通是主血脉的条件，心气充盈是动力，心血充足是基础，心神清明是心藏神的状态，题干重在两机能的相关性而非单一条件"},{"q":"具有“泻而不藏”特点的是","o":["五脏","六腑","脏腑","奇恒之腑","以上均非"],"a":1,"e":"六腑主传化水谷，泻而不藏，以通为用、以降为顺，故具有泻而不藏特点的是六腑。五脏藏而不泻，主贮藏精气；奇恒之腑形似腑而功能似脏，藏而不泻；脏腑为总称；以上均非不符事实"},{"q":"下列除哪项外，均属于疾病的复发诱因","o":["重感致复","食复","过逸","药物","情志致复"],"a":2,"e":"过逸指过度安逸，气血运行不畅，可致气滞血瘀、脾胃虚弱，但不属疾病复发诱因。重感致复因复感新邪，食复因饮食失节，药复因用药不当，情志致复因情志波动，皆为病后正气未复时常见的复发诱因"},{"q":"下列各项，不属肝主疏泄功能的是","o":["调畅气机","调畅情志","促进骨骼发育","促进脾胃的运化","促进血液运行"],"a":2,"e":"肝主疏泄，能调畅气机、调畅情志、促进脾胃运化、促进血液运行与津液输布，但不主骨骼发育。促进骨骼发育是肾的功能，肾主骨生髓，与肝主疏泄无涉；调畅气机、调畅情志、促进脾胃运化、促进血液运行皆属疏泄范畴"},{"q":"金元四大家中“寒凉派”的代表人物是","o":["张元素","刘完素","张从正","朱丹溪","李东垣"],"a":1,"e":"刘完素倡导火热论，认为六气皆从火化，治疗多用寒凉，为寒凉派代表。张从正主攻邪、为攻邪派；朱丹溪倡阳常有余阴常不足、为滋阴派；李东垣重脾胃、为补土派；张元素为易水学派，均非寒凉派"},{"q":"心的主要生理功能是","o":["主藏血","主神志","主运化","主统血","主疏泄"],"a":1,"e":"心主神志，主宰人体精神、意识、思维活动，为心的主要生理功能之一，另一为主血脉。主藏血属肝，主运化属脾，主统血属脾，主疏泄属肝，皆为他脏之职，非心之功能"},{"q":"“见肝之病，知肝传脾，当先实脾”的治法属于","o":["控制疾病传变","提高抗邪能力","避免病邪侵入","早期诊断治疗","防止疾病发生"],"a":0,"e":"见肝之病、知肝传脾、当先实脾，是在肝病初期预先调补脾脏，防止肝病传脾，属控制疾病传变。提高抗邪能力重在扶正固本，避免病邪侵入属未病先防，早期诊断治疗强调早治，防止疾病发生属预防，均非既病后防其传变"},{"q":"在一定条件下，“五志过极”和“五气”皆可化","o":["风","寒","湿","燥","火"],"a":4,"e":"五志过极则气机郁滞而化火，五气郁久亦从火化，故在一定条件下五志与五气皆可化为火。风、寒、湿、燥虽为六淫之一，但五志五气化生之趋向以火为归，他邪非其化生之果，此为刘完素火热论的依据之一"},{"q":"根据五行学说，水之“所胜”是","o":["木","水","金","火","土"],"a":3,"e":"五行相克中，克我者为所不胜，我克者为所胜，所胜即我所能克者。水克火，故水之所胜为火。木为水之所生，水为自身，金生水为水之母，土克水为水之所不胜，皆非水之所胜"},{"q":"肾在时为","o":["春","长夏","秋","冬","夏"],"a":3,"e":"肾属水，主封藏，冬主闭藏，与肾封藏之性相合，故肾在时为冬。春属木应肝，长夏属土应脾，秋属金应肺，夏属火应心，四时配五脏各有定属，冬季则专应于肾"},{"q":"称为“水谷气血之海”的是","o":["脾","大肠","小肠","胃","三焦"],"a":3,"e":"胃主受纳水谷、腐熟水谷，水谷入胃而气血由是化生，为水谷汇聚之处、气血生化之源，故称水谷气血之海。脾主运化而非受纳之海，大肠传导糟粕，小肠受盛化物，三焦为水道，皆非此海"},{"q":"金元四大家中“补土派”的代表人物是","o":["张元素","刘完素","张从正","朱丹溪","李东垣"],"a":4,"e":"李东垣著《脾胃论》，认为脾胃为元气之本，百病皆由脾胃衰而生，治疗重在补益脾胃，为补土派代表。张元素为易水学派，刘完素为寒凉派，张从正为攻邪派，朱丹溪为滋阴派，均非补土派"},{"q":"中医学构建经脉“子午流注”理论，所体现的思维方式是","o":["整体宏观","天人合一","恒动变化","动静相召","辨证唯物"],"a":1,"e":"子午流注依一日十二时辰气血在十二经脉中循环流注的规律，将人体气血运行与自然界时间周期相联系，体现天人合一。整体宏观强调从整体把握，恒动变化强调运动，动静相召、辨证唯物非中医学概括此理论的主要思维方式"},{"q":"小肠的主要生理功能是","o":["主运化","主通调水道","主受纳","主腐熟水谷","主泌别清浊"],"a":4,"e":"小肠主泌别清浊，将水谷精微与糟粕分开，清者上输于脾、浊者下传大肠，并吸收部分水液，故泌别清浊是小肠主要生理功能。主运化属脾，主通调水道属肺，主受纳、主腐熟水谷属胃，均非小肠之职"},{"q":"能调节十二经气血的经脉是","o":["阳维脉","阳跷脉","阴跷脉","冲脉","督脉"],"a":3,"e":"冲脉并足少阴上行，渗灌诸阳、濡养诸阴，能调节十二经气血，故称十二经之海、血海。阳维脉维系诸阳经，阳跷脉、阴跷脉主肢体运动与眼睑开合，督脉总督诸阳，调节十二经气血非其所主"},{"q":"提出“五志过极，皆为热甚”的医家是","o":["张元素","刘完素","张从正","朱丹溪","李东垣"],"a":1,"e":"刘完素提出五志过极皆为热甚，认为情志过极化火伤阴，又倡六气皆从火化，治多用寒凉，体现其火热论思想。张元素重脏腑辨证与引经报使，张从正主攻邪，朱丹溪主滋阴，李东垣主补脾，均无此论"},{"q":"人体热量来源，主要是","o":["气","血","精","液","津"],"a":0,"e":"气具有温煦作用，是人体热量的来源，气聚则生阳，阳气充盛则体温恒定、脏腑得温，故人体热量主要来自气。血主濡养，精主生殖与化生，津、液主滋润濡养，皆非热量的主要来源"},{"q":"阴胜则阳病指的是","o":["阳有余耗伤阴精","阴不足阳相对亢胜","阳不足阴相对亢胜","阴有余损伤阳气","阴虚损阳无所依"],"a":3,"e":"阴胜则阳病指阴邪偏盛、阴有余而损伤阳气，如寒邪内盛则阳气受损，故为阴有余损伤阳气。阳有余耗伤阴精是阳盛则阴病，阴不足阳相对亢盛为阴虚阳亢，阳不足阴相对亢盛为阳虚阴盛，阴虚损阳无所依为阴损及阳，均非此义"},{"q":"肝气逆是指","o":["肝气升发太过","肝气应升反降","肝气郁遏不达","肝气横犯脾胃","肺金乘克肝木"],"a":0,"e":"肝气逆即肝气上逆，指肝气升发太过、气机逆上，见头目胀痛、面红目赤、急躁易怒，甚则吐血、昏厥。肝气应升反降属肝气郁陷，肝气郁遏不达为肝气郁结，肝气横犯脾胃为肝气犯胃，肺金乘克肝木为相克失常，皆非肝气上逆"},{"q":"夺汗者无血，其理论依据是","o":["血可化津","津能生血","津能载气","气能摄血","气能行血"],"a":1,"e":"夺汗者无血指大汗之后津液大伤，而津能化生为血，津亏则血少，故不可再耗血，其理论依据是津能生血。血可化津是津血同源的另一面，津能载气言津为气之载体，气能摄血、气能行血皆言气对血的作用，均非此说依据"},{"q":"后天之本指","o":["脾","肝","心","肾","肺"],"a":0,"e":"脾主运化，为气血生化之源，人出生后依赖脾胃化生水谷精微以滋养全身，故称脾为后天之本。肝主疏泄藏血，心主血脉神志，肾藏精为先天之本，肺主气司呼吸，皆非后天之本"},{"q":"能够导致“心无所倚，神无所归，虑无所定”情绪的是","o":["惊","怒","思","喜","悲"],"a":0,"e":"七情致病各有气机变化，惊则气乱，心无所倚、神无所归、虑无所定正是惊恐导致心神不定、气机紊乱的表现。怒则气上，思则气结，喜则气缓，悲则气消，各有所伤，均无此心神无依之状"},{"q":"气滞宜","o":["益气","活血","降逆","行气","补气"],"a":3,"e":"气滞即气机郁滞不通，以胀痛、痛无定处为特征，治宜行气以疏通气机，使气行则血行、津布。益气、补气适用于气虚，活血适用于血瘀，降逆适用于气逆，病机与治法不对应，均非气滞之治"},{"q":"血虚引起气虚病变的理论根据是","o":["血能养气","气能行血","气能摄血","气能生血","血能载气"],"a":0,"e":"血能养气，血为气的物质基础之一，血足则气有所附而充盛，血虚则气无所养而亦虚，故血虚引起气虚的理论根据是血能养气。气能行血、气能摄血言气对血的作用，气能生血言气化生血，血能载气侧重气依附于血而行，养气更切血虚致气虚之理"},{"q":"不属于调摄情绪法的是哪一项","o":["节制法","疏泄法","转移法","清静养神","情志制约法"],"a":3,"e":"调摄情绪的方法主要有节制法、疏泄法、转移法、情志制约法等，清静养神属养生中调养神明的一般原则，重在静心少欲以养神，非针对具体情绪的调摄方法，故不属于。节制、疏泄、转移、情志制约皆为调摄情绪的具体方法"},{"q":"与肺主一身之气关系最密切的是","o":["元气","心气","营气","卫气","宗气"],"a":4,"e":"宗气积于胸中，由肺吸入之清气与脾胃化生之水谷精气结合而成，上走息道司呼吸、贯心脉行气血，肺主一身之气主要体现于宗气的生成与分布，故关系最密切。元气根于肾，心气属心，营气、卫气虽由肺宣发布散但不主一身之气"},{"q":"肝在体合","o":["筋","脉","肉","皮","骨"],"a":0,"e":"肝在体合筋，诸筋皆赖肝血滋养，肝血充足则筋脉得养、关节灵活、爪甲坚牢，故肝在体合筋。脉合心，肉合脾，皮合肺，骨合肾，五体与五脏各有固定归属，筋专属于肝，余者不涉"},{"q":"“用寒远寒，用热远热”，属于","o":["因病制宜","因地制宜","因人制宜","因时制宜","因证制宜"],"a":3,"e":"用寒远寒、用热远热指炎热季节慎用热药、寒冷季节慎用寒药，即用药须避开时令寒热之性，属因时制宜。因病制宜依病证，因地制宜依地域，因人制宜依体质年龄，因证制宜依证候，皆非依时令用药"},{"q":"火热邪气致病，症见头痛、耳鸣、咽喉红肿疼痛、唇口糜烂等症状，是由于","o":["热邪扰乱心神","热邪易致动血","火热之邪燔灼趋上","热邪伤津耗气","热邪易致生风"],"a":2,"e":"火热之性燔灼趋上，火性炎上，故头痛、耳鸣、咽喉红肿疼痛、唇口糜烂等头面五官症状，为火热之邪上炎所致。热扰心神致神昏谵语，热迫血妄行致出血，热伤津耗气致口渴乏力，热极生风致抽搐，病机各异"},{"q":"与呼吸功能关系最密切的两脏是","o":["肺与肾","肺与肝","肺与脾","肝与脾","心与肝"],"a":0,"e":"肺主呼气、肾主纳气，呼吸运动由肺肾共同完成，肺吸入之清气须下纳于肾，肾气充足则呼吸深沉，故与呼吸功能关系最密切的两脏是肺与肾。肺与肝、肺与脾、肝与脾、心与肝虽与气机气血相关，但不直接共司呼吸"},{"q":"阴阳的转化过程是","o":["量变过程","质变过程","两者都是","平衡过程","两者都不是"],"a":1,"e":"阴阳转化是阴阳对立双方在一定条件下向其反面转变，属事物性质的根本改变，为质变过程。阴阳消长是阴阳量的增减，属量变过程；平衡、两者都是或都不是均不合转化的本质，转化以质变区别于消长的量变"},{"q":"心脏精气的盛衰可以通过面部色泽来辨别主要是因为","o":["心在液为汗","心在志为喜","心在体合脉","心其华在面","心主通明"],"a":3,"e":"心其华在面，面部血脉丰富，心之气血上荣于面，故心脏精气盛衰可从面部色泽分辨，心气充足则面色红润有光泽。心在液为汗、在志为喜、在体合脉、主通明虽皆为心的生理联系，但直接体现于面色泽的唯有其华在面"},{"q":"六淫中具有病程长，难以速愈的邪气是","o":["寒邪","火邪","风邪","暑邪","湿邪"],"a":4,"e":"湿性黏滞，一是症状黏腻不爽，二是病程缠绵、反复难愈，故六淫中湿邪致病病程长、难以速愈。寒邪、火邪、风邪致病多较急骤，暑邪发病急、病程短，唯湿邪以黏滞而致久病难愈"},{"q":"以下各项属于五脏之外的是","o":["心","肺","脾","肝","女子胞"],"a":4,"e":"五脏为心、肺、脾、肝、肾，女子胞属奇恒之腑而非五脏，故为五脏之外。心、肺、脾、肝皆在五脏之列，唯女子胞主月经与孕育，形态中空似腑而功能藏精似脏，归属奇恒之腑"},{"q":"属于“七冲门”，下列错误的那项是","o":["吸门","飞门","户门","气门","阑门"],"a":3,"e":"七冲门为飞门（唇）、户门（齿）、吸门（会厌）、贲门（胃上口）、幽门（胃下口）、阑门（大小肠交界）、魄门（肛门），并无气门，故气门错误。吸门、飞门、户门、阑门皆在七冲门之列，须与三焦气口等概念区分"},{"q":"根据五行学说，“木亢侮金”是指","o":["相生","相克","相乘","相侮","制化"],"a":3,"e":"相侮指五行中某一行过于强盛，反克其所不胜，木本受金克，木亢反克金即为木亢侮金，属相侮。相生为资生助长，相克为正常制约，相乘为过度克制，制化为生克平衡，均非反克之义"},{"q":"下列适用于“阴盛格阳证”的治则是","o":["寒因寒用","热因热用","通因通用","热者寒之","寒者热之"],"a":0,"e":"官方答案为【寒因寒用】，但依据教材，正确答案为【热因热用】。阴盛格阳即真寒假热，阴寒内盛格虚阳于外，虽见面红、口渴等假热象，本质属寒，当以热药治其假热，是为热因热用。寒因寒用适用于阳盛格阴的真热假寒，以寒药治假寒，与本证寒热相反；通因通用治真实假虚之泄泻，热者寒之、寒者热之属正治，皆非格阳反治之法"},{"q":"首先提及七情可以致病的典籍是","o":["《伤寒论》","《三因极一病证方论》","《难经》","《内经》","《诸病源候论》"],"a":3,"e":"《内经》最早论及七情致病，如怒伤肝、喜伤心、思伤脾、忧伤肺、恐伤肾，故首先提及七情致病的典籍是《内经》。《伤寒论》主论外感寒邪，《三因极一病证方论》列七情为致病因素之一但非最早，《难经》补《内经》之不足，《诸病源候论》论病源较晚"},{"q":"下列属于正治法则的是","o":["标本兼治","塞因塞用","寒者热之","因人制宜","寒因寒用"],"a":2,"e":"正治即逆治，指采用与病证性质相反的治法，如寒证用热药即寒者热之、热证用寒药即热者寒之、虚则补之、实则泻之，故寒者热之属正治。塞因塞用、寒因寒用属反治，标本兼治是治疗先后，因人制宜是三因制宜，均非正治"},{"q":"“见肝之病，先实其脾气”，这种治疗属","o":["治病求本","既病防变","早期治疗","扶正祛邪","审因论治"],"a":1,"e":"见肝之病、先实其脾气，指在肝病未传脾之前先健脾，使脾旺不受邪，阻断疾病传变，属既病防变。治病求本是寻找根本病因，早期治疗强调早诊早治，扶正祛邪针对邪正关系，审因论治依据病因，皆非针对传变的预防"},{"q":"脏与脏之间主要表现为阴阳水火互济互制关系的是","o":["心与肺","心与肾","肝与肾","脾与肾","肺与脾"],"a":1,"e":"心属火居上，肾属水居下，心火下济肾水、肾水上承心火，水火既济、阴阳互济互制，故心与肾体现阴阳水火关系。心与肺为气血关系，肝与肾为精血同源，脾与肾为先后天互资，肺与脾为气的生成关系，均非水火互济互制"},{"q":"在藏象、脉学和针灸等方面对《黄帝内经》进行了补充的著作是","o":["《脉经》","《针灸甲乙经》","《难经》","《伤寒杂病论》","《神农本草经》"],"a":2,"e":"《难经》在藏象、脉学、针灸等方面对《黄帝内经》多有补充与发挥，如阐发命门、三焦，详论脉诊、经络俞穴，故为补充《内经》之作。《脉经》为王叔和所撰脉学专著，《针灸甲乙经》为皇甫谧针灸专著，《伤寒杂病论》为张仲景辨证论治之书，《神农本草经》为药物学著作"},{"q":"胆属于","o":["脏","腑","奇恒之腑","既是腑，又是奇恒之腑","既是脏，又是奇恒之腑"],"a":3,"e":"胆内藏胆汁，传化水谷而不直接受纳糟粕，功能似脏而形态似腑，故既属六腑又属奇恒之腑。单纯属脏或属腑均不确切，胆既非纯脏亦非纯腑，亦非既是脏又是奇恒之腑，其归属为六腑兼奇恒之腑"},{"q":"据五行学说，佐金平木法的适应证是","o":["肝脾不调证","肝火犯肺证","肝肾阴虚证","肝火上炎证","肝胆湿热证"],"a":1,"e":"佐金平木法是通过清肃肺气以抑制肝气上逆，适用于肝火犯肺之证，见咳嗽、胁痛、急躁易怒等。肝脾不调宜抑木扶土，肝肾阴虚宜滋水涵木，肝火上炎宜清肝泻火，肝胆湿热宜清利肝胆湿热，均非佐金平木之所主"},{"q":"预防的基本原则源于以下哪种理论","o":["治未病","未病先防","既病防变","病后防复","先安未受邪之地"],"a":0,"e":"预防的基本原则源于治未病思想，包括未病先防、既病防变、瘥后防复，故治未病是预防理论的总源。未病先防、既病防变、病后防复是治未病的具体内容，先安未受邪之地是既病防变的具体方法，皆为治未病思想的体现而非源头"},{"q":"七情内伤最容易伤及的脏腑是:","o":["心、肝、脾","心、肺、脾","肝、脾、肾","肺、脾、肾","心、肺、肾"],"a":0,"e":"七情内伤直接影响脏腑气机，心主神志、肝主疏泄调情志、脾主运化且思虑伤脾，故七情致病最易伤及心、肝、脾。肺、肾虽可被情志波及，悲忧伤肺、恐伤肾，但不如心肝脾之常见与直接"},{"q":"“无阴则阳无以化”说明了阴阳之间的何种关系","o":["阴阳交感","阴阳互根","阴阳对立","阴阳消长","阴阳转化"],"a":1,"e":"无阴则阳无以化指阴是阳化生的物质基础，阴精充足则阳气得以化生，体现阴阳互根互用、相互依存为用的关系。阴阳交感指阴阳相交合，对立指相互制约，消长指量的增减，转化指向对立面转变，皆非互根互用之义"},{"q":"同名手足阳经交接的部位是","o":["腹","足","胸","头","手"],"a":3,"e":"十二经脉交接有规律，同名手足阳经即手阳明与足阳明、手太阳与足太阳、手少阳与足少阳，均在头面部交接，故同名手足阳经交接于头。腹、胸多为阴经交接之处，手、足为表里经或异名经交接部位，非同名阳经之所"},{"q":"《素问·金匮真言论》所说“善病洞泄寒中”的季节是","o":["春季","仲夏","长夏","秋季","冬季"],"a":2,"e":"《素问·金匮真言论》指出长夏善病洞泄寒中，长夏主湿、脾土当令，湿困脾阳则运化失常，故易发洞泄寒中。春季善病鼽衄，仲夏善病胸胁，秋季善病风疟，冬季善病痹厥，四时发病各有其候"},{"q":"根据五行学说，脾虚病人面见青色是","o":["水克土","木乘土","土侮木","土生金","土克水"],"a":1,"e":"脾属土，青色属木，木乘土即肝木过旺而过度克制脾土，脾虚而面见青色正是木乘土之象。水克土为相克失常但面色不应青，土侮木方向相反，土生金、土克水为正常生克，均不能解释脾虚面青"},{"q":"既属六腑，又属奇恒之腑的是","o":["三焦","女子胞","胆","胃","脑"],"a":2,"e":"奇恒之腑为脑、髓、骨、脉、胆、女子胞，其中唯胆同时列入六腑，故既属六腑又属奇恒之腑的是胆。三焦为六腑但不属奇恒之腑，女子胞属奇恒之腑但不属六腑，胃为六腑，脑为奇恒之腑，皆不能兼具二者"},{"q":"运行在脉外并散行于全身的气是","o":["元气","宗气","营气","卫气","心气"],"a":3,"e":"卫气行于脉外，不受脉道约束，散行于全身，具有防御外邪、温养全身、调控腠理开合的作用，故运行在脉外并散行全身的是卫气。元气经三焦布散，宗气积于胸中，营气行于脉中，心气属心，其运行部位与卫气不同"},{"q":"阴损及阳的病机主要是指","o":["阴虚而阳相对亢盛","阴虚而导致阳气无以化生","阴寒病证转化为阳热病证","感受寒邪而伤及阳气","感受热邪而伤及阴津"],"a":1,"e":"阴损及阳指阴精亏损到一定程度，累及阳气，使阳气无以化生而亦虚，即阴虚导致阳气无以化生，终致阴阳两虚。阴虚而阳相对亢盛是阴虚火旺，阴寒化阳热是阴阳转化，感受寒邪伤阳、热邪伤阴为外邪致病，均非阴虚及阳的病机"},{"q":"下列各脏中，其生理特性以升为主的是","o":["肺与脾","肺与肝","肝与肾","心与肾","肝与脾"],"a":4,"e":"肝主疏泄，性喜条达而主升发；脾主升清，将水谷精微上输心肺，故肝与脾的生理特性以升为主。肺主宣发肃降、以降为主，肾主封藏，心主血脉向下传导，凡含肺、肾、心的组合皆兼降或藏之性，唯肝脾皆主升"},{"q":"脾主运化是指","o":["运化水湿","运化水液","运化水谷和水液","运化水谷","化生血液"],"a":2,"e":"脾主运化包括运化水谷与运化水液两方面，将水谷化为精微并转输全身，将水液吸收转输、布散排泄，故脾主运化指运化水谷和水液。单言运化水湿、运化水液或运化水谷均不全面，化生血液是脾气运化水谷后的功能，非运化本身"},{"q":"人体元气和水液运行的通道是指","o":["膀胱","肾","三焦","肝","脾"],"a":2,"e":"三焦为元气运行的通道，元气根于肾，经三焦布散全身；三焦又为水液运行的通道，主通调水道、气化水液，故三焦是人体元气和水液运行的通道。膀胱贮尿排尿，肾主水，肝主疏泄调气，脾主运化水液，皆非二者共同的通道"},{"q":"循行于头顶及后头部的经脉是","o":["足少阳胆经","足阳明胃经","足太阳膀胱经","足少阴肾经","足太阴脾经"],"a":2,"e":"足太阳膀胱经起于目内眦，上额交巅，循行于头顶及后头部、项背腰部，故循行头顶及后头部的是足太阳膀胱经。足少阳胆经循头侧部，足阳明胃经循前额及面部，足少阴肾经、足太阴脾经不上头巅，部位各异"},{"q":"下列哪项属于六淫致病特点以外的","o":["季节性","地域性","外感性","相兼性","强烈传染性"],"a":4,"e":"六淫致病有外感性、季节性、地域性、相兼性等特点，一般不具有强烈传染性。强烈传染性是疠气致病的特点，疠气致病发病急、病情重、传染性强，与六淫致病特点判然有别"},{"q":"“无阳则阴无以生”说明了阴阳之间的何种关系","o":["阴阳交感","阴阳互根","阴阳对立","阴阳消长","阴阳转化"],"a":1,"e":"无阳则阴无以生指阳是阴化生的动力与条件，阳气充足则阴精得以化生，体现阴阳互根互用、相互依存为用的关系。阴阳交感、对立、消长、转化各指不同关系，皆非此句所强调的阳生阴长的互根之义"},{"q":"下列选项中，属于瘀血所致疼痛特点，错误的是","o":["刺痛","固定不移","夜间加重","拒按","胀痛"],"a":4,"e":"瘀血致疼痛的特点为刺痛、痛处固定不移、夜间加重、拒按，因瘀血有形、阻滞不通、夜间血行缓慢而痛甚。胀痛是气滞致痛的特点，痛无定处、走窜攻胀，与瘀血刺痛固定不移相反，故胀痛错误"},{"q":"魄门位于","o":["大小肠连接处","胃与小肠连接处","胃上口","会厌","大肠末端"],"a":4,"e":"魄门即肛门，为大肠末端，是排泄糟粕的门户，在七冲门中居最下，故魄门位于大肠末端。大小肠连接处为阑门，胃与小肠连接处为幽门，胃上口为贲门，会厌为吸门，皆非魄门"},{"q":"脏与脏之间主要表现为气血关系的是","o":["心与肺","肺与肝","脾与肾","肝与肾","肺与肾"],"a":0,"e":"心主血脉、肺主气，心与肺的关系主要表现为气与血的关系：气为血之帅，血为气之母，气血相依，故气血关系见于心与肺。肺与肝调气机升降，脾与肾为先后天，肝与肾为精血，肺与肾为金水，均非气血关系之典范"},{"q":"根据五行学说，“亢则害，承乃制”是","o":["相克关系","相生关系","相乘关系","制化关系","相侮关系"],"a":3,"e":"亢则害、承乃制指五行中某一行过亢则为害，须有另一行承而制之，以维持生克制化的动态平衡，属制化关系。相克为正常制约，相乘为过度克制，相生为资生，相侮为反克，皆不能概括这种亢而制之的协调关系"},{"q":"易导致烦躁不安，失眠多梦，甚至神昏谵语的邪气是","o":["风邪","寒邪","湿邪","暑邪","燥邪"],"a":3,"e":"暑性升散，易扰心神，暑邪内侵则心神不宁，见烦躁不安、失眠多梦，甚则神昏谵语，故为暑邪。风邪善动，寒邪收引，湿邪重浊黏滞，燥邪干涩，虽各有致病特点，但致神昏谵语以暑邪扰心最为突出"},{"q":"五脏的生理特点是","o":["贮藏精气","传化水谷","排泄糟粕","受盛水谷","主持诸气"],"a":0,"e":"五脏主贮藏精气，藏而不泻，满而不实，故五脏的生理特点是贮藏精气。传化水谷、排泄糟粕是六腑泻而不藏、实而不满的特点，受盛水谷属小肠，主持诸气属三焦或肺，皆非五脏所主"},{"q":"人的生长发育取决于","o":["心气盈亏","脾胃健运","肾精盛衰","肝气调达","肺气宣降"],"a":2,"e":"肾藏精，肾精化生元气，主生长、发育与生殖，人的生长发育过程取决于肾精的盛衰，故为肾精盛衰。心气盈亏主血脉运行，脾胃健运为后天之本，肝气调达主疏泄，肺气宣降主呼吸，皆非决定生长发育的根本"},{"q":"“热极生寒”说明了阴阳之间的何种关系","o":["阴阳交感","阴阳互根","阴阳对立","阴阳消长","阴阳转化"],"a":4,"e":"热极生寒指热盛到极点可转化为寒，是阴阳在一定条件下向其对立面转化的例证，体现阴阳转化关系。阴阳交感指交合，互根指相互依存，对立指相互制约，消长指量的增减，皆非极则反的质变转化"},{"q":"与内脏位置恒定密切相关的脏是","o":["肝","肾","肺","脾","三焦"],"a":3,"e":"脾主升清，脾气上升能升举内脏、维持其位置恒定，脾气虚则中气下陷，可见内脏下垂，故与内脏位置恒定密切相关的是脾。肝主疏泄调气，肾主封藏，肺主宣降，三焦主气化，皆无升举固托内脏之职"},{"q":"“重阴必阳，重阳必阴”是指","o":["阴阳的对立制约","阴阳的互根互用","阴阳的消长平衡","阴阳的相互转化","阴阳的平衡关系失调"],"a":3,"e":"重阴必阳、重阳必阴指阴或阳盛极必向其反面转化，是阴阳相互转化的经典表述。对立制约指阴阳相互抑制，互根互用指相互依存为用，消长平衡指量的增减变化，平衡失调为病理，均非物极必反的转化之义"},{"q":"下列各项中不宜区分阴阳属性的是","o":["寒与热","邪与正","上与下","左与右","动与静"],"a":1,"e":"阴阳属性用于说明相互对立又关联的两种情况或方面，寒热、上下、左右、动静皆为典型对立统一，可分阴阳。邪与正是致病与抗病两种力量，属病机范畴，不按阴阳属性划分，故不宜区分阴阳属性的是邪与正"},{"q":"“阳病治阴”适用于下列何证","o":["实热证","实寒证","阴阳两虚","虚寒证","虚热证"],"a":4,"e":"阳病治阴即阴虚所致的虚热证，当滋阴以制阳，即王冰所谓壮水之主以制阳光，故适用于虚热证。实热证宜清热，实寒证宜散寒，虚寒证宜温阳，阴阳两虚宜阴阳双补，皆非阳病治阴之所主"},{"q":"阴阳平和质的体质特征为","o":["身体强壮，胖瘦适度；性格开朗随和，精力充沛，反应灵活","形体适中或偏瘦，但较结实；面色多略偏红或微苍黑，或呈油性皮肤","食量较大，消化吸收功能健旺；大便易干燥，小便易黄赤","形体适中或偏胖，但较弱，容易疲劳，面色偏白而欠华","食量较小，消化吸收功能一般；平时畏寒喜热，或体温偏低；精力偏弱，动作迟缓"],"a":0,"e":"阴阳平和质者气血调和、脏腑功能协调，表现为身体强壮、胖瘦适度、性格开朗随和、精力充沛、反应灵活。形体偏瘦而结实、面偏红或苍黑、油性皮肤是湿热质，食量大、便干溲黄是阳盛质，偏胖易疲、面白欠华是气虚质，食少畏寒、动作迟缓是阳虚质"},{"q":"以下不属于狭义之神的是","o":["思维","意识","情感","生命活动","情绪"],"a":3,"e":"狭义之神专指人的精神、意识、思维、情感、情绪等心理活动，而生命活动是广义之神的概念，泛指人体生命现象的总称，故生命活动不属于狭义之神。思维、意识、情感、情绪皆属狭义之神的范畴"},{"q":"《素问·上古天真论》认为男性开始走向衰老的年龄段是","o":["五七","五八","四八","七七","八八"],"a":1,"e":"《素问·上古天真论》述男子五八，肾气衰，发堕齿槁，即四十岁左右肾气始衰，标志男性开始走向衰老，故为五八。五七、四八为壮盛之时，七七、八八为天癸竭、形体衰老之极，非开始衰老之龄"},{"q":"属于病后防复的内容，下列错误的是","o":["防止复感新邪","防止传变","防止劳复","防止药复","防止食复"],"a":1,"e":"病后防复指病愈后防止复发，内容包括防止复感新邪、防止劳复、防止药复、防止食复等。防止传变属既病防变的范畴，是疾病已发后防其传变，而非病愈后防复，故不属于病后防复"},{"q":"下列属于阴的属性是","o":["向上的","温暖的","无形的","下降的","明亮的"],"a":3,"e":"阴阳属性以动静、升降、寒热、明暗分，阳主动、主升、主温煦，阴主静、主降、主寒凉，故下降的属阴。向上、温暖、明亮皆属阳；无形属阳，有形重浊方属阴，题干问属阴者唯下降的"},{"q":"患者胃肠热盛，大便秘结，腹满硬痛而拒按，潮热，神昏谵语，但又兼见面色苍白，四肢厥冷，精神委顿。其病机是","o":["虚中夹实","真实假虚","由实转虚","真虚假实","实中夹虚"],"a":1,"e":"胃肠热盛、大便秘结、腹满硬痛拒按、潮热谵语为里有实热，面色苍白、四肢厥冷、精神委顿为热深厥深的假寒象，本质属实热、外现虚寒，故为真实假虚。虚中夹实以虚为主夹实，由实转虚是实证转虚证，真虚假实是至虚有盛候，实中夹虚以实为主夹虚，均非此格阴之象"},{"q":"骨和髓之病变，论治的脏一般是","o":["心","肺","脾","肝","肾"],"a":4,"e":"肾主骨生髓，骨与髓的病变多从肾论治，肾精充足则骨坚髓满，肾虚则骨弱髓空，故论治之脏为肾。心主血脉，肺主气，脾主肌肉四肢，肝主筋，虽与骨髓有间接关系，但主骨生髓之职专属肾"},{"q":"精的本始含义是指","o":["脏腑之精","津液","生殖之精","水谷之精","血液"],"a":2,"e":"精的本始含义指生殖之精，即构成胚胎、繁衍生命的原始物质，是最初、最根本之义。脏腑之精、水谷之精为后天之精，津液、血液为其他基本物质，皆非精的本始含义，生殖之精才是精概念的本源"},{"q":"六淫中最易导致疼痛的外邪是","o":["风邪","寒邪","湿邪","暑邪","热邪"],"a":1,"e":"寒性凝滞、主痛，寒邪侵袭则气血运行阻滞、不通则痛，故六淫中最易导致疼痛的外邪是寒邪。风邪善行而数变、多致游走之痛，湿邪重着、酸痛困重，暑邪耗气、热邪灼痛，致痛之普遍与剧烈以寒邪为最"},{"q":"共同调节情志活动的是","o":["心和肝","心和肺","脾和胃","肺和脾","脾和肾"],"a":0,"e":"心主神明，为精神活动之主，肝主疏泄而调畅气机情志，二者协同完成情志活动之调节。肺项实为司呼吸、通调水道，脾与胃项实司运化受纳水谷，皆不直接统摄情志；肾虽在志为恐、主藏精，然不与心共司情志之总调"},{"q":"健康人体的阴阳关系可以概括为","o":["阴阳互根互用","阴阳相互制约","阴平阳秘","阴阳消长","阴阳转化"],"a":2,"e":"阴平阳秘概括阴阳双方在对立制约、互根互用中达到动态平衡，是健康生理状态的高度概括。阴阳互根互用项实指阴阳相互依存、互为根本，仅述关系之一端；相互制约、消长、转化各项各言阴阳运动的一个方面，只强调对立或变化，均未点明平衡协调这一健康本质"},{"q":"可以概括津和血之间可以相互转化、相互滋生的关系的是","o":["津可化血","血可化津","津血同源","津可养血","血可养津"],"a":2,"e":"津与血同源于水谷精微，可相互渗透转化，津入脉化血，血中津液渗出脉外为津，故称津血同源，又称血汗同源。津可化血、血可化津、津可养血诸项仅述单向转化的一个侧面，未概括互生互化的整体关系；夺血者无汗、夺汗者无血正是此理的临床体现"},{"q":"下列哪项属于五行之“水”的归类","o":["肝","思","膀胱","长","辛"],"a":2,"e":"五行水的归类包括肾、膀胱、耳、骨、冬、寒、咸、黑等，膀胱为水腑，主贮尿排尿，故属水。肝项实属木，主疏泄藏血；思项实为脾之志而属土；长夏之长属土，辛味属金，各归其类，皆非水行所属"},{"q":"根据“脉应四时”的理论，夏季的主脉是","o":["弦","洪","毛","石","代"],"a":1,"e":"脉应四时，春弦、夏洪、秋毛、冬石，夏季阳气隆盛，脉来盛去衰、如钩而洪大，故主洪脉。弦项实为春季之脉，端直以长；毛项实为秋季轻浮之脉；石项实为冬季沉石之脉；代脉为节律不齐之脉，不属四时平脉"},{"q":"喜乐过度首先伤及","o":["肺气","肝血","肾精","脾气","心神"],"a":4,"e":"心在志为喜，喜本为良性刺激，然过度则使心气涣散、神不守舍，故首先伤及心神，甚则发狂。肺气项对应悲忧，悲则气消；肝血项对应怒，怒则气上；肾精项对应恐，恐则气下；脾气项对应思，思则气结，皆非喜之所伤"},{"q":"别络分出的最小络脉是","o":["浮络","孙络","太阴别络","厥阴别络","少阳别络"],"a":1,"e":"络脉由经脉分出，别络较大，别络再分出浮络，浮络中最细、循于肌肤表层者为孙络，是络脉系统中最细小者。浮络项实为浮行浅表的络脉，较孙络为粗；太阴别络、厥阴别络、少阳别络皆为特定别络之名，属较大分支，非最小者"},{"q":"某些药物不仅自身对某脏某腑某经有天然的亲近性，还能够引导其他药物的药力到达该病处，起“向导”的作用，此即","o":["引经报使","药物归经","臣药","佐药","使药"],"a":0,"e":"某些药物既归某经，又引导他药药力直达病所，起向导作用，此即引经报使，为使药引经功能的专门表述。药物归经项实指药物对某脏腑经络的选择性作用，仅为归属而不含引导他药之义；臣药项实为助君药增效；佐药项实为佐助、佐制或反佐，皆不专指引经向导"},{"q":"具有调节生殖功能的两脏是","o":["心与肾","肺与肾","脾与肾","肝与肾","肝与脾"],"a":3,"e":"肝藏血，肾藏精，精血同源互生；肾主生殖，天癸至而生殖机能成熟，肝疏泄调畅气机并藏血，二者共调生殖，故有肝肾同源之说。心与肾项实为水火既济、主神明与藏精；肺与肾项实司呼吸与纳气；脾与肾项实为后天与先天、运化与藏精；肝与脾项实主藏血统血与疏肝运化，皆非主生殖之配对"},{"q":"根据五行学说，“水气凌心”属于","o":["母病及子","相乘","子病犯母","相侮","制化"],"a":1,"e":"相乘指五行中一行过强，过度克制所胜之行，属异常克制。肾水过盛，上乘心火，致心阳被抑，即水气凌心，为水乘火。相侮项实为反向克制、以下犯上，如木火刑金；母病及子、子病犯母项实为相生关系失常的传变；制化项实为正常状态下相生相克的协调，皆非此过度克制"},{"q":"中医学的预防思想称之为","o":["治未病","未病先防","既病防变","病后防复","先安未受邪之地"],"a":0,"e":"中医学以治未病作为预防思想的总称，首见于素问上工治未病，涵盖未病先防、既病防变等。未病先防、既病防变、病后防复各项实为治未病的具体环节或内容，先安未受邪之地实为既病防变的具体措施，均是局部而非预防思想的总概括"},{"q":"过食咸味可致","o":["心盛乘肺","肝盛乘脾","脾盛乘肾","肺盛乘肝","肾盛乘心"],"a":4,"e":"咸入肾，过食咸味则肾气水偏盛，水盛乘火，上凌于心，故心气被抑，素问有味过于咸心气抑之论。肝盛乘脾项实由过食酸味所致，酸入肝而木乘土；脾盛乘肾项实因过食甘味，甘入脾而土乘水；肺盛乘肝项实因过食辛味，辛入肺而金乘木，五味各归其脏而相乘"},{"q":"机体精神活动的物质基础是","o":["精","气","血","津","液"],"a":2,"e":"血富有营养，是神志活动的物质基础，灵枢称血气者人之神，血旺则神清、思维敏捷。精项实为生命本原、藏于肾，主生长发育生殖；气项实为推动温煦防御等功能的动力；津、液项实司濡润滋养，布散于肌表孔窍骨节，皆非精神活动之直接物质基础"},{"q":"后天因素中，对禀赋影响最大的因素是","o":["情志变化","外伤疾病","生活起居","饮食劳逸","药邪医过"],"a":3,"e":"禀赋虽受先天肾精制约，后天调养中仍以饮食劳逸影响最大，饮食为气血生化之源，劳逸失度则耗气伤形，素问强调饮食有节、不妄作劳。情志变化项实为七情内伤之因；外伤疾病项实为外感或跌仆损伤；生活起居项实涉作息寒温，虽相关而不如饮食劳逸对禀赋塑造直接；药邪医过项实为医源性因素"},{"q":"将肺称为“娇脏”的主要依据是","o":["肺主一身之气","肺外合皮毛","肺通天气，不耐寒热","肺为水之上源","肺朝百脉"],"a":2,"e":"肺主呼吸，外合皮毛，开窍于鼻，与外界大气直接相通，寒热燥湿之邪易从口鼻皮毛侵袭，故称娇脏而不耐寒热。肺主一身之气项实指其参与宗气生成、调节全身气机；外合皮毛项实仅言其表；为水之上源、朝百脉项实指通调水道与百脉会聚，皆非娇嫩易伤之依据"},{"q":"有加强表里两条经脉在体表联系作用者为","o":["浮络","络脉","十五别络","孙络","十二经别"],"a":2,"e":"十五别络为十二经脉各一别络，加任督二脉别络及脾之大络，其主要功能即加强表里两经在体表的联系并灌渗气血。浮络、孙络项实为络脉中浅表、细小者，主布散气血于肌肤，不专司表里联络；十二经别项实为别行的正经，功能为加强表里经在体内深部的联系，与别络之体表联系相对"},{"q":"五脏分阴阳，其中属于阴中之阴的是","o":["肝","心","脾","肺","肾"],"a":4,"e":"五脏分阴阳，心肺居上属阳，心为阳中之阳、肺为阳中之阴；肝脾肾居下属阴，肾居下焦，主藏精主水，属阴中之阴。肝项实为阴中之阳，主疏泄升发；脾项实为阴中之至阴，主运化；心、肺二项已属阳，故非阴中之阴"},{"q":"阳偏盛的治疗原则是","o":["滋阴壮水","寒者热之","补其不足","扶阳益火","热者寒之"],"a":4,"e":"阳偏盛则生内热，表现为实热证，治宜热者寒之，以寒凉药清泻阳热，即泻其有余。滋阴壮水项实为阴虚火旺虚热之治，即阳病治阴；扶阳益火项实为阳虚虚寒之治，即阴病治阳；寒者热之项实为实寒证治则；补其不足项实为虚证补法，均非阳盛实热所宜"},{"q":"脾阳虚衰，运化无权，水湿内停，肢体浮肿，下列哪一种病机描述更准确","o":["虚中夹实","实中夹虚","虚证","真虚假实","真实假虚"],"a":0,"e":"脾阳虚衰、运化无权为本虚，水湿内停、肢体浮肿为标实，虚实并见而以虚为主，故属虚中夹实。实中夹虚项实以实邪为主、兼见正虚，与本证以脾阳虚为本不符；纯虚证项不足以概括水湿停聚之实邪；真虚假实、真实假虚项实为病机真假疑似的特殊表现，非虚实错杂"},{"q":"以形神合一为理论基础的养生原则是","o":["顺应自然","形神兼养","保精护肾","调养脾胃","既病防变"],"a":1,"e":"形神合一认为形体与精神相互依存、不可分离，故养生须形神兼养，既调养形体又摄养精神。顺应自然项实为天人相应、顺四时寒温的养生原则；保精护肾项实重在固护先天之精；调养脾胃项实重在培补后天之本；既病防变项实为已病之后防其传变的措施，皆非以形神合一为理论根基"},{"q":"“既病防变”不仅是指对疾病进行早期治疗，还包括对疾病","o":["早期用药","早期预防","早期诊断","早期宣教","早期隔离"],"a":2,"e":"既病防变指疾病既发之后防其传变恶化，一在早期治疗，二在早期诊断，及时辨识病位病势方能阻断传变。早期用药项实包含在早期治疗之中，非并列要点；早期预防项实属未病先防，针对未病之人；早期宣教、早期隔离项实为健康教育或防疫举措，非既病防变的核心内涵"},{"q":"手太阴肺经起始点是","o":["胸中","肺","胃口","腋窝","中焦"],"a":4,"e":"手太阴肺经起于中焦，下络大肠，还循胃口，上膈属肺，从肺系横出腋下，循臂内下行至少商。胸中项实为手厥阴心包经等循行或宗气积聚之处；肺项实为该经所属之脏而非起点；胃口项实为经脉循行所过；腋窝项实为经脉横出腋下的路径节点，皆非起始部"},{"q":"《黄帝内经》所说“大怒则形气绝，而血菀于上，使人薄厥”的病机，是指","o":["气不摄血","气机逆乱","血随气脱","血随气逆","血随气结"],"a":3,"e":"大怒伤肝，肝气暴张上逆，血随气机上涌，郁积于上，蒙蔽清窍，发为薄厥，故素问有血菀于上使人薄厥之论。气不摄血项实为气虚不能统血而致出血；血随气脱项实为气脱随之血脱，如大出血；气机逆乱项泛指气机失常，未点明血随上逆之关键；血随气结项实指气血瘀结，非上涌薄厥"},{"q":"治疗大出血时，用益气固脱之法，其理论依据是","o":["气能生血","气能行血","气能摄血","血能载气","血能生气"],"a":2,"e":"官方答案为【气能摄血】，但依据教材，正确答案为【血能载气】。大出血时气随血暴脱，气无所附而亡，故须益气固脱，其依据正是血为气之母、血能载气。气能摄血项实指气固摄血液不外溢，对应补气摄血以止血，针对出血而非固脱；气能生血、气能行血项实述气对血的化生与推动，与固脱无涉"},{"q":"适用于“土壅木郁”证的治则是","o":["抑强为主","扶弱为主","补母为主","泻子为主","母子同补"],"a":0,"e":"土壅木郁指脾土壅滞太过，过度克制肝木，致肝失疏泄而郁，属五行相乘中土乘木，治则当抑强扶弱，以抑土之强为主。扶弱为主项实适用于被克一方虚弱为主的证候，本证关键在土壅之强；补母、泻子项实依虚则补其母、实则泻其子而设；母子同补项实为母子俱虚之法，皆不合土壅木郁"},{"q":"肝藏血的生理功能是指肝","o":["贮藏血液","调节血量","统摄血液","贮藏血液、调节血量和防止出血","化生血液与统摄血液"],"a":3,"e":"肝藏血包括三方面，贮藏血液以濡养肝体、制约肝阳，根据机体活动调节血量分布如人卧则血归于肝，固摄血液防止出血。仅答贮藏血液或调节血量项实各执一端，未得完整；统摄血液项实为脾气统血之功；化生血液项实与脾胃、营气、精相关，非肝所主"},{"q":"与人体防御外邪能力关系最直接的脏是","o":["肝","心","脾","肺","肾"],"a":3,"e":"肺主气司呼吸，外合皮毛，宣发卫气于肌表以温分肉、充皮肤、肥腠理、司开合，构成防御外邪的第一道屏障，关系最为直接。肝项实主疏泄藏血；心项实主血脉神明；脾项实主运化、为气血生化之源而扶正；肾项实藏精为正气之根，虽与正邪相关，但卫外抗邪之直接屏障在肺"},{"q":"下列何项属于胃的生理特性","o":["喜燥","喜满","喜润","喜运","喜升"],"a":2,"e":"胃为阳土，主受纳腐熟水谷，赖阴液濡润以降浊，故喜润恶燥；脾为阴土，主运化升清，故喜燥恶湿，二者燥湿相济。喜燥项实为脾之特性而非胃；喜升项实指脾气主升，胃气则主降；喜满、喜运项实非胃之规范特性，胃以通降为顺、以空为贵"},{"q":"七情刺激，易导致心气涣散的是","o":["喜","怒","悲","恐","惊"],"a":0,"e":"心在志为喜，喜则气缓，适度可使气血和畅，过喜则心气涣散、神不收敛，甚则喜伤心。怒项实伤肝、使气上逆；悲忧项实伤肺、使气消耗；恐项实伤肾、使气下陷；惊项实使气乱、心悸不安，与喜致心气涣散有别"},{"q":"元气运行的道路是","o":["心脉","胸腔","全身","脉外","三焦"],"a":4,"e":"元气根于肾，经三焦布散运行于全身脏腑经络，三焦为元气运行之通道，难经称其主持诸气。心脉项实为血液运行之管道；胸腔项实为部位而非通道；全身项实为元气布散所至之处，非运行道路；脉外项实为卫气等循行之所，皆非元气运行的专门道路"},{"q":"形成虚实错杂的病机是","o":["邪盛正衰","邪盛正未衰","正虚邪不盛","邪去正衰","正胜邪退"],"a":0,"e":"虚实错杂指虚证与实证同时并见，邪盛为实、正衰为虚，二者并存即邪盛正衰，如大病久病正虚而邪恋。邪盛正未衰项实为单纯实证；正虚邪不盛项实为单纯虚证；邪去正衰项实为邪已去而正未复，纯属虚；正胜邪退项实为疾病向愈之转归，皆非虚实错杂"},{"q":"运用姜汤治疗风寒感冒，说明了阴阳间的何种关系","o":["阴阳互根","阴阳对立制约","阴阳交感互藏","阴阳自和","阴阳转化"],"a":1,"e":"风寒为阴邪，生姜辛温属阳，以温热之阳药祛散寒邪，体现阴阳相互对立、相互制约，即寒者热之。阴阳互根项实指阴阳互为根本、互生互用；交感互藏项实指阴阳交合、互含对方；阴阳自和项实指阴阳自动趋向协调；转化项实指阴阳在一定条件下相互转变，均与以热制寒之制约关系有别"},{"q":"在头面部，分布于侧头部的经脉是","o":["太阴经","阳明经","厥阴经","太阳经","少阳经"],"a":4,"e":"头为诸阳之会，头面经脉分布有律，阳明经行前额、太阳经行后头及项、少阳经行头之两侧，故侧头部为少阳经三焦经与胆经所布。太阴、厥阴项实多循身之内侧、不达头面；阳明项实布于前额面颊；太阳项实布于后头项背，皆非侧头部之经"},{"q":"下列不属于气的固摄作用的是","o":["控制血液运行于脉中","防止汗出过多","固摄精液","固摄内脏的位置","控制尿液的排泄"],"a":3,"e":"气的固摄作用指固摄血液、津液、精液等液态物质，使血行脉中、汗尿有度、精液不泄，控制血行、防止汗多、固摄精液、控制排尿皆属之。固摄内脏的位置项实为脾气主升、升举内脏以防下垂，属气机升降范畴，非固摄液态物质之义，故不属于固摄作用"},{"q":"哪一项体现肺的肃降功能","o":["宣发卫气至皮毛腠理","治理调节呼吸运动","辅助心行血于周身","呼出体内浊气","吸入自然界清气"],"a":4,"e":"肺主宣发肃降，肃降为肺气向下向内运动，包括吸入自然界清气、将津液与水谷精微向下输布、清肃呼吸道异物。宣发卫气至皮毛、呼出体内浊气项实属肺的宣发功能，方向向上向外；治理调节呼吸项实为肺主气司呼吸的整体概括；辅助心行血项实为肺朝百脉主治节之效，皆非肃降之具体体现"},{"q":"下列选项中，属于《金匮要略》记载的四饮，错误的是","o":["留饮","痰饮","悬饮","溢饮","支饮"],"a":0,"e":"金匮要略将痰饮病分为痰饮、悬饮、溢饮、支饮四类，分别指饮停胃肠、饮停胸胁、饮溢四肢、饮停胸膈。留饮项实为饮邪日久留而不去、病程较长的统称，并非四饮分类之一；痰饮、悬饮、溢饮、支饮四项皆为四饮正名，故留饮为错误项"},{"q":"肾在体合","o":["筋","脉","肉","皮","骨"],"a":4,"e":"肾主骨生髓，骨之生长发育与密度赖肾精滋养，齿为骨之余，故肾在体合骨。筋项实为肝所合，肝主筋；脉项实为心所合，心主血脉；肉项实为脾所合，脾主肌肉；皮项实为肺所合，肺主皮毛，五脏各有所合"},{"q":"“利小便所以实大便”治法的依据是","o":["小肠泌别清浊","脾运化水液","肺宣发肃降","肾阳气化","肾主水液"],"a":0,"e":"小肠泌别清浊，将水谷精微与水液上输于脾，糟粕下传大肠，水液渗注膀胱而成尿。利小便所以实大便即通过分利水道使水液走膀胱、大便得以成形，依据在小肠泌别清浊。脾运化水液项实为水液代谢之中枢；肺通调水道项实为水液输布；肾主水与肾阳气化项实司水液气化排泄，皆非大便成形之直接依据"},{"q":"七情内伤致病最易损伤哪几脏","o":["心肺脾","心肺肝","肺脾肾","心肝脾","肝脾肾"],"a":3,"e":"七情内伤最易损伤心肝脾，心主神明，诸情志皆关于心；肝主疏泄调情志，怒忧易伤；脾主思虑，思虑过度伤脾。肺项实主悲忧、肾项实主惊恐，虽亦受七情波及，然七情致病以心肝脾受累最常见而突出，其余脏腑组合不如心肝脾之典型"},{"q":"“治未病”包括","o":["防止疾病的发生和发展","外避病邪和既病防变","未病先防和早期诊治","未病先防和既病防变","调养正气和控制病传"],"a":3,"e":"治未病包括两大方面，未病先防即在疾病未生之前调养正气、避邪防病，既病防变即既病之后早期诊治、防止传变。防止疾病发生和发展项实为对治未病作用的笼统描述，非其组成；外避病邪项实仅为未病先防之一环；未病先防与早期诊治项实遗漏既病防变的整体；调养正气项实侧重扶正，皆非规范概括"},{"q":"以下除哪项外均属于奇恒之腑","o":["三焦","脑","女子胞","骨","脉"],"a":0,"e":"奇恒之腑包括脑、髓、骨、脉、胆、女子胞共六者，形态中空类腑而功能贮藏精气类脏。三焦项实为六腑之一，主通行元气与运行水液，不属奇恒之腑；脑、女子胞、骨、脉四项皆为奇恒之腑成员，故三焦为例外"},{"q":"具有“阳脉之海”之称的是","o":["督脉","冲脉","任脉","带脉","跷脉"],"a":0,"e":"督脉行于背部正中，总督一身之阳经，与手足三阳经及阳维脉交会，故称阳脉之海。冲脉项实为十二经脉之海又称血海；任脉项实为阴脉之海；带脉项实环腰一周、约束纵行诸脉；跷脉项实司眼睑开合与下肢运动，皆非阳脉之海"},{"q":"肝在志为","o":["喜","思","怒","恐","悲"],"a":2,"e":"肝在志为怒，怒为肝之志，肝气郁滞或肝阳上亢易致烦躁易怒，过怒又伤肝，致肝气上逆、血随气涌。喜项实为心之志；思项实为脾之志；恐项实为肾之志；悲项实为肺之志，五脏在志各有归属，怒专属肝"},{"q":"“阴病治阳”适用于下列何证","o":["实热证","实寒证","阴阳两虚","虚寒证","虚热证"],"a":3,"e":"阴病治阳即益火之源以消阴翳，指阳虚阴盛之虚寒证，当补阳以制阴，如温阳治命门火衰。实热证项实宜热者寒之；实寒证项实宜寒者热之；虚热证项实宜阳病治阴、滋阴壮水；阴阳两虚项实当阴阳双补，皆非阴病治阳所主"},{"q":"心在志为","o":["怒","思","悲","喜","恐"],"a":3,"e":"心在志为喜，喜为心之志，适度则气血和调、心情舒畅，过喜则伤心、心气涣散。怒项实为肝之志；思项实为脾之志；悲项实为肺之志；恐项实为肾之志，诸志各归其脏，喜独属于心"},{"q":"肺为“水之上源”的主要依据是","o":["肺位最高，通调水道","肺具有布散津液的功能","肺具有输精于皮毛的功能","肺为脏腑之华盖","饮入于胃，上归于肺"],"a":0,"e":"肺位胸中为脏腑之华盖，主宣发肃降、通调水道，将水液输布全身并下输膀胱，故称水之上源，与脾肾主水相应。布散津液、输精于皮毛项实为肺宣发功能的具体表现，仅通调水道之一环；为脏腑之华盖项实言其位置而未及功能；饮入于胃上归于肺项实述水液上输之路，皆未直指通调水道这一核心依据"},{"q":"某退休干部因注重养生，而气色红润。下列属于“调神养生”错误的是","o":["清静养神","立志养德","开朗乐观","心细如发","心态平衡"],"a":3,"e":"调神养生重在养护心神，主张清静养神、立志养德、开朗乐观、心态平衡，使神气清净安定。清静养神、立志养德、开朗乐观、心态平衡四项皆属调神养生之法；心细如发形容处事精细、思虑过甚，反易耗神伤脾，与调神养生所倡的豁达清静相悖，故为错误项"},{"q":"六淫中，感受湿邪后，有的患者双膝关节沉重，伴下肢麻木不仁，阴雨天加剧，可称为","o":["痛风","寒痹","痛痹","着痹","行痹"],"a":3,"e":"湿性重浊黏滞，阻痹经络、留着关节，故见关节沉重酸痛、麻木不仁、遇阴雨天加剧，痛处固定不移，称着痹即湿痹。行痹项实以风邪为主，痛无定处、游走不定；痛痹寒痹项实以寒邪为主，痛势剧烈、遇寒加重、得温稍减；痛风项实为现代医学嘌呤代谢病，非六淫痹证分类，皆与此不符"},{"q":"以下哪项属于五脏之一","o":["胆","胃","心","三焦","脑"],"a":2,"e":"五脏为心、肝、脾、肺、肾，共同特点是化生和贮藏精气，藏而不泻。胆、胃、三焦项实属六腑，主受纳传化水谷，泻而不藏；脑项实属奇恒之腑，故唯心为五脏之一"},{"q":"根据阴阳虚实对体质进行分类的医家是","o":["岐伯","张仲景","张景岳","章虚谷","叶天士"],"a":3,"e":"清代章虚谷于医门棒喝中依阴阳虚实之偏，将体质分为偏阳质、偏阴质与阴阳平和质，开体质分类之先河。岐伯项实为内经中托名之医家；张仲景项实著伤寒杂病论、重辨证论治；张景岳项实为明代温补派代表；叶天士项实为清代温病学家、创卫气营血辨证，皆非以阴阳虚实分类体质者"},{"q":"对疾病力求早期诊断、早期治疗的目的","o":["提高正气抗邪能力","尽早确立治疗方法","提高诊断的正确率","中止其病情的发展变化","延缓疾病的恶化"],"a":3,"e":"疾病早期邪气初犯、正气未大虚，及时诊治可截断扭转病势，目的在于中止病情的发展变化，使疾病向愈。提高正气抗邪能力项实为未病先防、养生保健的目标；尽早确立治疗方法项实为诊断的直接环节而非终极目的；提高诊断正确率项实属诊断学要求；延缓恶化项实消极，早期诊治重在积极截断而非延缓"},{"q":"猝受惊恐之人，面色煞白，是由于","o":["气结","气消","气缓","气下","气上"],"a":3,"e":"恐则气下，骤受惊恐使肾气不固、气机下陷，气血不能上荣于面，故面色煞白，甚则二便失禁。气结项实为思虑过度、脾气郁结；气消项实为悲忧过度、肺气耗散；气缓项实为喜乐过度、心气涣散；气上项实为怒则气逆、血随气上，与恐惧致气下面色无华相反"},{"q":"五志与五脏对应关系，肺在志为","o":["喜","怒","思","悲","恐"],"a":3,"e":"肺在志为悲忧，悲忧过度耗伤肺气，致气短乏力、意志消沉，悲则气消。喜项实为心之志；怒项实为肝之志；思项实为脾之志；恐项实为肾之志，五志各有所属，悲忧独归于肺"},{"q":"与津液输布关系最密切的脏腑组是","o":["脾、肾、小肠、三焦","脾、肝、肾、三焦","肺、肾、三焦、小肠","肝、肺、脾、肾、三焦","心、肾、小肠、膀胱"],"a":3,"e":"津液输布赖多脏协同，脾运化水谷精微上输于肺，肺宣发肃降通调水道，肝疏泄调畅气机以行水，肾气化蒸腾推动水液，三焦为水液运行之通道，故关系最密切者为肝肺脾肾三焦。心项实主血脉、与输布关系较远；小肠项实主泌别清浊，参与水液分化但非输布主导；膀胱项实主贮尿排尿，属排泄环节"},{"q":"关于心肾相交，以下哪种说法是正确的","o":["水火相克","心肾间病理关系","肾阳上济于心， 心阴下降于肾","肾水上济于心， 心火下降于肾","心气不降及肾， 肾阴不上承于心"],"a":3,"e":"心肾相交即水火既济，心火下降温煦肾水使肾水不寒，肾水上济滋养心火使心火不亢，阴阳协调。水火相克项实仅言五行制约而未及既济升降；心肾间病理关系项实指心肾不交，非生理之交；肾阳上济、心阴下降项实把水火阴阳颠倒；心气不降、肾阴不上承项实为心肾不交之病机，皆非相交之健康状态"},{"q":"根据五行学说，下列情志相胜中错误的是","o":["喜胜恐","恐胜喜","怒胜思","喜胜悲","思胜恐"],"a":0,"e":"情志相胜依五行相克，怒木胜思土、思土胜恐水、恐水胜喜火、喜火胜悲金、悲金胜怒木。喜胜恐违背此规律，恐属水、喜属火，水克火当以恐胜喜，胜恐者应为思土克水，故喜胜恐错误；恐胜喜、怒胜思、喜胜悲、思胜恐四项皆合相克之序"},{"q":"下列除哪项外均属于顺应自然养生","o":["晨练","春夏养阳，秋冬养阴","顺应四时调摄","昼夜晨昏调养","起居有常"],"a":0,"e":"顺应自然养生强调天人相应，含春夏养阳、秋冬养阴，顺应四时调摄、昼夜晨昏调养及起居有常等，随自然规律作息。春夏养阳、顺应四时、昼夜晨昏、起居有常四项皆直接体现顺应自然；晨练仅为一种锻炼方式，虽有益健康，却非顺应自然养生的特定原则，故为例外"},{"q":"理想的体质应是","o":["偏阴质","偏阳质","特禀质","痰湿质","阴阳平和质"],"a":4,"e":"阴阳平和质者阴阳平衡、气血调和、脏腑功能协调，体质强健、精力充沛、适应力强，是最理想的体质。偏阴质项实阳气偏虚、喜静少动；偏阳质项实阳气偏亢、好动易躁；特禀质项实为过敏等先天特异体质；痰湿质项实为水湿痰饮内聚的偏颇体质，皆非理想"},{"q":"疾病病势缠绵，其邪正关系一般是","o":["邪胜正虚","邪正相持","邪去正虚","正虚邪恋","正胜邪退"],"a":3,"e":"疾病日久，正气已虚而邪气未尽，正虚不能驱邪、邪恋不去，邪正相持不下，故病势缠绵、反复难愈。邪胜正虚项实为邪盛正衰、病情较重；邪正相持项实强调相持而未必正虚；邪去正虚项实为病后正虚而邪已去；正胜邪退项实为疾病向愈之转归，皆非缠绵之因"},{"q":"六淫中其性干涩，易伤津液的邪气是","o":["风邪","寒邪","湿邪","暑邪","燥邪"],"a":4,"e":"燥邪为秋令主气，其性干涩，最易损伤津液，见口鼻干燥、咽干口渴、皮肤干裂、大便干结、干咳少痰等。风邪项实善行数变、轻扬开泄；寒邪项实收引凝滞、易伤阳气；湿邪项实重浊黏滞、阻遏气机；暑邪项实炎热升散、耗气伤津，虽亦伤津而以炎热为特征，非以干涩著称"},{"q":"关于实火和虚火的对比，论述错误的是","o":["实火病势急速，病程较短，虚火病势缓慢，病程较长","实火缘于阳热有余，虚火缘于阴液不足","实火可见壮热面赤，虚火可见潮热盗汗","实火多见于男性，虚火多见于女性","实火属于实证，虚火属于虚证"],"a":3,"e":"实火因阳热有余，病势急、病程短，见壮热面赤、渴喜冷饮；虚火因阴液不足，病势缓、病程长，见潮热盗汗、五心烦热，两者以邪正虚实为别，与性别无必然对应。实火急虚火缓项实为病程之别；阳热有余、阴液不足项实为病机之别；壮热面赤、潮热盗汗项实为表现之别；实火属实、虚火属虚项实为证候性质之别，皆论述正确"},{"q":"六淫邪气中，具有“阻遏气机”特点的是","o":["风","暑","湿","寒","火"],"a":2,"e":"湿为阴邪，黏腻停滞，易阻遏气机，使升降失常，见胸闷脘痞、腹胀便溏等中焦气机阻滞之象。风邪项实善行而数变、风性主动；暑邪项实炎热升散、耗气伤津；寒邪项实收引、凝滞气血；火邪项实燔灼趋上、耗气伤津，皆不以阻遏气机为主要特点"},{"q":"下列各项，适合用清法的是","o":["阳气被郁而发热者","气虚致热证者","血虚致热证者","肺热咳嗽","脏腑本寒者"],"a":3,"e":"清法即清热法，用于热邪内盛之实热证，肺热咳嗽见发热、咳黄痰、口渴，属实热，宜清泻肺热。阳气被郁发热项实宜疏郁升散如升阳散火，不可清；气虚发热项实宜甘温除热如补中益气；血虚发热项实宜补血养血；脏腑本寒项实宜温法，皆非清法所宜"},{"q":"下列哪项不是瘀血的别名","o":["恶血","败血","蓄血","衃血","离经之血"],"a":4,"e":"瘀血别名有恶血、败血、蓄血、衃血、死血等，皆指血液运行失常、停积不散的病理产物。离经之血项实为对瘀血来源的概念性描述，侧重血液离开经脉这一界定而非约定俗成的别名；恶血、败血、蓄血、衃血四项皆为瘀血规范别名，故离经之血为例外"},{"q":"维持呼吸深度需下列哪一脏的功能","o":["肝","肺","心","肾","脾"],"a":3,"e":"肾主纳气，肺吸入之清气须下纳于肾，肾气摄纳使呼吸保持一定深度、防止呼吸表浅，故肺为气之主、肾为气之根。肺项实主气司呼吸，为呼吸之外在主宰而不主纳气深度；肝项实主疏泄调气机；心项实主血脉；脾项实主运化、为气血生化之源，皆非维持呼吸深度之脏"},{"q":"适用“热因热用”治则的是","o":["热病见热象","寒病见热象","阴虚见热象","热病见寒象","寒病见寒象"],"a":1,"e":"热因热用即以热治热，适用于真寒假热证，阴寒内盛于里、虚阳浮越于外，面红身热等热象为假，本质属寒，故用温热药治其真寒。热病见热象项实为单纯实热，宜热者寒之；热病见寒象项实为真热假寒，宜寒因寒用；寒病见寒象项实为实寒，宜寒者热之；阴虚见热象项实为虚热，宜滋阴清热，皆非热因热用"}];
